```rust
use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "hebisland", about = "无边框通知 / 审批浮窗")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// 启动通知守护进程
    Daemon,
    /// 发送一条通知到正在运行的守护进程
    Notify {
        /// JSON 格式的 SocketMessage
        #[arg(long)]
        msg: String,
    },
}

fn main() {
    let cli = Cli::parse();
    match cli.command {
        Commands::Daemon => {
            // 启动 Tauri app，socket listener 在 setup 中启动
            hebisland_lib::run();
        }
        Commands::Notify { msg } => {
            // 同步发送到 socket
            notify_sync(&msg);
        }
    }
}

fn notify_sync(msg: &str) {
    use std::io::Write;
    use std::os::unix::net::UnixStream;
    let sock_path = dirs::home_dir()
        .unwrap()
        .join(".hebbian")
        .join("island.sock");
    match UnixStream::connect(&sock_path) {
        Ok(mut stream) => {
            let _ = stream.write_all(msg.as_bytes());
            let _ = stream.write_all(b"\n");
            println!("ok");
        }
        Err(e) => {
            eprintln!("无法连接到 hebisland daemon: {e}");
            eprintln!("请先运行: hebisland daemon");
            std::process::exit(1);
        }
    }
}
```

