apps/cli/src/tui/components/permission_p.content:
//! 审批弹窗（HITL）。
//!
//! 用法：App 收到 `PermissionRequested` 后构造 `PermissionPopupState` 并存在 App.state；
//! 主循环把它当 popup 渲染。按键 a/b/c/d 选 + Esc 取消，App 把决定通过 `RunHandle.resolve_permission`
//! 回写 → popup 清空。

use protocol::{ApprovalDecision, PermissionKind, PermissionRequestId, PermissionScope};
use ratatui::{
    prelude::*,
    widgets::{Block, Borders, Clear, Paragraph, Wrap},
};

use super::super::theme;

pub struct PermissionPopupState {
    pub request_id: PermissionRequestId,
    pub kind: PermissionKind,
    pub summary: String,
}

pub fn render(state: &PermissionPopupState, frame: &mut Frame, area: Rect) {
    let popup = centered_rect(70, 35, area);
    frame.render_widget(Clear, popup);
    let title = match &state.kind {
        PermissionKind::ToolCall { tool_name, .. } => format!("权限审批：{tool_name}"),
        PermissionKind::PathAccess { tool_name, paths } => {
            format!("权限审批：{tool_name} 越界访问 {} 个路径", paths.len())
        }
        PermissionKind::Plan { .. } => "权限审批：执行计划".to_string(),
        PermissionKind::ContinueLongRun { iterations_used } => {
            format!("已运行 {iterations_used} 轮，是否继续")
        }
    };
    let mut lines: Vec<Line> = Vec::new();
    if !state.summary.is_empty() {
        for ln in state.summary.lines() {
            lines.push(Line::from(Span::raw(ln.to_string())));
        }
        lines.push(Line::raw(""));
    }
    lines.push(Line::from(Span::styled(
        "(a) 仅本次允许",
        theme::auto_judged_allow(),
    )));
    lines.push(Line::from(Span::styled(
        "(b) 本对话不再询问（Session 级）",
        theme::auto_judged_allow(),
    )));
    lines.push(Line::from(Span::styled(
        "(c) 始终允许（Global 级）",
        theme::auto_judged_allow(),
    )));
    lines.push(Line::from(Span::styled(
        "(d) 拒绝",
        theme::auto_judged_deny(),
    )));
    lines.push(Line::raw(""));
    lines.push(Line::from(Span::styled(
        "Esc 取消（视同拒绝）",
        theme::hint(),
    )));

    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(theme::popup_border())
        .title(Span::styled(title, theme::popup_title()));
    let para = Paragraph::new(lines).block(block).wrap(Wrap { trim: false });
    frame.render_widget(para, popup);
}

/// 按键 → 决策。
pub fn decision_for_key(c: char) -> Option<ApprovalDecision> {
    match c {
        'a' | 'A' => Some(ApprovalDecision::AllowOnce),
        'b' | 'B' => Some(ApprovalDecision::AllowAndRemember {
            scope: PermissionScope::Session,
            pattern: None,
        extra_patterns: Vec::new(),
        }),
        'c' | 'C' => Some(ApprovalDecision::AllowAndRemember {
            scope: PermissionScope::Global,
            pattern: None,
        extra_patterns: Vec::new(),
        }),
        'd' | 'D' => Some(ApprovalDecision::Deny),
        _ => None,
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

apps/cli/src/tui/components/question_pop.content:
//! Ask 工具的提问弹窗：题目 + 选项 + 自由输入。
//!
//! 按 1-9 数字键选选项；按 Tab 切到「自由输入」模式，再 Enter 提交；Esc 取消。

use protocol::{PermissionRequestId, QuestionOption, UserAnswer};
use ratatui::{
    prelude::*,
    widgets::{Block, Borders, Clear, Paragraph, Wrap},
};

use super::super::theme;

pub struct QuestionPopupState {
    pub request_id: PermissionRequestId,
    pub question: String,
    pub options: Vec<QuestionOption>,
    /// `true` 时按 1-9 数字键叠加勾选，Enter 提交 SelectedMulti。
    pub multi: bool,
    /// 自由输入 buffer + 是否处于输入模式（Tab 切换）。
    pub input_buffer: String,
    pub free_input_mode: bool,
    /// 多选时已勾选的 label 列表。
    pub picked: Vec<String>,
}

pub fn render(state: &QuestionPopupState, frame: &mut Frame, area: Rect) {
    let popup = centered_rect(70, 50, area);
    frame.render_widget(Clear, popup);

    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(Span::styled(
        state.question.as_str(),
        theme::popup_title(),
    )));
    lines.push(Line::raw(""));
    for (i, opt) in state.options.iter().enumerate().take(9) {
        let mark = if state.multi && state.picked.contains(&opt.label) {
            "[x]"
        } else if state.multi {
            "[ ]"
        } else {
            ""
        };
        let line = format!("  ({}) {} {}", i + 1, mark, opt.label);
        let style = if state.free_input_mode {
            theme::hint()
        } else {
            Style::default()
        };
        lines.push(Line::from(Span::styled(line, style)));
        if !opt.description.is_empty() {
            lines.push(Line::from(Span::styled(
                format!("      {}", opt.description),
                theme::hint(),
            )));
        }
    }
    lines.push(Line::raw(""));
    let input_label = if state.free_input_mode {
        format!("[自由输入] {}_", state.input_buffer)
    } else {
        format!("[Tab 切到自由输入] {}", state.input_buffer)
    };
    let input_style = if state.free_input_mode {
        theme::auto_judged_allow()
    } else {
        theme::hint()
    };
    lines.push(Line::from(Span::styled(input_label, input_style)));
    lines.push(Line::raw(""));
    let hint = if state.multi {
        "1-9 切换勾选，Enter 提交，Tab 自由输入，Esc 取消"
    } else {
        "1-9 选项，Enter 提交自由输入，Tab 切换模式，Esc 取消"
    };
    lines.push(Line::from(Span::styled(hint, theme::hint())));

    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(theme::popup_border())
        .title(Span::styled("Agent 提问", theme::popup_title()));
    let para = Paragraph::new(lines).block(block).wrap(Wrap { trim: false });
    frame.render_widget(para, popup);
}

/// 数字键 → 选项 index。
pub fn option_index_for_key(c: char) -> Option<usize> {
    c.to_digit(10).and_then(|d| {
        if (1..=9).contains(&d) {
            Some(d as usize - 1)
        } else {
            None
        }
    })
}

/// 提交逻辑：根据当前 popup state 形成 UserAnswer。free_input 优先。
pub fn build_answer(state: &QuestionPopupState) -> UserAnswer {
    if state.free_input_mode && !state.input_buffer.trim().is_empty() {
        return UserAnswer::Custom {
            text: state.input_buffer.trim().to_string(),
        };
    }
    if state.multi {
        if state.picked.is_empty() {
            UserAnswer::Cancelled
        } else {
            UserAnswer::SelectedMulti {
                labels: state.picked.clone(),
            }
        }
    } else if let Some(first) = state.picked.first() {
        UserAnswer::Selected {
            label: first.clone(),
        }
    } else {
        UserAnswer::Cancelled
    }
}

fn centered_rect(percent_x: u16, percent_y: u16, r: Rect) -> Rect {
    let popup_layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(r);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(popup_layout[1])[1]
}

apps/cli/src/tui/components/status_bar.r.content:
//! 底部状态栏：provider·model / token usage / RunMode / step counter。

use ratatui::{prelude::*, widgets::Paragraph};

use super::super::theme;

pub struct StatusBarState {
    pub provider_display: String,
    pub used_tokens: u64,
    pub budget_tokens: u64,
    pub run_mode: String,
    pub model_step: u32,
    pub tool_step: u32,
}

pub fn render(state: &StatusBarState, frame: &mut Frame, area: Rect) {
    let used = state.used_tokens;
    let budget = state.budget_tokens.max(1);
    let pct = (used as f64 / budget as f64 * 100.0).clamp(0.0, 999.0) as u32;
    let text = format!(
        " {provider} ─ {used}/{budget} tokens ({pct}%) ─ {mode} ─ step m{ms}/t{ts} ",
        provider = state.provider_display,
        used = format_count(used),
        budget = format_count(budget),
        pct = pct,
        mode = state.run_mode,
        ms = state.model_step,
        ts = state.tool_step,
    );
    let para = Paragraph::new(Line::from(Span::styled(text, theme::status_bar())));
    frame.render_widget(para, area);
}

fn format_count(n: u64) -> String {
    if n >= 1000 {
        format!("{:.1}k", n as f64 / 1000.0)
    } else {
        n.to_string()
    }
}

