              },
            })
          }
          className="h-4 w-4 rounded"
        />
      </FieldRow>

      <FieldRow label="命令 Shell" description="运行命令前先用这个 Shell 读取你的 PATH；留空时使用系统默认 Shell">
        <input
          type="text"
          value={draft.general.shell ?? ""}
          onChange={(e) =>
            setDraft({
              ...draft,
              general: {
                ...draft.general,
                shell: e.target.value.trim() ? e.target.value : null,
