          className="w-72 rounded-md border border-border bg-background px-2 py-1 text-sm"
        />
      </FieldRow>

      <FieldRow label="Debug 日志" description="开启后右侧工作台会显示 Model I/O 入口，便于查看模型请求/响应原文">
