function ImagePreviewOverlay({
  image,
  onClose,
}: {
  image: PreviewImage;
  onClose: () => void;
}) {
  const [zoom, setZoom] = useState(1);

  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onClose]);

  useEffect(() => {
    setZoom(1);
  }, [image.src]);

  const handleWheel = useCallback((event: React.WheelEvent<HTMLElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setZoom((current) => nextPreviewZoom(current, event.deltaY));
  }, []);

  return (
    <div
      className="pointer-events-auto absolute inset-0 flex items-center justify-center overflow-hidden bg-foreground/40 p-4"
      role="dialog"
      aria-modal="true"
      aria-label={image.name}
      onClick={onClose}
    >
      <button
        type="button"
        onClick={onClose}
        className="absolute right-4 top-4 rounded-md bg-background/90 p-2 text-foreground shadow hover:bg-background"
        title="关闭"
      >
        <X className="h-5 w-5" />
      </button>
      <figure
        className="max-h-full max-w-full"
        onClick={(event) => event.stopPropagation()}
        onWheel={handleWheel}
        onDoubleClick={() => setZoom(1)}
      >
        <img
          src={image.src}
          alt={image.name}
          className="max-h-full max-w-full rounded-md object-contain shadow-2xl transition-transform duration-100"
          draggable={false}
          style={{ transform: `scale(${zoom})` }}
        />
        <figcaption className="mt-2 truncate text-center text-sm text-white/80">
          {image.name}
        </figcaption>
      </figure>
    </div>
  );
}

function imageAttachmentSrc(attachment: Extract<MessageAttachment, { kind: "image" }>) {
  return `data:${attachment.media_type};base64,${attachment.data}`;
}

