import { useState } from "react";
import { Loader2, LogIn, Mail, Smartphone } from "lucide-react";
import { toast } from "sonner";
import { Dialog } from "@/desktop/ui/components/ui/dialog";
import { Button } from "@/desktop/ui/components/ui/button";
import { Input, Label, SecretInput } from "@/desktop/ui/components/ui/input";
import { api, type DeepseekLoginToken } from "@/desktop/bridge/tauri";
import { cn } from "@/desktop/ui/lib/utils";

type LoginKind = "email" | "mobile";

interface Props {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  /** 登录成功后回调；token 写回 provider.api_key，login 作为账号显示。 */
  onSuccess: (result: DeepseekLoginToken) => void;
}

export function DeepseekLoginDialog({ open, onOpenChange, onSuccess }: Props) {
  const [kind, setKind] = useState<LoginKind>("email");
  const [email, setEmail] = useState("");
  const [mobile, setMobile] = useState("");
  const [areaCode, setAreaCode] = useState("+86");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  function reset() {
    setEmail("");
    setMobile("");
    setAreaCode("+86");
    setPassword("");
  }

  async function handleLogin() {
    if (!password.trim()) {
      toast.error("请填写密码");
      return;
    }
    if (kind === "email" && !email.trim()) {
      toast.error("请填写邮箱");
      return;
    }
    if (kind === "mobile" && !mobile.trim()) {
      toast.error("请填写手机号");
      return;
    }

    setLoading(true);
    try {
      const result = await api.deepseekLogin({
        email: kind === "email" ? email.trim() : null,
        mobile: kind === "mobile" ? mobile.trim() : null,
        area_code: kind === "mobile" ? areaCode.trim() : null,
        password,
      });
      onSuccess(result);
      toast.success(`已登录：${result.login}`);
      reset();
      onOpenChange(false);
    } catch (e: any) {
      toast.error(e?.message || String(e));
    } finally {
      setLoading(false);
    }
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(v) => {
        if (!loading) onOpenChange(v);
      }}
      title="用 DeepSeek 账号登录"
      description="使用 chat.deepseek.com 的账号密码登录，成功后 token 自动写入 API Key 字段。"
      size="md"
      footer={
        <>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={loading}
          >
            取消
          </Button>
          <Button onClick={handleLogin} disabled={loading}>
            {loading ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin mr-1" />
            ) : (
              <LogIn className="w-3.5 h-3.5 mr-1" />
            )}
            登录
          </Button>
        </>
      }
    >
      <div className="space-y-3">
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => setKind("email")}
            className={cn(
              "flex-1 inline-flex items-center justify-center gap-1.5 rounded-md border px-3 py-1.5 text-sm",
              kind === "email"
                ? "border-primary bg-primary/10 text-primary"
                : "border-border text-muted-foreground hover:bg-accent"
            )}
          >
            <Mail className="w-3.5 h-3.5" /> 邮箱
          </button>
          <button
            type="button"
            onClick={() => setKind("mobile")}
            className={cn(
              "flex-1 inline-flex items-center justify-center gap-1.5 rounded-md border px-3 py-1.5 text-sm",
              kind === "mobile"
                ? "border-primary bg-primary/10 text-primary"
                : "border-border text-muted-foreground hover:bg-accent"
            )}
          >
            <Smartphone className="w-3.5 h-3.5" /> 手机号
          </button>
        </div>

        {kind === "email" ? (
          <div className="space-y-1.5">
            <Label>邮箱</Label>
            <Input
              value={email}
              spellCheck={false}
              autoCorrect="off"
              autoCapitalize="off"
              placeholder="you@example.com"
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
        ) : (
          <div className="grid grid-cols-[80px_1fr] gap-2">
            <div className="space-y-1.5">
              <Label>区号</Label>
              <Input
                value={areaCode}
                onChange={(e) => setAreaCode(e.target.value)}
                spellCheck={false}
                autoCorrect="off"
                placeholder="+86"
              />
            </div>
            <div className="space-y-1.5">
              <Label>手机号</Label>
              <Input
                value={mobile}
                spellCheck={false}
                autoCorrect="off"
                inputMode="numeric"
                placeholder="13xxxxxxxxx"
                onChange={(e) => setMobile(e.target.value)}
              />
            </div>
          </div>
        )}

        <div className="space-y-1.5">
          <Label>密码</Label>
          <SecretInput
            value={password}
            spellCheck={false}
            autoCorrect="off"
            placeholder="DeepSeek 账号密码"
            onChange={(e) => setPassword(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") handleLogin();
            }}
          />
        </div>

        <p className="text-[11px] text-muted-foreground leading-relaxed">
          凭据仅会发送给 chat.deepseek.com 官方端点，不会上传到任何第三方。
          登录后获得的 token 会写入当前 provider 的 API Key。
        </p>
      </div>
    </Dialog>
  );
}

import { Fragment, useEffect, useMemo, useRef, useState, useCallback } from "react";
import { createPortal } from "react-dom";
import {
  X,
  Columns2,
  Rows3,
  Maximize2,
  Minimize2,
  ArrowLeft,
  ArrowRight,
  UnfoldVertical,
} from "lucide-react";
import { api } from "@/desktop/bridge/tauri";
import { cn } from "@/desktop/ui/lib/utils";
import { PathHint } from "@/desktop/ui/components/PathHint";
import type { DiffPayload, EditEntry } from "@/desktop/ui/types";

/**
 * 把全屏内容渲到 ChatView 末尾的 `#chat-fullscreen-anchor`。
 * 锚点是 ChatView 内 `absolute inset-0 pointer-events-none` 的覆盖层——
 * 这样放大只覆盖 chat 区域（不挡 sidebar），且需要交互时自己开 pointer-events-auto。
 * 锚点不存在时（未渲染 ChatView）回退到 document.body。
 */
export function FullscreenPortal({ children }: { children: React.ReactNode }) {
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => {
    setHost(
      typeof document !== "undefined"
        ? document.getElementById("chat-fullscreen-anchor") ?? document.body
        : null,
    );
  }, []);
  if (!host) return null;
  return createPortal(children, host);
}

/**
 * Diff 渲染布局（架构 §4.13.9）：
 * - inline: 单列 unified view（行号 + +/- 符号）
 * - split:  左右两栏分屏
 *
 * 注：是否「放大」由调用方独立管理（`expanded` state + FullscreenPortal 包装），
 * 不再揉进 DiffMode——拆开后切换布局不会误关掉放大框。
 */
export type DiffMode = "inline" | "split";

interface DiffRow {
  left: string;
  right: string;
  kind: "same" | "add" | "remove";
}

/** LCS-based diff: computes aligned rows marking added/removed/same lines. */
function computeDiff(beforeLines: string[], afterLines: string[]): DiffRow[] {
  const m = beforeLines.length;
  const n = afterLines.length;
  const dp = new Uint16Array((m + 1) * (n + 1));
  const idx = (i: number, j: number) => i * (n + 1) + j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (beforeLines[i - 1] === afterLines[j - 1]) {
        dp[idx(i, j)] = dp[idx(i - 1, j - 1)] + 1;
      } else {
        dp[idx(i, j)] = Math.max(dp[idx(i - 1, j)], dp[idx(i, j - 1)]);
      }
    }
  }

  const rev: DiffRow[] = [];
  let i = m;
  let j = n;
  while (i > 0 || j > 0) {
    if (i > 0 && j > 0 && beforeLines[i - 1] === afterLines[j - 1]) {
      rev.push({ left: beforeLines[i - 1], right: afterLines[j - 1], kind: "same" });
      i--;
      j--;
    } else if (j > 0 && (i === 0 || dp[idx(i, j - 1)] >= dp[idx(i - 1, j)])) {
      rev.push({ left: "", right: afterLines[j - 1], kind: "add" });
      j--;
    } else {
      rev.push({ left: beforeLines[i - 1], right: "", kind: "remove" });
      i--;
    }
  }
  return rev.reverse();
}

interface DiffViewerProps {
  /** 修改前的全文文本。Edit 流式时是 `args.old_string` 已收部分；Write 时为 ""。 */
  beforeText: string;
  /** 修改后的全文文本。Edit 流式时是 `args.new_string`；Write 时为 `args.content`。 */
  afterText: string;
  /** 文件路径（顶栏文件名 + 全路径 hover）。空字符串则用 fallback 文案。 */
  filePath?: string;
  /** 顶栏右上角动作标签："修改文件" / "创建文件" / "覆盖文件"… */
  actionLabel?: string;
  /** 当前布局（仅 inline / split）。 */
  mode: DiffMode;
  onCycleMode: () => void;
  /** 流式态：在 after 末尾追加光标占位，提示参数仍在写入。 */
  streaming?: boolean;
  /** 提供则在顶栏右侧渲染关闭按钮（放大 / 浮层场景）。 */
  onClose?: () => void;
  /** 顶栏左侧的额外标签（例如「审批前预览」）。 */
  badge?: string;
  /**
   * 当前是否处于放大态。仅影响顶栏切换按钮图标（Maximize2 ↔ Minimize2）。
   * 实际放大渲染由调用方包 FullscreenPortal 完成。
   */
  expanded?: boolean;
  /** 提供则在顶栏渲染放大/缩小按钮。 */
  onToggleExpanded?: () => void;
  /** 顶栏右侧追加渲染：留给将来自定义按钮。 */
  rightExtras?: React.ReactNode;
  /** 容器额外类名。 */
  className?: string;
  /** 滚动区域最多显示行数。超过自动滚动，未传则不限。 */
  maxRows?: number;
  /**
   * GitHub PR review 风格折叠：每个 change 行外保留 ±N 行 same 上下文，
   * 中间没被任何 change 邻居覆盖的 same 段折叠成「展开 K 行」按钮可点开。
   * 未传 / `0` / 没有任何 same 行可折叠时全展开。
   * 仅在拿到完整文件（含未改动上下文）时有意义，调用方在 detail+expanded 时传 3。
   */
  collapseContext?: number;
  /**
   * 行号起点：`beforeText` 实际对应原文件的第几行（1-based）。默认 1。
   * 流式 / 审批 / 非放大 detail 态拿到的 beforeText 只是 `old_string` 局部，
   * 调用方在原文中 indexOf 出起始行号传进来，行号槽才能显示真实位置。
   */
  baseLineBefore?: number;
  /** afterText 的起点行号。一般跟 baseLineBefore 一致（同一处替换），默认 1。 */
  baseLineAfter?: number;
}

/**
 * GitHub 风格的折叠视图：返回每个"展示单元"——可能是单行，也可能是一个可点开的折叠段。
 *
 * - 任何非 same 行（add / remove）和它周围 ±contextLines 的 same 行都直接展示
 * - 中间的纯 same 段折叠成一个 group，渲一个"展开 K 行原文"按钮
 * - `contextLines = 0` 表示不展示任何 same 上下文（仅 change 行）
 */
type DiffViewItem =
  | { kind: "row"; row: DiffRow; index: number }
  | { kind: "collapsed"; start: number; end: number; rows: DiffRow[] };

/**
 * 预计算每行 before/after 行号。避免在 React map 里 mutable 累加导致折叠段
 * 展开时闭包行号错乱。
 */
interface RenderRow {
  kind: "same" | "add" | "remove";
  textLeft: string;
  textRight: string;
  beforeNum: number | null;
  afterNum: number | null;
  diffIdx: number;
}

function buildRenderRows(
  diffRows: DiffRow[],
  baseBefore = 1,
  baseAfter = 1,
): RenderRow[] {
  let bn = baseBefore - 1;
  let an = baseAfter - 1;
  return diffRows.map((row, i) => {
    let beforeNum: number | null = null;
    let afterNum: number | null = null;
    if (row.kind === "same") {
      bn++;
      an++;
      beforeNum = bn;
      afterNum = an;
    } else if (row.kind === "remove") {
      bn++;
      beforeNum = bn;
    } else {
      an++;
      afterNum = an;
    }
    return {
      kind: row.kind,
      textLeft: row.left,
      textRight: row.right,
      beforeNum,
      afterNum,
      diffIdx: i,
    };
  });
}

function buildCollapsibleView(
  diffRows: DiffRow[],
  contextLines: number,
): DiffViewItem[] {
  if (contextLines < 0) contextLines = 0;
  const n = diffRows.length;
  const visible = new Array<boolean>(n).fill(false);
  for (let i = 0; i < n; i++) {
    if (diffRows[i].kind === "same") continue;
    const lo = Math.max(0, i - contextLines);
    const hi = Math.min(n - 1, i + contextLines);
    for (let k = lo; k <= hi; k++) visible[k] = true;
  }
  const result: DiffViewItem[] = [];
  let i = 0;
  while (i < n) {
    if (visible[i]) {
      result.push({ kind: "row", row: diffRows[i], index: i });
      i++;
    } else {
      const start = i;
      while (i < n && !visible[i]) i++;
      result.push({
        kind: "collapsed",
        start,
        end: i,
        rows: diffRows.slice(start, i),
      });
    }
  }
  return result;
}

/** 行高约 18px（text-[11px] leading-relaxed），统一用于 maxRows → maxHeight 换算 */
const DIFF_LINE_PX = 18;
const DIFF_VIEWPORT_PADDING_PX = 16;

/**
 * 流式态下让 diff 视口自动粘底：
 * - 新内容到达且当前粘底 → scrollTop = scrollHeight
 * - 用户主动向上滚 → 解除粘底，新内容不再强拉到底
 * - 用户重新滚回底部 → 自动恢复粘底
 *
 * 仅在 `streaming = true` 时生效；非流式态行为不变。
 */
function useStickyBottomScroll(streaming: boolean, signal: unknown) {
  const ref = useRef<HTMLDivElement | null>(null);
  const stickRef = useRef(true);

  const onScroll = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    stickRef.current = el.scrollTop + el.clientHeight >= el.scrollHeight - 4;
  }, []);

  useEffect(() => {
    if (!streaming) return;
    const el = ref.current;
    if (!el || !stickRef.current) return;
    el.scrollTop = el.scrollHeight;
  }, [streaming, signal]);

  // streaming 由 false → true 时重置粘底意图（新一轮 edit 默认跟随）
  useEffect(() => {
    if (streaming) stickRef.current = true;
  }, [streaming]);

  return { ref, onScroll };
}

function maxRowsToStyle(
  maxRows: number | undefined,
): React.CSSProperties | undefined {
  if (!maxRows) return undefined;
  return {
    maxHeight: `${maxRows * DIFF_LINE_PX + DIFF_VIEWPORT_PADDING_PX}px`,
  };
}

/**
 * 纯渲染组件：架构 §4.13.9 三态共用入口。父组件只需提供 before/after 文本即可。
 *
 * 三态接入点：
 * - streaming（消息卡片）：MessageBubble Edit/Write 流式展开
 * - approval（审批弹窗）：PermissionApprovalPopup Edit/Write
 * - detail（消息卡片）：MessageBubble Edit/Write 已落盘后展开
 */
export function DiffViewer({
  beforeText,
  afterText,
  filePath,
  actionLabel,
  mode,
  onCycleMode,
  streaming,
  onClose,
  badge,
  expanded,
  onToggleExpanded,
  rightExtras,
  className,
  maxRows,
  collapseContext,
  baseLineBefore = 1,
  baseLineAfter = 1,
}: DiffViewerProps) {
  const diffRows = useMemo(
    () => computeDiff(beforeText.split("\n"), afterText.split("\n")),
    [beforeText, afterText],
  );
  const renderRows = useMemo(
    () => buildRenderRows(diffRows, baseLineBefore, baseLineAfter),
    [diffRows, baseLineBefore, baseLineAfter],
  );
  const items = useMemo<DiffViewItem[] | null>(() => {
    if (collapseContext && collapseContext > 0) {
      return buildCollapsibleView(diffRows, collapseContext);
    }
    return null;
  }, [diffRows, collapseContext]);
  // 折叠段展开 state：key = `${start}-${end}`，跨切换 inline↔split 保留
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());
  const toggleGroup = useCallback((key: string) => {
    setExpandedGroups((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }, []);

  const addCount = diffRows.filter((r) => r.kind === "add").length;
  const removeCount = diffRows.filter((r) => r.kind === "remove").length;

  const isEmpty = !beforeText && !afterText;
  // 新建文件场景：old_string 为空、after 非空 → 没有"差异"语义，单栏纯 add 视图最直观
  const isCreate = !beforeText && !!afterText;
  const heightStyle = maxRowsToStyle(maxRows);

  return (
    <div className={cn("flex min-h-0 flex-col", className)}>
      <DiffHeader
        filePath={filePath ?? ""}
        actionLabel={actionLabel ?? ""}
        badge={badge}
        mode={mode}
        addCount={addCount}
        removeCount={removeCount}
        onCycleMode={onCycleMode}
        hideModeToggle={isCreate}
        expanded={expanded}
        onToggleExpanded={onToggleExpanded}
        onClose={onClose}
        rightExtras={rightExtras}
      />
      {isEmpty ? (
        <div className="flex-1 px-3 py-6 text-center text-[12px] text-muted-foreground">
          {streaming ? "等待参数…" : "文件为空（无变更）"}
        </div>
      ) : isCreate || mode === "inline" ? (
        // 新建文件没有差异语义，强走 inline 模式：全 add 行 + 绿底 + 行号，
        // 视觉跟 split 的右侧栏一致但去掉空白左栏
        <InlineDiff
          renderRows={renderRows}
          items={items}
          streaming={!!streaming}
          heightStyle={heightStyle}
          expandedGroups={expandedGroups}
          toggleGroup={toggleGroup}
        />
      ) : (
        <SplitDiff
          renderRows={renderRows}
          items={items}
          streaming={!!streaming}
          heightStyle={heightStyle}
          expandedGroups={expandedGroups}
          toggleGroup={toggleGroup}
        />
      )}
    </div>
  );
}

function DiffHeader({
  filePath,
  actionLabel,
  badge,
  mode,
  addCount,
  removeCount,
  onCycleMode,
  hideModeToggle,
  expanded,
  onToggleExpanded,
  onClose,
  rightExtras,
}: {
  filePath: string;
  actionLabel: string;
  badge?: string;
  mode: DiffMode;
  addCount: number;
  removeCount: number;
  onCycleMode: () => void;
  /** create / 单栏 add-only 场景下隐藏 split↔inline 切换按钮 */
  hideModeToggle?: boolean;
  expanded?: boolean;
  onToggleExpanded?: () => void;
  onClose?: () => void;
  rightExtras?: React.ReactNode;
}) {
  // 顶栏循环按钮：split ↔ inline；放大/缩小走独立按钮，不再混进 mode
  const modeLabel = mode === "split" ? "分栏" : "行内";
  const ModeIcon = mode === "split" ? Columns2 : Rows3;

  return (
    <div className="flex items-center justify-between gap-2 border-b border-border bg-muted/30 px-3 py-2 shrink-0">
      <div className="min-w-0 flex items-center gap-2">
        {filePath && (
          <PathHint path={filePath}>
            <span className="truncate text-[12px] font-medium font-mono">
              {pathLeaf(filePath)}
            </span>
          </PathHint>
        )}
        {actionLabel && (
          <span className="shrink-0 rounded bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground">
            {actionLabel}
          </span>
        )}
        {badge && (
          <span className="shrink-0 rounded bg-amber-500/10 px-1.5 py-0.5 text-[10px] text-amber-600 dark:text-amber-400">
            {badge}
          </span>
        )}
        {/* GitHub PR 风格：+N -M 分开渲染，绿/红 token；无变更则隐藏 */}
        {(addCount > 0 || removeCount > 0) && (
          <span className="shrink-0 inline-flex items-center gap-1.5 font-mono text-[10px] tabular-nums">
            {addCount > 0 && (
              <span className="text-green-700 dark:text-green-400">
                +{addCount}
              </span>
            )}
            {removeCount > 0 && (
              <span className="text-rose-600 dark:text-rose-400">
                −{removeCount}
              </span>
            )}
          </span>
        )}
      </div>
      <div className="flex items-center gap-1">
        {!hideModeToggle && (
          <button
            type="button"
            onClick={onCycleMode}
            className="inline-flex items-center gap-1 rounded px-2 py-1 text-[10px] text-muted-foreground hover:bg-accent hover:text-foreground"
            title={`当前：${modeLabel}。点击切换 split ↔ inline。`}
          >
            <ModeIcon className="h-3.5 w-3.5" />
            <span>{modeLabel}</span>
          </button>
        )}
        {onToggleExpanded && (
          <button
            type="button"
            onClick={onToggleExpanded}
            className="grid h-6 w-6 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
            title={expanded ? "退出放大 (Esc)" : "放大查看"}
          >
            {expanded ? (
              <Minimize2 className="h-3.5 w-3.5" />
            ) : (
              <Maximize2 className="h-3.5 w-3.5" />
            )}
          </button>
        )}
        {rightExtras}
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            className="grid h-6 w-6 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
            title="关闭 (Esc)"
          >
            <X className="h-4 w-4" />
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * 单行渲染：受控行号槽 + +/- 符号 + 文本。
 *
 * - 行号槽：传 `undefined` 不渲该槽，传 `null` 渲空字符串（占位保持对齐）。
 *   inline 模式同时渲 before/after 两个槽；split 模式只渲一个。
 * - sign：VSCode 风格的 +/-/空格符号；颜色跟随符号变化。`undefined` 不渲符号槽。
 * - text 用 `whitespace-pre-wrap break-all`，长行换行从文本起点缩进。
 */
function DiffLine({
  beforeNum,
  afterNum,
  sign,
  text,
  rowClass,
  showCursor,
}: {
  beforeNum?: number | null;
  afterNum?: number | null;
  sign?: "+" | "-" | " ";
  text: string;
  rowClass?: string;
  showCursor?: boolean;
}) {
  const renderGutter = (n: number | null | undefined) =>
    n === undefined ? null : (
      <span className="select-none shrink-0 w-8 mr-1 text-right text-[9px] text-muted-foreground tabular-nums">
        {n ?? ""}
      </span>
    );

  return (
    <div className={cn("flex min-h-[1.4em] items-start", rowClass)}>
      {renderGutter(beforeNum)}
      {renderGutter(afterNum)}
      {sign !== undefined && (
        <span
          className={cn(
            "select-none shrink-0 w-3 mr-1 text-center text-[12px] font-mono leading-[1.4em]",
            sign === "+" && "text-green-600 dark:text-green-400",
            sign === "-" && "text-destructive",
          )}
        >
          {sign === " " ? "" : sign}
        </span>
      )}
      <span className="min-w-0 flex-1 whitespace-pre-wrap break-all">
        {text || " "}
        {showCursor && <StreamCursor />}
      </span>
    </div>
  );
}

/**
 * Unified inline diff（VSCode 风格）：单列、同时显示 before 和 after 行号、行首 +/-/空格符号。
 * - 删除行：左行号 + 空右行号 + `-`，红底
 * - 新增行：空左行号 + 右行号 + `+`，绿底
 * - 不变行：两行号都有 + 空格符
 */
interface DiffListProps {
  renderRows: RenderRow[];
  items: DiffViewItem[] | null;
  streaming: boolean;
  heightStyle?: React.CSSProperties;
  expandedGroups: Set<string>;
  toggleGroup: (key: string) => void;
}

/** 找出 renderRows 最后一个非 remove 行，做流式光标位置 */
function findLastNonRemoveIdx(renderRows: RenderRow[]): number {
  for (let i = renderRows.length - 1; i >= 0; i--) {
    if (renderRows[i].kind !== "remove") return i;
  }
  return -1;
}

function InlineDiff({
  renderRows,
  items,
  streaming,
  heightStyle,
  expandedGroups,
  toggleGroup,
}: DiffListProps) {
  const lastNonRemoveIdx = findLastNonRemoveIdx(renderRows);
  const { ref: scrollRef, onScroll } = useStickyBottomScroll(streaming, renderRows);

  const renderRow = (r: RenderRow) => {
    let sign: "+" | "-" | " ";
    let text: string;
    let rowClass: string;
    if (r.kind === "remove") {
      sign = "-";
      text = r.textLeft;
      rowClass = "bg-destructive/10 text-destructive px-1";
    } else if (r.kind === "add") {
      sign = "+";
      text = r.textRight;
      rowClass = "bg-green-500/10 text-green-700 dark:text-green-400 px-1";
    } else {
      sign = " ";
      text = r.textLeft;
      rowClass = "px-1";
    }
    return (
      <DiffLine
        key={r.diffIdx}
        beforeNum={r.beforeNum}
        afterNum={r.afterNum}
        sign={sign}
        text={text}
        rowClass={rowClass}
        showCursor={streaming && r.diffIdx === lastNonRemoveIdx}
      />
    );
  };

  return (
    <div
      ref={scrollRef}
      onScroll={onScroll}
      className="flex-1 overflow-auto font-mono text-[11px] leading-relaxed"
      style={heightStyle}
    >
      <div className="p-2">
        {items
          ? items.map((item) => {
              if (item.kind === "row") {
                return renderRow(renderRows[item.index]);
              }
              const groupKey = `${item.start}-${item.end}`;
              const open = expandedGroups.has(groupKey);
              if (open) {
                return (
                  <Fragment key={groupKey}>
                    {Array.from(
                      { length: item.end - item.start },
                      (_, k) => renderRows[item.start + k],
                    ).map((r) => renderRow(r))}
                  </Fragment>
                );
              }
              return (
                <CollapsedToggle
                  key={groupKey}
                  rowCount={item.end - item.start}
                  startLine={item.start + 1}
                  endLine={item.end}
                  onClick={() => toggleGroup(groupKey)}
                />
              );
            })
          : renderRows.map((r) => renderRow(r))}
      </div>
    </div>
  );
}

function SplitDiff({
  renderRows,
  items,
  streaming,
  heightStyle,
  expandedGroups,
  toggleGroup,
}: DiffListProps) {
  const lastNonRemoveIdx = findLastNonRemoveIdx(renderRows);
  const { ref: scrollRef, onScroll } = useStickyBottomScroll(streaming, renderRows);

  const PlaceholderCell = (
    <div className="min-h-[1.4em] flex-1 min-w-0 bg-muted/10" />
  );

  // row-first 渲染：每一行用一个 flex container 装左右两个 cell；flex stretch 自动等高
  const renderRow = (r: RenderRow) => {
    let leftCell: React.ReactNode;
    let rightCell: React.ReactNode;

    if (r.kind === "add") {
      leftCell = PlaceholderCell;
    } else {
      leftCell = (
        <div className="flex-1 min-w-0">
          <DiffLine
            beforeNum={r.beforeNum ?? undefined}
            sign={r.kind === "remove" ? "-" : " "}
            text={r.textLeft}
            rowClass={cn(
              "px-1",
              r.kind === "remove" && "bg-destructive/10 text-destructive",
            )}
          />
        </div>
      );
    }

    if (r.kind === "remove") {
      rightCell = PlaceholderCell;
    } else {
      rightCell = (
        <div className="flex-1 min-w-0">
          <DiffLine
            afterNum={r.afterNum ?? undefined}
            sign={r.kind === "add" ? "+" : " "}
            text={r.textRight}
            showCursor={streaming && r.diffIdx === lastNonRemoveIdx}
            rowClass={cn(
              "px-1",
              r.kind === "add" && "bg-green-500/10 text-green-700 dark:text-green-400",
            )}
          />
        </div>
      );
    }

    return (
      <div key={r.diffIdx} className="flex divide-x divide-border">
        {leftCell}
        {rightCell}
      </div>
    );
  };

  return (
    <div
      ref={scrollRef}
      onScroll={onScroll}
      className="flex-1 overflow-auto font-mono text-[11px] leading-relaxed"
      style={heightStyle}
    >
      {/* 双列 sticky header */}
      <div className="sticky top-0 z-10 flex divide-x divide-border border-b border-border bg-muted/40">
        <div className="flex-1 min-w-0 flex items-center gap-1 px-2 py-1 text-[10px] text-muted-foreground">
          <ArrowLeft className="h-3 w-3" />
          修改前
        </div>
        <div className="flex-1 min-w-0 flex items-center gap-1 px-2 py-1 text-[10px] text-muted-foreground">
          <ArrowRight className="h-3 w-3" />
          修改后
        </div>
      </div>

      <div className="p-2">
        {items
          ? items.map((item) => {
              if (item.kind === "row") {
                return renderRow(renderRows[item.index]);
              }
              const groupKey = `${item.start}-${item.end}`;
              const open = expandedGroups.has(groupKey);
              if (open) {
                return (
                  <Fragment key={groupKey}>
                    {Array.from(
                      { length: item.end - item.start },
                      (_, k) => renderRows[item.start + k],
                    ).map((r) => renderRow(r))}
                  </Fragment>
                );
              }
              return (
                <CollapsedToggle
                  key={groupKey}
                  rowCount={item.end - item.start}
                  startLine={item.start + 1}
                  endLine={item.end}
                  onClick={() => toggleGroup(groupKey)}
                />
              );
            })
          : renderRows.map((r) => renderRow(r))}
      </div>
    </div>
  );
}

/** GitHub PR review 风格"展开 N 行原文"按钮——跨整行渲染，点击展开该折叠段 */
function CollapsedToggle({
  rowCount,
  startLine,
  endLine,
  onClick,
}: {
  rowCount: number;
  startLine: number;
  endLine: number;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="my-px flex w-full items-center justify-center gap-1.5 rounded-sm border border-dashed border-border/60 bg-muted/30 px-2 py-0.5 text-[10px] text-muted-foreground transition-colors hover:border-border hover:bg-muted hover:text-foreground"
      title={`展开第 ${startLine}—${endLine} 行原文`}
    >
      <UnfoldVertical className="h-3 w-3" />
      <span>展开 {rowCount} 行原文（#{startLine}—#{endLine}）</span>
    </button>
  );
}

function StreamCursor() {
  return (
    <span
      aria-hidden="true"
      className="ml-0.5 inline-block h-3 w-[2px] -translate-y-[1px] animate-pulse rounded-sm bg-foreground/70 align-middle"
    />
  );
}

/* ───────────────── DiffPanel：detail 态浮层（基于 EditEntry / api.diffEdit）─────── */

interface DiffPanelProps {
  sessionId: string;
  entry: EditEntry;
  onClose: () => void;
}

export function DiffPanel({ sessionId, entry, onClose }: DiffPanelProps) {
  const [payload, setPayload] = useState<DiffPayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<DiffMode>("split");
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    api
      .diffEdit(sessionId, entry.snapshot_id)
      .then((p) => {
        if (!cancelled) setPayload(p);
      })
      .catch((e) => {
        if (!cancelled) setError(e?.message ?? String(e));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [sessionId, entry.snapshot_id]);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        if (expanded) setExpanded(false);
        else onClose();
      }
    },
    [expanded, onClose],
  );

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [handleKeyDown]);

  const cycleMode = () =>
    setViewMode((prev) => (prev === "split" ? "inline" : "split"));
  const toggleExpanded = () => setExpanded((e) => !e);

  const actionLabel =
    entry.action === "create"
      ? "创建文件"
      : entry.action === "overwrite"
        ? "覆盖文件"
        : "修改文件";

  const content = (
    <>
      {loading && payload == null ? (
        <div className="flex-1 flex items-center justify-center text-sm text-muted-foreground py-16">
          加载差异…
        </div>
      ) : error ? (
        <div className="flex-1 flex items-center justify-center text-sm text-destructive py-16 px-4 text-center">
          {error}
        </div>
      ) : payload ? (
        <DiffViewer
          beforeText={payload.before_text}
          afterText={payload.after_text}
          filePath={payload.file_path}
          actionLabel={actionLabel}
          mode={viewMode}
          onCycleMode={cycleMode}
          maxRows={expanded ? undefined : 20}
          expanded={expanded}
          onToggleExpanded={toggleExpanded}
          collapseContext={3}
          onClose={onClose}
          className="min-h-0 flex-1"
        />
      ) : (
        <div className="flex-1 flex items-center justify-center text-sm text-muted-foreground py-16">
          无差异数据
        </div>
      )}
    </>
  );

  if (expanded) {
    return (
      <FullscreenPortal>
        <div
          className="pointer-events-auto absolute inset-0 bg-foreground/30"
          onClick={() => setExpanded(false)}
        />
        <div
          className="pointer-events-auto absolute inset-3 flex flex-col overflow-hidden border border-border bg-background shadow-2xl"
          onClick={(e) => e.stopPropagation()}
        >
          {content}
        </div>
      </FullscreenPortal>
    );
  }

  // 非阻塞浮层：portal 到 chat 区域；仅卡片本身接收点击，背景透传到聊天界面。
  return (
    <FullscreenPortal>
      <div className="pointer-events-auto absolute right-4 top-4 w-[85%] max-w-[960px] max-h-[calc(100%-2rem)] flex flex-col border border-border bg-background/95 shadow-xl backdrop-blur">
        {content}
      </div>
    </FullscreenPortal>
  );
}

function pathLeaf(filePath: string): string {
  const parts = filePath.replace(/\\/g, "/").split("/");
  return parts[parts.length - 1] || filePath;
}

import { useState, useEffect } from "react";
import { toast } from "sonner";
import { FilePenLine, Plus, Rewind, ChevronDown, ChevronRight } from "lucide-react";
import { useStore } from "@/desktop/ui/store/useStore";
import { api } from "@/desktop/bridge/tauri";
import { cn, formatTime } from "@/desktop/ui/lib/utils";
import { focusToolCall } from "@/desktop/ui/lib/focusToolCall";
import type { EditEntry } from "@/desktop/ui/types";

// 稳定空数组引用：zustand selector 用浅比较，每次返回新 `[]` 会触发无限重渲染。
const EMPTY_ENTRIES: EditEntry[] = [];

/**
 * 旧版本浮动卡片——已被 RightSidebar 内的 `EditTreeTab` 替代（架构 §4.13.x 修订）。
 * 保留 export 占位让老的 import 还能通过类型检查；本身永远不渲染。
 */
export function EditTreePanel() {
  return null;
}

/**
 * 工作台 sidebar 内的「修改文件」tab 内容（架构 §4.13 修订）。
 *
 * 展示当前 session 所有 Edit 工具快照，按文件路径分组、支持单次回退。
 * 数据源（`useStore.sessionEditSnapshots[currentSessionId]`，session-scoped），
 * 嵌入 RightSidebar tab 区。空状态显示 hint 而不是 return null（沿 sidebar 风格）。
 */
export function EditTreeTab() {
  const sessionId = useStore((s) => s.currentSession?.id ?? null);
  const editSnapshots = useStore(
    (s) => (sessionId ? s.sessionEditSnapshots[sessionId] : undefined) ?? EMPTY_ENTRIES,
  );
  const revertEdit = useStore((s) => s.revertEdit);
  const refreshEdits = useStore((s) => s.refreshEdits);
  const [reverting, setReverting] = useState<Set<string>>(new Set());

  useEffect(() => {
    if (!sessionId) return;
    let cancelled = false;
    // 切到本 tab 时主动拉一次后端权威列表——覆盖「应用启动后没开过 run」的场景：
    // openSession 那边的 refreshEdits 也会跑，这里是兜底（特别是 hebweb 上 listen
    // 不到 edit 事件、只能靠拉的场景）。
    void refreshEdits();
    api.editsWorktreeStatus(sessionId)
      .then((status) => {
        if (!cancelled && !status.enabled && status.entry_count === 0) {
          toast.warning("Git 不可用，Edit 修改记录功能已禁用", {
            description: "请确认系统已安装 git CLI 工具。",
          });
        }
      })
      .catch(() => { /* 静默 */ });
    return () => { cancelled = true; };
  }, [sessionId, refreshEdits]);

  async function handleRevert(snapshotId: string) {
    if (!sessionId) return;
    setReverting((prev) => new Set(prev).add(snapshotId));
    try {
      await revertEdit(sessionId, snapshotId);
      toast.success("已回退修改");
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setReverting((prev) => {
        const next = new Set(prev);
        next.delete(snapshotId);
        return next;
      });
    }
  }

  if (!sessionId) {
    return (
      <div className="grid h-full place-items-center px-4 py-8 text-center text-[11px] text-muted-foreground">
        <div>
          <FilePenLine className="mx-auto mb-2 h-5 w-5 opacity-40" />
          当前没打开对话
        </div>
      </div>
    );
  }

  if (editSnapshots.length === 0) {
    return (
      <div className="grid h-full place-items-center px-4 py-8 text-center text-[11px] text-muted-foreground">
        <div>
          <FilePenLine className="mx-auto mb-2 h-5 w-5 opacity-40" />
          还没有 Edit 修改。
          <br />
          <span className="text-[10px]">
            模型用 <code className="rounded bg-muted px-1">Edit</code> 修改文件后会出现在这里。
          </span>
        </div>
      </div>
    );
  }

  const activeEntries = editSnapshots.filter((e) => !e.reverted);
  const revertedEntries = editSnapshots.filter((e) => e.reverted);

  return (
    <div className="text-[12px]">
      {activeEntries.length > 0 && (
        <EditSection
          entries={activeEntries}
          reverting={reverting}
          onRevert={handleRevert}
        />
      )}
      {revertedEntries.length > 0 && (
        <EditSection
          title="已回退"
          entries={revertedEntries}
          reverting={reverting}
          onRevert={undefined}
          dimmed
        />
      )}
    </div>
  );
}

function EditSection({
  title,
  entries,
  reverting,
  onRevert,
  dimmed,
}: {
  title?: string;
  entries: EditEntry[];
  reverting: Set<string>;
  onRevert?: (snapshotId: string) => void;
  dimmed?: boolean;
}) {
  // 按文件路径分组
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const groups = new Map<string, EditEntry[]>();
  for (const entry of entries) {
    const existing = groups.get(entry.real_path) ?? [];
    existing.push(entry);
    groups.set(entry.real_path, existing);
  }

  return (
    <div className="space-y-2 px-2 py-2">
      {title && (
        <div className="px-1 text-[10px] uppercase tracking-wide text-muted-foreground">
          {title}
        </div>
      )}
      {[...groups.entries()].map(([filePath, fileEntries]) => {
        const groupKey = filePath;
        const expanded = expandedGroups.has(groupKey);
        const latest = fileEntries[0];
        return (
          <div
            key={groupKey}
            className={cn(
              "overflow-hidden rounded-md border border-border/60 bg-background transition-all",
              // 默认：与大卡片同款的模糊散开阴影；hover 才切成 neobrutalism 错位
              "shadow-[-3px_2px_8px_-2px_rgba(0,0,0,0.10),-1px_1px_2px_-1px_rgba(0,0,0,0.06)]",
              "dark:shadow-[-3px_2px_8px_-2px_rgba(0,0,0,0.45),-1px_1px_2px_-1px_rgba(0,0,0,0.3)]",
              "hover:shadow-[-6px_8px_4px_1px_rgba(0,0,0,0.50),-18px_21px_14px_-1px_rgba(0,0,0,0.16)] dark:hover:shadow-[-6px_8px_4px_1px_rgba(0,0,0,0.75),-18px_21px_14px_-1px_rgba(0,0,0,0.40)]",
              "hover:translate-x-px hover:-translate-y-px hover:border-border",
              dimmed && "opacity-60",
            )}
          >
            <button
              type="button"
              onClick={() =>
                setExpandedGroups((prev) => {
                  const next = new Set(prev);
                  if (next.has(groupKey)) next.delete(groupKey);
                  else next.add(groupKey);
                  return next;
                })
              }
              className="flex w-full items-center gap-1 px-2 py-1.5 text-left text-[11px] transition-colors hover:bg-accent/30"
            >
              {fileEntries.length > 1 ? (
                expanded ? (
                  <ChevronDown className="h-3 w-3 shrink-0 text-muted-foreground" />
                ) : (
                  <ChevronRight className="h-3 w-3 shrink-0 text-muted-foreground" />
                )
              ) : (
                <span className="w-3 shrink-0" />
              )}
              <ActionIcon action={latest.action} />
              <span className="truncate flex-1 font-mono text-[10px]">
                {pathLeaf(latest.real_path)}
              </span>
              <span className="shrink-0 text-[9px] text-muted-foreground">
                {formatTime(latest.ts_ms)}
              </span>
            </button>
            {expanded && (
              <div className="border-t border-border/40 bg-muted/20 py-1">
                {fileEntries.map((entry, idx) => {
                  // 反向 patch 的天然限制：回退非最新一次 Edit 时，patch 的上下文
                  // 行可能已被后续 Edit 改动，git apply 会拒绝。让用户提前知道。
                  const isLatest = idx === fileEntries.length - 1;
                  const revertHint = isLatest
                    ? "撤销本次修改"
                    : "撤销此次修改；若后续 Edit 改动了同一段，可能因冲突失败";
                  return (
                  <div
                    key={entry.snapshot_id}
                    className={cn(
                      "flex items-center gap-1 px-3 py-1 text-[10px] transition-colors",
                      !dimmed && "hover:bg-accent/40 cursor-pointer",
                      dimmed && "opacity-40"
                    )}
                    onClick={() => focusToolCall(entry.call_id)}
                    title="跳到对话里的这次修改"
                    role="button"
                  >
                    <span className="flex-1 truncate text-muted-foreground">
                      {entry.action === "create" ? "创建" : entry.action === "overwrite" ? "覆写" : "修改"}
                      {" · "}
                      {entry.before_bytes === entry.after_bytes
                        ? `${entry.before_bytes}B`
                        : `${entry.before_bytes}→${entry.after_bytes}B`}
                    </span>
                    {onRevert && !entry.reverted && (
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          onRevert(entry.snapshot_id);
                        }}
                        disabled={reverting.has(entry.snapshot_id)}
                        title={revertHint}
                        className="rounded px-1 text-[9px] text-amber-600 hover:bg-amber-500/10 disabled:opacity-50"
                      >
                        <Rewind className="h-3 w-3" />
                      </button>
                    )}
                  </div>
                );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function ActionIcon({ action }: { action: EditEntry["action"] }) {
  const cls = "h-3 w-3 shrink-0";
  if (action === "create") return <Plus className={cn(cls, "text-green-500")} />;
  if (action === "overwrite")
    return <FilePenLine className={cn(cls, "text-amber-500")} />;
  return <FilePenLine className={cn(cls, "text-sky-500")} />;
}

function pathLeaf(filePath: string): string {
  const parts = filePath.replace(/\\/g, "/").split("/");
  return parts[parts.length - 1] || filePath;
}

import { Component, type ErrorInfo, type ReactNode } from "react";
import { Toaster, toast } from "sonner";

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
}

/**
 * 全局 React ErrorBoundary：捕获子树 render/commit 阶段的未处理异常，
 * 用 toast 弹出错误信息，同时尝试恢复渲染（不白屏）。
 *
 * 配合 App 里的 window error/unhandledrejection 监听，覆盖事件回调和异步代码中的异常。
 */
export class ErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false };

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    const message = error?.message || String(error);
    const component = info.componentStack?.split("\n")[1]?.trim() ?? "";
    console.error("[ErrorBoundary]", error, info);
    toast.error(`渲染错误: ${message}`, {
      description: component || undefined,
      duration: 12000,
    });
    // 下一帧尝试恢复——大部分瞬时渲染错误在 state 变化后可自愈
    setTimeout(() => this.setState({ hasError: false }), 0);
  }

  render() {
    if (this.state.hasError) {
      // 崩溃时渲染独立 Toaster 保证 toast 可见；
      // 同时仍渲染 children——setState(false) 后下一帧重试
      return (
        <>
          {this.props.children}
          <Toaster position="top-center" richColors closeButton toastOptions={{ className: "text-sm" }} />
        </>
      );
    }
    return this.props.children;
  }
}

import { useState } from "react";
import { toast } from "sonner";
import { Check, Copy, Loader2 } from "lucide-react";
import { Dialog } from "./ui/dialog";
import { Button } from "./ui/button";
import { api, type ClaudeResumeResult } from "@/desktop/bridge/tauri";

interface ExportClaudeDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  sessionId: string;
}

/**
 * 把当前对话导出成一个 Claude 会话，给出可直接粘进终端恢复的命令。
 *
 * 思维链开关：带上时上下文更完整，但 Claude 那边对历史思维链有签名校验，
 * 续聊的第一条可能被拒——默认关掉，需要再开。
 */
export function ExportClaudeDialog({
  open,
  onOpenChange,
  sessionId,
}: ExportClaudeDialogProps) {
  const [includeThinking, setIncludeThinking] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [result, setResult] = useState<ClaudeResumeResult | null>(null);
  const [copied, setCopied] = useState(false);

  async function handleExport() {
    setExporting(true);
    try {
      const r = await api.exportSessionToClaude(sessionId, includeThinking);
      setResult(r);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err));
    } finally {
      setExporting(false);
    }
  }

  async function handleCopy() {
    if (!result) return;
    await navigator.clipboard.writeText(result.resume_command);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  }

  // 关掉时重置，下次打开是干净状态。
  function handleOpenChange(v: boolean) {
    if (!v) {
      setResult(null);
      setCopied(false);
    }
    onOpenChange(v);
  }

  return (
    <Dialog
      open={open}
      onOpenChange={handleOpenChange}
      title="导出到 Claude"
      description="把这段对话变成一个 Claude 会话，在终端里继续聊，上下文照旧。"
      size="md"
    >
      {result ? (
        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">
            导出好了。复制下面这行，粘到终端回车即可继续这段对话：
          </p>
          <div className="flex items-center gap-2 rounded-lg border border-border bg-muted/40 px-3 py-2">
            <code className="flex-1 select-text font-mono text-xs break-all">
              {result.resume_command}
            </code>
            <Button size="sm" variant="ghost" onClick={handleCopy}>
              {copied ? (
                <Check className="h-4 w-4 text-green-500" />
              ) : (
                <Copy className="h-4 w-4" />
              )}
            </Button>
          </div>
        </div>
      ) : (
        <label className="flex items-start gap-3 cursor-pointer select-none">
          <input
            type="checkbox"
            checked={includeThinking}
            onChange={(e) => setIncludeThinking(e.target.checked)}
            className="mt-0.5 h-4 w-4 accent-primary"
          />
          <span className="text-sm">
            连思维链一起带过去
            <span className="block text-xs text-muted-foreground mt-0.5">
              上下文更全，但终端里续聊的第一条可能报错；不确定就别勾。
            </span>
          </span>
        </label>
      )}

      <div className="mt-5 flex justify-end gap-2">
        {result ? (
          <Button variant="ghost" onClick={() => handleOpenChange(false)}>
            完成
          </Button>
        ) : (
          <>
            <Button variant="ghost" onClick={() => handleOpenChange(false)}>
              取消
            </Button>
            <Button onClick={handleExport} disabled={exporting}>
              {exporting && <Loader2 className="mr-1.5 h-4 w-4 animate-spin" />}
              导出
            </Button>
          </>
        )}
      </div>
    </Dialog>
  );
}

import type { CatalogEntry } from "@/desktop/ui/types";
import { ModelCard } from "./ModelCard";

interface FamilyGroupProps {
  /** family 名称（如 "claude-sonnet"） */
  family: string;
  /** 该 family 下的所有模型 */
  models: ModelItem[];
  /** 当前选中的模型列表 */
  selectedModels: string[];
  /** 切换模型选中状态 */
  onToggleModel: (modelId: string) => void;
  /** models.dev catalog（用于查找元数据） */
  catalog: Record<string, CatalogEntry> | null;
  /** 用户手动 override 的 context/output */
  overrides: Record<string, { context?: string; output?: string }>;
  /** 更新某个模型的 override */
  onUpdateOverride: (modelId: string, patch: { context?: string; output?: string }) => void;
}

export interface ModelItem {
  id: string;
  owned_by?: string | null;
}

/**
 * Family 分组：按 family 展示一组模型（单列列表，限定高度内滚动）。
 */
export function FamilyGroup({
  family,
  models,
  selectedModels,
  onToggleModel,
  catalog,
  overrides,
  onUpdateOverride,
}: FamilyGroupProps) {
  // 构建不带前缀的 catalog 映射（如 "anthropic/claude-sonnet-4-5" → "claude-sonnet-4-5"）
  const catalogLookup = (modelId: string): CatalogEntry | undefined => {
    if (!catalog) return undefined;
    // 1. 精确匹配
    if (catalog[modelId]) return catalog[modelId];
    // 2. 尝试带前缀的变体
    for (const [key, value] of Object.entries(catalog)) {
      if (key.endsWith("/" + modelId) || key === modelId) return value;
    }
    return undefined;
  };

  return (
    <div className="space-y-1.5">
      {/* Family 标题 */}
      <div className="flex items-center gap-2 px-1">
        <div className="text-xs font-medium text-muted-foreground">{family}</div>
        <div className="text-[10px] text-muted-foreground/60">
          {models.length}
        </div>
      </div>

      {/* 模型卡片单列列表 */}
      <div className="space-y-1">
        {models.map((model) => (
          <ModelCard
            key={model.id}
            modelId={model.id}
            entry={catalogLookup(model.id)}
            override={overrides[model.id]}
            selected={selectedModels.includes(model.id)}
            onClick={() => onToggleModel(model.id)}
            onContextChange={(value) =>
              onUpdateOverride(model.id, { context: value })
            }
            onOutputChange={(value) =>
              onUpdateOverride(model.id, { output: value })
            }
          />
        ))}
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import { X, ChevronUp, ChevronDown, Regex, CaseSensitive } from "lucide-react";
import { cn } from "@/desktop/ui/lib/utils";

export interface FindState {
  query: string;
  regex: boolean;
  caseSensitive: boolean;
  current: number; // 1-based, 0 = 无命中
  total: number;
}

interface Props {
  open: boolean;
  onClose: () => void;
  state: FindState;
  onChange: (patch: Partial<FindState>) => void;
  onPrev: () => void;
  onNext: () => void;
}

export function FindBar({ open, onClose, state, onChange, onPrev, onNext }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) {
      const id = window.setTimeout(() => inputRef.current?.select(), 10);
      return () => window.clearTimeout(id);
    }
  }, [open]);

  if (!open) return null;

  const invalid = state.query.length > 0 && state.total === 0;

  return (
    <div className="absolute top-3 right-4 z-[55] flex items-center gap-1 rounded-lg border border-border bg-background shadow-lg px-2 py-1.5 animate-slide-up">
      <input
        ref={inputRef}
        value={state.query}
        onChange={(e) => onChange({ query: e.target.value })}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            e.preventDefault();
            if (e.shiftKey) onPrev();
            else onNext();
          } else if (e.key === "Escape") {
            e.preventDefault();
            onClose();
          }
        }}
        spellCheck={false}
        autoCorrect="off"
        placeholder="在当前对话中查找"
        className={cn(
          "h-7 w-56 rounded-md border border-input bg-background px-2 text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
          invalid && "border-destructive/60"
        )}
      />
      <span className="text-[11px] text-muted-foreground w-14 text-center tabular-nums">
        {state.total === 0
          ? state.query
            ? "0 / 0"
            : "—"
          : `${state.current} / ${state.total}`}
      </span>
      <div className="h-4 w-px bg-border mx-0.5" />
      <button
        onClick={() => onChange({ caseSensitive: !state.caseSensitive })}
        className={cn(
          "h-7 w-7 inline-flex items-center justify-center rounded-md text-muted-foreground hover:bg-accent",
          state.caseSensitive && "bg-primary/15 text-primary"
        )}
        title="区分大小写 (Alt+C)"
      >
        <CaseSensitive className="w-4 h-4" />
      </button>
      <button
        onClick={() => onChange({ regex: !state.regex })}
        className={cn(
          "h-7 w-7 inline-flex items-center justify-center rounded-md text-muted-foreground hover:bg-accent",
          state.regex && "bg-primary/15 text-primary"
        )}
        title="正则表达式 (Alt+R)"
      >
        <Regex className="w-4 h-4" />
      </button>
      <div className="h-4 w-px bg-border mx-0.5" />
      <button
        onClick={onPrev}
        disabled={state.total === 0}
        className="h-7 w-7 inline-flex items-center justify-center rounded-md text-muted-foreground hover:bg-accent disabled:opacity-40"
        title="上一个 (Shift+Enter)"
      >
        <ChevronUp className="w-4 h-4" />
      </button>
      <button
        onClick={onNext}
        disabled={state.total === 0}
        className="h-7 w-7 inline-flex items-center justify-center rounded-md text-muted-foreground hover:bg-accent disabled:opacity-40"
        title="下一个 (Enter)"
      >
        <ChevronDown className="w-4 h-4" />
      </button>
      <button
        onClick={onClose}
        className="h-7 w-7 inline-flex items-center justify-center rounded-md text-muted-foreground hover:bg-accent"
        title="关闭 (Esc)"
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

/**
 * 在给定文本里寻找所有匹配的字节区间
 */
export function findMatches(
  text: string,
  query: string,
  regex: boolean,
  caseSensitive: boolean
): Array<[number, number]> {
  if (!query) return [];
  if (regex) {
    let re: RegExp;
    try {
      re = new RegExp(query, caseSensitive ? "g" : "gi");
    } catch {
      return [];
    }
    const out: Array<[number, number]> = [];
    let m: RegExpExecArray | null;
    while ((m = re.exec(text))) {
      if (m[0].length === 0) {
        re.lastIndex++;
        continue;
      }
      out.push([m.index, m.index + m[0].length]);
    }
    return out;
  }
  const hay = caseSensitive ? text : text.toLowerCase();
  const needle = caseSensitive ? query : query.toLowerCase();
  const out: Array<[number, number]> = [];
  let i = 0;
  while (i <= hay.length - needle.length) {
    const idx = hay.indexOf(needle, i);
    if (idx < 0) break;
    out.push([idx, idx + needle.length]);
    i = idx + needle.length;
  }
  return out;
}

/**
 * 把文本 + 匹配区间渲染成带高亮的 span
 */
export function highlight(
  text: string,
  matches: Array<[number, number]>,
  activeIdx: number | null,
  keyPrefix: string
) {
  if (matches.length === 0) return text;
  const out: React.ReactNode[] = [];
  let cursor = 0;
  matches.forEach(([s, e], i) => {
    if (s > cursor) out.push(text.slice(cursor, s));
    const active = i === activeIdx;
    out.push(
      <mark
        key={`${keyPrefix}-${i}`}
        data-find-match
        data-active={active ? "true" : undefined}
        className={cn(
          "rounded-sm px-0.5",
          active
            ? "bg-amber-400 text-black"
            : "bg-yellow-200 text-black dark:bg-yellow-300/90"
        )}
      >
        {text.slice(s, e)}
      </mark>
    );
    cursor = e;
  });
  if (cursor < text.length) out.push(text.slice(cursor));
  return out;
}

/**
 * 将消息列表展平，返回每条消息的匹配数量（用于计算全局 current/total）
 */
export function useMessageMatches(
  contents: string[],
  query: string,
  regex: boolean,
  caseSensitive: boolean
) {
  return useMemo(() => {
    const per = contents.map((c) =>
      findMatches(c, query, regex, caseSensitive)
    );
    const total = per.reduce((s, a) => s + a.length, 0);
    return { per, total };
  }, [contents, query, regex, caseSensitive]);
}

export function useFindController(totalMatches: number) {
  const [active, setActive] = useState(0);
  useEffect(() => {
    if (active >= totalMatches) setActive(0);
  }, [totalMatches, active]);
  const next = () =>
    setActive((i) => (totalMatches === 0 ? 0 : (i + 1) % totalMatches));
  const prev = () =>
    setActive((i) =>
      totalMatches === 0 ? 0 : (i - 1 + totalMatches) % totalMatches
    );
  return { active, setActive, next, prev };
}

import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/desktop/ui/components/ui/button";
import { Label, Textarea } from "@/desktop/ui/components/ui/input";
import { api } from "@/desktop/bridge/tauri";

/**
 * Hooks 设置面板（架构 §4.8）。
 *
 * 用 JSON 编辑器直接展示和编辑 `~/.hebbian/hooks.json`。
 * hooks 配置结构（事件 → 规则数组）天然适合 JSON 编辑：
 *
 * ```json
 * {
 *   "PreToolUse": [
 *     { "matcher": { "tool": "Bash" }, "command": "python guard.py" }
 *   ],
 *   "Stop": [
 *     { "command": "cargo check 2>&1 | tail -50", "mode": "sync", "timeout_secs": 60 }
 *   ]
 * }
 * ```
 */
export function HooksPane() {
  const [raw, setRaw] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const text = await api.getHooksRaw();
      // 格式化展示
      try {
        const parsed = JSON.parse(text);
        setRaw(JSON.stringify(parsed, null, 2));
      } catch {
        setRaw(text);
      }
      setDirty(false);
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    reload();
  }, [reload]);

  function handleChange(value: string) {
    setRaw(value);
    setDirty(true);
  }

  async function handleSave() {
    // 前端先校验 JSON
    try {
      JSON.parse(raw);
    } catch (e: any) {
      toast.error(`JSON 格式错误：${e.message}`);
      return;
    }
    setSaving(true);
    try {
      await api.saveHooksRaw(raw);
      toast.success("Hooks 已保存");
      setDirty(false);
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-4">
      <div>
        <Label>全局 Hooks 配置</Label>
        <p className="text-xs text-muted-foreground mt-1">
          编辑 <code className="text-[11px]">~/.hebbian/hooks.json</code>。
          每个事件点位（如 PreToolUse、Stop）对应一组规则。
          新 session 启动时自动加载。
        </p>
      </div>

      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <span className="text-xs text-muted-foreground">
            {loading ? "加载中…" : dirty ? "有未保存的修改" : "已同步"}
          </span>
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={reload} disabled={loading}>
              刷新
            </Button>
            <Button size="sm" onClick={handleSave} disabled={saving || !dirty}>
              {saving ? "保存中…" : "保存"}
            </Button>
          </div>
        </div>
        <Textarea
          value={raw}
          onChange={(e) => handleChange(e.target.value)}
          rows={20}
          className="font-mono text-xs leading-relaxed"
          placeholder='{\n  "Stop": [\n    { "command": "cargo check 2>&1 | tail -50", "mode": "sync", "timeout_secs": 60 }\n  ]\n}'
          spellCheck={false}
        />
      </div>

      <div className="space-y-2 text-xs text-muted-foreground">
        <p className="font-medium text-foreground">可用事件点位</p>
        <div className="grid grid-cols-2 gap-x-4 gap-y-1">
          <span><code>SessionStart</code> — 会话开始</span>
          <span><code>SessionEnd</code> — 会话结束</span>
          <span><code>UserPromptSubmit</code> — 用户提交消息</span>
          <span><code>PreToolUse</code> — 工具调用前</span>
          <span><code>PostToolUse</code> — 工具调用后</span>
          <span><code>PostToolUseFailure</code> — 工具调用失败</span>
          <span><code>PermissionRequest</code> — 权限请求</span>
          <span><code>PreCompact</code> — 压缩前</span>
          <span><code>PostCompact</code> — 压缩后</span>
          <span><code>Notification</code> — 通知</span>
          <span><code>Stop</code> — 模型回复结束</span>
        </div>
        <p className="mt-2 font-medium text-foreground">规则字段</p>
        <div className="space-y-0.5">
          <span><code>command</code> — 要执行的 shell 命令</span><br/>
          <span><code>matcher</code> — 可选，<code>{`{ "tool": "Bash" }`}</code> 按工具名过滤</span><br/>
          <span><code>mode</code> — <code>"sync"</code>（默认）或 <code>"async"</code>（fire-and-forget）</span><br/>
          <span><code>timeout_secs</code> — 超时秒数（默认 5，Stop 建议 30-60）</span>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { cn } from "@/desktop/ui/lib/utils";

interface Props {
  hint: ReactNode;
  side?: "top" | "bottom";
  align?: "start" | "center" | "end";
  className?: string;
  keepOpenDelayMs?: number;
  children: ReactNode;
}

/**
 * 鼠标移入即显示的提示气泡，替代 HTML title 的浏览器原生 tooltip
 * （原生 title 有 1~2 秒延迟且无法配置，体感"等很久才出来"）。
 *
 * 浮层 portal 到 body 顶层 + position fixed：避免被任何祖先 overflow:hidden
 * 裁掉（典型场景：工具调用卡片 ToolCallTimeline 的 rounded 卡片需要 overflow-hidden
 * 让圆角生效，但 hint 又必须能溢出卡片边界）。
 *
 * hint 节点可选中文本，鼠标移出后延迟关闭，方便复制长路径。
 */
export function HoverHint({
  hint,
  side = "top",
  align = "center",
  className,
  keepOpenDelayMs = 50,
  children,
}: Props) {
  const [open, setOpen] = useState(false);
  const [rect, setRect] = useState<DOMRect | null>(null);
  const anchorRef = useRef<HTMLSpanElement>(null);
  const closeTimerRef = useRef<number | null>(null);

  const updateRect = useCallback(() => {
    const anchor = anchorRef.current;
    if (!anchor) return;
    const r = anchor.getBoundingClientRect();

    // 若 anchor 已经被某个滚动祖先 (overflow auto/scroll/hidden) 横向裁切到不可见，
    // 关掉 popup——否则 portal 出去的 popup 会"飘"到容器外的 sidebar 区域。
    let parent: HTMLElement | null = anchor.parentElement;
    while (parent && parent !== document.body) {
      const style = window.getComputedStyle(parent);
      const ox = style.overflowX;
      const oy = style.overflowY;
      const clips =
        ox === "auto" || ox === "scroll" || ox === "hidden" ||
        oy === "auto" || oy === "scroll" || oy === "hidden";
      if (clips) {
        const pr = parent.getBoundingClientRect();
        if (
          r.right <= pr.left ||
          r.left >= pr.right ||
          r.bottom <= pr.top ||
          r.top >= pr.bottom
        ) {
          setOpen(false);
          return;
        }
      }
      parent = parent.parentElement;
    }

    setRect(r);
  }, []);

  useEffect(() => {
    return () => {
      if (closeTimerRef.current != null) {
        window.clearTimeout(closeTimerRef.current);
      }
    };
  }, []);

  // 打开时锁定一次位置；滚动 / resize 期间跟随更新
  useLayoutEffect(() => {
    if (!open) return;
    updateRect();
    window.addEventListener("scroll", updateRect, true);
    window.addEventListener("resize", updateRect);
    return () => {
      window.removeEventListener("scroll", updateRect, true);
      window.removeEventListener("resize", updateRect);
    };
  }, [open, updateRect]);

  function openHint() {
    if (closeTimerRef.current != null) {
      window.clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
    setOpen(true);
  }

  function closeHint() {
    if (closeTimerRef.current != null) {
      window.clearTimeout(closeTimerRef.current);
    }
    closeTimerRef.current = window.setTimeout(() => {
      setOpen(false);
      closeTimerRef.current = null;
    }, keepOpenDelayMs);
  }

  if (hint == null || hint === "") return <>{children}</>;

  // fixed 定位坐标 + transform：side 控制上下，align 控制左右锚点对齐
  const top = rect ? (side === "top" ? rect.top - 4 : rect.bottom + 4) : 0;
  const left = rect
    ? align === "start"
      ? rect.left
      : align === "center"
        ? rect.left + rect.width / 2
        : rect.right
    : 0;
  const translateX =
    align === "start" ? "0" : align === "center" ? "-50%" : "-100%";
  const translateY = side === "top" ? "-100%" : "0";

  return (
    <>
      <span
        ref={anchorRef}
        className={cn("relative inline-flex", className)}
        onMouseEnter={openHint}
        onMouseLeave={closeHint}
      >
        {children}
      </span>
      {open && rect && createPortal(
        <span
          role="tooltip"
          style={{
            position: "fixed",
            top,
            left,
            transform: `translate(${translateX}, ${translateY})`,
          }}
          className="z-[100] px-2 py-1 rounded-md border border-border bg-card text-foreground text-[11px] leading-relaxed shadow-md whitespace-pre-wrap break-words max-w-[320px] w-max select-text pointer-events-auto"
          onMouseEnter={openHint}
          onMouseLeave={closeHint}
        >
          {hint}
        </span>,
        document.body,
      )}
    </>
  );
}

import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Download, Loader2, Search } from "lucide-react";
import { Dialog } from "./ui/dialog";
import { api, type ClaudeSessionInfo } from "@/desktop/bridge/tauri";
import { formatTime, pathLeaf } from "@/desktop/ui/lib/utils";

interface ImportClaudeDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  /** 导入成功后回调，传新建 session 的 id，由父去刷新列表 + 打开它。 */
  onImported: (sessionId: string) => void;
}

const NO_DIR = "（没有项目目录）";

/**
 * 从 Claude 导入一段对话。扫描列表按原项目目录分组，点一条即搬进来。
 */
export function ImportClaudeDialog({
  open,
  onOpenChange,
  onImported,
}: ImportClaudeDialogProps) {
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<ClaudeSessionInfo[]>([]);
  const [query, setQuery] = useState("");
  const [importingPath, setImportingPath] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    setQuery("");
    api
      .listClaudeSessions()
      .then(setItems)
      .catch((e) => toast.error(e instanceof Error ? e.message : String(e)))
      .finally(() => setLoading(false));
  }, [open]);

  // 过滤 + 按目录分组，组按组内最新时间倒序。
  const groups = useMemo(() => {
    const q = query.trim().toLowerCase();
    const filtered = q
      ? items.filter(
          (i) =>
            i.title.toLowerCase().includes(q) ||
            i.cwd.toLowerCase().includes(q)
        )
      : items;
    const map = new Map<string, ClaudeSessionInfo[]>();
    for (const it of filtered) {
      const key = it.cwd || NO_DIR;
      const list = map.get(key);
      if (list) list.push(it);
      else map.set(key, [it]);
    }
    const latest = (list: ClaudeSessionInfo[]) =>
      Math.max(...list.map((x) => x.modified_ms));
    return [...map.entries()].sort((a, b) => latest(b[1]) - latest(a[1]));
  }, [items, query]);

  async function handleImport(it: ClaudeSessionInfo) {
    setImportingPath(it.path);
    try {
      const session = await api.importClaudeSession(it.path);
      toast.success(`已导入「${session.title}」`);
      onOpenChange(false);
      onImported(session.id);
    } catch (e) {
      toast.error(e instanceof Error ? e.message : String(e));
    } finally {
      setImportingPath(null);
    }
  }

  return (
    <Dialog
      open={open}
      onOpenChange={onOpenChange}
      title="从 Claude 导入"
      description="选一段 Claude 里的对话搬进来，按项目分组。导入后可在这里接着聊。"
      size="lg"
    >
      <div className="relative mb-3">
        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="搜索标题或目录"
          className="w-full h-9 pl-8 pr-3 rounded-lg border border-border bg-background text-sm outline-none focus:border-primary/50"
        />
      </div>

      {loading ? (
        <div className="py-12 text-center text-sm text-muted-foreground">
          <Loader2 className="inline h-4 w-4 animate-spin mr-1.5" />
          扫描中…
        </div>
      ) : groups.length === 0 ? (
        <div className="py-12 text-center text-sm text-muted-foreground">
          没有可导入的会话
        </div>
      ) : (
        <div className="space-y-4 max-h-[55vh] overflow-y-auto pr-1">
          {groups.map(([cwd, list]) => (
            <div key={cwd}>
              <div
                className="text-xs font-medium text-muted-foreground mb-1.5 truncate"
                title={cwd}
              >
                {cwd === NO_DIR ? cwd : pathLeaf(cwd)}
                <span className="text-muted-foreground/50"> · {list.length}</span>
              </div>
              <div className="space-y-1">
                {list.map((it) => (
                  <button
                    key={it.path}
                    onClick={() => handleImport(it)}
                    disabled={importingPath !== null}
                    className="w-full text-left rounded-lg border border-border px-3 py-2 hover:bg-accent/50 disabled:opacity-50 flex items-center gap-2"
                  >
                    <div className="min-w-0 flex-1">
                      <div className="text-sm truncate">{it.title}</div>
                      <div className="text-[11px] text-muted-foreground">
                        {it.message_count} 条 · {formatTime(it.modified_ms)}
                      </div>
                    </div>
                    {importingPath === it.path ? (
                      <Loader2 className="h-4 w-4 animate-spin shrink-0" />
                    ) : (
                      <Download className="h-4 w-4 text-muted-foreground shrink-0" />
                    )}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </Dialog>
  );
}

import { useEffect, useState, type ReactNode } from "react";
import { ChevronUp } from "lucide-react";
import { cn } from "@/desktop/ui/lib/utils";

/**
 * 挂在白色输入框最底部的"展开更多设置"触发条。
 *
 * 一条 14px chevron 条，无底色——仅靠 chevron 朝向 + 颜色明暗暗示状态；
 * 展开/折叠状态由调用方持有，故意不持久化。
 */
export function DrawerToggle({
  open,
  onToggle,
  disabled,
}: {
  open: boolean;
  onToggle: () => void;
  disabled?: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onToggle}
      disabled={disabled}
      className={cn(
        // 5px 高的窄触发条——overflow-hidden 把 chevron 上下裁掉，只露中间一段细线
        "group/drawer flex h-[5px] w-full items-center justify-center overflow-hidden",
        "transition-colors",
        "disabled:opacity-40 disabled:pointer-events-none"
      )}
      aria-expanded={open}
      aria-label={open ? "收起更多设置" : "展开更多设置"}
      title={open ? "收起" : "更多设置"}
    >
      <ChevronUp
        className={cn(
          "h-3 w-3 text-muted-foreground/50 transition-[transform,color] duration-150",
          "group-hover/drawer:text-foreground",
          open ? "rotate-0" : "rotate-180"
        )}
      />
    </button>
  );
}

interface InputDrawerProps {
  open: boolean;
  left?: ReactNode;
  right?: ReactNode;
}

/**
 * 输入框下方的二级抽屉——独立 rounded-3xl 卡片，向上重叠 32px (-mt-8) 钻入白色卡片下沿，
 * 配合白色卡片 z-10 盖住抽屉上半圆角，视觉上从白色卡片下端"伸出"而不是漂浮分离。
 *
 * 入退场动画：
 * - open: true → mount + animate-slide-up（150ms）
 * - open: false → 标记 closing → animate-slide-down-out（160ms）→ onAnimationEnd 后真正 unmount
 * - 不用 grid-rows/max-height（那需要 overflow-hidden，会裁切 Reasoning / RunMode 的上拉 popup）
 *
 * 反色：容器加 `dark` class，里面的 design token 自动切到 dark 主题。
 */
export function InputDrawer({ open, left, right }: InputDrawerProps) {
  // mounted：组件在 DOM 中（即使 open=false 但退场动画未跑完时也保留）
  const [mounted, setMounted] = useState(open);

  useEffect(() => {
    if (open) setMounted(true);
    // open=false 时不立刻 unmount——等 onAnimationEnd 触发后才卸载（让退场动画跑完）
  }, [open]);

  function handleAnimationEnd() {
    if (!open) setMounted(false);
  }

  if (!mounted) return null;

  return (
    <div
      className={cn(
        // 与白色卡片左右对齐；向上重叠 24px (-mt-6 = rounded-3xl 半径)，让黑色矩形顶部对齐
        // 白色下圆角顶端 y=H-24。白色 z-10 在上覆盖 [H-24, H] 范围内**白色圆角内**的部分，
        // 圆角**外侧凹陷三角**白色没填充——黑色透过显示，从而"填实"白色下圆角的凹陷。
        "dark -mt-6 relative",
        open ? "animate-slide-up" : "animate-slide-down-out"
      )}
      onAnimationEnd={handleAnimationEnd}
      aria-hidden={!open}
    >
      <div
        className={cn(
          "flex flex-wrap items-center justify-between gap-2",
          // 上沿直角（rounded-t-none），下沿圆角——配合 -mt-6 让黑色填实白色下圆角凹陷
          "rounded-t-none rounded-b-3xl bg-background text-foreground",
          // pt-8 补回 -mt-6 钻入区域 (24px) + 8px 视觉间距
          "px-3 pt-8 pb-2"
        )}
      >
        <div className="flex flex-wrap items-center gap-1.5">{left}</div>
        <div className="flex items-center gap-1.5">{right}</div>
      </div>
    </div>
  );
}

import { CornerDownLeft, Trash2, X } from "lucide-react";
import { toast } from "sonner";
import { useStore } from "@/desktop/ui/store/useStore";
import { cn } from "@/desktop/ui/lib/utils";

/**
 * 运行时输入队列面板：streaming 期间用户排队的下一条 / 下几条 user message。
 *
 * 队列语义（架构.md §4.2.3）：
 * - 默认 Enter 入队 → 等本 Run 跑完后 drainNext 顺次作为新 Run 发出。
 * - Shift+Enter / 行内 ↩「引导」按钮 → 走 PendingInputs，agent_loop
 *   在下一次 ModelStep 之前 drain，等价于"当前 model_call+tool_call
 *   完成后立即插队"，不开新 Run。
 *
 * 行内三按钮：
 * - ↩ 引导：把这条注入 PendingInputs（任意位置可点）
 * - 🗑 删除：从队列移除
 * - ✕ 放回输入框：移除并把内容追加回 ChatInput 草稿
 */
export function InputQueuePanel() {
  const queue = useStore((s) => s.currentInputQueue);
  const removeQueuedInput = useStore((s) => s.removeQueuedInput);
  const flushQueuedItem = useStore((s) => s.flushQueuedItem);
  const returnQueuedToComposer = useStore((s) => s.returnQueuedToComposer);

  if (queue.length === 0) return null;

  async function flush(id: string) {
    try {
      await flushQueuedItem(id);
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    }
  }

  return (
    <div className="px-4 pb-2">
      <div className="max-w-3xl mx-auto pr-[50px]">
        <ul className="flex flex-col gap-1">
          {queue.map((item, idx) => {
            const isHead = idx === 0;
            const preview =
              item.content.trim() ||
              (item.attachments.length > 0
                ? `（${item.attachments.length} 个附件）`
                : "（空）");
            return (
              <li
                key={item.id}
                className={cn(
                  "flex items-center gap-2 rounded-md border px-2 py-1.5 text-sm",
                  isHead
                    ? "border-primary/40 bg-primary/5"
                    : "border-border bg-muted/40"
                )}
              >
                <span
                  className={cn(
                    "shrink-0 inline-flex items-center justify-center w-5 h-5 rounded-full text-[10px] font-mono",
                    isHead
                      ? "bg-primary text-primary-foreground"
                      : "bg-muted text-muted-foreground"
                  )}
                  title={isHead ? "下一个发送" : `第 ${idx + 1} 条`}
                >
                  {idx + 1}
                </span>
                <span
                  className="flex-1 min-w-0 truncate text-foreground/90"
                  title={item.content}
                >
                  {preview}
                </span>
                {item.attachments.length > 0 && (
                  <span className="shrink-0 text-[10px] text-muted-foreground">
                    +{item.attachments.length} 附件
                  </span>
                )}
                <button
                  type="button"
                  onClick={() => flush(item.id)}
                  className="shrink-0 h-6 w-6 rounded inline-flex items-center justify-center text-primary hover:bg-primary/15 transition"
                  title="引导：当前模型调用完成后立即插队"
                  aria-label="引导"
                >
                  <CornerDownLeft className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  onClick={() => removeQueuedInput(item.id)}
                  className="shrink-0 h-6 w-6 rounded inline-flex items-center justify-center text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  title="删除"
                  aria-label="删除"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  onClick={() => returnQueuedToComposer(item.id)}
                  className="shrink-0 h-6 w-6 rounded inline-flex items-center justify-center text-muted-foreground hover:bg-muted hover:text-foreground"
                  title="放回输入框"
                  aria-label="放回输入框"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

