/**
 * Edit / Write 工具卡片的差异视图（架构 §4.13.9）。
 *
 * 数据源策略：
 * - **默认（非放大）**：永远只渲 args 的 old_string / new_string，不读 worktree——
 *   零网络等待，每次 ToolCallDelta 立刻刷新画面。
 * - **放大（GitHub review 风格）**：若 `editSnapshots` 里能按 `call.id` 找到 EditEntry，
 *   异步拉 `api.diffEdit` 取完整 before/after（含未改动上下文行），否则仍渲局部 args。
 *
 * 布局（inline / split）和"是否放大"两个状态独立——切换 inline↔split 不会关掉放大框。
 */
function EditDiffDetail({ call }: { call: ToolCallItem }) {
  const sessionId = useStore((s) => s.currentSession?.id ?? null);
  const workdir = useStore((s) => s.currentSession?.workdir ?? null);
  const editSnapshots = useStore(
    (s) => (sessionId ? s.sessionEditSnapshots[sessionId] : undefined) ?? EMPTY_EDIT_ENTRIES,
  );
  const [viewMode, setViewMode] = useState<DiffMode>("split");
  const [expanded, setExpanded] = useState(false);
  const [fullPayload, setFullPayload] = useState<{
    before: string;
    after: string;
    action: string;
    file_path: string;
  } | null>(null);
  const [fullError, setFullError] = useState<string | null>(null);

  const snapshot = call.id
    ? editSnapshots.find((e) => e.call_id === call.id)
    : null;

  // 仅在「放大且有 snapshot」时才拉服务端权威完整文件——非放大永不发请求。
  useEffect(() => {
    if (!expanded || !sessionId || !snapshot) {
      return;
    }
    let cancelled = false;
    setFullError(null);
    api
      .diffEdit(sessionId, snapshot.snapshot_id)
      .then((p) => {
        if (cancelled) return;
        setFullPayload({
          before: p.before_text,
          after: p.after_text,
          action: p.action,
          file_path: p.file_path,
        });
      })
      .catch((e) => {
        if (cancelled) return;
        setFullError(e?.message ?? String(e));
      });
    return () => {
      cancelled = true;
    };
  }, [expanded, sessionId, snapshot?.snapshot_id]);

  const partial = parsePartialEditArgs(call.argumentsText);
  const argSides = diffSidesFromArgs(call.name, partial);
  const action = snapshot?.action ?? inferDiffAction(call.name, partial);
  const actionLabel =
    action === "create" ? "创建文件" : action === "overwrite" ? "覆盖文件" : "修改文件";

  // 数据源选择：放大态优先用完整 payload；非放大态/未加载完成都用 args 局部
  const useFull = expanded && !!fullPayload && !!snapshot;
  const beforeText = useFull ? fullPayload!.before : argSides.beforeText;
  const afterText = useFull ? fullPayload!.after : argSides.afterText;
  const filePath = (useFull ? fullPayload!.file_path : partial.file_path) ?? "";

  // args 局部 diff 渲染时（流式 / 非放大 detail），读盘原文件给出 old_string
  // 真实起始行号；放大态 fullPayload 已是完整文件，行号天然正确。
  const isCreateAction = action === "create" || call.name === "Write";
  const enableBaseLookup = !useFull && !isCreateAction && !!partial.old_string;
  const originalText = useOriginalFileText(
    partial.file_path,
    workdir,
    enableBaseLookup,
  );
  const baseLine = enableBaseLookup && originalText
    ? lineOfOldString(originalText, partial.old_string ?? "")
    : 1;

  const streamingFlag = call.status === "streaming";
  const badge = (() => {
    if (call.status === "streaming") return "实时预览";
    if (expanded && snapshot && !fullPayload && !fullError) return "加载完整文件…";
    if (expanded && fullError) return "完整文件加载失败";
    if (expanded && useFull) return "完整文件";
    return undefined;
  })();

  const cycleMode = () => setViewMode((prev) => (prev === "split" ? "inline" : "split"));
  const toggleExpanded = () => setExpanded((e) => !e);

  // Esc 在放大态退出而不是关掉父展开
  useEffect(() => {
    if (!expanded) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        setExpanded(false);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [expanded]);

  if (expanded) {
    return (
      <FullscreenPortal>
        <div
          className="pointer-events-auto absolute inset-0 bg-foreground/30"
          onClick={() => setExpanded(false)}
        />
        <div
          className="pointer-events-auto absolute inset-3 flex flex-col overflow-hidden border border-border bg-background shadow-2xl"
          onClick={(e) => e.stopPropagation()}
        >
          <DiffViewer
            beforeText={beforeText}
            afterText={afterText}
            filePath={filePath}
            actionLabel={actionLabel}
            badge={badge}
            mode={viewMode}
            onCycleMode={cycleMode}
            expanded={expanded}
            onToggleExpanded={toggleExpanded}
            streaming={streamingFlag}
            onClose={() => setExpanded(false)}
            className="min-h-0 flex-1"
            collapseContext={useFull ? 3 : undefined}
            baseLineBefore={baseLine}
            baseLineAfter={baseLine}
          />
        </div>
      </FullscreenPortal>
    );
  }

  return (
    <DiffViewer
      beforeText={beforeText}
      afterText={afterText}
      filePath={filePath}
      actionLabel={actionLabel}
      badge={badge}
      mode={viewMode}
      onCycleMode={cycleMode}
      expanded={expanded}
      onToggleExpanded={toggleExpanded}
      streaming={streamingFlag}
      maxRows={14}
      baseLineBefore={baseLine}
      baseLineAfter={baseLine}
    />
  );
}

function ToolCallDetail({
  call,
  appSettings,
  sessionId,
}: {
  call: ToolCallItem;
  appSettings?: AppSettings;
  sessionId?: string;
}) {
  const name = call.name || "工具调用";
  const result = call.result || "等待返回…";
  const title = `${name} · ${callSummary(call)}`;

  // 提取 Bash 后台任务的 task_id（从 result 文本匹配，适用于真后台任务）
  const taskIdFromResult = result?.match(/\[([a-z0-9-]+)\]\s+(?:background|后台)/i)?.[1];

  // 对于前台 Bash，需要从注册表匹配 task_id
  const cmd = name === "Bash" || name === "PowerShell" ? argString(callArgs(call), "command") : "";
  const [matchedTaskId, setMatchedTaskId] = useState<string | null>(null);
  const [bgTaskState, setBgTaskState] = useState<string | null>(null);
  const [killedLocally, setKilledLocally] = useState(false);

  // 前台 Bash 运行中时，轮询 listBackgroundTasks 按 command 匹配 task_id
  useEffect(() => {
    // 仅对运行中的前台 Bash 生效（真后台从 result 已能提取 task_id）
    if (!sessionId || killedLocally || taskIdFromResult || name !== "Bash" || call.status === "done" || !cmd) {
      return;
    }

    let cancelled = false;
    const poll = async () => {
      try {
        const report = await api.listBackgroundTasks(sessionId);
        if (cancelled) return;
        // 按 command 精确匹配找前台运行中的任务
        const match = report.shells.find(
          (s) => s.command === cmd && s.state === "running" && !s.is_background
        );
        if (match) {
          setMatchedTaskId(match.task_id);
          setBgTaskState(match.state);
        }
      } catch {
        // 静默失败
      }
    };

    poll();
    const interval = setInterval(poll, 2000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [sessionId, killedLocally, taskIdFromResult, name, call.status, cmd]);

  // 真后台任务：轮询状态
  useEffect(() => {
    if (!taskIdFromResult || !sessionId || killedLocally) return;

    let cancelled = false;
    const poll = async () => {
      try {
        const output = await api.readBackgroundTaskOutput(sessionId, taskIdFromResult, 0);
        if (!cancelled) {
          setBgTaskState(output.state);
        }
      } catch {
        // 静默失败
      }
    };

    poll();
    const interval = setInterval(poll, 3000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [taskIdFromResult, sessionId, killedLocally]);

  // 最终用于 kill 的 task_id
  const effectiveTaskId = taskIdFromResult || matchedTaskId;

  // Kill 处理函数
  const handleKill = async () => {
    if (!effectiveTaskId || !sessionId) return;
    try {
      await api.killBackgroundTask(sessionId, effectiveTaskId);
      setKilledLocally(true);
      setBgTaskState("killed");
      toast.success(`已终止任务 ${effectiveTaskId}`);
    } catch (err) {
      toast.error(`终止失败: ${err instanceof Error ? err.message : String(err)}`);
    }
  };

  const isBgTaskRunning = bgTaskState === "running";
  const isRunning = call.status === "running";
  const canKill = effectiveTaskId && sessionId && !killedLocally && (isBgTaskRunning || (isRunning && !call.result));

  if (
    name === "Bash" ||
    name === "PowerShell" ||
    name === "BashOutput" ||
    name === "KillShell"
  ) {
    // status=running 且收到过 ToolOutputDelta：实时控制台展示，命令仍在跑。
    // status=done 后 result 已是聚合后的完整文本，覆盖掉 liveOutput。
    const live = call.liveOutput ?? "";
    let stream = isRunning ? (live || "等待输出…") : result;

    // 如果用户本地 kill 了，追加提示
    if (killedLocally) {
      stream = stream + "\n\n[用户已结束进程]";
    }

    const body = cmd
      ? `$ ${cmd}\n\n${stream}${isRunning && live && !killedLocally ? "\n▍" : ""}`
      : stream;

    return (
      <div className="relative">
        <ExpandButton title={title}>
          <ToolPre dark>{body}</ToolPre>
        </ExpandButton>
        <ToolPre dark>{body}</ToolPre>
        {/* Kill 按钮：仅当有 taskId 且任务正在运行时显示 */}
        {canKill && (
          <button
            onClick={handleKill}
            className="absolute top-2 right-2 flex items-center gap-1 rounded-md bg-red-500/10 px-2 py-1 text-xs text-red-500 hover:bg-red-500/20 transition-colors"
            title="终止任务"
          >
            <Square className="w-3 h-3 fill-current" />
            终止
          </button>
        )}
      </div>
    );
  }
  if (name === "Read") {
    return (
      <div className="relative">
        <ExpandButton title={title}>
          <ToolPre>{result}</ToolPre>
        </ExpandButton>
        <ToolPre>{result}</ToolPre>
      </div>
    );
  }
  if (name === "Skill") {
    return (
      <div className="relative">
        <ExpandButton title={title}>
          <ToolPre>{result}</ToolPre>
        </ExpandButton>
        <SkillHeader call={call} />
        <ToolPre>{result}</ToolPre>
      </div>
    );
  }
  if (name === "Write" || name === "Edit") {
    return <EditDiffDetail call={call} />;
  }
  if (name === "Grep" || name === "Glob") {
    const showSearchPath =
      name === "Grep" ? appSettings?.general.show_grep_search_path ?? true : true;
    return (
      <div className="relative">
        <ExpandButton title={title}>
          <SearchResults call={call} showPath={showSearchPath} />
        </ExpandButton>
        <SearchResults call={call} showPath={showSearchPath} />
      </div>
    );
  }
  if (name === "WebSearch") {
    return (
      <div className="relative">
        <ExpandButton title={title}>
          <SearchResults call={call} web />
        </ExpandButton>
        <SearchResults call={call} web />
      </div>
    );
  }
  if (name === "Fetch") {
    return (
      <div className="relative">
        <ExpandButton title={title}>
          <div className="space-y-2">
            <RenderedMarkdown text={result} />
            <ToolPre>{result}</ToolPre>
          </div>
        </ExpandButton>
        <FetchHeader call={call} />
        <div className="space-y-2 p-2">
          <RenderedMarkdown text={result} />
          <ToolPre>{result}</ToolPre>
        </div>
      </div>
    );
  }
  if (name === "Ask") {
    const args = callArgs(call);
    return (
      <div className="space-y-2 rounded-md border border-border bg-muted/30 p-2 text-[14px] text-muted-foreground">
        <div className="font-medium text-foreground">
          {argString(args, "question") || "用户提问"}
        </div>
        <ToolPre>{result}</ToolPre>
      </div>
    );
  }
  if (name === "ExitPlanMode") {
    return (
      <div className="relative">
        <ExpandButton title={title}>
          <RenderedMarkdown text={result} />
        </ExpandButton>
        <RenderedMarkdown text={result} />
      </div>
    );
  }
  if (name === "image_generation") {
    return (
      <div className="grid overflow-hidden bg-background md:grid-cols-[160px_minmax(0,1fr)]">
        <div className="min-h-32 bg-[radial-gradient(circle_at_35%_35%,rgba(22,119,255,0.28),transparent_28%),radial-gradient(circle_at_70%_65%,rgba(18,166,111,0.24),transparent_30%),linear-gradient(135deg,#f8fafc,#edf1f7)]" />
        <div className="space-y-2 p-2 text-[14px]">
          <div className="rounded-md border border-border bg-muted/40 px-2 py-1 text-muted-foreground">
            Hosted image_generation 由 provider 端执行。
          </div>
          <ToolPre>{result}</ToolPre>
        </div>
      </div>
    );
  }
  if (isTaskListTool(name)) {
    // 浮动 TaskPanel 显示最新状态，这里只回放本次调用提交的快照
    return (
      <div className="overflow-hidden bg-background">
        <TodoChecklist todos={parseTodos(call.argumentsText)} />
      </div>
    );
  }
  return <DefaultToolDetail call={call} />;
}

// ─── 嵌套子 agent 渲染（架构 §4.4.11.8 / P7）────────────────────────────────

function buildNestedRenderParts(parts: StreamingAssistantPart[]): AssistantRenderPart[] {
  const out: AssistantRenderPart[] = [];
  const pendingTools: ToolCallItem[] = [];
  parts.forEach((part, index) => {
    if (part.type === "text") {
      pushToolGroup(out, pendingTools);
      out.push({ type: "text", key: `nested-text-${index}`, text: part.text });
    } else if (part.type === "reasoning") {
      pushToolGroup(out, pendingTools);
      out.push({ type: "reasoning", key: `nested-reasoning-${index}`, text: part.text, streaming: false });
    } else {
      pendingTools.push(normalizeStreamingToolPart(part, index));
    }
  });
  pushToolGroup(out, pendingTools);
  return out;
}

function NestedTaskContent({
  nestedParts,
  appSettings,
  sessionId,
}: {
  nestedParts: StreamingAssistantPart[];
  appSettings?: AppSettings;
  sessionId?: string;
}) {
  const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set());
  const onToggle = useCallback((key: string) => {
    setExpandedKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }, []);

  const renderParts = buildNestedRenderParts(nestedParts);
  if (renderParts.length === 0) return null;

  return (
    <div className="ml-3 border-l-2 border-primary/20 pl-3 py-1 space-y-1">
      {renderParts.map((part) => {
        if (part.type === "text") {
          return (
            <p key={part.key} className="text-[13px] text-muted-foreground whitespace-pre-wrap">
              {part.text}
            </p>
          );
        }
        if (part.type === "reasoning") {
          return <ReasoningBlock key={part.key} text={part.text} streaming={part.streaming} />;
        }
        if (part.type === "tool_group") {
          return (
            <ToolCallTimeline
              key={part.key}
              calls={part.calls}
              expandedKeys={expandedKeys}
              onToggle={onToggle}
              appSettings={appSettings}
              sessionId={sessionId}
            />
          );
        }
        return null;
      })}
    </div>
  );
}

function ToolCallTimeline({
  calls,
  expandedKeys,
  onToggle,
  appSettings,
  sessionId,
}: {
  calls: ToolCallItem[];
  expandedKeys: Set<string>;
  onToggle: (key: string) => void;
  appSettings?: AppSettings;
  sessionId?: string;
}) {
  // Read 工具显示路径用：在 workdir 内显示相对路径、在 allowed_paths 之一内显示
  // `<basename>/...`、否则显示完整绝对路径。沿用当前 session 的实际 workdir / allowed_paths。
  const workdir = useStore((s) => s.currentSession?.workdir ?? null);
  const allowedPaths = useStore(
    (s) => s.currentSession?.allowed_paths ?? EMPTY_STR_ARR,
  );

  // 监听 sidebar / 任何外部组件派发的「跳到这个 call」事件：
  // 如果是本 timeline 持有的某条 call，就把它展开（已展开则不动）。
  // 滚动 + 闪烁由 focusToolCall util 自己负责，不需要在这里做。
  useEffect(() => {
    function handler(e: Event) {
      const callId = (e as CustomEvent<string>).detail;
      const match = calls.find((c) => c.id === callId);
      if (!match) return;
      if (match.status !== "done") return; // 未 done 默认展开，不需要触发
      if (expandedKeys.has(match.key)) return;
      onToggle(match.key);
    }
    window.addEventListener(FOCUS_TOOL_CALL_EVENT, handler);
    return () => window.removeEventListener(FOCUS_TOOL_CALL_EVENT, handler);
  }, [calls, expandedKeys, onToggle]);

  if (calls.length === 0) return null;
  return (
    <div className="relative mt-3 space-y-1 rounded-md bg-muted/70 py-1.5 pl-6 pr-2">
      {calls.map((call, index) => {
        // 未 done 时（streaming / running / failed）默认展开，让运行中的 tool
        // 边输出边看；done 后立即折叠，靠用户手动 toggle 展开看 detail。
        // 这跟 ReasoningBlock 的"流完立即折叠"是一致语义。
        //
        // 例外：Read / Grep / Glob / Ask 等「查询类」工具运行中默认不展开——
        // 输出量大但用户多半不关心实时进度（Read 输出文件全文滚屏、Grep 输出大堆
        // 匹配行），自动展开反而把消息流挤到底。继续靠用户手动 toggle。
        const READ_LIKE = new Set(["Read", "Grep", "Glob", "Ask"]);
        const autoExpand = !READ_LIKE.has(call.name ?? "");
        // `expandedKeys` 语义 = 「相对默认值的显式翻转」。默认展开的 running tool
        // 点击 → 命中 expandedKeys → 折叠成功；再点击 → 移出 expandedKeys → 回到默认。
        // 旧实现把它当「显式展开集合」用 OR 拼起来，在 autoExpand 路径下用户怎么点
        // active 都是 true（OR 的右分支恒真），折不下去——这就是 bug。
        const defaultExpanded = autoExpand && call.status !== "done";
        const active = expandedKeys.has(call.key) ? !defaultExpanded : defaultExpanded;
        // 左侧时间轴上的"状态点"取代原 ChevronRight：颜色编码状态——
        // done=绿 / running=蓝呼吸 / streaming(生成参数中)=灰 / 未来若新增 failed=红。
        // 点击仍触发展开/折叠；ToolCallStatus 目前只有 streaming|running|done 三态，
        // failed 分支预留，等后端加枚举时自然激活。
        const statusDot =
          call.status === "done"
            ? "bg-green-400"
            : call.status === "running"
              ? "animate-breathe bg-primary"
              : (call.status as string) === "failed" ||
                (call.status as string) === "error"
                ? "bg-rose-400"
                : "bg-muted-foreground/40";
        return (
          <div
            key={call.key}
            data-tool-call-id={call.id}
            // rounded-md：跟外层 tool_group 容器（line 1494 也是 rounded-md）保持一致——
            // focus-flash 闪烁时 box-shadow 沿这个 wrapper 自身的 border-radius 绘制，
            // 视觉上贴着卡片本身边缘的圆角，不再"小一圈"。平时 wrapper 无背景 / 边框，
            // 圆角不可见——仅 focus-flash 期间 box-shadow 才显示。
            className={cn("relative rounded-md", index === calls.length - 1 && "pb-0")}
          >
            {index !== calls.length - 1 && (
              <div className="absolute -left-[15px] top-6 bottom-[-8px] w-px bg-border" />
            )}
            <button
              type="button"
              onClick={() => onToggle(call.key)}
              aria-label={active ? "折叠工具调用" : "展开工具调用"}
              // 竖线在 -left-[15px] w-px，中心 -14.5；让 button 本身就是圆点，
              // 中心 = -17.5 + 3 = -14.5，精确对齐竖线
              className={cn(
                "absolute -left-[17.5px] top-[11px] h-1.5 w-1.5 cursor-pointer rounded-full",
                statusDot
              )}
            />
            <div
              className={cn(
                // border 始终占 1px，避免 active 切换时几何偏移导致 button 行抖动；
                // 折叠态 border-transparent 看不到，展开态切到 border-border 显形
                "overflow-hidden border border-transparent",
                active && "border-border bg-background"
              )}
            >
              {call.name === "Read" ? (
                <button
                  type="button"
                  onClick={() => onToggle(call.key)}
                  className={cn(
                    "grid min-h-8 w-full cursor-pointer grid-cols-[18px_minmax(88px,auto)_minmax(0,1fr)] items-center gap-2 px-1 py-1 text-left",
                    active && "border-b border-border bg-muted/30"
                  )}
                >
                  {(() => {
                    const args = callArgs(call);
                    const path = argString(args, "file_path") || "读取文件";
                    const offset = argString(args, "offset");
                    const limit = argString(args, "limit");
                    const range = offset
                      ? limit
                        ? `${offset}-${Number(offset) + Number(limit) - 1}`
                        : `${offset}+`
                      : "";
                    const display = relativizeReadPath(path, workdir, allowedPaths);
                    // 行号合并到路径后面，`:#xx-xx` 形式——选中复制粘到外部工具
                    // 是「path:#100-150」一体的 vscode 风格 anchor，不再拆成两列
                    const displayWithRange = range ? `${display}:#${range}` : display;
                    return (
                      <>
                        <span className="grid h-[18px] w-[18px] place-items-center text-muted-foreground">
                          <ScrollText className="h-3.5 w-3.5" />
                        </span>
                        <span className="whitespace-nowrap text-[12px] font-semibold">
                          Read
                        </span>
                        <span className="flex min-w-0 items-center gap-1.5 text-[12px] text-muted-foreground">
                          <span className="shrink-0">读取文件</span>
                          <code className="min-w-0 truncate font-mono text-[11px] text-foreground">
                            {displayWithRange}
                          </code>
                        </span>
                      </>
                    );
                  })()}
                </button>
              ) : (
                <button
                  type="button"
                  onClick={() => onToggle(call.key)}
                  className={cn(
                    "grid min-h-8 w-full cursor-pointer grid-cols-[18px_minmax(88px,auto)_minmax(0,1fr)] items-center gap-2 px-1 py-1 text-left",
                    active && "border-b border-border bg-muted/30"
                  )}
                >
                  <span className="grid h-[18px] w-[18px] place-items-center text-muted-foreground">
                    <ToolIcon name={call.name} />
                  </span>
                  <span className="whitespace-nowrap text-[12px] font-semibold">
                    {call.name || "工具调用"}
                  </span>
                  <span className="flex min-w-0 items-center gap-1.5 text-[12px] text-muted-foreground">
   <span className="shrink-0">{callDescription(call)}</span>
         <code className="min-w-0 truncate font-mono text-[11px] text-foreground">
                      {callSummary(call)}
                    </code>
                  </span>
                </button>
              )}
              {active && (
                <>
                  <ToolCallDetail call={call} appSettings={appSettings} sessionId={sessionId} />
                  {call.name === "Task" &&
                    call.nestedParts &&
                    call.nestedParts.length > 0 && (
                      <div className="border-t border-border">
                        <NestedTaskContent
                          nestedParts={call.nestedParts}
                          appSettings={appSettings}
                          sessionId={sessionId}
                        />
                      </div>
                    )}
                  {call.artifactPath && (
                    <div className="border-t border-border p-2">
                      <ArtifactBadge path={call.artifactPath} />
                    </div>
                  )}
                </>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// CodeBlock / extractText 已抽到 ./CodeBlock 共享给 PlanTab / MarkdownRenderer 等。
// markdownComponents 也复用一份配置，避免本文件再单独维护。
const markdownComponents = { pre: CodeBlock } satisfies React.ComponentProps<
  typeof ReactMarkdown
>["components"];

function ReasoningBlock({
  text,
  streaming,
}: {
  text: string;
  streaming: boolean;
}) {
  // 流式时展开、流完立即折叠（不等整个 loop 结束）。
  // 用 prev ref detect streaming 边界变化，避免覆盖用户在 streaming 期间的手动 toggle。
  const [open, setOpen] = useState(streaming);
  const prevStreamingRef = useRef(streaming);
  useEffect(() => {
    if (prevStreamingRef.current !== streaming) {
      setOpen(streaming);
    }
    prevStreamingRef.current = streaming;
  }, [streaming]);

  const trimmed = text.trim();
  if (!trimmed && !streaming) return null;

  return (
    <div className="space-y-1">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="inline-flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground"
      >
        <Brain className="h-3.5 w-3.5 shrink-0" />
        <span className="font-medium">
          {streaming ? "思考中…" : "思考过程"}
        </span>
        {streaming && (
          <span className="ml-1 inline-flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse" />
        )}
        {open ? (
          <ChevronDown className="h-3 w-3" />
        ) : (
          <ChevronRight className="h-3 w-3" />
        )}
      </button>
      {open && (
        <div className="border-l border-border/50 pl-3 text-[12px] leading-relaxed text-muted-foreground break-words">
          {text ? (
            <div className="markdown-segment">
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                components={markdownComponents}
              >
                {text}
              </ReactMarkdown>
            </div>
          ) : streaming ? (
            "▍"
          ) : null}
        </div>
      )}
    </div>
  );
}

function AssistantParts({
  parts,
  streaming,
  expandedKeys,
  onToggle,
  appSettings,
  sessionId,
}: {
  parts: AssistantRenderPart[];
  streaming?: boolean;
  expandedKeys: Set<string>;
  onToggle: (key: string) => void;
  appSettings?: AppSettings;
  sessionId?: string;
}) {
  if (parts.length === 0) {
    return streaming ? <span>▍</span> : null;
  }

  return (
    <div className="space-y-3">
      {parts.map((part) => {
        if (part.type === "text") {
          return (
            <div key={part.key} className="markdown-segment">
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                components={markdownComponents}
              >
                {part.text || (streaming ? "▍" : "")}
              </ReactMarkdown>
            </div>
          );
        }
        if (part.type === "reasoning") {
          return (
            <ReasoningBlock
              key={part.key}
              text={part.text}
              streaming={part.streaming}
            />
          );
        }
        return (
          <ToolCallTimeline
            key={part.key}
            calls={part.calls}
            expandedKeys={expandedKeys}
            onToggle={onToggle}
            appSettings={appSettings}
            sessionId={sessionId}
          />
        );
      })}
    </div>
  );
}

export const MessageBubble = memo(function MessageBubble({
  message,
  streaming,
  prompt,
  userAvatar,
  sessionId,
  onFork,
  onRegenerate,
  onEdit,
  streamingParts,
  find,
  archived,
  summaryExpanded,
  onToggleSummary,
  historyExpanded,
  onToggleHistory,
  archivedCount,
  canUndoCompaction,
  onUndoCompaction,
  appSettings,
}: Props) {
  const [copied, setCopied] = useState(false);
  const [expandedToolCalls, setExpandedToolCalls] = useState<Set<string>>(
    () => new Set()
  );
  const [showRawText, setShowRawText] = useState(false);
  const [actionMenuOpen, setActionMenuOpen] = useState(false);
  const actionMenuRef = useRef<HTMLDivElement>(null);
  const [editing, setEditing] = useState(false);
  const [editDraft, setEditDraft] = useState("");
  const [submittingEdit, setSubmittingEdit] = useState(false);
  const editTextareaRef = useRef<HTMLTextAreaElement>(null);

  // 编辑态打开时自动 focus + 末尾光标
  useEffect(() => {
    if (!editing) return;
    const ta = editTextareaRef.current;
    if (!ta) return;
    ta.focus();
    const len = ta.value.length;
    ta.setSelectionRange(len, len);
  }, [editing]);

  function startEdit() {
    setEditDraft(message.content);
    setEditing(true);
  }

  function cancelEdit() {
    setEditing(false);
    setEditDraft("");
  }

  async function commitEdit() {
    if (!onEdit) return;
    const next = editDraft.trim();
    if (!next || submittingEdit) return;
    if (next === message.content.trim()) {
      cancelEdit();
      return;
    }
    setSubmittingEdit(true);
    try {
      await onEdit(message.id, next);
      // 提交成功后该消息会被 truncate 并重发，组件会被卸载，无需手动收尾
    } catch {
      // 失败时让用户继续编辑：保留草稿
      setSubmittingEdit(false);
    }
  }

  useEffect(() => {
    if (!actionMenuOpen) return;

    const onMouseDown = (event: MouseEvent) => {
      if (actionMenuRef.current?.contains(event.target as Node)) return;
      setActionMenuOpen(false);
    };

    window.addEventListener("mousedown", onMouseDown);
    return () => window.removeEventListener("mousedown", onMouseDown);
  }, [actionMenuOpen]);

  if (message.role === "marker" && message.meta?.type === "switch") {
    const { from_provider, from_model, to_provider, to_model } = message.meta;
    return (
      <div className="px-6 py-3 flex items-center gap-3 text-[11px] text-muted-foreground select-none">
        <div className="flex-1 h-px bg-border" />
        <div className="inline-flex items-center gap-1.5 rounded-full border border-border bg-background px-2.5 py-1">
          <ArrowRightLeft className="w-3 h-3" />
          <span className="font-medium text-foreground/70">
            {from_provider} · {from_model}
          </span>
          <span>→</span>
          <span className="font-medium text-primary">
            {to_provider} · {to_model}
          </span>
        </div>
        <div className="flex-1 h-px bg-border" />
      </div>
    );
  }

  if (message.role === "marker" && message.meta?.type === "interrupted") {
    return (
      <div className="px-6 py-3 flex items-center gap-3 text-[11px] text-muted-foreground select-none">
        <div className="flex-1 h-px bg-border" />
        <div className="inline-flex items-center gap-1.5 rounded-full border border-border bg-background px-2.5 py-1">
          <Ban className="w-3 h-3 text-destructive" />
          <span className="font-medium text-foreground/70">
            用户中断对话
          </span>
        </div>
        <div className="flex-1 h-px bg-border" />
      </div>
    );
  }

  if (message.role === "marker" && message.meta?.type === "reasoning_switch") {
    const { from, to } = message.meta;
    return (
      <div className="px-6 py-3 flex items-center gap-3 text-[11px] text-muted-foreground select-none">
        <div className="flex-1 h-px bg-border" />
        <div className="inline-flex items-center gap-1.5 rounded-full border border-border bg-background px-2.5 py-1">
          <ArrowRightLeft className="w-3 h-3" />
          <span className="font-medium text-foreground/70">
            {formatReasoningLabel(from)}
          </span>
          <span>→</span>
          <span className="font-medium text-primary">
            {formatReasoningLabel(to)}
          </span>
        </div>
        <div className="flex-1 h-px bg-border" />
      </div>
    );
  }

  if (message.role === "marker" && message.meta?.type === "compact_boundary") {
    const { before_tokens, after_tokens, summary } = message.meta;
    const summaryOn = !!summaryExpanded;
    const historyOn = !!historyExpanded;
    const count = archivedCount ?? 0;
    return (
      <div className="px-6 py-3 flex flex-col items-stretch gap-2 text-[11px] text-muted-foreground select-none">
        <div className="flex items-center gap-3">
          <div className="flex-1 h-px bg-border" />
          <button
            type="button"
            onClick={onToggleSummary ? () => onToggleSummary(message.id) : undefined}
            title={summaryOn ? "点击折叠压缩摘要" : "点击查看压缩摘要"}
            className="inline-flex items-center gap-1.5 rounded-full border border-border bg-background px-2.5 py-1 transition-colors hover:bg-muted hover:text-foreground cursor-pointer"
          >
            {summaryOn ? (
              <ChevronDown className="w-3 h-3" />
            ) : (
              <ChevronRight className="w-3 h-3" />
            )}
            <span className="font-medium text-foreground/70">上下文已压缩</span>
            <span className="tabular-nums">
              {before_tokens} → {after_tokens} tokens
            </span>
          </button>
          {count > 0 && (
            <button
              type="button"
              onClick={onToggleHistory ? () => onToggleHistory(message.id) : undefined}
              title={
                historyOn
                  ? "点击折叠原始历史对话"
                  : `点击展开 ${count} 条原始历史对话`
              }
              className="inline-flex items-center gap-1 rounded-full border border-border bg-background px-2 py-1 transition-colors hover:bg-muted hover:text-foreground cursor-pointer"
            >
              {historyOn ? (
                <ChevronDown className="w-3 h-3" />
              ) : (
                <ChevronRight className="w-3 h-3" />
              )}
              <span>历史对话 · {count}</span>
            </button>
          )}
          {canUndoCompaction && (
            <button
              type="button"
              onClick={
                onUndoCompaction ? () => onUndoCompaction(message.id) : undefined
              }
              title="撤销这次压缩，回到压缩前（可换模型重新压缩）"
              className="inline-flex items-center gap-1 rounded-full border border-border bg-background px-2 py-1 transition-colors hover:bg-muted hover:text-foreground cursor-pointer"
            >
              <Undo2 className="w-3 h-3" />
              <span>撤销压缩</span>
            </button>
          )}
          <div className="flex-1 h-px bg-border" />
        </div>
        {summaryOn && summary && (
          <div className="mx-auto max-w-3xl w-full rounded-md border border-border bg-muted/30 px-3 py-2 text-[12px] leading-relaxed text-foreground whitespace-pre-wrap">
            {summary}
          </div>
        )}
      </div>
    );
  }

  const isUser = message.role === "user";

  const assistantParts = buildAssistantRenderParts(
    message,
    streamingParts,
    streaming
  );
  const rawText = getMessageRawText(message);
  const canToggleRawText = !streaming && canShowRawMessage(message);

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(message.content);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error("复制失败");
    }
  }

  // 查找模式：以纯文本 + 高亮渲染（Markdown 让路）
  const findActive = !!find && find.query.length > 0;
  let body: React.ReactNode;
  if (findActive) {
    const matches = findMatches(
      message.content,
      find!.query,
      find!.regex,
      find!.caseSensitive
    );
    body = (
      <div className="whitespace-pre-wrap font-sans">
        {highlight(message.content, matches, find!.activeLocalIdx, message.id)}
      </div>
    );
  } else if (showRawText && canToggleRawText) {
    body = (
      <div className="whitespace-pre-wrap break-words rounded-md border border-border bg-muted/40 px-3 py-2 font-mono text-[13px] leading-relaxed text-foreground">
        {rawText}
      </div>
    );
  } else if (isUser && editing) {
    body = (
      <div className="space-y-2">
        <textarea
          ref={editTextareaRef}
          value={editDraft}
          onChange={(e) => setEditDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              e.preventDefault();
              cancelEdit();
            } else if (
              (e.metaKey || e.ctrlKey) &&
              e.key === "Enter" &&
              !submittingEdit
            ) {
              e.preventDefault();
              void commitEdit();
            }
          }}
          rows={Math.min(12, Math.max(2, editDraft.split("\n").length))}
          disabled={submittingEdit}
          className="w-full resize-y rounded-md border border-border bg-background px-3 py-2 text-[14px] leading-relaxed text-foreground outline-none focus:border-primary disabled:opacity-60"
          placeholder="编辑消息…"
        />
        <div className="flex items-center justify-end gap-2 text-xs">
          <span className="mr-auto text-[11px] text-muted-foreground">
            ⌘/Ctrl + Enter 保存并重跑 · Esc 取消
          </span>
          <button
            type="button"
            onClick={cancelEdit}
            disabled={submittingEdit}
            className="inline-flex h-7 items-center gap-1 rounded-md border border-border px-2 text-muted-foreground hover:bg-accent hover:text-foreground disabled:opacity-60"
          >
            <X className="h-3.5 w-3.5" />
            取消
          </button>
          <button
            type="button"
            onClick={() => void commitEdit()}
            disabled={
              submittingEdit ||
              !editDraft.trim() ||
              editDraft.trim() === message.content.trim()
            }
            className="inline-flex h-7 items-center gap-1 rounded-md bg-primary px-2 text-primary-foreground hover:bg-primary/90 disabled:opacity-60"
          >
            {submittingEdit ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin" />
            ) : (
              <Check className="h-3.5 w-3.5" />
            )}
            保存并重跑
          </button>
        </div>
      </div>
    );
  } else if (isUser) {
    body = message.content ? (
      message.content.includes("```") ? (
        <div className="markdown-segment">
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            components={markdownComponents}
          >
            {message.content}
          </ReactMarkdown>
        </div>
      ) : (
        <div className="whitespace-pre-wrap">{message.content}</div>
      )
    ) : null;
  } else {
    body = (
      <AssistantParts
        parts={assistantParts}
        streaming={streaming}
        expandedKeys={expandedToolCalls}
        onToggle={(key) =>
          setExpandedToolCalls((current) => {
            const next = new Set(current);
            if (next.has(key)) next.delete(key);
            else next.add(key);
            return next;
          })
        }
        appSettings={appSettings}
        sessionId={sessionId}
      />
    );
  }

  return (
    <div
      data-message-role={message.role}
      data-message-id={message.id}
      title={archived ? "已被压缩，模型不再读取此消息（点击右上角圆环可再次压缩）" : undefined}
      className={cn(
        "group relative flex gap-3 px-6 py-4",
        archived && "opacity-50 hover:opacity-100 transition-opacity"
      )}
    >
      <div
        ref={actionMenuRef}
        className={cn(
          "absolute right-4 top-3 z-20 opacity-0 transition-opacity group-hover:opacity-100 focus-within:opacity-100",
          actionMenuOpen && "opacity-100"
        )}
      >
        <button
          type="button"
          onClick={(event) => {
            event.stopPropagation();
            setActionMenuOpen((open) => !open);
          }}
          className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground hover:bg-accent hover:text-foreground"
          aria-label="消息操作"
          title="消息操作"
        >
          <MoreHorizontal className="h-4 w-4" />
        </button>
        {actionMenuOpen && (
          <div
            onClick={(event) => event.stopPropagation()}
            className="absolute right-0 mt-1 w-40 rounded-md border border-border bg-card py-1 text-xs shadow-lg"
          >
            {canToggleRawText && (
              <button
                type="button"
                onClick={() => {
                  setShowRawText((show) => !show);
                  setActionMenuOpen(false);
                }}
                className="flex w-full items-center gap-2 px-2.5 py-1.5 text-left text-muted-foreground hover:bg-accent hover:text-foreground"
              >
                <FileText className="h-3.5 w-3.5" />
                <span>{showRawText ? "显示渲染" : "显示原文"}</span>
              </button>
            )}
          </div>
        )}
      </div>
      <div className="shrink-0 flex w-7 flex-col items-center gap-1.5">
        <AvatarPreview
          value={isUser ? userAvatar : prompt?.avatar}
          fallback={
            isUser ? (
              <User className="w-4 h-4" />
            ) : (
              <Bot className="w-4 h-4" />
            )
          }
          className={cn(
            "h-7 w-7 text-sm",
            isUser
              ? "bg-gradient-to-br from-sky-500 to-blue-600 text-white"
              : "bg-transparent text-muted-foreground"
          )}
          title={!isUser && prompt ? prompt.name : undefined}
        />
      </div>
      <div className={cn("flex-1 min-w-0", canToggleRawText && "pr-8")}>
        <div className="flex items-center gap-2 mb-1.5 text-xs">
          <span className="font-medium">
            {isUser ? "你" : prompt?.name ?? "助手"}
          </span>
          {streaming && (
            <span className="inline-flex items-center gap-1 text-primary">
              <span className="h-1.5 w-1.5 bg-primary rounded-full animate-pulse" />
              生成中…
            </span>
          )}
        </div>
        <div className="markdown text-[14px] leading-relaxed break-words">
          {body}
        </div>
        {!isUser && streaming && (
          <LoopingWebm
            src={animations.sendInterrupt}
            className="mt-2 h-8 w-8 rounded-full"
          />
        )}
        <AttachmentPreviewStrip
          attachments={message.attachments}
          variant={isUser ? "compact" : "gallery"}
          className="mt-2"
        />
        {!streaming && !editing && (
          <div className="opacity-0 group-hover:opacity-100 transition-opacity flex items-center gap-1 mt-2 -ml-1.5">
            <button
              onClick={handleCopy}
              className="px-1.5 py-1 rounded hover:bg-accent text-muted-foreground inline-flex items-center gap-1 text-xs"
              title="复制"
            >
              {copied ? (
                <Check className="w-3.5 h-3.5 text-emerald-500" />
              ) : (
                <Copy className="w-3.5 h-3.5" />
              )}
            </button>
            {onFork && (
              <button
                onClick={() => onFork(message.id)}
                className="px-1.5 py-1 rounded hover:bg-accent text-muted-foreground inline-flex items-center gap-1 text-xs"
                title="从此处分叉新对话"
              >
                <GitBranch className="w-3.5 h-3.5" />
                <span>分叉</span>
              </button>
            )}
            {isUser && onEdit && (
              <button
                onClick={startEdit}
                className="px-1.5 py-1 rounded hover:bg-accent text-muted-foreground inline-flex items-center gap-1 text-xs"
                title="编辑后重跑"
              >
                <Pencil className="w-3.5 h-3.5" />
                <span>编辑</span>
              </button>
            )}
            {onRegenerate && (
              <button
                onClick={() => onRegenerate(message.id)}
                className="px-1.5 py-1 rounded hover:bg-accent text-muted-foreground inline-flex items-center gap-1 text-xs"
                title={isUser ? "用同样内容重跑" : "重新生成"}
              >
                <RefreshCw className="w-3.5 h-3.5" />
                <span>重新生成</span>
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
});

/**
 * 历史消息列表 —— 从 ChatView 拆出来的 memo 组件。
 *
 * 目的：避免流式期间 ChatView 高频 setState 把所有历史 bubble 都重渲。
 * 这里**故意不**接收整个 session 对象 —— session 的引用每次 store 事件都会变，
 * 让所有 bubble 跟着 memo bust。我们只接需要的小 props（消息数组本身的引用、
 * find 状态、几个稳定的回调），shallow compare 就能挡住绝大多数无关重渲染。
 *
 * 调用方在 ChatView 必须：
 * - 所有 callback 用 useCallback 包，引用稳定
 * - find 对象用 useMemo 包
 * - matchesPerMessage / nextBoundaryId / boundaryArchivedCounts 用 useMemo 包
 * 否则 memo 失效。
 */

import { memo, useMemo } from "react";
import { MessageBubble } from "./MessageBubble";
import type { Message, Prompt } from "@/desktop/ui/types";

/**
 * 计算消息渲染顺序（架构 §4.12.5 修订）。
 *
 * 物理 jsonl 顺序可能出现 wakeup 在 assistant 之前——因为 wakeup 是即写即落
 * （bash 后台任务完成的瞬间），而 assistant 等 stream 完成才落盘。view 上把
 * wakeup 卡片排在 tool_call 卡片之前是反直觉的（wakeup 是该 tool_call 的回应）。
 *
 * 重排策略：
 * - 普通消息按物理顺序
 * - `meta.system_notification` 的 user message 带 `tool_use_id`，找它之后第一个
 *   `tool_calls` 含该 id 的 assistant：把 wakeup **推迟到该 assistant 之后**
 * - 找不到（wakeup 物理位置已在 assistant 之后 / 或 tool_call 已经不存在）→
 *   保留原位，兜底
 *
 * 返回值是原 index 序列。所有按物理 index 索引的字段（find / boundary /
 * archived 等）都拿原 index 取值，保持正确。
 */
export function reorderForWakeupView(messages: Message[]): number[] {
  // 1. 标记需要"推迟"的 wakeup：找它后面的目标 assistant 原 index
  const deferTo = new Map<number, number>(); // wakeupIdx -> targetAssistantIdx
  for (let i = 0; i < messages.length; i++) {
    const m = messages[i];
    if (m.role !== "user" || m.meta?.type !== "system_notification") continue;
    const toolUseId = m.meta.tool_use_id;
    if (!toolUseId) continue;
    for (let j = i + 1; j < messages.length; j++) {
      const target = messages[j];
      if (target.role === "assistant" && target.tool_calls?.some((tc) => tc.id === toolUseId)) {
        deferTo.set(i, j);
        break;
      }
    }
  }

  // 2. 按 target 反向索引：assistantIdx -> wakeupIdx[]
  const pendingByAssistant = new Map<number, number[]>();
  for (const [wakeupIdx, assistantIdx] of deferTo) {
    const list = pendingByAssistant.get(assistantIdx) ?? [];
    list.push(wakeupIdx);
    pendingByAssistant.set(assistantIdx, list);
  }

  // 3. 渲染顺序：跳过被 defer 的 wakeup，在 target assistant 之后插入
  const order: number[] = [];
  for (let i = 0; i < messages.length; i++) {
    if (deferTo.has(i)) continue; // wakeup 跳过原位
    order.push(i);
    const pending = pendingByAssistant.get(i);
    if (pending) {
      for (const wakeupIdx of pending) order.push(wakeupIdx);
    }
  }
  return order;
}

interface FindCtx {
  query: string;
  regex: boolean;
  caseSensitive: boolean;
  matchesPerMessage: Array<Array<[number, number]>>;
  activeLocation: { msgIdx: number; localIdx: number } | null;
}

export interface MessageListProps {
  messages: Message[];
  prompt?: Prompt;
  userAvatar?: string;
  sessionId?: string;
  isStreaming: boolean;
  lastUserMsgId: string | null;
  lastUserHasAssistantAfter: boolean;
  lastCompactBoundaryIdx: number;
  /** 每条非 boundary 消息归属下一个 boundary id（null 表示属于最后一段）。长度 = messages.length */
  ownerBoundaryByIndex: Array<string | null>;
  expandedHistories: Set<string>;
  expandedSummaries: Set<string>;
  boundaryArchivedCounts: Record<string, number>;
  find: FindCtx | null;
  onFork: (id: string) => void;
  onRegenerate: (id: string) => void;
  onRegenerateUser: (id: string) => void;
  onEdit: (id: string, nextContent: string) => Promise<void> | void;
  onToggleSummary: (id: string) => void;
  onToggleHistory: (id: string) => void;
  onUndoCompaction?: (markerId: string) => void;
  /** compact_boundary marker ID set：可撤销的压缩标记（之后无非 marker 消息）。 */
  undoableCompactionIds?: Set<string>;
}

export const MessageList = memo(function MessageList({
  messages,
  prompt,
  userAvatar,
  sessionId,
  isStreaming,
  lastUserMsgId,
  lastUserHasAssistantAfter,
  lastCompactBoundaryIdx,
  ownerBoundaryByIndex,
  expandedHistories,
  expandedSummaries,
  boundaryArchivedCounts,
  find,
  onFork,
  onRegenerate,
  onRegenerateUser,
  onEdit,
  onToggleSummary,
  onToggleHistory,
  onUndoCompaction,
  undoableCompactionIds,
}: MessageListProps) {
  /**
   * 把 messages 转成 (m, i, baseMatchIdx) 元组：每条消息在「全局命中数组」里
   * 的起始下标（matchBaseIdx）—— FindBar 高亮跳转时用全局 index 定位。
   *
   * 提前算好避免在 map 里跑累加 sum。
   */
  const matchBaseByIndex = useMemo(() => {
    const out: number[] = new Array(messages.length).fill(0);
    if (!find) return out;
    let running = 0;
    for (let i = 0; i < messages.length; i++) {
      out[i] = running;
      running += find.matchesPerMessage[i]?.length ?? 0;
    }
    return out;
  }, [messages.length, find]);

  // 计算视觉顺序：wakeup 被推迟到对应 assistant 之后；其他保持物理顺序。
  // viewOrder 是原 index 序列——后续按物理 index 索引的字段（boundary / archived /
  // find activeLocation / matchBase）仍按原 i 取值，**仅渲染顺序**调整。
  const viewOrder = useMemo(() => reorderForWakeupView(messages), [messages]);

  return (
    <div>
      {viewOrder.map((i) => {
        const m = messages[i];
        const isBoundary = m.meta?.type === "compact_boundary";
        if (!isBoundary) {
          const owner = ownerBoundaryByIndex[i];
          if (owner !== null && !expandedHistories.has(owner)) {
            return null;
          }
        }
        const isLatestUser = m.role === "user" && m.id === lastUserMsgId;
        const onRegenerateProp =
          m.role === "assistant"
            ? onRegenerate
            : isLatestUser && !lastUserHasAssistantAfter && !isStreaming
              ? onRegenerateUser
              : undefined;
        const onEditProp =
          isLatestUser && !isStreaming ? onEdit : undefined;
        return (
          <MessageBubble
            key={m.id}
            message={m}
            prompt={prompt}
            userAvatar={userAvatar}
            sessionId={sessionId}
            onFork={onFork}
            onRegenerate={onRegenerateProp}
            onEdit={onEditProp}
            archived={lastCompactBoundaryIdx > 0 && i < lastCompactBoundaryIdx}
            summaryExpanded={isBoundary && expandedSummaries.has(m.id)}
            onToggleSummary={isBoundary ? onToggleSummary : undefined}
            historyExpanded={isBoundary && expandedHistories.has(m.id)}
            onToggleHistory={isBoundary ? onToggleHistory : undefined}
            archivedCount={isBoundary ? boundaryArchivedCounts[m.id] : undefined}
            canUndoCompaction={isBoundary && undoableCompactionIds?.has(m.id)}
            onUndoCompaction={isBoundary ? onUndoCompaction : undefined}
            find={
              find
                ? {
                    query: find.query,
                    regex: find.regex,
                    caseSensitive: find.caseSensitive,
                    activeLocalIdx:
                      find.activeLocation?.msgIdx === i
                        ? find.activeLocation.localIdx
                        : null,
                    matchBaseIdx: matchBaseByIndex[i],
                  }
                : undefined
            }
          />
        );
      })}
    </div>
  );
});

import type { CatalogEntry } from "@/desktop/ui/types";
import { cn } from "@/desktop/ui/lib/utils";
