/**
 * 按 family 分组模型列表。
 * 如果 models.dev catalog 中没有该模型的 family 信息，则根据模型 ID 前缀推断。
 */
function groupModelsByFamily(
  models: FetchedModel[],
  catalog: Record<string, CatalogEntry> | null
): { family: string; models: FetchedModel[] }[] {
  const groups = new Map<string, FetchedModel[]>();

  // 构建不带前缀的 catalog 映射（如 "anthropic/claude-sonnet-4-5" → "claude-sonnet-4-5"）
  const catalogWithoutPrefix: Record<string, CatalogEntry> = {};
  if (catalog) {
    for (const [key, value] of Object.entries(catalog)) {
      catalogWithoutPrefix[key] = value;
      const slashIdx = key.indexOf("/");
      if (slashIdx > 0) {
        const withoutPrefix = key.substring(slashIdx + 1);
        catalogWithoutPrefix[withoutPrefix] = value;
      }
    }
  }

  for (const model of models) {
    const entry = catalogWithoutPrefix?.[model.id] || catalog?.[model.id];
    let family = entry?.family;

    // 如果 catalog 中没有 family，根据模型 ID 前缀推断（去掉可能的 provider 前缀）
    if (!family) {
      const id = model.id.toLowerCase();
      const idWithoutPrefix = id.includes("/") ? id.split("/").pop() || id : id;

      if (idWithoutPrefix.startsWith("gpt-") || idWithoutPrefix.startsWith("o1") || idWithoutPrefix.startsWith("o3")) {
        family = "GPT";
      } else if (idWithoutPrefix.startsWith("claude-")) {
        if (idWithoutPrefix.includes("opus")) family = "Claude Opus";
        else if (idWithoutPrefix.includes("sonnet")) family = "Claude Sonnet";
        else if (idWithoutPrefix.includes("haiku")) family = "Claude Haiku";
        else family = "Claude";
      } else if (idWithoutPrefix.startsWith("gemini-")) {
        if (idWithoutPrefix.includes("pro")) family = "Gemini Pro";
        else if (idWithoutPrefix.includes("flash")) family = "Gemini Flash";
        else family = "Gemini";
      } else if (idWithoutPrefix.startsWith("deepseek-")) {
        if (idWithoutPrefix.includes("r1") || idWithoutPrefix.includes("reasoner")) family = "DeepSeek Reasoner";
        else family = "DeepSeek";
      } else if (idWithoutPrefix.startsWith("qwen-")) {
        family = "Qwen";
      } else {
        family = "其他";
      }
    }

    if (!groups.has(family)) {
      groups.set(family, []);
    }
    groups.get(family)!.push(model);
  }

  // 按 family 名称排序
  return Array.from(groups.entries())
    .map(([family, models]) => ({ family, models }))
    .sort((a, b) => a.family.localeCompare(b.family));
}

import { Fragment, useEffect, useRef, useState } from "react";
import { ChevronDown, Flame } from "lucide-react";
import { toast } from "sonner";

import { useStore } from "@/desktop/ui/store/useStore";
import {
  DEFAULT_REASONING,
  REASONING_EFFORT_LABEL,
  REASONING_EFFORT_ORDER,
  effortDisplay,
  modelSupportsReasoning,
} from "@/desktop/ui/lib/reasoning";
import { cn } from "@/desktop/ui/lib/utils";
import type { ReasoningEffort } from "@/desktop/ui/types";

/**
 * 抽屉里的思考强度 chip：点击向上弹出菜单选择 low / medium / high / extra。
 *
 * 与 ModelPicker popup 里的 ReasoningControls 共享同一份 store 数据（SSoT 不冲突）。
 * 不支持 reasoning 的模型 / thinking 已关闭时，分别按情况隐藏或 disabled。
 */
export function ReasoningEffortPill() {
  const session = useStore((s) => s.currentSession);
  const providers = useStore((s) => s.providersFile.providers);
  const setReasoning = useStore((s) => s.setReasoning);

  const [open, setOpen] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onClick(event: MouseEvent) {
      if (
        wrapperRef.current &&
        !wrapperRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
      }
    }
    window.addEventListener("click", onClick);
    return () => window.removeEventListener("click", onClick);
  }, [open]);

  if (!session) return null;
  const provider = providers.find((p) => p.id === session.provider_id);
  if (!provider) return null;
  if (!modelSupportsReasoning(provider.kind, session.model)) return null;

  const reasoning = session.reasoning ?? DEFAULT_REASONING;
  const enabled = reasoning.enabled ?? true;
  const effort = reasoning.effort ?? "extra";

  function pick(next: ReasoningEffort) {
    setOpen(false);
    if (next === effort) return;
    void setReasoning({ ...reasoning, effort: next }).catch((e: unknown) => {
      toast.error(e instanceof Error ? e.message : String(e));
    });
  }

  return (
    <div className="relative" ref={wrapperRef}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        disabled={!enabled}
        className={cn(
          "h-8 inline-flex items-center gap-1 rounded-md px-2 text-xs",
          "bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground transition-colors",
          "disabled:opacity-40 disabled:pointer-events-none",
          open && "bg-muted text-foreground"
        )}
        title={
          enabled
            ? "切换思考强度"
            : "thinking 已关闭，可在模型菜单里开启"
        }
      >
        <Flame className="h-3.5 w-3.5" />
        <span className="font-medium">{REASONING_EFFORT_LABEL[effort]}</span>
        <ChevronDown className="w-3 h-3 opacity-60" />
      </button>
      {open && (
        <div
          onClick={(e) => e.stopPropagation()}
          className="absolute bottom-full left-0 mb-1 min-w-[160px] rounded-lg border border-border bg-card shadow-lg z-[90] overflow-hidden animate-slide-up"
        >
          {REASONING_EFFORT_ORDER.map((level, i) => {
            const real = effortDisplay(provider.kind, session.model, level);
            return (
              <Fragment key={level}>
                {i > 0 && <div className="h-px bg-border mx-3" />}
                <button
                  type="button"
                  onClick={() => pick(level)}
                  className={cn(
                    "w-full flex items-center justify-between gap-3 px-3 py-2 text-sm hover:bg-accent text-left",
                    level === effort && "bg-accent/60"
                  )}
                  title={`实际发送：${real}`}
                >
                  <span className="font-medium">
                    {REASONING_EFFORT_LABEL[level]}
                  </span>
                  <span className="text-[10px] text-muted-foreground tabular-nums">
                    {real}
                  </span>
                </button>
              </Fragment>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import {
  ChevronsRight,
  ChevronsLeft,
  Terminal,
  FilePenLine,
  FileJson,
  ListChecks,
  ClipboardList,
} from "lucide-react";
import { cn } from "@/desktop/ui/lib/utils";
import { useStore } from "@/desktop/ui/store/useStore";
import { BackgroundTaskTab } from "./BackgroundTaskPanel";
import { EditTreeTab } from "./EditTreePanel";
import { ModelIoInspector } from "./ModelIoInspector";
import { TodoTab } from "./TodoTab";
import { PlanTab } from "./PlanTab";

/**
 * 右侧工作台：固定列布局（被 ChatView 的 grid 让位），承载「后台任务 / 修改文件」两个 tab。
 *
 * 设计要点：
 * - **不浮动**：作为 ChatView 的 grid 第三列存在，挤压 chat 区域（不是 overlay）
 * - **可折叠**：右上角箭头按钮收起到 32px 宽，只剩 tab 图标列；再点恢复
 * - **左边缘可拖**：用户拖动左侧 4px 抓手改 sidebar 宽度（240-600 范围）
 * - **状态持久化**：宽度 / 折叠态 / 当前 tab 全部走 localStorage，跨会话刷新保留
 *
 * 内容数据全部走对应 tab 组件自己 fetch（BackgroundTaskTab / EditTreeTab）；
 * sidebar 不持有业务数据，仅管布局。
 */

type TabId = "tasks" | "edits" | "todos" | "plans";

const TAB_IDS: TabId[] = ["tasks", "edits", "todos", "plans"];

const STORAGE_WIDTH = "hebbian.rightSidebar.width";
const STORAGE_COLLAPSED = "hebbian.rightSidebar.collapsed";
const STORAGE_TAB = "hebbian.rightSidebar.tab";

const DEFAULT_WIDTH = 320;
const MIN_WIDTH = 240;
const MAX_WIDTH = 600;
const COLLAPSED_WIDTH = 36;

function loadInitial<T>(key: string, fallback: T, parse: (raw: string) => T): T {
  try {
    const raw = localStorage.getItem(key);
    if (raw === null) return fallback;
    return parse(raw);
  } catch {
    return fallback;
  }
}

export function RightSidebar() {
  // 首次打开默认折叠（仅显示 36px 图标列），用户主动点开。
  // localStorage 有记录则用记录值。
  const [collapsed, setCollapsed] = useState(() =>
    loadInitial(STORAGE_COLLAPSED, true, (s) => s === "1")
  );
  const [width, setWidth] = useState(() =>
    loadInitial(STORAGE_WIDTH, DEFAULT_WIDTH, (s) => {
      const n = Number(s);
      return Number.isFinite(n) && n >= MIN_WIDTH && n <= MAX_WIDTH ? n : DEFAULT_WIDTH;
    })
  );
  const [tab, setTab] = useState<TabId>(() =>
    loadInitial<TabId>(STORAGE_TAB, "tasks", (s) =>
      (TAB_IDS as string[]).includes(s) ? (s as TabId) : "tasks"
    )
  );

  // Model I/O Drawer 由本 sidebar 持有：debug 开启时多一个入口，点击打开覆盖式查看器。
  // 不放进 tab 内嵌是因为 Inspector 信息密度极大（RequestDetail/N 条 MessageRow/嵌套 PrettyJson），
  // 320px tab 容不下。
  const debugEnabled = useStore((s) => s.debugEnabled);
  const sessionId = useStore((s) => s.currentSession?.id ?? null);
  const todos = useStore((s) => s.todos);
  const [modelIoOpen, setModelIoOpen] = useState(false);
  const closeModelIo = useCallback(() => setModelIoOpen(false), []);

  // todo 列表变化时自动聚焦：用 (id, status) 列表的 stable hash 判断是否"真变化"——
  // 仅模型 TodoWrite 触发的 store 写入会让这个 key 变；mirrorFromSlot 同步引用不算。
  // 用户原话："新增任务列表时，自动展开右侧 sidebar 并聚焦任务列表 tab"。
  //
  // **跨 session 切换不抢焦点**：用 sessionIdRef 跟踪 session 边界，切到新 session
  // 时只重置基线、不触发 setTab。仅同一 session 内 todosKey 变化（=agent 调了
  // TodoWrite）才聚焦。这样：
  //   - 用户从无 todo 的 session 切到有 todo 的 session → 保留用户当前 tab 偏好
  //   - 用户停在某 session → agent 加任务 → sidebar 自动跳出来 todos tab
  const todosKey = useMemo(
    () => todos.map((t) => `${t.id}:${t.status}`).join("|"),
    [todos],
  );
  const prevTodosKeyRef = useRef(todosKey);
  const prevSessionIdRef = useRef(sessionId);
  useEffect(() => {
    // 切 session（含从 null 进入第一个 session）：重置基线，不抢焦点
    if (prevSessionIdRef.current !== sessionId) {
      prevSessionIdRef.current = sessionId;
      prevTodosKeyRef.current = todosKey;
      return;
    }
    if (todosKey === prevTodosKeyRef.current) return;
    prevTodosKeyRef.current = todosKey;
    if (todos.length === 0) return;
    setCollapsed(false);
    setTab("todos");
  }, [sessionId, todosKey, todos.length]);

  // 持久化折叠状态
  useEffect(() => {
    localStorage.setItem(STORAGE_COLLAPSED, collapsed ? "1" : "0");
  }, [collapsed]);
  useEffect(() => {
    if (!collapsed) localStorage.setItem(STORAGE_WIDTH, String(width));
  }, [width, collapsed]);
  useEffect(() => {
    localStorage.setItem(STORAGE_TAB, tab);
  }, [tab]);

  // 拖拽逻辑：mousedown 在左边缘 → 进入 dragging 模式 → mousemove 更新宽度
  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const onDragStart = useCallback(
    (e: React.MouseEvent) => {
      if (collapsed) return;
      e.preventDefault();
      dragRef.current = { startX: e.clientX, startWidth: width };
      document.body.style.cursor = "ew-resize";
      document.body.style.userSelect = "none";

      const onMove = (ev: MouseEvent) => {
        if (!dragRef.current) return;
        // 拖向左 = 增宽；拖向右 = 减宽
        const delta = dragRef.current.startX - ev.clientX;
        const next = Math.min(
          MAX_WIDTH,
          Math.max(MIN_WIDTH, dragRef.current.startWidth + delta)
        );
        setWidth(next);
      };
      const onUp = () => {
        dragRef.current = null;
        document.body.style.cursor = "";
        document.body.style.userSelect = "";
        window.removeEventListener("mousemove", onMove);
        window.removeEventListener("mouseup", onUp);
      };
      window.addEventListener("mousemove", onMove);
      window.addEventListener("mouseup", onUp);
    },
    [collapsed, width]
  );

  // 折叠态：仅显示一列图标 + 展开按钮；点图标也直接展开到对应 tab
  if (collapsed) {
    return (
      <>
        <aside
          className="relative flex h-full flex-col border-l border-border"
          style={{ width: `${COLLAPSED_WIDTH}px` }}
        >
          <button
            type="button"
            onClick={() => setCollapsed(false)}
            className="grid h-9 w-full place-items-center border-b border-border text-muted-foreground hover:bg-accent hover:text-foreground"
            title="展开工作台"
            aria-label="展开工作台"
          >
            <ChevronsLeft className="h-4 w-4" />
          </button>
          <SidebarIconButton
            icon={<Terminal className="h-4 w-4" />}
            label="后台任务"
            onClick={() => {
              setTab("tasks");
              setCollapsed(false);
            }}
            active={tab === "tasks"}
          />
          <SidebarIconButton
            icon={<FilePenLine className="h-4 w-4" />}
            label="修改文件"
            onClick={() => {
              setTab("edits");
              setCollapsed(false);
            }}
            active={tab === "edits"}
          />
          <SidebarIconButton
            icon={<ListChecks className="h-4 w-4" />}
            label="任务清单"
            onClick={() => {
              setTab("todos");
              setCollapsed(false);
            }}
            active={tab === "todos"}
          />
          <SidebarIconButton
            icon={<ClipboardList className="h-4 w-4" />}
            label="计划"
            onClick={() => {
              setTab("plans");
              setCollapsed(false);
            }}
            active={tab === "plans"}
          />
          {debugEnabled && sessionId && (
            <SidebarIconButton
              icon={<FileJson className="h-4 w-4" />}
              label="Model I/O"
              onClick={() => setModelIoOpen(true)}
              active={false}
            />
          )}
        </aside>
        {sessionId && (
          <ModelIoInspector
            sessionId={sessionId}
            open={modelIoOpen}
            onClose={closeModelIo}
          />
        )}
      </>
    );
  }

  return (
    <>
      <aside
        className="relative flex h-full flex-col border-l border-border bg-muted/40"
        style={{ width: `${width}px` }}
      >
        {/* 拖拽抓手：左边缘 4px 透明区域，hover 时显示一条细线 */}
        <div
          onMouseDown={onDragStart}
          className="absolute left-0 top-0 z-10 h-full w-1 cursor-ew-resize hover:bg-primary/30"
          title="拖动改宽度"
          aria-label="调整工作台宽度"
        />

        {/* 顶栏：tab 切换 + 折叠按钮。
           - tab 列表始终显示完整中文标签（不缩成图标）
           - 容器宽度不够时整条横向滚动
           - 鼠标在 tab 区上下滚动会被 onWheel 转成横向滚动，免按 Shift */}
        <div className="flex h-9 shrink-0 items-stretch border-b border-border bg-background/50">
          <TabScroller>
            <SidebarTab
              id="tasks"
              current={tab}
              onClick={setTab}
              icon={<Terminal className="h-3.5 w-3.5" />}
              label="后台任务"
            />
            <SidebarTab
              id="edits"
              current={tab}
              onClick={setTab}
              icon={<FilePenLine className="h-3.5 w-3.5" />}
              label="修改文件"
            />
            <SidebarTab
              id="todos"
              current={tab}
              onClick={setTab}
              icon={<ListChecks className="h-3.5 w-3.5" />}
              label="任务清单"
            />
            <SidebarTab
              id="plans"
              current={tab}
              onClick={setTab}
              icon={<ClipboardList className="h-3.5 w-3.5" />}
              label="计划"
            />
          </TabScroller>
          <div className="flex shrink-0 items-center gap-0.5 border-l border-border/40 bg-background/50 pl-1 pr-1">
            {debugEnabled && sessionId && (
              <button
                type="button"
                onClick={() => setModelIoOpen(true)}
                className="grid h-6 w-6 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
                title="Model I/O"
                aria-label="Model I/O"
              >
                <FileJson className="h-3.5 w-3.5" />
              </button>
            )}
            <button
              type="button"
              onClick={() => setCollapsed(true)}
              className="grid h-6 w-6 place-items-center rounded text-muted-foreground hover:bg-accent hover:text-foreground"
              title="折叠工作台"
              aria-label="折叠工作台"
            >
              <ChevronsRight className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>

        {/* tab 内容区 */}
        <div className="min-h-0 flex-1 overflow-auto">
          {tab === "tasks" && <BackgroundTaskTab />}
          {tab === "edits" && <EditTreeTab />}
          {tab === "todos" && <TodoTab />}
          {tab === "plans" && <PlanTab />}
        </div>
      </aside>
      {sessionId && (
        <ModelIoInspector
          sessionId={sessionId}
          open={modelIoOpen}
          onClose={closeModelIo}
        />
      )}
    </>
  );
}

function SidebarTab({
  id,
  current,
  onClick,
  icon,
  label,
}: {
  id: TabId;
  current: TabId;
  onClick: (id: TabId) => void;
  icon: ReactNode;
  label: string;
}) {
  const active = id === current;
  return (
    <button
      type="button"
      onClick={() => onClick(id)}
      title={label}
      aria-label={label}
      className={cn(
        "inline-flex h-7 shrink-0 items-center gap-1 whitespace-nowrap rounded px-2 text-[12px] transition-colors",
        active
          ? "bg-background text-foreground shadow-sm"
          : "text-muted-foreground hover:bg-accent/50 hover:text-foreground"
      )}
    >
      {icon}
      <span>{label}</span>
    </button>
  );
}

/**
 * Tab 列表的横向滚动容器。
 *
 * - 不够宽时整条 tab 横向滚动；不裁切文字
 * - 滚动条做隐式（仅 hover 出现，靠 [data-tab-scroller] 全局样式控制）
 * - 鼠标滚轮（垂直）→ 横向滚动：让用户在窄 sidebar 里不必按 Shift 也能切 tab
 */
function TabScroller({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onWheel = (e: WheelEvent) => {
      // 只把垂直滚动转横向；用户主动按 shift 已经天然是横向，不重复处理
      if (e.shiftKey) return;
      // 如果横向 delta 已经不为 0（触摸板横滑 / 横向滚轮），交给浏览器原生处理
      if (Math.abs(e.deltaX) > Math.abs(e.deltaY)) return;
      if (e.deltaY === 0) return;
      // 滚到尽头时让事件冒泡（页面继续滚），避免在边界吞掉用户输入
      const maxScroll = el.scrollWidth - el.clientWidth;
      const next = el.scrollLeft + e.deltaY;
      if ((e.deltaY > 0 && el.scrollLeft >= maxScroll) ||
          (e.deltaY < 0 && el.scrollLeft <= 0)) {
        return;
      }
      e.preventDefault();
      el.scrollLeft = Math.max(0, Math.min(maxScroll, next));
    };
    // passive: false 才能 preventDefault
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, []);

  return (
    <div
      ref={ref}
      className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto px-1.5 [scrollbar-width:thin]"
      style={{ scrollbarColor: "transparent transparent" }}
      onMouseEnter={(e) => {
        // hover 时显示滚动条颜色（仅本元素，避免侵入全局样式）
        (e.currentTarget as HTMLDivElement).style.scrollbarColor =
          "rgb(0 0 0 / 0.2) transparent";
      }}
      onMouseLeave={(e) => {
        (e.currentTarget as HTMLDivElement).style.scrollbarColor =
          "transparent transparent";
      }}
    >
      {children}
    </div>
  );
}

function SidebarIconButton({
  icon,
  label,
  onClick,
  active,
}: {
  icon: ReactNode;
  label: string;
  onClick: () => void;
  active: boolean;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "grid h-9 w-full place-items-center text-muted-foreground transition-colors hover:bg-accent hover:text-foreground",
        active && "bg-accent/40 text-foreground"
      )}
      title={label}
      aria-label={label}
    >
      {icon}
    </button>
  );
}

import { Fragment, useEffect, useRef, useState } from "react";
import { ChevronDown, Gauge } from "lucide-react";
import { toast } from "sonner";

import { api } from "@/desktop/bridge/tauri";
import { cn } from "@/desktop/ui/lib/utils";

/** 与后端 `agent_core::run_mode::RunMode::as_str()` 一一对应。 */
type RunMode = "AskBeforeEdits" | "EditAutomatically" | "PlanMode" | "AutoMode";

const MODE_OPTIONS: { value: RunMode; label: string; desc: string }[] = [
  {
    value: "AskBeforeEdits",
    label: "编辑前询问",
    desc: "修改文件或运行命令前都会询问",
  },
  {
    value: "EditAutomatically",
    label: "编辑自动执行",
    desc: "直接修改文件，运行命令前仍会询问",
  },
  {
    value: "PlanMode",
    label: "计划模式",
    desc: "只读模式，先规划再动手",
  },
  {
    value: "AutoMode",
    label: "自动模式",
    desc: "让 AI 自己判断哪些操作可以放行",
  },
];

/** 把后端 RunMode 字符串映射成展示给用户的中文 label。 */
export function runModeLabel(mode: string): string {
  return MODE_OPTIONS.find((o) => o.value === mode)?.label ?? mode;
}

function labelOf(mode: RunMode): string {
  return runModeLabel(mode);
}

interface Props {
  sessionId: string | null;
  disabled?: boolean;
}

/**
 * 工具栏 chip：显示当前 [`RunMode`]，点击弹出下拉切换。
 *
 * 状态走后端 `RunModeState` 进程级 in-memory 表（架构 §4.4.3 / §8），重启回归
 * `AskBeforeEdits`。本 chip 不订阅 session 变更，每次 sessionId 切换时拉一次最新值。
 */
export function RunModeChip({ sessionId, disabled }: Props) {
  const [mode, setMode] = useState<RunMode>("AskBeforeEdits");
  const [open, setOpen] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let cancelled = false;
    if (!sessionId) {
      setMode("AskBeforeEdits");
      return;
    }
    api
      .getRunMode(sessionId)
      .then((value) => {
        if (!cancelled) setMode(value as RunMode);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [sessionId]);

  useEffect(() => {
    if (!open) return;
    function onClick(event: MouseEvent) {
      if (
        wrapperRef.current &&
        !wrapperRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
      }
    }
    window.addEventListener("click", onClick);
    return () => window.removeEventListener("click", onClick);
  }, [open]);

  async function pick(next: RunMode) {
    setOpen(false);
    if (!sessionId) {
      toast.error("当前没有打开的对话");
      return;
    }
    if (next === mode) return;
    try {
      const applied = await api.setRunMode(sessionId, next);
      setMode(applied as RunMode);
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    }
  }

  const buttonDisabled = disabled || !sessionId;

  return (
    <div className="relative" ref={wrapperRef}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        disabled={buttonDisabled}
        className={cn(
          "h-8 inline-flex items-center gap-1 rounded-md px-2 text-xs bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-40 disabled:pointer-events-none",
          open && "bg-muted text-foreground"
        )}
        title="切换运行模式"
      >
        <Gauge className="w-3.5 h-3.5" />
        <span className="font-medium">{labelOf(mode)}</span>
        <ChevronDown className="w-3 h-3 opacity-60" />
      </button>
      {open && (
        <div
          onClick={(e) => e.stopPropagation()}
          className="absolute bottom-full left-0 mb-1 min-w-[260px] rounded-lg border border-border bg-card shadow-lg z-[90] overflow-hidden animate-slide-up"
        >
          {/* hairline 用 `mx-3` 缩进，两端留 12px；hover bg 全宽 */}
          {MODE_OPTIONS.map((o, i) => (
            <Fragment key={o.value}>
              {i > 0 && <div className="h-px bg-border mx-3" />}
              <button
                type="button"
                onClick={() => pick(o.value)}
                className={cn(
                  "w-full flex flex-col gap-0.5 px-3 py-2 text-sm hover:bg-accent text-left",
                  o.value === mode && "bg-accent/60"
                )}
              >
                <span className="font-medium">{o.label}</span>
                <span className="text-xs text-muted-foreground">{o.desc}</span>
              </button>
            </Fragment>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { toast } from "sonner";
import { Bot, ChevronDown, ChevronRight, RotateCcw, Zap, FileText, FolderOpen, Sparkles } from "lucide-react";
import { Dialog } from "@/desktop/ui/components/ui/dialog";
import { Button } from "@/desktop/ui/components/ui/button";
import { Label, Select, Textarea } from "@/desktop/ui/components/ui/input";
import { AvatarPreview } from "@/desktop/ui/components/AvatarField";
import { SkillsPane } from "@/desktop/ui/components/SkillsPane";
import { invoke } from "@/desktop/bridge/transport";
import {
  DirPicker,
  PathListField,
  ToolToggleList,
} from "@/desktop/ui/components/workspaceFields";
import { useStore } from "@/desktop/ui/store/useStore";
import { cn } from "@/desktop/ui/lib/utils";
import { api } from "@/desktop/bridge/tauri";
import type { Provider, RuleFileInfo, RuleFileState } from "@/desktop/ui/types";

function isProviderEnabled(provider: Provider) {
  return provider.enabled !== false;
}

export function SessionSettingsDialog() {
  const {
    settingsOpen,
    setSettingsOpen,
    currentSession,
    providersFile,
    prompts,
    updateCurrentConfig,
    appSettings,
    refreshAppSettings,
    availableTools,
  } = useStore();

  const [providerId, setProviderId] = useState("");
  const [model, setModel] = useState("");
  const [systemPrompt, setSystemPrompt] = useState("");
  const [promptId, setPromptId] = useState("");
  const [stream, setStream] = useState(true);

  // workspace 覆盖：null = 用全局默认；undefined = 字段被首次打开时还没初始化
  const [workdir, setWorkdir] = useState<string | null>(null);
  // allowedPaths 是给 PathListField 的"扁平视图"——initial(可改) + 已宣告 runtime + 待宣告 pending
  // 都合到一个数组里，对话已开始时整个列表被 lockedPaths 标记成只读，仅添加按钮可用。
  const [allowedPaths, setAllowedPaths] = useState<string[] | null>(null);
  const [enabledTools, setEnabledTools] = useState<string[] | null>(null);

  // Rules 分区
  const [globalRules, setGlobalRules] = useState<string[] | null>(null);
  const [rulesFiles, setRulesFiles] = useState<RuleFileState[] | null>(null);
  const [discoveredRules, setDiscoveredRules] = useState<RuleFileInfo[]>([]);
  const [rulesLoading, setRulesLoading] = useState(false);

  // 对话是否已经发出过 user message——只有非空才需要锁定 / 走 pending 通道。
  const conversationStarted = !!currentSession?.messages?.some(
    (m) => m.role === "user"
  );

  // 对话已开始时，session.allowed_paths（initial）+ runtime_allowed_paths + pending 全部锁定，
  // 用户只能通过添加按钮追加（保存时后端把新增项落到 pending_runtime_allowed_paths）。
  const sessionRuntimePaths = [
    ...(currentSession?.runtime_allowed_paths ?? []),
    ...(currentSession?.pending_runtime_allowed_paths ?? []),
  ];

  useEffect(() => {
    if (settingsOpen && currentSession) {
      setProviderId(currentSession.provider_id);
      setModel(currentSession.model);
      setSystemPrompt(currentSession.system_prompt ?? "");
      setPromptId(currentSession.prompt_id ?? "");
      setStream(currentSession.stream);
      setWorkdir(currentSession.workdir ?? null);
      // 把 initial / announced / pending 拼成扁平视图供 PathListField 渲染
      const initial = currentSession.allowed_paths ?? null;
      const runtimePaths = [
        ...(currentSession.runtime_allowed_paths ?? []),
        ...(currentSession.pending_runtime_allowed_paths ?? []),
      ];
      if (initial === null && runtimePaths.length === 0) {
        setAllowedPaths(null);
      } else {
        setAllowedPaths([...(initial ?? []), ...runtimePaths]);
      }
      setEnabledTools(currentSession.enabled_tools ?? null);
      setGlobalRules(currentSession.global_rules ?? null);
      setRulesFiles(currentSession.rules_files ?? null);
      // 拉一次全局 settings 用作 placeholder
      refreshAppSettings().catch(() => {});
      // 扫所有规则文件（全局 default + 项目祖先链）
      setRulesLoading(true);
      const wd = currentSession.workdir ?? null;
      const allowed = currentSession.allowed_paths ?? [];
      invoke<RuleFileInfo[]>("discover_all_rules", {
        workdir: wd,
        allowedPaths: allowed,
        globalCandidates:
          currentSession.global_rules ?? null,
      })
        .then(setDiscoveredRules)
        .catch(() => setDiscoveredRules([]))
        .finally(() => setRulesLoading(false));
    }
  }, [settingsOpen, currentSession, refreshAppSettings]);

  const provider = providersFile.providers.find((p) => p.id === providerId);
  const selectableProviders = providersFile.providers.filter(
    (p) => isProviderEnabled(p) || p.id === providerId
  );

  async function handleSave() {
    if (!currentSession) return;
    try {
      await updateCurrentConfig({
        provider_id: providerId,
        model,
        system_prompt: systemPrompt,
        prompt_id: promptId,
        stream,
      });
      // 单独保存 workspace 字段；空数组也算"明确清空覆盖"，需要传 null
      await api.updateSessionSettings(currentSession.id, {
        workdir,
        allowed_paths: allowedPaths,
        enabled_tools: enabledTools,
        global_rules: globalRules,
        rules_files: rulesFiles,
      });
      toast.success("已更新");
      setSettingsOpen(false);
    } catch (e: any) {
      toast.error(e.message || String(e));
    }
  }

  function applyPrompt(pid: string) {
    setPromptId(pid);
    const p = prompts.find((x) => x.id === pid);
    if (p) setSystemPrompt(p.content);
  }

  if (!currentSession) return null;

  const globalDefaults = appSettings?.conversation;
  const inheritedAllowedPaths = globalDefaults?.allowed_paths ?? [];
  const inheritedEnabledTools = globalDefaults?.enabled_tools ?? [];
  const inheritedWorkdir = globalDefaults?.workdir ?? "~/";

  return (
    <Dialog
      open={settingsOpen}
      onOpenChange={setSettingsOpen}
      title="对话设置"
      description="调整当前对话的供应商、模型、Agent、流式开关"
      size="lg"
      footer={
        <>
          <Button variant="outline" onClick={() => setSettingsOpen(false)}>
            取消
          </Button>
          <Button onClick={handleSave}>保存</Button>
        </>
      }
    >
      <div className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-1.5">
            <Label>供应商</Label>
            <Select
              value={providerId}
              onChange={(e) => {
                const id = e.target.value;
                setProviderId(id);
                const p = selectableProviders.find((x) => x.id === id);
                if (p) setModel(p.default_model || p.models[0] || "");
              }}
            >
              {selectableProviders.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.name} ({p.kind}
                  {p.enabled === false ? "，已停用" : ""})
                </option>
              ))}
            </Select>
          </div>
          <div className="space-y-1.5">
            <Label>模型</Label>
            <Select value={model} onChange={(e) => setModel(e.target.value)}>
              {(provider?.models ?? []).map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
              {provider && !provider.models.includes(model) && (
                <option value={model}>{model}</option>
              )}
            </Select>
          </div>
        </div>

        <div className="space-y-1.5">
          <Label>Agent</Label>
          <div className="grid grid-cols-3 gap-2">
            <button
              type="button"
              onClick={() => {
                setPromptId("");
              }}
              className={cn(
                "flex items-center gap-2 px-3 py-2 rounded-md border text-left text-sm transition-colors",
                promptId === ""
                  ? "border-primary bg-primary/10"
                  : "border-border hover:bg-accent"
              )}
            >
              <span className="h-6 w-6 rounded-md bg-muted flex items-center justify-center text-sm">
                ∅
              </span>
              <span className="truncate">无 Agent</span>
            </button>
            {prompts.map((p) => (
              <button
                key={p.id}
                type="button"
                onClick={() => applyPrompt(p.id)}
                className={cn(
                  "flex items-center gap-2 px-3 py-2 rounded-md border text-left text-sm transition-colors",
                  promptId === p.id
                    ? "border-primary bg-primary/10"
                    : "border-border hover:bg-accent"
                )}
                title={p.content}
              >
                <AvatarPreview
                  value={p.avatar}
                  fallback={<Bot className="h-3.5 w-3.5" />}
                  className="h-6 w-6 shrink-0 text-sm"
                />
                <span className="truncate">{p.name}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-1.5">
          <Label>系统指令（覆盖 Agent 内容）</Label>
          <Textarea
            rows={5}
            value={systemPrompt}
            spellCheck={false}
            autoCorrect="off"
            onChange={(e) => setSystemPrompt(e.target.value)}
            placeholder="可直接修改，选择上方预置会自动填入"
          />
        </div>

        <div className="flex items-center justify-between border-t border-border pt-3">
          <div className="flex items-center gap-2">
            <Zap className="w-4 h-4 text-muted-foreground" />
            <div>
              <div className="text-sm font-medium">流式输出</div>
              <div className="text-xs text-muted-foreground">
                关闭后模型一次性返回完整回复
              </div>
            </div>
          </div>
          <button
            type="button"
            role="switch"
            aria-checked={stream}
            onClick={() => setStream((v) => !v)}
            className={cn(
              "relative inline-flex h-6 w-11 shrink-0 rounded-full transition-colors",
              stream ? "bg-primary" : "bg-muted"
            )}
          >
            <span
              className={cn(
                "inline-block h-5 w-5 rounded-full bg-white shadow transform transition-transform mt-0.5",
                stream ? "translate-x-5" : "translate-x-0.5"
              )}
            />
          </button>
        </div>

        {/* ── Workspace 覆盖 ── */}
        <CollapsibleSection
          title="目录与工具"
          icon={<FolderOpen className="w-4 h-4 text-muted-foreground" />}
          description="以下字段留空 = 继承全局设置；任意改动都会成为本对话的覆盖。"
        >
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <Label>工作目录（workdir）</Label>
              {workdir !== null && (
                <button
                  type="button"
                  onClick={() => setWorkdir(null)}
                  className="text-[11px] text-muted-foreground hover:text-foreground inline-flex items-center gap-1"
                  title="恢复使用全局默认"
                >
                  <RotateCcw className="w-3 h-3" />
                  恢复默认
                </button>
              )}
            </div>
            <DirPicker
              value={workdir ?? ""}
              onChange={(v) => setWorkdir(v || null)}
              placeholder={inheritedWorkdir}
            />
          </div>

          <PathListField
            label="允许访问的路径"
            paths={allowedPaths ?? []}
            inheritedPaths={allowedPaths === null ? inheritedAllowedPaths : undefined}
            onChange={(paths) => setAllowedPaths(paths)}
            relativeTo={workdir ?? inheritedWorkdir}
            lockedPaths={
              // 对话已开始：当前 session 持久化里已知的路径全部 locked。
              // 用户在 UI 里新加的（还在 state 里、还没保存）不在 locked 里，可删。
              conversationStarted
                ? [
                    ...(currentSession.allowed_paths ?? []),
                    ...sessionRuntimePaths,
                  ]
                : undefined
            }
            lockedHint={
              conversationStarted
                ? "对话已开始，已生效的路径不能再移除；新追加项会在下一条消息发送时通过 <workspace-update> 通知模型，不会改 system prompt。"
                : undefined
            }
            allowFiles
            trailing={
              !conversationStarted && allowedPaths !== null && (
                <button
                  type="button"
                  onClick={() => setAllowedPaths(null)}
                  className="text-[11px] text-muted-foreground hover:text-foreground inline-flex items-center gap-1 mr-1"
                >
                  <RotateCcw className="w-3 h-3" />
                  恢复默认
                </button>
              )
            }
          />

          <ToolToggleList
            label="启用的工具"
            availableTools={availableTools}
            enabled={enabledTools}
            inheritedEnabled={inheritedEnabledTools}
            onChange={(next) => setEnabledTools(next)}
            trailing={
              enabledTools !== null && (
                <button
                  type="button"
                  onClick={() => setEnabledTools(null)}
                  className="text-[11px] text-muted-foreground hover:text-foreground inline-flex items-center gap-1 mr-1"
                >
                  <RotateCcw className="w-3 h-3" />
                  恢复默认
                </button>
              )
            }
          />
        </CollapsibleSection>

        {/* ── Skills（项目级管理与导入）── */}
        <CollapsibleSection
          title="Skills"
          icon={<Sparkles className="w-4 h-4 text-muted-foreground" />}
          description="管理本对话 workdir 加载的 skills，可从本地目录 / Git 仓库 / ~/.claude/skills 导入到当前项目或全局。"
        >
          <SkillsPane workdir={workdir} scope="project" />
        </CollapsibleSection>

        {/* ── Rules ── */}
        <CollapsibleSection
          title="规则"
          icon={<FileText className="w-4 h-4 text-muted-foreground" />}
          description="自动注入到对话上下文，无需 agent 手动读取。复选框控制本对话是否启用该文件。"
        >
          <RulesList
            discovered={discoveredRules}
            loading={rulesLoading}
            globalEnabled={
              globalRules ?? globalDefaults?.global_rules ?? []
            }
            onToggleGlobal={(path) => {
              const cur = new Set(
                globalRules ?? globalDefaults?.global_rules ?? []
              );
              if (cur.has(path)) cur.delete(path);
              else cur.add(path);
              setGlobalRules(Array.from(cur));
            }}
            rulesFiles={rulesFiles ?? []}
            onToggleProject={(info) => {
              const next = rulesFiles
                ? [...rulesFiles]
                : discoveredRules
                    .filter((r) => r.source !== "global")
                    .map((r) => ({
                      path: r.path,
                      enabled: r.source === "workdir",
                    }));
              const idx = next.findIndex((s) => s.path === info.path);
              if (idx >= 0) {
                next[idx] = { ...next[idx], enabled: !next[idx].enabled };
              } else {
                next.push({
                  path: info.path,
                  enabled: !(info.source === "workdir"),
                });
              }
              setRulesFiles(next);
            }}
          />
        </CollapsibleSection>
      </div>
    </Dialog>
  );
}

/**
 * 规则文件列表：按 source 分两段。
 * - 上段「全局」：列 source==="global" 的文件，复选框对应 session.global_rules
 * - 下段「项目」：列 source==="workdir"/"allowed_path"，复选框对应 session.rules_files
 *
 * 中间一条分隔线 + 小字 label 视觉分割。
 */
function RulesList({
  discovered,
  loading,
  globalEnabled,
  onToggleGlobal,
  rulesFiles,
  onToggleProject,
}: {
  discovered: RuleFileInfo[];
  loading: boolean;
  globalEnabled: string[];
  onToggleGlobal: (path: string) => void;
  rulesFiles: RuleFileState[];
  onToggleProject: (info: RuleFileInfo) => void;
}) {
  const globalRules = discovered.filter((r) => r.source === "global");
  const projectRules = discovered.filter((r) => r.source !== "global");
  const globalSet = new Set(globalEnabled);

  if (loading) {
    return <div className="text-xs text-muted-foreground py-1">扫描中…</div>;
  }
  if (discovered.length === 0) {
    return (
      <div className="text-xs text-muted-foreground py-1">
        未发现 CLAUDE.md / AGENTS.md
      </div>
    );
  }
  return (
    <div className="space-y-3">
      <div>
        <div className="text-[11px] text-muted-foreground mb-1 uppercase tracking-wide">
          全局
        </div>
        {globalRules.length === 0 ? (
          <div className="text-xs text-muted-foreground py-1">
            未配置全局规则文件
          </div>
        ) : (
          <ul className="space-y-1">
            {globalRules.map((info) => {
              const enabled = globalSet.has(info.path);
              return (
                <li key={info.path}>
                  <button
                    type="button"
                    onClick={() => onToggleGlobal(info.path)}
                    className="flex items-center gap-2 w-full text-left px-2 py-1 rounded text-xs transition-colors hover:bg-accent"
                  >
                    <span
                      className={cn(
                        "inline-block w-2 h-2 rounded-full shrink-0",
                        enabled ? "bg-primary" : "bg-muted-foreground/30"
                      )}
                    />
                    <span className="truncate font-mono">{info.path}</span>
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>

      <div className="border-t border-border" />

      <div>
        <div className="text-[11px] text-muted-foreground mb-1 uppercase tracking-wide">
          项目
        </div>
        {projectRules.length === 0 ? (
          <div className="text-xs text-muted-foreground py-1">
            当前 workdir 与 allowed_paths 下没发现规则文件
          </div>
        ) : (
          <ul className="space-y-1 max-h-60 overflow-y-auto">
            {projectRules.map((info) => {
              const state = rulesFiles.find((s) => s.path === info.path);
              const enabled = state?.enabled ?? info.source === "workdir";
              return (
                <li key={info.path}>
                  <button
                    type="button"
                    onClick={() => onToggleProject(info)}
                    className="flex items-center gap-2 w-full text-left px-2 py-1 rounded text-xs transition-colors hover:bg-accent"
                  >
                    <span
                      className={cn(
                        "inline-block w-2 h-2 rounded-full shrink-0",
                        enabled ? "bg-primary" : "bg-muted-foreground/30"
                      )}
                    />
                    <span className="shrink-0 px-1 rounded text-[9px] uppercase bg-muted">
                      {info.source === "workdir" ? "wd" : "allowed"}
                    </span>
                    <span className="truncate font-mono">{info.path}</span>
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
}

/**
 * 可折叠区段：头部点击切换展开/收起，默认折叠。
 * 用于「目录」「Skills」「规则」三段二级配置——首屏只露常用项（provider/model/agent/stream），
 * 高级配置默认收起避免视觉过载。
 */
function CollapsibleSection({
  title,
  icon,
  defaultOpen = false,
  description,
  children,
}: {
  title: string;
  icon?: React.ReactNode;
  defaultOpen?: boolean;
  description?: string;
  children: React.ReactNode;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="space-y-3 border-t border-border pt-4">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="w-full flex items-center gap-2 text-left -mx-1 px-1 py-1 rounded hover:bg-accent/40 transition-colors"
      >
        {open ? (
          <ChevronDown className="w-4 h-4 text-muted-foreground" />
        ) : (
          <ChevronRight className="w-4 h-4 text-muted-foreground" />
        )}
        {icon}
        <span className="text-sm font-medium">{title}</span>
      </button>
      {open && (
        <div className="space-y-4">
          {description && (
            <div className="text-xs text-muted-foreground">{description}</div>
          )}
          {children}
        </div>
      )}
    </div>
  );
}

