  ArrowLeft,
  BriefcaseBusiness,
  FolderKanban,
  FolderOpen,
  MessageSquarePlus,
  MessagesSquare,
  Settings,
  SlidersHorizontal,
  Moon,
  Sun,
  Trash2,
  Edit3,
  Sparkles,
  Search,
  X,
  CaseSensitive,
  Command,
  Regex,
  Terminal,
  Plus,
  Upload,
  Download,
