  isNewConversationShortcut,
} from "@/desktop/ui/lib/keyboardShortcuts";
import {
  findSearchMatches,
  splitHighlightedText,
} from "@/desktop/ui/lib/searchHighlight";
import type { SessionMeta, WorkspaceProject } from "@/desktop/ui/types";
import { animations } from "@/assets/animations";
import { BUILD_INFO } from "@/buildInfo";

type GroupKey = "today" | "yesterday" | "last7" | "last30" | "older";

function groupOf(updatedAt: number): GroupKey {
  const now = new Date();
  const d = new Date(updatedAt);
  const sameDay = (a: Date, b: Date) =>
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate();
  if (sameDay(d, now)) return "today";
  const y = new Date(now);
  y.setDate(y.getDate() - 1);
  if (sameDay(d, y)) return "yesterday";
  const diff = (now.getTime() - d.getTime()) / 86400000;
  if (diff < 7) return "last7";
  if (diff < 30) return "last30";
  return "older";
}

const GROUP_LABEL: Record<GroupKey, string> = {
  today: "今天",
  yesterday: "昨天",
  last7: "过去 7 天",
  last30: "过去 30 天",
  older: "更早",
};
const GROUP_ORDER: GroupKey[] = ["today", "yesterday", "last7", "last30", "older"];

export function Sidebar() {
  const {
    sessions,
    projects,
    projectSidebarMode,
    selectedProjectId,
    setProjectSidebarMode,
    openProject,
    closeProject,
    saveProject,
    deleteProject: deleteProjectAction,
    importVscodeProject,
    importProjectFile: importProjectFileAction,
    currentSession,
    searchQuery,
    searchResults,
    searchCaseSensitive,
    searchRegex,
    searching,
    runSearch,
    clearSearch,
    openSession,
    refreshSessions,
    deleteSession,
    renameSession,
    regenerateTitle,
    setAppSettingsOpen,
    setSettingsOpen,
    newSession,
    toggleTheme,
    theme,
    runningSessions,
    unreadFinishedSessions,
    sessionStreams,
  } = useStore();

  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [renameText, setRenameText] = useState("");
  const [regeneratingId, setRegeneratingId] = useState<string | null>(null);
  const [creatingSession, setCreatingSession] = useState(false);
  const [importClaudeOpen, setImportClaudeOpen] = useState(false);
  const [projectMenuOpen, setProjectMenuOpen] = useState(false);
  const [query, setQuery] = useState(searchQuery);
  const debounceRef = useRef<number | null>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const projectMenuRef = useRef<HTMLDivElement>(null);
  const selectedProject = useMemo(
    () => projects.find((project) => project.id === selectedProjectId) ?? null,
    [projects, selectedProjectId]
  );

  useEffect(() => {
    if (debounceRef.current) window.clearTimeout(debounceRef.current);
    debounceRef.current = window.setTimeout(() => {
      runSearch(query, searchCaseSensitive).catch((e) =>
        toast.error(e.message || String(e))
      );
    }, 180);
    return () => {
      if (debounceRef.current) window.clearTimeout(debounceRef.current);
    };
  }, [query, searchCaseSensitive, searchRegex, runSearch]);

  async function commitRename(id: string) {
    const t = renameText.trim();
    if (t) {
      try {
        await renameSession(id, t);
      } catch (e: any) {
        toast.error(e.message || String(e));
      }
    }
    setRenamingId(null);
  }

  async function handleRegenerateTitle(id: string) {
    setRegeneratingId(id);
    try {
      await regenerateTitle();
      toast.success("已重新生成标题");
    } catch (e: any) {
      toast.error(e.message || String(e));
    } finally {
      setRegeneratingId(null);
    }
  }

  const handleCreateSession = useCallback(async () => {
    if (creatingSession) return;
    setCreatingSession(true);
    try {
      await newSession({
        projectId:
          projectSidebarMode === "projects" && selectedProject
            ? selectedProject.id
            : null,
      });
    } catch (e: any) {
      toast.error(e.message || String(e));
    } finally {
      setCreatingSession(false);
    }
  }, [creatingSession, newSession, projectSidebarMode, selectedProject]);

  useEffect(() => {
    if (!projectMenuOpen) return;
    function onClick(event: MouseEvent) {
      if (!projectMenuRef.current?.contains(event.target as Node)) {
        setProjectMenuOpen(false);
      }
    }
    window.addEventListener("click", onClick);
    return () => window.removeEventListener("click", onClick);
  }, [projectMenuOpen]);

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (isNewConversationShortcut(e)) {
        e.preventDefault();
        handleCreateSession();
        return;
      }

      if (isGlobalSearchShortcut(e)) {
        e.preventDefault();
        searchInputRef.current?.focus();
        searchInputRef.current?.select();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [handleCreateSession]);

  function projectWorkdir(project: WorkspaceProject) {
    return project.folders[0]?.path ?? "";
  }

  function projectAllowedPaths(project: WorkspaceProject) {
    return project.folders.slice(1).map((folder) => folder.path);
  }

  async function persistProjectProject(
    project: WorkspaceProject,
    workdir: string,
    allowedPaths: string[]
  ) {
    await saveProject({
      id: project.id,
      name: project.name,
      workdir,
      allowed_paths: allowedPaths,
      source: project.source ?? "manual",
    });
  }

  async function createProjectFromDialog() {
    setProjectMenuOpen(false);
    try {
      const dir = await openDialog({ directory: true, multiple: false });
      if (typeof dir !== "string") return;
      const name = pathLeaf(dir) || "项目";
      const project = await saveProject({
        name,
        workdir: dir,
        allowed_paths: [],
        source: "manual",
      });
      openProject(project.id);
    } catch (e: any) {
      toast.error(e.message || String(e));
    }
  }

  async function importProjectFile(vscode: boolean) {
    setProjectMenuOpen(false);
    try {
      const files = await openDialog({
        directory: false,
        multiple: false,
        filters: [{ name: "Workspace JSON", extensions: ["json", "code-workspace"] }],
      });
      if (typeof files !== "string") return;
      if (vscode) {
        const project = await importVscodeProject(files, pathLeaf(files).replace(/\.code-workspace$|\.json$/i, ""));
        openProject(project.id);
        return;
      }
      const project = await importProjectFileAction(files);
      openProject(project.id);
    } catch (e: any) {
      toast.error(e.message || String(e));
    }
  }

  function sessionBelongsToProject(session: SessionMeta, project: WorkspaceProject) {
    const workdir = projectWorkdir(project);
    return session.project_id === project.id || (!!workdir && session.workdir === workdir);
  }

  // 显示源：搜索命中或全量会话
  const displayItems: (SessionMeta & { snippet?: string | null })[] = useMemo(() => {
    const base = searchResults ?? sessions;
    if (projectSidebarMode === "projects" && selectedProject) {
      return base.filter((session) => sessionBelongsToProject(session, selectedProject));
    }
    return base;
  }, [searchResults, sessions, projectSidebarMode, selectedProject]);

  const grouped = useMemo(() => {
    const g: Record<GroupKey, typeof displayItems> = {
      today: [],
      yesterday: [],
      last7: [],
      last30: [],
      older: [],
    };
    for (const s of displayItems) g[groupOf(s.updated_at)].push(s);
    return g;
  }, [displayItems]);

  function renderSearchText(text: string, keyPrefix: string) {
    if (!searchResults || !query.trim()) return text;

    const segments = splitHighlightedText(
      text,
      findSearchMatches(text, query, searchCaseSensitive, searchRegex)
    );
    if (!segments.some((segment) => segment.highlighted)) return text;

    return segments.map((segment, index) =>
      segment.highlighted ? (
        <mark
          key={`${keyPrefix}-${index}`}
          className="rounded-sm bg-amber-300 px-0.5 text-black"
        >
          {segment.text}
        </mark>
      ) : (
        <span key={`${keyPrefix}-${index}`}>{segment.text}</span>
      )
    );
  }

  function renderSessionList() {
    return (
      <>
        {displayItems.length === 0 && (
          <div className="text-center text-xs text-muted-foreground py-10 px-4">
            {searchResults
              ? "无匹配结果"
              : selectedProject
                ? "这个项目下还没有对话"
                : "暂无对话，点击上方按钮创建"}
          </div>
        )}
        {GROUP_ORDER.map((key) => {
          const items = grouped[key];
          if (items.length === 0) return null;
          return (
            <div key={key} className="mb-2">
              <div className="px-2 py-1 text-[10px] font-semibold text-muted-foreground/80 uppercase tracking-wider">
                {GROUP_LABEL[key]}
              </div>
              <ul className="space-y-0.5">
                {items.map((s) => renderSessionItem(s))}
              </ul>
            </div>
          );
        })}
      </>
    );
  }

  function renderSessionItem(s: SessionMeta & { snippet?: string | null }) {
    const active = currentSession?.id === s.id;
    const regenerating = regeneratingId === s.id;
    const snippet = (s as any).snippet as string | undefined;
    const running = runningSessions.has(s.id) && !active;
    const unread = !active && !running && unreadFinishedSessions.has(s.id);
    // 待审批：slot 本身持有悬挂的审批 / 提问（run 结束 slot 被删，自然清除）。
    const slot = sessionStreams[s.id];
    const pendingApproval = !!(slot?.pendingApproval || slot?.pendingQuestion);
    return (
      <li key={s.id}>
        <div
          onClick={() => openSession(s.id)}
          className={cn(
            "group px-3 py-2 rounded-md cursor-pointer transition-colors",
            active ? "bg-accent text-accent-foreground" : "hover:bg-accent/50",
            pendingApproval ? "glow-pending" : unread && "glow-finished"
          )}
        >
          <div className="flex items-center gap-2 min-w-0">
            {(running || unread) && (
              <span
                className={cn("h-2 w-2 shrink-0 rounded-full bg-primary", running && "animate-breathe")}
                title={running ? "后台正在运行" : "运行已完成，未查看"}
                aria-label={running ? "running" : "unread"}
              />
            )}
            {renamingId === s.id ? (
              <input
                autoFocus
                spellCheck={false}
                autoCorrect="off"
                value={renameText}
                onChange={(e) => setRenameText(e.target.value)}
                onBlur={() => commitRename(s.id)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") commitRename(s.id);
                  if (e.key === "Escape") setRenamingId(null);
                }}
                className="flex-1 text-sm bg-background border border-input rounded px-1.5 py-0.5 outline-none focus-visible:ring-2 focus-visible:ring-ring"
              />
            ) : (
              <span className="text-sm truncate flex-1" title={s.title}>
                {renderSearchText(s.title, `${s.id}-title`)}
              </span>
            )}
          </div>
          <div className="flex items-center gap-1 mt-0.5 text-[11px] text-muted-foreground">
            <span className="truncate flex-1">{s.model}</span>
            {s.source === "cli" && (
              <span
                className="inline-flex items-center gap-0.5 px-1 py-0 rounded text-[10px] font-medium uppercase tracking-wide bg-primary/10 text-primary border border-primary/20 shrink-0"
                title="本对话由 hebbian-cli 创建"
              >
                <Terminal className="w-2.5 h-2.5" />
                CLI
              </span>
            )}
            {s.source === "claude" && (
              <span
                className="inline-flex items-center gap-0.5 px-1 py-0 rounded text-[10px] font-medium uppercase tracking-wide bg-amber-500/10 text-amber-600 border border-amber-500/20 shrink-0"
                title="从 Claude 导入"
              >
                <Download className="w-2.5 h-2.5" />
                Claude
              </span>
            )}
            {!renamingId && (
              <div className="flex items-center gap-0 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                {active && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleRegenerateTitle(s.id);
                    }}
                    disabled={regenerating}
                    className="p-0.5 rounded hover:bg-background text-muted-foreground disabled:opacity-50"
                    title="用模型重新生成标题"
                  >
                    <Sparkles className={cn("w-3 h-3", regenerating && "animate-pulse text-primary")} />
                  </button>
                )}
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setRenamingId(s.id);
                    setRenameText(s.title);
                  }}
                  className="p-0.5 rounded hover:bg-background text-muted-foreground"
                  title="重命名"
                >
                  <Edit3 className="w-3 h-3" />
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    if (confirm(`删除对话 "${s.title}"？`)) {
                      deleteSession(s.id).catch((err) => toast.error(err.message || String(err)));
                    }
                  }}
                  className="p-0.5 rounded hover:bg-background text-muted-foreground hover:text-destructive"
                  title="删除"
                >
                  <Trash2 className="w-3 h-3" />
                </button>
              </div>
            )}
            <span className="shrink-0">{formatTime(s.updated_at)}</span>
          </div>
          {snippet && (
            <div className="text-[11px] text-muted-foreground/80 mt-1 line-clamp-2">
              {renderSearchText(snippet, `${s.id}-snippet`)}
            </div>
          )}
        </div>
      </li>
    );
  }

  return (
    <aside className="w-64 shrink-0 flex flex-col gap-2 p-2 pb-3">
      {/* 品牌区：无框、溶进浅灰底；仍保留 macOS traffic-light 留空（pt-8） */}
      <div
        className="h-16 px-5 pt-8 flex items-start drag-region"
        data-tauri-drag-region
      >
        <div className="flex items-end gap-2 pointer-events-none">
          <LoopingWebm
            src={animations.brandMark}
            className="h-7 w-7 rounded-md shadow-sm shrink-0"
          />
          {/* `Hebbian` 字号视觉跟 logo 高度对齐（h-7 = 28px）：
              text-2xl=24px + leading-none 让 cap-height 紧贴 logo；
              版本号小字 baseline 对齐 Hebbian 底（items-end + -mb-0.5 微调） */}
          <div
            className="flex items-end gap-1"
            title={`build ${BUILD_INFO.build} · ${BUILD_INFO.builtAt}`}
          >
            <span className="text-2xl font-semibold leading-none">Hebbian</span>
            <span className="text-[9px] font-mono leading-none text-muted-foreground/70 -mb-0.5">
              v{BUILD_INFO.version}·{BUILD_INFO.commit}
              {BUILD_INFO.dirty ? "+" : ""}
            </span>
          </div>
        </div>
      </div>

      {/* 列表卡：项目/对话切换 + 列表 + 底栏（hairline 分隔）全部聚到一块 */}
      {/* 左侧 sidebar 主体卡片（logo 下方的整张白卡）。双向阴影：朝右散得多（主投影），
          朝左散得少（薄薄一层让卡片左缘也跟窗口边脱开），整体浮起感更对称。 */}
      <div className="flex flex-1 min-h-0 flex-col rounded-3xl border border-border bg-card shadow-[10px_0_28px_-10px_rgba(0,0,0,0.28),-4px_0_16px_-8px_rgba(0,0,0,0.16)] overflow-hidden">
      <div className="px-3 py-3 no-drag">
        <div className="mb-2 grid grid-cols-2 gap-1 rounded-lg bg-muted/50 p-1">
          <button
            type="button"
            onClick={() => setProjectSidebarMode("projects")}
            className={cn(
              "h-8 rounded-md inline-flex items-center justify-center gap-1.5 text-xs font-medium transition-colors",
              projectSidebarMode === "projects"
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground"
            )}
          >
            <BriefcaseBusiness className="w-3.5 h-3.5" />
            项目
          </button>
          <button
            type="button"
            onClick={() => setProjectSidebarMode("all")}
            className={cn(
              "h-8 rounded-md inline-flex items-center justify-center gap-1.5 text-xs font-medium transition-colors",
              projectSidebarMode === "all"
                ? "bg-background text-foreground shadow-sm"
                : "text-muted-foreground hover:text-foreground"
            )}
          >
            <MessagesSquare className="w-3.5 h-3.5" />
            全部
          </button>
        </div>
        <Button
          onClick={handleCreateSession}
          className="w-full justify-between"
          size="md"
          disabled={creatingSession}
        >
          <span className="inline-flex items-center gap-1.5">
            <MessageSquarePlus className="w-4 h-4" />
            新建对话
          </span>
          <span className="ml-auto inline-flex items-center gap-0.5 text-[10px] font-medium text-primary-foreground/70">
            <Command className="h-3 w-3" />
            N
          </span>
        </Button>
        <button
          onClick={() => setImportClaudeOpen(true)}
          className="mt-1.5 w-full inline-flex items-center justify-center gap-1.5 text-xs text-muted-foreground hover:text-foreground no-drag"
        >
          <Download className="w-3.5 h-3.5" />
          从 Claude 导入
        </button>
      </div>

      <ImportClaudeDialog
        open={importClaudeOpen}
        onOpenChange={setImportClaudeOpen}
        onImported={async (id) => {
          await refreshSessions();
          await openSession(id);
        }}
      />

      {projectSidebarMode === "projects" && (
        <div className="px-3 pb-2 no-drag">
          {selectedProject ? (
            <div className="space-y-2 rounded-lg border border-border bg-background/60 p-2">
              <div className="flex items-center gap-1">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={closeProject}
                  title="返回项目列表"
                  className="shrink-0"
                >
                  <ArrowLeft className="w-4 h-4" />
                </Button>
                <div className="min-w-0">
                  <div className="truncate text-sm font-semibold">{selectedProject.name}</div>
                  {projectWorkdir(selectedProject) && (
                    <PathHint path={projectWorkdir(selectedProject)}>
                      <div className="truncate text-[11px] text-muted-foreground font-mono">
                        {pathLeaf(projectWorkdir(selectedProject))}
                      </div>
                    </PathHint>
                  )}
                </div>
              </div>
              <div className="space-y-2">
                <div className="space-y-1">
                  <div className="text-[11px] text-muted-foreground px-1">主目录</div>
                  <DirPicker
                    value={projectWorkdir(selectedProject)}
                    onChange={(v) => {
                      if (!v) return;
                      persistProjectProject(
                        selectedProject,
                        v,
                        projectAllowedPaths(selectedProject)
                      ).catch((err) => toast.error(err.message || String(err)));
                    }}
                  />
                </div>
                <PathListField
                  label="允许访问的路径"
                  paths={projectAllowedPaths(selectedProject)}
                  onChange={(paths) => {
                    persistProjectProject(selectedProject, projectWorkdir(selectedProject), paths).catch((err) =>
                      toast.error(err.message || String(err))
                    );
                  }}
                  emptyHint="暂无额外路径"
                  allowFiles
                  maxVisibleRows={5}
                  relativeTo={projectWorkdir(selectedProject)}
                />
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-between">
              <div className="text-xs font-semibold text-muted-foreground">项目列表</div>
              <div className="relative" ref={projectMenuRef}>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setProjectMenuOpen((v) => !v)}
                  title="添加项目"
                >
                  <Plus className="w-4 h-4" />
                </Button>
                {projectMenuOpen && (
                  <div
                    onClick={(e) => e.stopPropagation()}
                    className="absolute right-0 top-full mt-1 w-44 rounded-lg border border-border bg-card shadow-lg z-[90] overflow-hidden"
                  >
                    <button
                      type="button"
                      onClick={createProjectFromDialog}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-accent text-left"
                    >
                      <FolderKanban className="w-4 h-4 text-muted-foreground" />
                      新建项目
                    </button>
                    <button
                      type="button"
                      onClick={() => importProjectFile(false)}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-accent text-left"
                    >
                      <Upload className="w-4 h-4 text-muted-foreground" />
                      导入项目
                    </button>
                    <button
                      type="button"
                      onClick={() => importProjectFile(true)}
                      className="w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-accent text-left"
                    >
                      <FolderOpen className="w-4 h-4 text-muted-foreground" />
                      导入 VS Code 项目
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}

      {/* 搜索框 */}
      <div className="px-3 pb-2 no-drag">
        <div className="relative flex items-center">
          <Search className="w-3.5 h-3.5 absolute left-2.5 text-muted-foreground pointer-events-none" />
          <input
            ref={searchInputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="全局搜索标题 / 内容"
            spellCheck={false}
            autoCorrect="off"
            className="h-8 w-full rounded-md border border-input bg-background pl-8 pr-[5.75rem] text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring"
          />
          <div className="absolute right-1 flex items-center">
            <button
              onClick={() =>
                runSearch(query, searchCaseSensitive, !searchRegex).catch(() => {})
              }
              className={cn(
                "h-6 w-6 inline-flex items-center justify-center rounded text-muted-foreground hover:bg-accent",
                searchRegex && "bg-primary/20 text-primary"
              )}
              title={`正则表达式：${searchRegex ? "开" : "关"}`}
            >
              <Regex className="w-3.5 h-3.5" />
            </button>
            <button
              onClick={() =>
                runSearch(query, !searchCaseSensitive, searchRegex).catch(() => {})
              }
              className={cn(
                "h-6 w-6 inline-flex items-center justify-center rounded text-muted-foreground hover:bg-accent",
                searchCaseSensitive && "bg-primary/20 text-primary"
              )}
              title={`区分大小写：${searchCaseSensitive ? "开" : "关"}`}
            >
              <CaseSensitive className="w-3.5 h-3.5" />
            </button>
            {query && (
              <button
                onClick={() => {
                  setQuery("");
                  clearSearch();
                }}
                className="h-6 w-6 inline-flex items-center justify-center rounded text-muted-foreground hover:bg-accent"
                title="清除"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        </div>
        {searching && (
          <div className="text-[11px] text-muted-foreground mt-1 px-0.5">
            搜索中…
          </div>
        )}
        {searchResults && !searching && (
          <div className="text-[11px] text-muted-foreground mt-1 px-0.5">
            命中 {searchResults.length} 条
          </div>
        )}
      </div>

      <div className="flex-1 overflow-y-auto px-2 pb-2 no-drag">
        {projectSidebarMode === "projects" && !selectedProject ? (
          projects.length === 0 ? (
            <div className="text-center text-xs text-muted-foreground py-10 px-4">
              暂无项目，点击上方加号创建
            </div>
          ) : (
            <ul className="space-y-1">
              {projects.map((project) => {
                const count = sessions.filter((session) => sessionBelongsToProject(session, project)).length;
                return (
                  <li key={project.id}>
                    <div
                      onClick={() => openProject(project.id)}
                      className="group px-3 py-2 rounded-md cursor-pointer hover:bg-accent/50 transition-colors"
                    >
                      <div className="flex items-center gap-2">
                        <FolderKanban className="w-4 h-4 shrink-0 text-muted-foreground" />
                        <span className="min-w-0 flex-1 truncate text-sm font-medium">{project.name}</span>
                        <span className="text-[11px] text-muted-foreground">{count}</span>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            if (confirm(`删除项目 "${project.name}"？不会删除已有对话。`)) {
                              deleteProjectAction(project.id).catch((err) =>
                                toast.error(err.message || String(err))
                              );
                            }
                          }}
                          className="p-1 rounded hover:bg-background text-muted-foreground hover:text-destructive opacity-0 group-hover:opacity-100 transition-opacity"
                          title="删除项目"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                      {projectWorkdir(project) && (
                        <PathHint path={projectWorkdir(project)}>
                          <div className="mt-0.5 truncate text-[11px] text-muted-foreground font-mono">
                            {pathLeaf(projectWorkdir(project))}
                          </div>
                        </PathHint>
                      )}
                    </div>
                  </li>
                );
              })}
            </ul>
          )
        ) : (
          renderSessionList()
        )}
      </div>

      <div className="border-t border-border p-1.5 flex items-center gap-0.5 no-drag">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => setAppSettingsOpen(true)}
          title="设置"
        >
          <Settings className="w-4 h-4" />
        </Button>
        {currentSession && (
          <Button
            variant="ghost"
            size="icon"
            onClick={() => setSettingsOpen(true)}
            title={currentSession.project_id ? "项目设置" : "对话设置"}
          >
            <SlidersHorizontal className="w-4 h-4" />
          </Button>
        )}
        <div className="flex-1" />
        <Button
          variant="ghost"
          size="icon"
          onClick={toggleTheme}
          title="切换主题"
        >
          {theme === "dark" ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
        </Button>
      </div>
      </div>
    </aside>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { ChevronDown, ChevronRight, Trash2 } from "lucide-react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { invoke } from "@/desktop/bridge/transport";
import { Button } from "@/desktop/ui/components/ui/button";
import { Dialog } from "@/desktop/ui/components/ui/dialog";
import { Input, Label } from "@/desktop/ui/components/ui/input";
import { cn } from "@/desktop/ui/lib/utils";
import type { SkillCollection, SkillItem } from "@/desktop/ui/types";

// 老调用路径仍想从本文件 import SkillItem 时不破坏。
export type { SkillItem };

/** 跳过 SKILL.md 头部的 YAML frontmatter（`---\n...\n---\n`），只返回正文。 */
function stripFrontmatter(text: string): string {
  if (!text.startsWith("---")) return text;
  const lines = text.split("\n");
  // 第 0 行是 `---`；找下一个 `---` 行作为结束
  let end = -1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].trim() === "---") {
      end = i;
      break;
    }
  }
  if (end < 0) return text;
  return lines.slice(end + 1).join("\n").replace(/^\n+/, "");
}

/** 给 UI 用：把 collection.source 渲染成一行简短描述。 */
function formatSource(s: SkillCollection["source"]): string {
  if (s.kind === "github") {
    const base = s.repo_url.replace(/\.git$/, "").replace(/\/+$/, "");
    return s.subpath ? `${base} (${s.subpath})` : base;
  }
  if (s.kind === "local") {
    return s.path;
  }
  if (s.kind === "plugin") {
    return `plugin: ${s.plugin_name}`;
  }
  return s.src_dir;
}

type ScannedSkill = {
  name: string;
  relative_path: string;
  description: string;
  dir_path: string;
};

/**
 * Skills 管理面板：列出当前 workdir 加载的三层 skills，提供三种导入入口
 *  - 本地目录（Tauri dialog 选目录）
 *  - Git 仓库（`git clone --depth=1` 到临时目录后拷贝）
 *  - `~/.claude/skills`（一次性迁移）
 *
 * Scope 由调用方写死：AppSettingsDialog 永远 global、SessionSettingsDialog 永远 project。
 * 无 workdir 时 project scope 自动降级提示，不允许导入到项目层。
 */
export function SkillsPane({
  workdir,
  scope,
}: {
  workdir: string | null;
  scope: "global" | "project";
}) {
  const [skills, setSkills] = useState<SkillItem[]>([]);
  const [collections, setCollections] = useState<SkillCollection[]>([]);
  const [claudeSkills, setClaudeSkills] = useState<string[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [importing, setImporting] = useState(false);
  const [loading, setLoading] = useState(false);
  const [githubUrl, setGithubUrl] = useState("");
  const [githubSubpath, setGithubSubpath] = useState("");
  const [previewSkill, setPreviewSkill] = useState<SkillItem | null>(null);
  const [previewContent, setPreviewContent] = useState<string | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  // 扫描结果选择 modal 状态
  const [scanResults, setScanResults] = useState<ScannedSkill[] | null>(null);
  const [scanSelected, setScanSelected] = useState<Set<string>>(new Set());
  const [scanSource, setScanSource] = useState<
    { kind: "dir"; srcDir: string } | { kind: "github"; repoUrl: string; subpath: string | null } | null
  >(null);
  const [scanLoading, setScanLoading] = useState(false);
  const [scanImporting, setScanImporting] = useState(false);
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const effectiveWorkdir = workdir ?? "";
  const projectUnavailable = scope === "project" && !effectiveWorkdir;

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const wd = effectiveWorkdir || ".";
      const [list, claudeList, colls] = await Promise.all([
        invoke<SkillItem[]>("list_skills", { workdir: wd }),
        invoke<string[]>("list_claude_skills"),
        invoke<SkillCollection[]>("list_skill_collections"),
      ]);
      setSkills(list);
      setClaudeSkills(claudeList);
      setCollections(colls);
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setLoading(false);
    }
  }, [effectiveWorkdir]);

  // 架构 §6.1.3：把 skills 按 collection_id 分组——同一来源（GitHub 仓库 / 本地目录）
  // 一次性导入的归一组，未分组的（手放 / 老导入 / 非 Global source）归到末尾默认段。
  const grouped = useMemo(() => {
    const collMap = new Map<string, SkillCollection>();
    for (const c of collections) collMap.set(c.id, c);
    const byCollection = new Map<string, SkillItem[]>();
    const ungrouped: SkillItem[] = [];
    for (const s of skills) {
      if (s.collection_id && collMap.has(s.collection_id)) {
        const arr = byCollection.get(s.collection_id) ?? [];
        arr.push(s);
        byCollection.set(s.collection_id, arr);
      } else {
        ungrouped.push(s);
      }
    }
    // 用 collections 的原始顺序（按 imported_at append）渲染分组
    const orderedCollectionIds = collections
      .map((c) => c.id)
      .filter((id) => byCollection.has(id));
    return { byCollection, ungrouped, collMap, orderedCollectionIds };
  }, [skills, collections]);

  /**
   * 每组的展开状态——默认**全部折叠**（state 存"展开"集合，初始为空集）。
   * 用户展开过的会保留到下次 dialog 关闭重开（state 跟 component 生命周期一致），
   * reload() 不重置。卸载某 collection 后对应 id 仍可能留在 set 里——无害（渲染时
   * 找不到 collection 就不显示）。
   */
  const [expandedCollections, setExpandedCollections] = useState<Set<string>>(new Set());
  function toggleExpanded(id: string) {
    setExpandedCollections((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  /**
   * 整组启用/禁用：全启用 → 全禁；其他状态（全禁或部分）→ 全启。
   * 单个 skill 的 set_skill_enabled API 已有，前端 loop 调即可——批量
   * 通常 N≤20，不是 hot path 不值得加新后端 API。
   */
  async function toggleCollectionEnabled(items: SkillItem[]) {
    if (items.length === 0) return;
    const allOn = items.every((s) => s.enabled);
    const next = !allOn;
    try {
      for (const s of items) {
        if (s.enabled === next) continue;
        await invoke("set_skill_enabled", { name: s.name, enabled: next });
      }
      await reload();
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    }
  }

  async function uninstallCollection(c: SkillCollection) {
    const count = c.skills.length;
    if (
      !confirm(
        `卸载「${c.label}」整组？将删除 ${count} 个 skill 目录（来源：${formatSource(c.source)}）`
      )
    ) {
      return;
    }
    try {
      const deleted = await invoke<string[]>("delete_skill_collection", { id: c.id });
      toast.success(`已卸载「${c.label}」（${deleted.length} 个 skill）`);
      await reload();
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    }
  }

  useEffect(() => {
    reload();
  }, [reload]);

  // 同名 skill 是否已存在于当前 scope（→ 已导入）。用 source 区分：
  //  - scope=global → 看 skills 里 source=="global"
  //  - scope=project → 看 skills 里 source=="project"
  const installedNames = useMemo(() => {
    const want = scope === "global" ? "global" : "project";
    return new Set(skills.filter((s) => s.source === want).map((s) => s.name));
  }, [skills, scope]);

  function toggle(name: string) {
    if (installedNames.has(name)) return; // 已导入禁选
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(name)) next.delete(name);
      else next.add(name);
      return next;
    });
  }

  async function doImport() {
    if (selected.size === 0) {
      toast.error("请选择至少一个 skill");
      return;
    }
    if (projectUnavailable) {
      toast.error("当前对话没绑定项目，先去「目录与工具」选一个项目再来");
      return;
    }
    setImporting(true);
    try {
      const imported = await invoke<{ name: string; overwritten: boolean }[]>(
        "import_claude_skills",
        {
          scope,
          workdir: scope === "project" ? effectiveWorkdir : null,
          names: Array.from(selected),
          overwrite: true,
        }
      );
      toast.success(`已导入 ${imported.length} 个 skill`);
      setSelected(new Set());
      await reload();
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setImporting(false);
    }
  }

  async function doDelete(s: SkillItem) {
    if (s.source === "project_code") {
      toast.error("这条 skill 在你的项目代码里，去源文件改");
      return;
    }
    try {
      const wd = s.source === "project" ? effectiveWorkdir : null;
      await invoke<boolean>("delete_skill", {
        source: s.source,
        name: s.name,
        workdir: wd,
      });
      await reload();
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    }
  }

  async function doScanFromDir() {
    const { open } = await import("@tauri-apps/plugin-dialog");
    const result = await open({
      directory: true,
      multiple: false,
      title: "选一个目录开始扫描",
    });
    if (!result || Array.isArray(result)) return;
    if (projectUnavailable) {
      toast.error("当前对话没绑定项目，先去「目录与工具」选一个项目再来");
      return;
    }
    setScanLoading(true);
    try {
      const scanned = await invoke<ScannedSkill[]>("scan_skill_dir", {
        srcDir: result,
      });
      if (scanned.length === 0) {
        toast.error("目录里没找到 SKILL.md");
        return;
      }
      setScanResults(scanned);
      setScanSelected(new Set(scanned.map((s) => s.dir_path)));
      setScanSource({ kind: "dir", srcDir: result });
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setScanLoading(false);
    }
  }

  async function doScanFromGithub() {
    const url = githubUrl.trim();
    if (!url) {
      toast.error("请输入 git 仓库 URL");
      return;
    }
    if (projectUnavailable) {
      toast.error("当前对话没绑定项目，先去「目录与工具」选一个项目再来");
      return;
    }
    setScanLoading(true);
    try {
      const subpath = githubSubpath.trim() || null;
      const scanned = await invoke<ScannedSkill[]>("scan_skill_github", {
        repoUrl: url,
        subpath,
      });
      if (scanned.length === 0) {
        toast.error("仓库里没找到 SKILL.md");
        return;
      }
      setScanResults(scanned);
      setScanSelected(new Set(scanned.map((s) => s.dir_path)));
      setScanSource({ kind: "github", repoUrl: url, subpath });
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setScanLoading(false);
    }
  }

  async function confirmScanImport() {
    if (!scanResults || !scanSource) return;
    if (scanSelected.size === 0) {
      toast.error("请至少选一个 skill");
      return;
    }
    // scanSelected 用 dir_path 当**勾选标识**（绝对路径，scanResults 内永远唯一，
    // 不怕同名不同层级撞 key）；但传给后端 import 必须用 **relative_path**——
    // 后端 import_from_dir / import_from_github 会重新 scan 一次 src_dir 拿到
    // 新一批 ScannedSkill 再按 relative_path filter。GitHub 场景尤其重要：
    // scan 时 clone 到 /tmp/hebbian-scan-<uuidA>，import 时又 clone 到 uuidB，
    // 两次的绝对 dir_path 完全不同，只有 relative_path 跨调用稳定。
    const chosen = scanResults.filter((s) => scanSelected.has(s.dir_path));
    const selectedPaths = chosen.map((s) => s.relative_path);
    setScanImporting(true);
    try {
      let imported: { name: string; overwritten: boolean }[];
      if (scanSource.kind === "dir") {
        imported = await invoke("import_skills_from_dir", {
          scope,
          srcDir: scanSource.srcDir,
          workdir: scope === "project" ? effectiveWorkdir : null,
          selectedPaths,
          overwrite: true,
        });
      } else {
        imported = await invoke("import_skills_from_github", {
          scope,
          repoUrl: scanSource.repoUrl,
          subpath: scanSource.subpath,
          workdir: scope === "project" ? effectiveWorkdir : null,
          selectedPaths,
          overwrite: true,
        });
      }
      toast.success(`已导入 ${imported.length} 个 skill`);
      setScanResults(null);
      setScanSource(null);
      setScanSelected(new Set());
      if (scanSource.kind === "github") {
        setGithubUrl("");
        setGithubSubpath("");
      }
      await reload();
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    } finally {
      setScanImporting(false);
    }
  }

  function toggleScanItem(dirPath: string) {
    setScanSelected((prev) => {
      const next = new Set(prev);
      if (next.has(dirPath)) next.delete(dirPath);
      else next.add(dirPath);
      return next;
    });
  }

  async function toggleSkillEnabled(s: SkillItem) {
    try {
      await invoke("set_skill_enabled", {
        name: s.name,
        enabled: !s.enabled,
      });
      await reload();
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
    }
  }

  async function openPreview(s: SkillItem) {
    setPreviewSkill(s);
    setPreviewContent(null);
    setPreviewLoading(true);
    try {
      const text = await invoke<string>("read_skill_md", { path: s.path });
      setPreviewContent(stripFrontmatter(text));
    } catch (e: any) {
      toast.error(e?.message ?? String(e));
      setPreviewSkill(null);
    } finally {
      setPreviewLoading(false);
    }
  }

  return (
    <>
    <div className="space-y-5">
      {projectUnavailable && (
        <div className="text-xs px-2 py-1.5 rounded border border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-300">
          当前对话没绑定项目；要装到「当前项目」需要先去「目录与工具」选一个项目，或换到应用全局设置里管理 Skills。
        </div>
      )}

      <section className="space-y-2">
        <div className="flex items-center justify-between">
          <Label>已加载的 Skills</Label>
          {loading && <span className="text-xs text-muted-foreground">加载中…</span>}
        </div>
        <p className="text-xs text-muted-foreground">
          点击任一条预览内容；勾选框控制是否启用，禁用后模型不会看到这个 skill。
        </p>
        {skills.length === 0 ? (
          <p className="text-xs text-muted-foreground">暂无</p>
        ) : (
          <div className="space-y-3">
            {/* 按集合分组：每组带折叠 chevron + 三态组开关 + label + 来源 + 卸载按钮 */}
            {grouped.orderedCollectionIds.map((cid) => {
              const meta = grouped.collMap.get(cid)!;
              const items = grouped.byCollection.get(cid)!;
              const isExpanded = expandedCollections.has(cid);
              const enabledCount = items.filter((s) => s.enabled).length;
              const groupState: "all" | "none" | "partial" =
                enabledCount === items.length
                  ? "all"
                  : enabledCount === 0
                  ? "none"
                  : "partial";
              return (
                <div key={cid} className="rounded border">
                  <div className="flex items-center justify-between gap-2 px-2 py-1.5 bg-muted/30">
                    <button
                      type="button"
                      onClick={() => toggleExpanded(cid)}
                      className="flex items-center gap-1.5 min-w-0 flex-1 text-left hover:opacity-80"
                      title={isExpanded ? "折叠" : "展开"}
                    >
                      {isExpanded ? (
                        <ChevronDown className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                      ) : (
                        <ChevronRight className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                      )}
                      <GroupCheckbox
                        state={groupState}
                        onToggle={() => toggleCollectionEnabled(items)}
                        label={
                          groupState === "all"
                            ? `禁用整组「${meta.label}」`
                            : `启用整组「${meta.label}」`
                        }
                      />
                      <div className="min-w-0 flex-1">
                        <div className="text-sm font-medium truncate">
                          {meta.label}
                          <span className="ml-2 text-xs text-muted-foreground font-normal">
                            {items.length} 个
                            {groupState === "partial" && (
                              <span className="ml-1">· 已启用 {enabledCount}</span>
                            )}
                          </span>
                        </div>
                        <div className="text-[10px] text-muted-foreground truncate">
                          {formatSource(meta.source)}
                        </div>
                      </div>
                    </button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => uninstallCollection(meta)}
                      title={`卸载整组「${meta.label}」`}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                      <span className="ml-1 text-xs">卸载组</span>
                    </Button>
                  </div>
                  {isExpanded && (
                    <ul className="space-y-1 p-1 border-t">
                      {items.map((s) => (
                        <SkillRow
                          key={`${s.source}:${s.name}`}
                          s={s}
                          onToggleEnabled={toggleSkillEnabled}
                          onPreview={openPreview}
                          onDelete={doDelete}
                        />
                      ))}
                    </ul>
                  )}
                </div>
              );
            })}

            {/* 未分组：手放 / 老导入的 Global + Project + ProjectCode 全归这里 */}
            {grouped.ungrouped.length > 0 && (
              <div>
                {grouped.orderedCollectionIds.length > 0 && (
                  <div className="text-[10px] uppercase tracking-wider text-muted-foreground/80 px-1 pb-1">
                    未分组
                  </div>
                )}
                <ul className="space-y-1">
                  {grouped.ungrouped.map((s) => (
                    <SkillRow
                      key={`${s.source}:${s.name}`}
                      s={s}
                      onToggleEnabled={toggleSkillEnabled}
                      onPreview={openPreview}
                      onDelete={doDelete}
                    />
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}
      </section>

      <section className="space-y-2">
        <Label>从本地目录导入</Label>
        <p className="text-xs text-muted-foreground">
          选一个目录，自动扫描里面所有 skill，让你挑哪些导入。
        </p>
        <Button onClick={doScanFromDir} disabled={scanLoading || projectUnavailable}>
          {scanLoading ? "扫描中…" : "选择目录…"}
        </Button>
      </section>

      <section className="space-y-2">
        <Label>从 Git 仓库导入</Label>
        <p className="text-xs text-muted-foreground">
          需要本机装了 git。下载下来扫描完，未导入的部分会自动清理。
        </p>
        <Input
          value={githubUrl}
          onChange={(e) => setGithubUrl(e.target.value)}
          placeholder="https://github.com/user/repo.git"
        />
        <Input
          value={githubSubpath}
          onChange={(e) => setGithubSubpath(e.target.value)}
          placeholder="子路径（可选）例如 skills/ 或 .claude/skills/"
        />
        <Button
          onClick={doScanFromGithub}
          disabled={scanLoading || !githubUrl.trim() || projectUnavailable}
        >
          {scanLoading ? "扫描中…" : "扫描仓库"}
        </Button>
      </section>

