    {scanResults && scanSource && (
      <div className="fixed inset-0 z-[110]">
        <div
          className="absolute inset-0 bg-foreground/30"
          onClick={() => {
            if (!scanImporting) {
              setScanResults(null);
              setScanSource(null);
              setScanSelected(new Set());
            }
          }}
        />
        <div
          className="absolute inset-3 grid grid-rows-[auto_minmax(0,1fr)_auto] overflow-hidden rounded-xl border border-border bg-background shadow-2xl"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="flex min-h-10 items-center justify-between gap-3 border-b border-border bg-muted/30 px-3">
            <div className="min-w-0 truncate text-[13px]">
              <strong>选择要导入的 skill</strong>
              <span className="ml-2 text-xs text-muted-foreground font-normal">
                {scanSource.kind === "dir"
                  ? scanSource.srcDir
                  : `${scanSource.repoUrl}${scanSource.subpath ? ` / ${scanSource.subpath}` : ""}`}
                · 共 {scanResults.length} 个
              </span>
            </div>
            <button
              type="button"
              onClick={() => {
                if (!scanImporting) {
                  setScanResults(null);
                  setScanSource(null);
                  setScanSelected(new Set());
                }
              }}
              className="inline-flex h-7 w-7 items-center justify-center rounded-md border border-border bg-background text-muted-foreground hover:text-foreground"
              aria-label="关闭"
              disabled={scanImporting}
            >
              ×
            </button>
          </div>
          <div className="min-h-0 overflow-auto p-4">
            {(() => {
              // 按 relative_path 第一段分组；relative_path 为空（顶层就是单 skill）归到 "."
              const groups = new Map<string, ScannedSkill[]>();
              for (const s of scanResults) {
                const first = s.relative_path.split(/[\\/]/)[0] || ".";
                const arr = groups.get(first) ?? [];
                arr.push(s);
                groups.set(first, arr);
              }
              const entries = Array.from(groups.entries()).sort((a, b) =>
                a[0].localeCompare(b[0])
              );

              const renderItem = (s: ScannedSkill, indent: boolean) => (
                <li key={s.dir_path}>
                  <label
                    className={cn(
                      "flex items-start gap-2 px-2 py-1.5 rounded border hover:bg-accent/40 cursor-pointer",
                      indent && "ml-5"
                    )}
                  >
                    <input
                      type="checkbox"
                      checked={scanSelected.has(s.dir_path)}
                      onChange={() => toggleScanItem(s.dir_path)}
                      className="mt-1 h-3.5 w-3.5 rounded"
                    />
                    <div className="min-w-0 flex-1">
                      <div className="font-mono text-sm">{s.name}</div>
                      {s.description && (
                        <div className="text-xs text-muted-foreground line-clamp-2">
                          {s.description}
                        </div>
                      )}
                    </div>
                  </label>
                </li>
              );

              return (
                <ul className="space-y-1.5">
                  {entries.map(([group, items]) => {
                    // 单条 skill 直接展示，不需要分组头
                    if (items.length === 1) {
                      return renderItem(items[0], false);
                    }
                    const open = expandedGroups.has(group);
                    const allOn = items.every((s) => scanSelected.has(s.dir_path));
                    const someOn = items.some((s) => scanSelected.has(s.dir_path));
                    return (
                      <li key={group} className="space-y-1">
                        <div className="flex items-center gap-2 px-2 py-1.5 rounded border bg-muted/20">
                          <button
                            type="button"
                            onClick={() => {
                              const next = new Set(expandedGroups);
                              if (open) next.delete(group);
                              else next.add(group);
                              setExpandedGroups(next);
                            }}
                            className="shrink-0 text-muted-foreground hover:text-foreground"
                            aria-label={open ? "收起" : "展开"}
                          >
                            {open ? (
                              <ChevronDown className="w-4 h-4" />
                            ) : (
                              <ChevronRight className="w-4 h-4" />
                            )}
                          </button>
                          <input
                            type="checkbox"
                            checked={allOn}
                            ref={(el) => {
                              if (el) el.indeterminate = !allOn && someOn;
                            }}
                            onChange={() => {
                              const next = new Set(scanSelected);
                              for (const s of items) {
                                if (allOn) next.delete(s.dir_path);
                                else next.add(s.dir_path);
                              }
                              setScanSelected(next);
                            }}
                            className="h-3.5 w-3.5 rounded shrink-0"
                            aria-label={allOn ? `取消勾选 ${group} 全部` : `勾选 ${group} 全部`}
                          />
                          <button
                            type="button"
                            onClick={() => {
                              const next = new Set(expandedGroups);
                              if (open) next.delete(group);
                              else next.add(group);
                              setExpandedGroups(next);
                            }}
                            className="min-w-0 flex-1 text-left"
                          >
                            <span className="font-mono text-sm">{group}</span>
                            <span className="ml-2 text-[11px] text-muted-foreground">
                              {items.length} 个
                            </span>
                          </button>
                        </div>
                        {open && (
                          <ul className="space-y-1">
                            {items.map((s) => renderItem(s, true))}
                          </ul>
                        )}
                      </li>
                    );
                  })}
                </ul>
              );
            })()}
          </div>
          <div className="flex items-center justify-between gap-3 border-t border-border bg-muted/30 px-3 py-2">
            <div className="text-xs text-muted-foreground">
              已选 {scanSelected.size} / {scanResults.length}（写入
              {scope === "project" ? "当前项目" : "全局"}）
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                onClick={() => {
                  if (!scanImporting) {
                    setScanResults(null);
                    setScanSource(null);
                    setScanSelected(new Set());
                  }
                }}
                disabled={scanImporting}
              >
                取消
              </Button>
              <Button
                onClick={confirmScanImport}
                disabled={scanImporting || scanSelected.size === 0}
              >
                {scanImporting ? "导入中…" : `导入 ${scanSelected.size} 个`}
              </Button>
            </div>
          </div>
        </div>
      </div>
    )}
    </>
  );
}

/**
 * 三态分组开关。
 * - `all`：勾选（点击 = 全禁）
 * - `none`：未勾选（点击 = 全启）
 * - `partial`：indeterminate（点击 = 全启——朝"启用"方向收敛比"禁用"更友好）
 *
 * 用原生 `<input type="checkbox">` + 手动设 `indeterminate`（React 不通过 props 控制
 * 这个属性，必须用 ref / effect）；点击事件 stopPropagation 避免冒泡触发组 header 折叠。
 */
function GroupCheckbox({
  state,
  onToggle,
  label,
}: {
  state: "all" | "none" | "partial";
  onToggle: () => void;
  label: string;
}) {
  const ref = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (ref.current) ref.current.indeterminate = state === "partial";
  }, [state]);
  return (
    <input
      ref={ref}
      type="checkbox"
      checked={state === "all"}
      onChange={(e) => {
        e.stopPropagation();
        onToggle();
      }}
      onClick={(e) => e.stopPropagation()}
      className="h-3.5 w-3.5 rounded shrink-0"
      aria-label={label}
      title={label}
    />
  );
}

/**
 * 单条 skill 行——分组内 / 未分组两条渲染路径复用。
 *
 * source 徽标保留：即使在集合分组里也用色块区分 global/project/project_code，
 * 避免用户混淆"这是哪一层"。
 */
function SkillRow({
  s,
  onToggleEnabled,
  onPreview,
  onDelete,
}: {
  s: SkillItem;
  onToggleEnabled: (s: SkillItem) => void;
  onPreview: (s: SkillItem) => void;
  onDelete: (s: SkillItem) => void;
}) {
  return (
    <li>
      <div
        className={cn(
          "flex items-start gap-2 px-2 py-1.5 rounded border hover:bg-accent/40 transition-colors",
          !s.enabled && "opacity-50"
        )}
      >
        <input
          type="checkbox"
          checked={s.enabled}
          onChange={() => onToggleEnabled(s)}
          className="mt-1 h-3.5 w-3.5 rounded shrink-0"
          aria-label={s.enabled ? `禁用 ${s.name}` : `启用 ${s.name}`}
          title={s.enabled ? "启用中（取消勾选 = 禁用）" : "已禁用"}
        />
        <span
          className={cn(
            "shrink-0 mt-0.5 px-1.5 py-0.5 text-[10px] rounded font-medium",
            s.source === "global" && "bg-blue-500/15 text-blue-700 dark:text-blue-300",
            s.source === "project" && "bg-purple-500/15 text-purple-700 dark:text-purple-300",
            s.source === "project_code" && "bg-zinc-500/15 text-zinc-700 dark:text-zinc-300"
          )}
        >
          {s.source}
        </span>
        <button
          type="button"
          onClick={() => onPreview(s)}
          className="min-w-0 flex-1 text-left cursor-pointer"
        >
          <div className="font-mono text-sm">{s.name}</div>
          <div className="text-xs text-muted-foreground line-clamp-2">{s.description}</div>
        </button>
        {s.source !== "project_code" && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onDelete(s)}
            aria-label={`删除 ${s.name}`}
          >
            <Trash2 className="w-3.5 h-3.5" />
          </Button>
        )}
      </div>
    </li>
  );
}

import { Fragment, useEffect, useMemo, useRef, useState } from "react";

import { cn } from "@/desktop/ui/lib/utils";
import type { SlashCommandMeta } from "@/desktop/ui/lib/slashCommands";

interface Props {
  disabled?: boolean;
  /** 由上层装配（内置 + 动态 skills）；空数组时按钮仍可点开但 popup 显示提示。 */
  commands: SlashCommandMeta[];
  /** 用户点中一条命令时回调；调用方把 `//<name> ` 写入输入框并 focus 末尾。 */
  onPick: (cmd: SlashCommandMeta) => void;
}

const SOURCE_LABEL: Record<string, string> = {
  global: "global",
  project: "project",
  project_code: "code",
};

/**
 * 工具栏按钮：点击弹出已注册的 `//` 命令清单。
 *
 * 按 §8 的"前端拦截"原则，本组件只负责把命令模板写到输入框——真正派发由
 * `dispatchSlashCommand` 在 ChatInput 的 submit 路径完成。Popup 分两组：
 * - 内置控制命令（builtin）
 * - Skills（按 source 角标区分 global / project / project_code）
 */
export function SlashCommandButton({ disabled, commands, onPick }: Props) {
  const [open, setOpen] = useState(false);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onClick(event: MouseEvent) {
      if (
        wrapperRef.current &&
        !wrapperRef.current.contains(event.target as Node)
      ) {
        setOpen(false);
      }
    }
    window.addEventListener("click", onClick);
    return () => window.removeEventListener("click", onClick);
  }, [open]);

  const { builtins, skills } = useMemo(() => {
    const builtins: SlashCommandMeta[] = [];
    const skills: SlashCommandMeta[] = [];
    for (const c of commands) {
      if (c.kind === "skill") skills.push(c);
      else builtins.push(c);
    }
    return { builtins, skills };
  }, [commands]);

  return (
    <div className="relative" ref={wrapperRef}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        disabled={disabled}
        className={cn(
          "h-8 w-8 rounded-md inline-flex items-center justify-center bg-transparent text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-40 disabled:pointer-events-none",
          open && "bg-muted text-foreground"
        )}
        title="插入命令"
        aria-label="插入命令"
      >
        <span
          className={cn(
            "inline-flex h-4 w-4 items-center justify-center rounded-[3px]",
            "border border-current text-[9px] leading-none font-medium"
          )}
        >
          /
        </span>
      </button>
      {open && (
        <div
          onClick={(e) => e.stopPropagation()}
          className="absolute bottom-full left-0 mb-1 min-w-[300px] max-w-[420px] max-h-[60vh] overflow-y-auto rounded-lg border border-border bg-card shadow-lg z-[90] animate-slide-up"
        >
          {builtins.length === 0 && skills.length === 0 ? (
            <div className="px-3 py-2 text-xs text-muted-foreground">
              暂无可用命令
            </div>
          ) : (
            <>
              {builtins.length > 0 && (
                <CommandSection title="命令" items={builtins} onPick={(c) => { setOpen(false); onPick(c); }} />
              )}
              {skills.length > 0 && (
                <CommandSection
                  title="Skills"
                  items={skills}
                  onPick={(c) => { setOpen(false); onPick(c); }}
                />
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
}

function CommandSection({
  title,
  items,
  onPick,
}: {
  title: string;
  items: SlashCommandMeta[];
  onPick: (cmd: SlashCommandMeta) => void;
}) {
  return (
    <div>
      <div className="px-3 pt-2 pb-1 text-[10px] font-medium uppercase tracking-wider text-muted-foreground/80">
        {title}
      </div>
      {/* hairline 用 `mx-3` 缩进，左右离 popup 边界留 12px；hover bg 仍然全宽到边 */}
      {items.map((cmd, i) => (
        <Fragment key={`${cmd.kind}:${cmd.name}`}>
          {i > 0 && <div className="h-px bg-border mx-3" />}
        <button
          type="button"
          onClick={() => onPick(cmd)}
          className="w-full flex items-center justify-between gap-3 px-3 py-2 text-sm hover:bg-accent text-left"
        >
          <div className="flex flex-col min-w-0 flex-1">
            <span className="font-mono text-foreground truncate">
              //{cmd.name}{cmd.args ? " " : ""}
              {cmd.args && (
                <span className="text-muted-foreground">{cmd.args}</span>
              )}
            </span>
            {cmd.desc && (
              <span className="text-xs text-muted-foreground truncate">
                {cmd.desc}
              </span>
            )}
          </div>
          {cmd.kind === "skill" && cmd.skillSource && (
            <span className="shrink-0 rounded bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
              {SOURCE_LABEL[cmd.skillSource] ?? cmd.skillSource}
            </span>
          )}
        </button>
        </Fragment>
      ))}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { AlertTriangle, Info, X, XCircle } from "lucide-react";

import { useToastStore, type ModelToast } from "@/desktop/ui/store/useToastStore";

/** 无 hover 时单条 toast 的自动关闭时长（ms）。 */
const AUTO_DISMISS_MS = 8000;

const LEVEL_STYLE: Record<ModelToast["level"], { icon: typeof Info; cls: string }> = {
  info: { icon: Info, cls: "border-border bg-background/95 text-foreground" },
  warn: {
    icon: AlertTriangle,
    cls: "border-amber-500/40 bg-amber-50/95 text-amber-900 dark:bg-amber-950/80 dark:text-amber-100",
  },
  error: {
    icon: XCircle,
    cls: "border-red-500/40 bg-red-50/95 text-red-900 dark:bg-red-950/80 dark:text-red-100",
  },
};

function ToastCard({ toast }: { toast: ModelToast }) {
  const dismiss = useToastStore((s) => s.dismiss);
  // 入场动画：先挂载在屏幕右侧外，下一帧滑入。
  const [shown, setShown] = useState(false);
  const hovering = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const armTimer = () => {
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      if (!hovering.current) dismiss(toast.id);
    }, AUTO_DISMISS_MS);
  };

  useEffect(() => {
    const raf = requestAnimationFrame(() => setShown(true));
    armTimer();
    return () => {
      cancelAnimationFrame(raf);
      if (timer.current) clearTimeout(timer.current);
    };
    // toast.id 稳定，仅挂载时跑一次。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const { icon: Icon, cls } = LEVEL_STYLE[toast.level];

  return (
    <div
      onMouseEnter={() => {
        hovering.current = true;
        if (timer.current) clearTimeout(timer.current);
      }}
      onMouseLeave={() => {
        hovering.current = false;
        armTimer();
      }}
      className={`pointer-events-auto flex w-[min(28rem,calc(100vw-3rem))] items-start gap-2 rounded-lg border px-3 py-2 text-sm shadow-lg backdrop-blur transition-all duration-300 ease-out ${cls} ${
        shown ? "translate-x-0 opacity-100" : "translate-x-full opacity-0"
      }`}
    >
      <Icon className="mt-0.5 h-4 w-4 shrink-0" />
      <span className="min-w-0 flex-1 break-words leading-snug">{toast.message}</span>
      <button
        type="button"
        onClick={() => dismiss(toast.id)}
        className="mt-0.5 shrink-0 rounded p-0.5 opacity-60 transition-opacity hover:opacity-100"
        aria-label="关闭"
      >
        <X className="h-3.5 w-3.5" />
      </button>
    </div>
  );
}

/**
 * 输入框上方右侧的模型异常退出 toast 区（架构 §7.3）。
 * 容器底对齐 + 右对齐：新消息追加在底部，旧的被往上挤；每条右→左滑入；hover 暂停关闭。
 */
export function ToastRegion() {
  const toasts = useToastStore((s) => s.toasts);
  if (toasts.length === 0) return null;
  return (
    <div className="pointer-events-none flex flex-col items-end gap-2 px-3 pb-2">
      {toasts.map((t) => (
        <ToastCard key={t.id} toast={t} />
      ))}
    </div>
  );
}

import { todoBlocksForDisplay } from "./todoBlocksForDisplay";

type Todo = { id: string; content: string; status: string };

function expectOrder(name: string, actual: string[], expected: string[]) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    throw new Error(`${name}: expected ${e}, got ${a}`);
  }
}

const fallback = [
  {
    key: "history",
    todos: [{ id: "old", content: "old task", status: "completed" }],
    ts: 1,
    streaming: false,
  },
];

const activeTodos: Todo[] = [
  { id: "active", content: "active task", status: "in_progress" },
];

const activeBlocks = todoBlocksForDisplay(activeTodos, fallback, 2);
expectOrder(
  "uses active run todo snapshot before persisted history",
  activeBlocks.map((block) => block.key),
  ["active-run"]
);
expectOrder(
  "keeps active run todos in the visible block",
  activeBlocks[0].todos.map((todo) => todo.id),
  ["active"]
);

expectOrder(
  "falls back to persisted todo blocks when there is no active snapshot",
  todoBlocksForDisplay([], fallback, 2).map((block) => block.key),
  ["history"]
);

export type TodoDisplayBlock<TTodo> = {
  key: string;
  todos: TTodo[];
  ts: number;
  streaming: boolean;
};

export function todoBlocksForDisplay<TTodo>(
  activeTodos: TTodo[] | null | undefined,
  fallbackBlocks: Array<TodoDisplayBlock<TTodo>>,
  now: number = Date.now()
): Array<TodoDisplayBlock<TTodo>> {
  if (activeTodos && activeTodos.length > 0) {
    return [
      {
        key: "active-run",
        todos: activeTodos,
        ts: now,
        streaming: true,
      },
    ];
  }
  return fallbackBlocks;
}

import { useMemo, useState } from "react";
import { Check, ChevronDown, ChevronRight, Circle, ListTodo } from "lucide-react";
