import {
  isTaskListTool,
  parseTodos,
  type TodoItem,
  type TodoStatus,
} from "./MessageBubble";
import { todoBlocksForDisplay, type TodoDisplayBlock } from "./todoBlocksForDisplay";
import type { Session, StreamingAssistantPart } from "@/desktop/ui/types";

/**
 * 右侧工作台「任务清单」tab。
 *
 * 数据派生：扫 currentSession.messages + 当前 streamingParts 里所有 TodoWrite
 * 调用，每次调用 → 一次"快照"。同一份 list 的多次更新（pending → completed）
 * 通过 **id 重叠 / content 重叠** 归并成同一个块；新一轮独立任务集形成新块。
 *
 * 渲染：blocks 倒序——最新在最上面（默认展开），旧块在下（默认折叠）。
 * 折叠头**只放图标 + 进度条 + N/M**，不写文字标题——窄 sidebar 才不会被挤崩。
 */
export function TodoTab() {
  const currentSession = useStore((s) => s.currentSession);
  const streamingParts = useStore((s) => s.streamingParts);
  const todos = useStore((s) => s.todos);

  const fallbackBlocks = useMemo(
    () => extractTodoBlocks(currentSession ?? undefined, streamingParts),
    [currentSession, streamingParts],
  );
  const blocks = useMemo(
    () => todoBlocksForDisplay(todos, fallbackBlocks),
    [todos, fallbackBlocks],
  );

  if (!currentSession) {
    return (
      <div className="p-4 text-xs text-muted-foreground">打开对话后会显示任务清单。</div>
    );
  }
  if (blocks.length === 0) {
    return (
      <div className="p-4 text-xs text-muted-foreground">
        Agent 调用 TodoWrite 时自动填入。
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      <div className="min-h-0 flex-1 space-y-2 overflow-auto px-2 py-2">
        {blocks.map((block, idx) => (
          <TodoBlock key={block.key} block={block} defaultOpen={idx === 0} />
        ))}
      </div>
    </div>
  );
}

type Block = TodoDisplayBlock<TodoItem>;

function TodoBlock({ block, defaultOpen }: { block: Block; defaultOpen: boolean }) {
  const total = block.todos.length;
  const completed = block.todos.filter((t) => t.status === "completed").length;
  const inProgress = block.todos.filter((t) => t.status === "in_progress").length;
  const allDone = total > 0 && completed === total;
  const ratio = total > 0 ? Math.round((completed / total) * 100) : 0;
  const [open, setOpen] = useState(defaultOpen);

  // 配色：全部完成淡绿，否则淡黄
  const headerCls = allDone
    ? "bg-emerald-500/10 text-emerald-800 hover:bg-emerald-500/15 dark:text-emerald-200"
    : "bg-amber-500/10 text-amber-800 hover:bg-amber-500/15 dark:text-amber-200";
  const barTrackCls = allDone ? "bg-emerald-500/15" : "bg-amber-500/15";
  const barFillCls = allDone ? "bg-emerald-500/70" : "bg-amber-500/70";

  return (
    <div
      className={cn(
        "overflow-hidden rounded-lg border border-border/60 bg-card transition-shadow",
        // 大卡片：左偏的普通模糊阴影，hover 时颜色加深
        "shadow-[-6px_4px_14px_-4px_rgba(0,0,0,0.14),-2px_1px_4px_-2px_rgba(0,0,0,0.08)]",
        "dark:shadow-[-6px_4px_14px_-4px_rgba(0,0,0,0.5),-2px_1px_4px_-2px_rgba(0,0,0,0.35)]",
        "hover:shadow-[-6px_4px_14px_-4px_rgba(0,0,0,0.22),-2px_1px_4px_-2px_rgba(0,0,0,0.14)]",
        "dark:hover:shadow-[-6px_4px_14px_-4px_rgba(0,0,0,0.65),-2px_1px_4px_-2px_rgba(0,0,0,0.45)]",
      )}
    >
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className={cn(
          "flex w-full items-center gap-1.5 px-2 py-1.5 text-xs transition-colors",
          headerCls,
        )}
        title={open ? "收起" : "展开"}
      >
        {open ? (
          <ChevronDown className="h-3 w-3 shrink-0" />
        ) : (
          <ChevronRight className="h-3 w-3 shrink-0" />
        )}
        {allDone ? (
          <Check className="h-3.5 w-3.5 shrink-0" strokeWidth={3} />
        ) : (
          <ListTodo className="h-3.5 w-3.5 shrink-0" />
        )}
        <div className={cn("h-1.5 flex-1 overflow-hidden rounded-full", barTrackCls)}>
          <div
            className={cn("h-full transition-all", barFillCls)}
            style={{ width: `${ratio}%` }}
          />
        </div>
        <span className="shrink-0 font-mono text-[11px] tabular-nums">
          {completed}/{total}
        </span>
        {inProgress > 0 && !allDone && (
          <span
            className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500"
            title={`${inProgress} 进行中`}
          />
        )}
      </button>
      {open && (
        <ul className="space-y-1.5 border-t border-border/40 bg-muted/20 px-2 py-2">
          {block.todos.map((it, i) => (
            <li
              key={it.id ?? `${block.key}-${i}`}
              className={cn(
                "group/item flex items-start gap-2 rounded-md border border-border/60 bg-background px-2.5 py-1.5 text-sm leading-snug transition-all",
                // 默认：与大卡片同款的左偏模糊散开阴影（轻量版）
                "shadow-[-3px_2px_8px_-2px_rgba(0,0,0,0.10),-1px_1px_2px_-1px_rgba(0,0,0,0.06)]",
                "dark:shadow-[-3px_2px_8px_-2px_rgba(0,0,0,0.45),-1px_1px_2px_-1px_rgba(0,0,0,0.3)]",
                // hover：切换成 neobrutalism 左下错位硬阴影 + 卡片右上微抬
                "hover:shadow-[-6px_8px_4px_1px_rgba(0,0,0,0.50),-18px_21px_14px_-1px_rgba(0,0,0,0.16)] dark:hover:shadow-[-6px_8px_4px_1px_rgba(0,0,0,0.75),-18px_21px_14px_-1px_rgba(0,0,0,0.40)]",
                "hover:translate-x-px hover:-translate-y-px hover:border-border",
                it.status === "completed"
                  ? "bg-emerald-50/60 text-emerald-900 dark:bg-emerald-500/[0.08] dark:text-emerald-100"
                  : "bg-amber-50/60 text-amber-900 dark:bg-amber-500/[0.08] dark:text-amber-100",
              )}
            >
              <StatusIndicator status={it.status} />
              <span className="min-w-0 break-words">
                {it.status === "in_progress" && it.activeForm ? it.activeForm : it.content}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function StatusIndicator({ status }: { status: TodoStatus }) {
  if (status === "completed") {
    return (
      <span
        aria-label="已完成"
        className="mt-0.5 inline-flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-emerald-500 text-[10px] text-white"
      >
        ✓
      </span>
    );
  }
  if (status === "in_progress") {
    return (
      <span
        aria-label="进行中"
        className="mt-0.5 inline-flex h-4 w-4 shrink-0 items-center justify-center rounded-full border-2 border-amber-500"
      >
        <span className="h-0.5 w-2 bg-amber-500" />
      </span>
    );
  }
  return <Circle className="mt-0.5 h-4 w-4 shrink-0 text-amber-500/70" />;
}

/**
 * 扫 messages + streamingParts 里所有 TodoWrite 调用，按时间序排好，再归并成 blocks。
 *
 * 归并：从前往后处理每次调用，如果当前调用的 todos 与**上一个块**有 id 重叠或
 * content 重叠（兜底——模型不传稳定 id 时），视为同块更新（覆盖整块）；否则新块。
 *
 * 返回顺序倒序：新块在前。
 */
function extractTodoBlocks(
  session: Session | undefined,
  streamingParts: StreamingAssistantPart[] | null | undefined,
): Block[] {
  const calls: Array<{ key: string; todos: TodoItem[]; ts: number; streaming: boolean }> = [];

  for (const msg of session?.messages ?? []) {
    if (msg.role !== "assistant") continue;
    const parts = msg.parts ?? [];
    for (const p of parts) {
      if (p.type === "tool_call" && isTaskListTool(p.name)) {
        const text =
          p.input === undefined
            ? p.arguments ?? ""
            : typeof p.input === "string"
              ? p.input
              : JSON.stringify(p.input);
        const todos = parseTodos(text);
        if (todos.length > 0) {
          calls.push({
            key: p.id ?? `${msg.id}-${calls.length}`,
            todos,
            ts: msg.created_at,
            streaming: false,
          });
        }
      }
    }
    const legacy = msg.tool_calls ?? [];
    for (const c of legacy) {
      if (!isTaskListTool(c.name)) continue;
      if (calls.some((x) => x.key === c.id)) continue;
      const text = typeof c.input === "string" ? c.input : JSON.stringify(c.input);
      const todos = parseTodos(text);
      if (todos.length > 0) {
        calls.push({ key: c.id, todos, ts: msg.created_at, streaming: false });
      }
    }
  }

  for (const sp of streamingParts ?? []) {
    if (sp.type !== "tool_call" || !isTaskListTool(sp.name)) continue;
    const text =
      sp.input === undefined
        ? sp.arguments ?? ""
        : typeof sp.input === "string"
          ? sp.input
          : JSON.stringify(sp.input);
    const todos = parseTodos(text);
    if (todos.length > 0) {
      const key = sp.id ?? `streaming-${calls.length}`;
      if (!calls.some((x) => x.key === key)) {
        calls.push({ key, todos, ts: Date.now(), streaming: true });
      }
    }
  }

  const blocks: Block[] = [];
  for (const call of calls) {
    const last = blocks[blocks.length - 1];
    if (last && (hasIdOverlap(last.todos, call.todos) || hasContentOverlap(last.todos, call.todos))) {
      last.todos = call.todos;
      last.ts = call.ts;
      last.streaming = call.streaming;
    } else {
      blocks.push({
        key: call.key,
        todos: call.todos,
        ts: call.ts,
        streaming: call.streaming,
      });
    }
  }

  return blocks.reverse();
}

function hasIdOverlap(a: TodoItem[], b: TodoItem[]): boolean {
  const ids = new Set(a.map((t) => t.id).filter((id): id is string => Boolean(id)));
  if (ids.size === 0) return false;
  return b.some((t) => t.id && ids.has(t.id));
}

/** id 不匹配时的兜底——模型不传稳定 id 时，按 content 字符串重叠判同块。 */
function hasContentOverlap(a: TodoItem[], b: TodoItem[]): boolean {
  const set = new Set(a.map((t) => t.content.trim()));
  return b.some((t) => set.has(t.content.trim()));
}

import { ArrowDownToLine, ArrowUpFromLine, Database, Layers } from "lucide-react";
import { cn } from "@/desktop/ui/lib/utils";
import type { TokenStats } from "@/desktop/ui/types";

interface Props {
  stats: TokenStats | null;
  size?: number;
  className?: string;
}

/**
 * 紧贴输入框右侧的 token 统计图标：默认只显示一个圆形按钮（与 ContextRing 同尺寸），
 * 鼠标悬停时浮出面板展示输入 / 输出 / 缓存命中 / 缓存写入 详情。
 */
export function TokenStatsPanel({ stats, size = 14, className }: Props) {
  const empty = !stats || stats.run_count === 0;
  const hitRate =
    !empty && stats!.input_tokens > 0
      ? Math.round((stats!.cache_read_tokens / stats!.input_tokens) * 100)
      : 0;

  return (
    <div className={cn("relative group/token", className)}>
      <button
        type="button"
        tabIndex={-1}
        className={cn(
          "inline-flex items-center justify-center rounded-lg border border-transparent",
          "text-muted-foreground hover:border-border hover:bg-muted hover:text-foreground transition-colors cursor-default",
          empty && "opacity-60"
        )}
        style={{ width: size + 8, height: size + 8 }}
        aria-label="Token 用量"
      >
        {/* 「两个桶」造型：两个 Database 圆柱错位叠加，象征 cache 读 + 写双层 */}
        <span className="relative inline-block h-3 w-3">
          <Database className="absolute left-0 top-0 h-2.5 w-2.5 opacity-50" />
          <Database className="absolute -right-px -bottom-px h-2.5 w-2.5" />
        </span>
      </button>

      <div
        className={cn(
          "pointer-events-none absolute bottom-full right-0 mb-2 w-52 z-50",
          "rounded-lg border border-border bg-background text-foreground shadow-lg",
          "px-3 py-2 text-[11px] select-none",
          "opacity-0 translate-y-1 transition-all duration-150",
          "group-hover/token:opacity-100 group-hover/token:translate-y-0 group-hover/token:pointer-events-auto"
        )}
      >
        {empty ? (
          <div className="text-muted-foreground/80">尚未发起请求</div>
        ) : (
          <>
            <div className="flex items-center justify-between mb-1.5">
              <span className="font-medium text-foreground/80">Token 用量</span>
              <span className="text-muted-foreground tabular-nums">
                ×{stats!.run_count}
              </span>
            </div>
            <Row
              icon={<ArrowUpFromLine className="w-3 h-3" />}
              label="输入"
              value={stats!.input_tokens}
              tone="text-foreground/80"
            />
            <Row
              icon={<ArrowDownToLine className="w-3 h-3" />}
              label="输出"
              value={stats!.output_tokens}
              tone="text-foreground/80"
            />
            <Row
              icon={<Database className="w-3 h-3" />}
              label="缓存命中"
              value={stats!.cache_read_tokens}
              tone="text-emerald-600 dark:text-emerald-400"
              suffix={hitRate > 0 ? ` (${hitRate}%)` : undefined}
            />
            {stats!.cache_creation_tokens > 0 && (
              <Row
                icon={<Layers className="w-3 h-3" />}
                label="缓存写入"
                value={stats!.cache_creation_tokens}
                tone="text-amber-600 dark:text-amber-400"
              />
            )}
          </>
        )}
      </div>
    </div>
  );
}

function Row({
  icon,
  label,
  value,
  tone,
  suffix,
}: {
  icon: React.ReactNode;
  label: string;
  value: number;
  tone: string;
  suffix?: string;
}) {
  return (
    <div className="flex items-center justify-between gap-2 py-0.5">
      <span className="inline-flex items-center gap-1.5 text-muted-foreground">
        {icon}
        {label}
      </span>
      <span className={cn("tabular-nums", tone)}>
        {formatTokens(value)}
        {suffix}
      </span>
    </div>
  );
}

function formatTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(2)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
  return String(n);
}

