import { Fragment, useEffect, useMemo, useRef, useState } from "react";
import { CircleHelp, Send, X } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/desktop/ui/lib/utils";
import { useStore } from "@/desktop/ui/store/useStore";

const OTHER_KEY = "__other__";

/**
 * agent 主动提问弹窗（ask 工具）。挂在 ChatInput 上方。
 *
 * 单选：点击切换选中，最后一项 "其他" 选中时露出 textarea；ESC 取消。
 * 多选（`pending.multi=true`）：点击勾选/取消勾选，可多个；不提供 "其他" 自由输入。
 * 选项均按 `1./2./3.` 编号显示，跟终端模式风格一致。
 */
export function UserQuestionPopup() {
  const pending = useStore((s) => s.pendingQuestion);
  const resolveQuestion = useStore((s) => s.resolveQuestion);

  // 单选状态：label 或 OTHER_KEY
  const [selected, setSelected] = useState<string | null>(null);
  // 多选状态：勾选的 label 集合（按勾选顺序保存）
  const [multiSelected, setMultiSelected] = useState<string[]>([]);
  const [otherText, setOtherText] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const otherInputRef = useRef<HTMLTextAreaElement>(null);

  const isMulti = !!pending?.multi;

  // 切换 question 时重置
  useEffect(() => {
    setSelected(null);
    setMultiSelected([]);
    setOtherText("");
  }, [pending?.requestId]);

  // 单选 + "其他" 时自动聚焦输入框
  useEffect(() => {
    if (!isMulti && selected === OTHER_KEY) {
      otherInputRef.current?.focus();
    }
  }, [isMulti, selected]);

  // ESC 取消
  useEffect(() => {
    if (!pending) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") {
        e.preventDefault();
        cancel();
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pending?.requestId]);

  const canSubmit = useMemo(() => {
    if (submitting) return false;
    if (isMulti) return multiSelected.length > 0;
    if (!selected) return false;
    if (selected === OTHER_KEY) return otherText.trim().length > 0;
    return true;
  }, [isMulti, multiSelected, selected, otherText, submitting]);

  if (!pending) return null;

  function toggleMulti(label: string) {
    setMultiSelected((prev) =>
      prev.includes(label) ? prev.filter((l) => l !== label) : [...prev, label]
    );
  }

  async function cancel() {
    setSubmitting(true);
    try {
      await resolveQuestion({ kind: "cancelled" });
    } catch (e: any) {
      toast.error(e?.message ?? "提交失败");
    } finally {
      setSubmitting(false);
    }
  }

  async function submit() {
    if (!canSubmit) return;
    let payload: Parameters<typeof resolveQuestion>[0];
    if (isMulti) {
      payload = { kind: "selected_multi", labels: multiSelected };
    } else if (selected === OTHER_KEY) {
      payload = { kind: "custom", text: otherText.trim() };
    } else if (selected) {
      payload = { kind: "selected", label: selected };
    } else {
      return;
    }
    setSubmitting(true);
    try {
      await resolveQuestion(payload);
    } catch (e: any) {
      toast.error(e?.message ?? "提交失败");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="px-4 pb-2">
      <div className="max-w-3xl mx-auto pr-[50px]">
        <div
          className={cn(
            "w-full rounded-lg border border-border bg-card text-card-foreground shadow-lg overflow-hidden pointer-events-auto",
            "animate-in fade-in slide-in-from-bottom-2 duration-150"
          )}
        >
          {/* 头部 */}
          <div className="flex items-start gap-2 px-3 py-1.5 border-b border-border bg-muted/40">
            <CircleHelp className="w-3.5 h-3.5 text-primary shrink-0 mt-1" />
            <span className="text-sm font-medium flex-1 whitespace-pre-wrap break-words leading-5">
              {pending.question}
            </span>
            {isMulti && (
              <span className="text-[11px] px-1.5 py-0.5 rounded bg-primary/15 text-primary font-medium shrink-0 mt-0.5">
                多选
              </span>
            )}
            <span className="text-[11px] text-muted-foreground/80 shrink-0 mt-1">
              ESC 取消
            </span>
          </div>

          {/* 选项列表：选项 button 贴 popup 两端 hover bg 全宽，hairline mx-3 缩进留 12px */}
          <div>
            {pending.options.map((opt, idx) => {
              const checked = isMulti
                ? multiSelected.includes(opt.label)
                : selected === opt.label;
              return (
                <Fragment key={`${idx}-${opt.label}`}>
                  {idx > 0 && <div className="h-px bg-border mx-3" />}
                <button
                  type="button"
                  onClick={() =>
                    isMulti ? toggleMulti(opt.label) : setSelected(opt.label)
                  }
                  disabled={submitting}
                  aria-pressed={checked}
                  className={cn(
                    "w-full text-left px-3 py-1.5 transition-colors text-sm flex items-start gap-2",
                    checked
                      ? "bg-primary/10 text-primary"
                      : "hover:bg-muted"
                  )}
                >
                  {isMulti ? (
                    <span
                      className={cn(
                        "mt-[3px] inline-flex items-center justify-center w-3.5 h-3.5 rounded border text-[10px] leading-none shrink-0",
                        checked
                          ? "bg-primary border-primary text-primary-foreground"
                          : "border-muted-foreground/40"
                      )}
                      aria-hidden
                    >
                      {checked ? "✓" : ""}
                    </span>
                  ) : null}
                  <span
                    className={cn(
                      "shrink-0 font-mono text-[12px] tabular-nums select-none leading-5",
                      checked ? "text-primary" : "text-muted-foreground"
                    )}
                  >
                    {idx + 1}.
                  </span>
                  <span className="flex-1 min-w-0">
                    <div className="font-medium leading-5">{opt.label}</div>
                    {opt.description && (
                      <div className="text-[12px] text-muted-foreground leading-4">
                        {opt.description}
                      </div>
                    )}
                  </span>
                </button>
                </Fragment>
              );
            })}

            {/* "其他"：仅单选模式提供 */}
            {!isMulti && (
              <>
              {pending.options.length > 0 && <div className="h-px bg-border mx-3" />}
              <button
                type="button"
                onClick={() => setSelected(OTHER_KEY)}
                disabled={submitting}
                className={cn(
                  "w-full text-left px-3 py-1.5 transition-colors text-sm",
                  selected === OTHER_KEY
                    ? "bg-primary/10 text-primary"
                    : "hover:bg-muted text-muted-foreground"
                )}
              >
                {selected === OTHER_KEY ? (
                  <textarea
                    ref={otherInputRef}
                    value={otherText}
                    onChange={(e) => setOtherText(e.target.value)}
                    onClick={(e) => e.stopPropagation()}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                        e.preventDefault();
                        submit();
                      }
                    }}
                    placeholder="其他回答…（Cmd/Ctrl+Enter 提交）"
                    rows={2}
                    className="w-full resize-none rounded-md border border-input bg-background px-2 py-1 text-sm outline-none focus:ring-2 focus:ring-ring"
                  />
                ) : (
                  <div className="text-muted-foreground text-[13px] leading-5">
                    其他回答…
                  </div>
                )}
              </button>
              </>
            )}
          </div>

          {/* 底部按钮 */}
          <div className="flex items-center gap-1.5 px-2 py-1.5 border-t border-border bg-background/60">
            {isMulti && multiSelected.length > 0 && (
              <span className="text-[11px] text-muted-foreground pl-1">
                已选 {multiSelected.length} 项
              </span>
            )}
            <div className="flex-1" />
            <button
              type="button"
              onClick={cancel}
              disabled={submitting}
              className={cn(
                "h-7 px-2.5 rounded-md text-[13px] inline-flex items-center gap-1 transition-colors",
                "text-muted-foreground hover:bg-muted hover:text-foreground disabled:opacity-50"
              )}
            >
              <X className="w-3.5 h-3.5" />
              取消
            </button>
            <button
              type="button"
              onClick={submit}
              disabled={!canSubmit}
              className={cn(
                "h-7 px-2.5 rounded-md text-[13px] font-medium inline-flex items-center gap-1 transition-colors",
                "bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-40"
              )}
            >
              <Send className="w-3.5 h-3.5" />
              提交
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useLayoutEffect, useMemo, useRef } from "react";
import { open as openDialog } from "@tauri-apps/plugin-dialog";
import {
  File,
  FileArchive,
  FileAudio,
  FileCode,
  FileCog,
  FileImage,
  FileJson,
  FilePlus,
  FileSpreadsheet,
  FileText,
  FileVideoCamera,
  Folder,
  FolderPlus,
  Lock,
  Plus,
  X,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { toast } from "sonner";
import { PathHint } from "@/desktop/ui/components/PathHint";
import { Button } from "@/desktop/ui/components/ui/button";
import { Input, Label } from "@/desktop/ui/components/ui/input";
import { cn, pathLeaf, relativizeIfUnder } from "@/desktop/ui/lib/utils";

/** 单选目录输入：path + 「选择」按钮，placeholder 通常用来显示全局默认值。 */
export function DirPicker({
  value,
  onChange,
  placeholder,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  async function pick() {
    try {
      const dir = await openDialog({ directory: true, multiple: false });
      if (typeof dir === "string") onChange(dir);
    } catch (e: any) {
      toast.error(e.message ?? String(e));
    }
  }
  const inputRef = useRef<HTMLInputElement | null>(null);
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input || document.activeElement === input) return;
    input.scrollLeft = input.scrollWidth;
  }, [value]);
  return (
    <div className="flex items-center gap-2">
      <Input
        ref={inputRef}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="flex-1 font-mono text-xs"
      />
      <Button
        variant="outline"
        type="button"
        onClick={pick}
        className="shrink-0"
      >
        <Folder className="w-4 h-4" />
        选择
      </Button>
    </div>
  );
}

const CODE_EXTENSIONS = new Set([
  "c",
  "cc",
  "cpp",
  "cs",
  "css",
  "go",
  "h",
  "hpp",
  "html",
  "java",
  "js",
  "jsx",
  "kt",
  "lua",
  "mjs",
  "php",
  "py",
  "rb",
  "rs",
  "scss",
  "sh",
  "swift",
  "ts",
  "tsx",
  "vue",
]);

const TEXT_EXTENSIONS = new Set([
  "csv",
  "log",
  "md",
  "rst",
  "text",
  "toml",
  "txt",
  "yaml",
  "yml",
]);

const IMAGE_EXTENSIONS = new Set(["avif", "bmp", "gif", "jpeg", "jpg", "png", "svg", "webp"]);
const AUDIO_EXTENSIONS = new Set(["aac", "aiff", "flac", "m4a", "mp3", "ogg", "wav"]);
const VIDEO_EXTENSIONS = new Set(["avi", "m4v", "mov", "mp4", "mpeg", "mpg", "webm"]);
const ARCHIVE_EXTENSIONS = new Set(["7z", "bz2", "dmg", "gz", "rar", "tar", "tgz", "xz", "zip"]);
const SPREADSHEET_EXTENSIONS = new Set(["ods", "tsv", "xls", "xlsm", "xlsx"]);
const CONFIG_FILE_NAMES = new Set([
  ".env",
  ".gitignore",
  ".npmrc",
  "dockerfile",
  "makefile",
  "package.json",
  "pnpm-lock.yaml",
  "tsconfig.json",
]);
const TEXT_FILE_NAMES = new Set(["license", "readme"]);

function pathExtension(path: string) {
  const leaf = pathLeaf(path).toLowerCase();
  const dot = leaf.lastIndexOf(".");
  if (dot <= 0 || dot === leaf.length - 1) return "";
  return leaf.slice(dot + 1);
}

function looksLikeFile(path: string) {
  const leaf = pathLeaf(path).toLowerCase();
  return CONFIG_FILE_NAMES.has(leaf) || TEXT_FILE_NAMES.has(leaf) || pathExtension(path) !== "";
}

function pathIconFor(path: string, forceDirectory: boolean): LucideIcon {
  if (forceDirectory || !looksLikeFile(path)) return Folder;
  const leaf = pathLeaf(path).toLowerCase();
  const ext = pathExtension(path);
  if (leaf === "package.json" || ext === "json" || ext === "jsonl") return FileJson;
  if (CONFIG_FILE_NAMES.has(leaf) || ["lock", "conf", "config", "ini"].includes(ext)) return FileCog;
  if (CODE_EXTENSIONS.has(ext)) return FileCode;
  if (IMAGE_EXTENSIONS.has(ext)) return FileImage;
  if (AUDIO_EXTENSIONS.has(ext)) return FileAudio;
  if (VIDEO_EXTENSIONS.has(ext)) return FileVideoCamera;
  if (ARCHIVE_EXTENSIONS.has(ext)) return FileArchive;
  if (SPREADSHEET_EXTENSIONS.has(ext)) return FileSpreadsheet;
  if (TEXT_EXTENSIONS.has(ext) || TEXT_FILE_NAMES.has(leaf)) return FileText;
  return File;
}

export function PathTypeIcon({
  path,
  forceDirectory = false,
  className,
}: {
  path: string;
  forceDirectory?: boolean;
  className?: string;
}) {
  const Icon = pathIconFor(path, forceDirectory);
  return <Icon className={className} />;
}

/**
 * 一组路径管理：增 / 删 / 行内显示。
 *
 * - `paths`：当前生效的路径列表。
 * - `inheritedPaths`：当 `paths.length === 0` 时显示这些灰色条目，提示"用全局默认"。
 * - `lockedPaths`：这些条目仅展示，不可删除（用于"对话已开始后锁定的路径"等场景）。
 *   `paths` 里凡是出现在 `lockedPaths` 中的项，会渲染锁图标且没有移除按钮。
 * - `lockedHint`：当存在 locked 条目时，在列表上方显示的一行提示。
 * - `relativeTo`：可选基准目录。条目路径在该目录下时显示为相对路径
 *   （如 `./src/x` 或 `src/x`），不在或未传则显示完整路径。仅影响渲染，
 *   onChange 回传的仍是原始绝对路径。用于项目级目录列表减少视觉噪音；
 *   全局级不传即可保持完整路径。
 */
export function PathListField({
  label,
  paths,
  onChange,
  inheritedPaths,
  emptyHint,
  trailing,
  lockedPaths,
  lockedHint,
  allowFiles = false,
  maxVisibleRows,
  relativeTo,
}: {
  label: string;
  paths: string[];
  onChange: (paths: string[]) => void;
  inheritedPaths?: string[];
  emptyHint?: string;
  trailing?: React.ReactNode;
  lockedPaths?: string[];
  lockedHint?: string;
  allowFiles?: boolean;
  maxVisibleRows?: number;
  relativeTo?: string | null;
}) {
  const showingInherited = paths.length === 0 && (inheritedPaths?.length ?? 0) > 0;
  const lockedSet = useMemo(() => new Set(lockedPaths ?? []), [lockedPaths]);
  const hasLocked = (lockedPaths?.length ?? 0) > 0;
  const visiblePaths = showingInherited ? inheritedPaths! : paths;
  const scrollable = maxVisibleRows != null && visiblePaths.length > maxVisibleRows;

  function merge(nextPaths: string[]) {
    const merged = [...paths];
    for (const path of nextPaths) {
      if (typeof path === "string" && !merged.includes(path)) merged.push(path);
    }
    onChange(merged);
  }

  async function addFolder() {
    try {
      const dir = await openDialog({ directory: true, multiple: true });
      if (!dir) return;
      const arr = Array.isArray(dir) ? dir : [dir];
      merge(arr);
    } catch (e: any) {
      toast.error(e.message ?? String(e));
    }
  }

  async function addFile() {
    try {
      const file = await openDialog({ directory: false, multiple: true });
      if (!file) return;
      const arr = Array.isArray(file) ? file : [file];
      merge(arr);
    } catch (e: any) {
      toast.error(e.message ?? String(e));
    }
  }
  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between">
        <Label>{label}</Label>
        <div className="flex items-center gap-1">
          {trailing}
          {allowFiles && (
            <Button
              variant="outline"
              size="icon"
              type="button"
              onClick={addFile}
              title="添加文件"
              aria-label="添加文件"
            >
              <FilePlus className="w-3.5 h-3.5" />
            </Button>
          )}
          <Button
            variant="outline"
            size={allowFiles ? "icon" : "sm"}
            type="button"
            onClick={addFolder}
            title="添加文件夹"
            aria-label="添加文件夹"
          >
            {allowFiles ? (
              <FolderPlus className="w-3.5 h-3.5" />
            ) : (
              <>
                <Plus className="w-3.5 h-3.5" />
                添加
              </>
            )}
          </Button>
        </div>
      </div>
      {hasLocked && lockedHint && !showingInherited && (
        <div className="text-[11px] text-muted-foreground/80 px-1">{lockedHint}</div>
      )}
      {paths.length === 0 && !showingInherited ? (
        <div className="text-xs text-muted-foreground/70 italic px-2 py-3 border border-dashed border-border rounded-md text-center">
          {emptyHint ?? "暂无"}
        </div>
      ) : (
        <ul
          className={cn("space-y-1", scrollable && "overflow-y-auto pr-1")}
          style={scrollable ? { maxHeight: `${maxVisibleRows! * 30}px` } : undefined}
        >
          {visiblePaths.map((d) => {
            const inherited = showingInherited;
            const locked = !inherited && lockedSet.has(d);
            return (
              <li key={d}>
                <PathHint path={d} className="w-full">
                  <span
                    className={cn(
                      "flex items-center gap-2 px-2 py-1 rounded-md group w-full",
                      inherited
                        ? "bg-muted/20 text-muted-foreground italic"
                        : locked
                          ? "bg-muted/30"
                          : "bg-muted/40"
                    )}
                    title={locked ? "对话已开始，此路径不能再移除" : undefined}
                  >
                    {locked ? (
                      <Lock className="w-3.5 h-3.5 shrink-0 text-muted-foreground/70" />
                    ) : (
                      <PathTypeIcon
                        path={d}
                        forceDirectory={!allowFiles}
                        className={cn(
                          "w-3.5 h-3.5 shrink-0",
                          inherited
                            ? "text-muted-foreground/60"
                            : "text-muted-foreground"
                        )}
                      />
                    )}
                    <span
                      className={cn(
                        "flex-1 truncate text-xs font-mono",
                        locked && "text-muted-foreground"
                      )}
                    >
                      {relativeTo ? relativizeIfUnder(d, relativeTo) : pathLeaf(d)}
                      {inherited && (
                        <span className="ml-1.5 not-italic font-sans text-[10px] text-muted-foreground/70">
                          （全局默认）
                        </span>
                      )}
                    </span>
                    {!inherited && !locked && (
                      <button
                        type="button"
                        onClick={() => onChange(paths.filter((path) => path !== d))}
                        className="text-muted-foreground hover:text-destructive opacity-0 group-hover:opacity-100 transition-opacity"
                        aria-label="移除路径"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </span>
                </PathHint>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

/**
 * 工具开关列表。`inherited`：当 `enabled === null` 时（即继承全局）显示这些灰色项作为占位。
 */
export function ToolToggleList({
  label,
  availableTools,
  enabled,
  onChange,
  inheritedEnabled,
  trailing,
}: {
  label: string;
  availableTools: { name: string; description: string }[];
  enabled: string[] | null;
  onChange: (next: string[] | null) => void;
  inheritedEnabled?: string[];
  trailing?: React.ReactNode;
}) {
  const inheriting = enabled === null;
  const effective = inheriting ? (inheritedEnabled ?? []) : enabled!;
  const enabledSet = useMemo(() => new Set(effective), [effective]);

  function toggle(name: string) {
    // 若当前继承全局，先把"全局快照"复制到本地，再修改
    const base = inheriting ? new Set(inheritedEnabled ?? []) : new Set(enabled);
    if (base.has(name)) base.delete(name);
    else base.add(name);
    onChange(Array.from(base));
  }

  return (
    <div className="space-y-1.5">
      <div className="flex items-center justify-between">
        <Label>{label}</Label>
        {trailing}
      </div>
      {availableTools.length === 0 ? (
        <div className="text-xs text-muted-foreground/70 italic px-2 py-3 border border-dashed border-border rounded-md text-center">
          没有可选工具
        </div>
      ) : (
        <ul className="space-y-1">
          {availableTools.map((t) => (
            <li
              key={t.name}
              className={cn(
                "flex items-start gap-2 px-2 py-1.5 rounded-md hover:bg-muted/30",
                inheriting && "bg-muted/10"
              )}
            >
              <input
                type="checkbox"
                id={`toolchk-${label}-${t.name}`}
                checked={enabledSet.has(t.name)}
                onChange={() => toggle(t.name)}
                className="h-4 w-4 mt-0.5 rounded"
              />
              <label
                htmlFor={`toolchk-${label}-${t.name}`}
                className="flex-1 cursor-pointer"
              >
                <div
                  className={cn(
                    "text-sm font-medium",
                    inheriting && "text-muted-foreground"
                  )}
                >
                  {t.name}
                  {inheriting && enabledSet.has(t.name) && (
                    <span className="ml-1.5 text-[10px] font-normal text-muted-foreground/70">
                      （全局默认启用）
                    </span>
                  )}
                </div>
                {t.description && (
                  <div className="text-xs text-muted-foreground">
                    {t.description}
                  </div>
                )}
              </label>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

