/**
 * Minimal ANSI escape → HTML converter.
 * Handles SGR codes (colors, bold, dim, italic, underline, reset).
 * Input: raw string that may contain \x1b[...m sequences.
 * Output: HTML string safe for dangerouslySetInnerHTML inside a <pre>.
 */

const ANSI_COLORS: Record<number, string> = {
  30: "#1e1e1e", 31: "#f44747", 32: "#6a9955", 33: "#dcdcaa",
  34: "#569cd6", 35: "#c586c0", 36: "#4ec9b0", 37: "#d4d4d4",
  90: "#808080", 91: "#f44747", 92: "#b5cea8", 93: "#dcdcaa",
  94: "#9cdcfe", 95: "#c586c0", 96: "#4ec9b0", 97: "#ffffff",
};

const BG_COLORS: Record<number, string> = {
  40: "#1e1e1e", 41: "#f44747", 42: "#6a9955", 43: "#dcdcaa",
  44: "#569cd6", 45: "#c586c0", 46: "#4ec9b0", 47: "#d4d4d4",
  100: "#808080", 101: "#f44747", 102: "#b5cea8", 103: "#dcdcaa",
  104: "#9cdcfe", 105: "#c586c0", 106: "#4ec9b0", 107: "#ffffff",
};

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function ansiToHtml(input: string): string {
  // Split on ANSI CSI sequences: ESC [ ... m
  // eslint-disable-next-line no-control-regex
  const parts = input.split(/\x1b\[([0-9;]*)m/);
  if (parts.length === 1) return escapeHtml(input);

  let result = "";
  let fg = "";
  let bg = "";
  let bold = false;
  let dim = false;
  let italic = false;
  let underline = false;
  let openSpan = false;

  const flushOpen = () => {
    if (openSpan) return;
    const styles: string[] = [];
    const effectiveFg = bold && fg ? fg : fg; // bold doesn't change color in our theme
    if (effectiveFg) styles.push(`color:${effectiveFg}`);
    if (bg) styles.push(`background-color:${bg}`);
    if (bold) styles.push("font-weight:bold");
    if (dim) styles.push("opacity:0.6");
    if (italic) styles.push("font-style:italic");
    if (underline) styles.push("text-decoration:underline");
    if (styles.length > 0) {
      result += `<span style="${styles.join(";")}">`;
      openSpan = true;
    }
  };

  const flushClose = () => {
    if (openSpan) {
      result += "</span>";
      openSpan = false;
    }
  };

  for (let i = 0; i < parts.length; i++) {
    if (i % 2 === 0) {
      // Literal text
      if (parts[i]) {
        flushOpen();
        result += escapeHtml(parts[i]);
      }
    } else {
      // SGR params
      const params = parts[i] ? parts[i].split(";").map(Number) : [0];
      for (const code of params) {
        if (code === 0) {
          flushClose();
          fg = ""; bg = ""; bold = false; dim = false; italic = false; underline = false;
        } else if (code === 1) { bold = true; }
        else if (code === 2) { dim = true; }
        else if (code === 3) { italic = true; }
        else if (code === 4) { underline = true; }
        else if (code === 22) { bold = false; dim = false; }
        else if (code === 23) { italic = false; }
        else if (code === 24) { underline = false; }
        else if (ANSI_COLORS[code]) {
          flushClose();
          fg = ANSI_COLORS[code];
        }
        else if (BG_COLORS[code]) {
          flushClose();
          bg = BG_COLORS[code];
        }
        else if (code === 39) { flushClose(); fg = ""; }
        else if (code === 49) { flushClose(); bg = ""; }
      }
      // Close and reopen to apply new styles
      flushClose();
    }
  }
  flushClose();
  return result;
}

const BASE64_IMAGE_PREFIXES: Array<[RegExp, string]> = [
  [/^iVBORw0KGgo/i, "image/png"],
  [/^\/9j\//i, "image/jpeg"],
  [/^R0lGOD/i, "image/gif"],
  [/^UklGR/i, "image/webp"],
];

function compactBase64(value: string) {
  return value.replace(/\s/g, "");
}

export function avatarImageSrc(value?: string | null): string | null {
  const raw = value?.trim();
  if (!raw) return null;

  if (/^data:image\/(?:png|jpe?g|gif|webp);base64,/i.test(raw)) {
    return raw;
  }

  try {
    const url = new URL(raw);
    if (url.protocol === "http:" || url.protocol === "https:") {
      return raw;
    }
  } catch {
    // Not a URL; it may still be a raw base64 image.
  }

  const encoded = compactBase64(raw);
  if (encoded.length < 80 || !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded)) {
    return null;
  }

  const detected = BASE64_IMAGE_PREFIXES.find(([pattern]) =>
    pattern.test(encoded)
  );
  if (!detected) return null;

  return `data:${detected[1]};base64,${encoded}`;
}

export function isImageAvatar(value?: string | null) {
  return avatarImageSrc(value) !== null;
}

import type { Message, MessageAttachment, Session } from "@/desktop/ui/types";

type TextBlock = { type: "text"; text: string };
type ImageBlock = {
  type: "image_url";
  image_url: { url: string };
};
type UserContent = string | Array<TextBlock | ImageBlock>;

interface OpenAiToolCall {
  id: string;
  type: "function";
  function: { name: string; arguments: string };
}

type ModelMessage =
  | { role: "system"; content: string }
  | { role: "user"; content: UserContent }
  | {
      role: "assistant";
      content: string;
      reasoning?: string;
      tool_calls?: OpenAiToolCall[];
    }
  | { role: "tool"; tool_call_id: string; content: string };

function userContentFromMessage(m: Message): UserContent {
  const attachments = m.attachments ?? [];
  if (attachments.length === 0) return m.content;
  const blocks: Array<TextBlock | ImageBlock> = [];
  if (m.content) blocks.push({ type: "text", text: m.content });
  for (const a of attachments) {
    if (a.kind === "image") {
      blocks.push({
        type: "image_url",
        image_url: { url: `data:${a.media_type};base64,${a.data}` },
      });
    } else {
      blocks.push(textFileBlock(a));
    }
  }
  return blocks;
}

function textFileBlock(a: Extract<MessageAttachment, { kind: "text_file" }>): TextBlock {
  return {
    type: "text",
    text: `<file name="${a.name}" media_type="${a.media_type}">\n${a.content}\n</file>`,
  };
}

function argumentsString(input: unknown, raw?: string): string {
  if (raw && raw.length > 0) return raw;
  if (input === undefined) return "{}";
  try {
    return JSON.stringify(input);
  } catch {
    return String(input);
  }
}

function pushAssistant(out: ModelMessage[], m: Message) {
  const textParts: string[] = [];
  const reasoningParts: string[] = [];
  const toolCalls: OpenAiToolCall[] = [];
  const toolResults: ModelMessage[] = [];

  if (m.parts?.length) {
    for (const p of m.parts) {
      if (p.type === "text") {
        textParts.push(p.text);
      } else if (p.type === "reasoning") {
        reasoningParts.push(p.text);
      } else {
        toolCalls.push({
          id: p.id,
          type: "function",
          function: {
            name: p.name,
            arguments: argumentsString(p.input, p.arguments),
          },
        });
        if (p.result != null) {
          toolResults.push({
            role: "tool",
            tool_call_id: p.id,
            content: p.result,
          });
        }
      }
    }
  } else if (m.tool_calls?.length) {
    if (m.content) textParts.push(m.content);
    for (const tc of m.tool_calls) {
      toolCalls.push({
        id: tc.id,
        type: "function",
        function: { name: tc.name, arguments: argumentsString(tc.input) },
      });
      if (tc.result != null) {
        toolResults.push({
          role: "tool",
          tool_call_id: tc.id,
          content: tc.result,
        });
      }
    }
  } else if (m.content) {
    textParts.push(m.content);
  }

  const assistant: Extract<ModelMessage, { role: "assistant" }> = {
    role: "assistant",
    content: textParts.join(""),
  };
  if (reasoningParts.length > 0) assistant.reasoning = reasoningParts.join("");
  if (toolCalls.length > 0) assistant.tool_calls = toolCalls;
  out.push(assistant);
  out.push(...toolResults);
}

/**
 * 把 session.messages 翻译成 OpenAI 风格的 messages 数组,
 * 用于「显示原始 JSON」面板,让用户直观看到发给模型的载荷形态。
 *
 * - 始终在最前面注入 system prompt(若 session 有配置)
 * - 跳过 marker 消息
 * - 截断到 uptoMessageId(包含),让每条 bubble 都能看到自己出现时的上下文
 */
export function buildModelMessages(
  session: Session,
  uptoMessageId?: string
): ModelMessage[] {
  const out: ModelMessage[] = [];
  if (session.system_prompt) {
    out.push({ role: "system", content: session.system_prompt });
  }
  for (const m of session.messages) {
    if (m.role !== "marker") {
      if (m.role === "user") {
        out.push({ role: "user", content: userContentFromMessage(m) });
      } else if (m.role === "assistant") {
        pushAssistant(out, m);
      }
    }
    if (uptoMessageId && m.id === uptoMessageId) break;
  }
  return out;
}

/**
 * 各 provider 主力模型的 context window 兜底查表，与 Rust 侧
 * `crates/model-gateway/src/context_window.rs` 保持同步。
 *
 * 调度策略：**先按 model 名识别家族，再按 provider kind 兜底**。
 * 用户经常用 anthropic-kind / openai-kind 的第三方网关代理 deepseek-v4-pro
 * 这种跨家族模型；按 kind 分发会落到错的表。模型名命中关键字时优先用模型表。
 *
 * 这里只用来在 UI 提示里展示上下文窗口；和 Rust 那张表偶尔漂移不会影响功能
 * 正确性（`/compact` 进度条仍然以后端 resolve_context_window 为准）。
 */
export function contextWindowFor(providerKind: string, model: string): number {
  const m = normalizeModelId(model);
  const byModel = lookupByModelName(m);
  if (byModel !== null) return byModel;
  return fallbackByKind(providerKind);
}

/**
 * 与 Rust `common::reasoning::normalize_model_id` 一致：lowercase + dot→dash。
 * 同一款模型在不同上游网关里命名风格不一致（`opus-4-7` vs `opus-4.7`、
 * `gpt-5-5` vs `gpt-5.5`），归一化后只用 dash 形式比对。
 */
export function normalizeModelId(model: string): string {
  return model.toLowerCase().replace(/\./g, "-");
}

function lookupByModelName(m: string): number | null {
  // DeepSeek 家族（与 openhanako known-models.json deepseek 分区对齐）
  if (m.includes("deepseek")) {
    if (m.includes("v4")) return 1_000_000;
    // v3.2 在网关里写成 `deepseek-v3.2` 或缺 v 的 `deepseek-3.2`（kiro），归一化
    // 后是 `v3-2` / `-3-2`，两种都要命中，否则缺 v 的会掉到末尾兜底 1M。
    if (m.includes("v3-2") || m.includes("-3-2")) return 163_840;
    if (m.includes("r1")) return 65_536;
    if (m.includes("coder")) return 128_000;
    if (m.endsWith("deepseek-chat") || m.endsWith("deepseek-reasoner")) {
      return 1_000_000;
    }
    return 1_000_000;
  }
  // Claude 家族
  if (m.includes("claude") || m.includes("mythos")) {
    if (
      m.includes("opus-4-8") ||
      m.includes("opus-4-7") ||
      m.includes("opus-4-6") ||
      m.includes("sonnet-4-6") ||
      m.includes("mythos")
    ) {
      return 1_000_000;
    }
    return 200_000;
  }
  // 小米 MiMo v2+：1M 上下文。/v1/models 不返回 context_length，只能预设兜底。
  if (m.startsWith("mimo-v2")) return 1_000_000;
  // OpenAI GPT 家族
  if (
    m.startsWith("gpt-") ||
    m.startsWith("o1-") ||
    m.startsWith("o3-") ||
    m.startsWith("o4-")
  ) {
    if (m.startsWith("gpt-5-5") || m.startsWith("gpt-5-4")) {
      return 1_000_000;
    }
    if (m.startsWith("gpt-5")) return 400_000;
    return 128_000;
  }
  // Gemini 家族
  if (m.startsWith("gemini-")) {
    if (m.includes("flash") && m.includes("3")) return 200_000;
    return 1_000_000;
  }
  return null;
}

function fallbackByKind(providerKind: string): number {
  switch (providerKind) {
    case "anthropic":
      return 200_000;
    case "openai":
      return 128_000;
    case "deepseek":
      return 1_000_000;
    case "gemini":
      return 1_000_000;
    default:
      return 0;
  }
}

export function formatContextWindow(tokens: number): string {
  if (tokens <= 0) return "未知";
  if (tokens >= 1_000_000) {
    const m = tokens / 1_000_000;
    return Number.isInteger(m) ? `${m}M` : `${m.toFixed(1)}M`;
  }
  return `${Math.round(tokens / 1000)}k`;
}

/**
 * 把焦点送到 chat 区域里某个 tool_call 卡片上：自动滚到视图中央、展开折叠态、
 * 闪一下边框作为视觉确认。
 *
 * 流程：
 *  1. 派发 `focus-tool-call` 自定义事件，所有 `ToolCallTimeline` 实例都在监听
 *  2. 拥有这个 call 的 timeline 看到匹配的 id，会把对应 key 加进 expandedToolCalls
 *  3. 给 React 两帧时间完成 expand 渲染，再 querySelector 抓 DOM 节点
 *  4. `scrollIntoView` + 加 `focus-flash` class（800ms 自动移除）
 *
 * 为什么用 DOM + CustomEvent 而不是 zustand：tool_call 的 `expandedToolCalls`
 * state 是 per-MessageBubble 局部 state，要外置成全局会牵动好几个传参链；
 * 自定义事件让组件解耦——sidebar 只需要喊「我要这个 callId」，监听端自己决定要不要响应。
 */
export const FOCUS_TOOL_CALL_EVENT = "focus-tool-call";

export function focusToolCall(callId: string): void {
  if (!callId) return;
  window.dispatchEvent(
    new CustomEvent<string>(FOCUS_TOOL_CALL_EVENT, { detail: callId })
  );
  // 等两帧让 ToolCallTimeline 收到事件 → setState → 重渲染 → 折叠态展开
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      const el = document.querySelector<HTMLElement>(
        `[data-tool-call-id="${CSS.escape(callId)}"]`
      );
      if (!el) return;
      el.scrollIntoView({ behavior: "smooth", block: "center" });
      el.classList.add("focus-flash");
      // 动画时长 800ms 后清掉 class，避免 DOM 上堆积
      window.setTimeout(() => el.classList.remove("focus-flash"), 900);
    });
  });
}

export const MIN_PREVIEW_ZOOM = 0.25;
export const MAX_PREVIEW_ZOOM = 4;
export const PREVIEW_ZOOM_STEP = 0.1;

export function nextPreviewZoom(current: number, wheelDeltaY: number) {
  if (wheelDeltaY === 0) return clampPreviewZoom(current);
  const direction = wheelDeltaY < 0 ? 1 : -1;
  return clampPreviewZoom(current + direction * PREVIEW_ZOOM_STEP);
}

function clampPreviewZoom(value: number) {
  return roundZoom(Math.min(MAX_PREVIEW_ZOOM, Math.max(MIN_PREVIEW_ZOOM, value)));
}

function roundZoom(value: number) {
  return Math.round(value * 100) / 100;
}

export interface KeyboardShortcutEvent {
  key: string;
  metaKey?: boolean;
  ctrlKey?: boolean;
  shiftKey?: boolean;
  altKey?: boolean;
  defaultPrevented?: boolean;
}

export interface KeyboardFocusTarget {
  tagName?: string | null;
  isContentEditable?: boolean;
  getAttribute?: (name: string) => string | null;
  hasAttribute?: (name: string) => boolean;
}

function hasPrimaryModifier(event: KeyboardShortcutEvent) {
  return Boolean(event.metaKey || event.ctrlKey);
}

function keyIs(event: KeyboardShortcutEvent, key: string) {
  return event.key.toLowerCase() === key;
}

export function isNewConversationShortcut(event: KeyboardShortcutEvent) {
  return (
    hasPrimaryModifier(event) &&
    keyIs(event, "n") &&
    !event.shiftKey &&
    !event.altKey
  );
}

export function isGlobalSearchShortcut(event: KeyboardShortcutEvent) {
  return (
    hasPrimaryModifier(event) &&
    keyIs(event, "f") &&
    Boolean(event.shiftKey) &&
    !event.altKey
  );
}

export function isLocalFindShortcut(event: KeyboardShortcutEvent) {
  return (
    hasPrimaryModifier(event) &&
    keyIs(event, "f") &&
    !event.shiftKey &&
    !event.altKey
  );
}

export function shouldSuppressBareEnterOnDocument(
  event: KeyboardShortcutEvent,
  activeElement: KeyboardFocusTarget | null | undefined
) {
  return (
    event.key === "Enter" &&
    !event.defaultPrevented &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey &&
    !isKeyboardInteractiveTarget(activeElement)
  );
}

function isKeyboardInteractiveTarget(
  target: KeyboardFocusTarget | null | undefined
) {
  if (!target) return false;
  if (target.isContentEditable) return true;

  const tagName = target.tagName?.toUpperCase();
  if (!tagName) return false;
  if (["INPUT", "TEXTAREA", "SELECT", "BUTTON"].includes(tagName)) return true;

  if (tagName === "A" && target.hasAttribute?.("href")) return true;

  const role = target.getAttribute?.("role");
  return Boolean(
    role &&
      [
        "button",
        "checkbox",
        "combobox",
        "link",
        "listbox",
        "menuitem",
        "option",
        "radio",
        "searchbox",
        "switch",
        "tab",
        "textbox",
      ].includes(role)
  );
}

import { indexMcpToolReports, normalizeMcpConfig } from "./mcpSettings";

function expectEqual(name: string, actual: unknown, expected: unknown) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    throw new Error(`${name}: expected ${e}, got ${a}`);
  }
}

expectEqual(
  "normalizes null mcp config to an empty server record",
  normalizeMcpConfig(null),
  { mcp_servers: {} }
);

expectEqual(
  "indexes discovered tool reports by server name",
  Object.keys(
    indexMcpToolReports([
      {
        server_name: "filesystem",
        transport: "stdio",
        disabled: false,
        tools: [
          {
            server_name: "filesystem",
            name: "read_file",
            runtime_name: "Mcp__filesystem__read_file",
            description: "Read a file",
            input_schema: { type: "object" },
          },
        ],
        error: null,
      },
    ])
  ),
  ["filesystem"]
);

import type {
  McpConfig,
  McpServerConfig,
  McpToolReport,
  McpTransport,
} from "../types";

export function inferMcpTransport(server: McpServerConfig): McpTransport {
  if (server.transport) return server.transport;
  return server.url ? "streamable_http" : "stdio";
}

export function normalizeMcpConfig(input: unknown): McpConfig {
  const source = input as
    | {
        mcp_servers?: unknown;
        mcpServers?: unknown;
        servers?: unknown;
      }
    | null
    | undefined;
  const raw = source?.mcp_servers ?? source?.mcpServers ?? source?.servers ?? {};
  const mcp_servers: Record<string, McpServerConfig> = {};
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return { mcp_servers };
  }
  for (const [name, value] of Object.entries(raw as Record<string, unknown>)) {
    const server = value && typeof value === "object" && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : {};
    mcp_servers[name] = {
      name,
      transport: isMcpTransport(server.transport) ? server.transport : null,
      command: stringOrNull(server.command),
      args: Array.isArray(server.args) ? server.args.map(String) : [],
      env: objectToStringRecord(server.env),
      url: stringOrNull(server.url),
      headers: objectToStringRecord(server.headers),
      disabled: Boolean(server.disabled),
    };
  }
  return { mcp_servers };
}

export function toCamelMcpConfig(config: McpConfig | unknown) {
  const normalized = normalizeMcpConfig(config);
  const mcpServers: Record<string, unknown> = {};
  for (const [name, server] of Object.entries(normalized.mcp_servers)) {
    const transport = server.transport ?? inferMcpTransport(server);
    const item: Record<string, unknown> = {
      transport,
      disabled: server.disabled,
    };
    if (transport === "stdio") {
      item.command = server.command ?? "";
      item.args = server.args ?? [];
      if (Object.keys(server.env ?? {}).length > 0) item.env = server.env;
    } else {
      item.url = server.url ?? "";
      if (Object.keys(server.headers ?? {}).length > 0) item.headers = server.headers;
    }
    mcpServers[name] = item;
  }
  return { mcpServers };
}

export function parseMcpJson(text: string): McpConfig {
  if (!text.trim()) return { mcp_servers: {} };
  return normalizeMcpConfig(JSON.parse(text));
}

export function indexMcpToolReports(
  reports: McpToolReport[] | null | undefined
): Record<string, McpToolReport> {
  const out: Record<string, McpToolReport> = {};
  for (const report of reports ?? []) {
    if (!report || typeof report.server_name !== "string") continue;
    out[report.server_name] = {
      ...report,
      tools: Array.isArray(report.tools) ? report.tools : [],
      error: report.error ?? null,
    };
  }
  return out;
}

export function objectToStringRecord(input: unknown): Record<string, string> {
  if (!input || typeof input !== "object" || Array.isArray(input)) return {};
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(input as Record<string, unknown>)) {
    if (v == null) continue;
    out[k] = String(v);
  }
  return out;
}

function isMcpTransport(input: unknown): input is McpTransport {
  return input === "stdio" || input === "streamable_http" || input === "sse";
}

function stringOrNull(input: unknown): string | null {
  return typeof input === "string" ? input : null;
}

type RawMessagePart =
  | {
      type: "text";
      text: string;
    }
  | {
      type: string;
    };

type RawMessage = {
  role: string;
  content: string;
  parts?: RawMessagePart[];
};

export function getMessageRawText(message: RawMessage): string {
  const textParts = message.parts?.filter(
    (part): part is Extract<RawMessagePart, { type: "text" }> =>
      part.type === "text"
  );

  if (textParts?.length) {
    return textParts.map((part) => part.text).join("");
  }

  return message.content;
}

export function canShowRawMessage(message: RawMessage): boolean {
  if (message.role !== "user" && message.role !== "assistant") {
    return false;
  }

  return getMessageRawText(message).length > 0;
}

/**
 * 架构 §4.13.8：Edit/Write 工具的流式参数解析。
 *
 * 模型在 stream 阶段通过 ToolCallDelta { arguments_delta } 逐 token 吐 JSON，
 * 此时还不能 JSON.parse。本函数容错地扫出 string 类型字段的「已收部分」，
 * 让 DiffViewer 立即把 `old_string` / `new_string` / `content` / `file_path` 渲出来。
 *
 * 设计取舍：
 * - 只识别顶层对象的若干已知 string 字段；不递归、不处理嵌套对象。
 * - 字符串字段未闭合时也返回已收的部分内容（带 \n 等转义还原），让 UI 渲到光标位置。
 * - 解析失败（明显坏 JSON）整体返回 {}，由调用方决定渲不渲。
 */

const TARGET_KEYS = ["file_path", "old_string", "new_string", "content"] as const;
type TargetKey = (typeof TARGET_KEYS)[number];

export interface PartialEditArgs {
  file_path?: string;
  old_string?: string;
  new_string?: string;
  content?: string;
}

export function parsePartialEditArgs(text: string): PartialEditArgs {
  const out: PartialEditArgs = {};
  if (!text) return out;

  // 跳过开头空白和可能的 `{`
  let i = 0;
  while (i < text.length && /\s/.test(text[i])) i++;
  if (text[i] === "{") i++;

  while (i < text.length) {
    // 跳过空白、逗号
    while (i < text.length && /[\s,]/.test(text[i])) i++;
    if (text[i] !== '"') break;
    i++;

    // 读 key
    const keyStart = i;
    while (i < text.length && text[i] !== '"') {
      if (text[i] === "\\") i++;
      i++;
    }
    if (i >= text.length) break;
    const key = text.slice(keyStart, i);
    i++;

    // 跳过 : 与空白
    while (i < text.length && /\s/.test(text[i])) i++;
    if (text[i] !== ":") break;
    i++;
    while (i < text.length && /\s/.test(text[i])) i++;

    // 值：只关心 string 字段；其它类型直接跳过
    if (text[i] === '"') {
      i++;
      const [value, nextI, closed] = readStringValue(text, i);
      if (TARGET_KEYS.includes(key as TargetKey)) {
        (out as Record<string, string>)[key] = value;
      }
      i = nextI;
      // 未闭合 → 已经到流末，结束
      if (!closed) break;
    } else {
      // 非 string 值（number / bool / object / array）：试图跳到下一个逗号或 `}` 层级
      i = skipNonStringValue(text, i);
      if (i < 0) break;
    }
  }

  return out;
}

/**
 * 从开引号之后开始读 JSON string 内容，处理转义。
 * 返回 [unescaped, nextIndex, closed]：
 * - closed = true 表示遇到了配对的 `"`，nextIndex 指向其后第一个字符
 * - closed = false 表示流到这里就断了，把已读字符当成「已收部分」返回
 */
function readStringValue(s: string, start: number): [string, number, boolean] {
  let out = "";
  let i = start;
  while (i < s.length) {
    const ch = s[i];
    if (ch === '"') {
      return [out, i + 1, true];
    }
    if (ch === "\\") {
      i++;
      if (i >= s.length) {
        // 转义符也没收完：把前面那个 `\` 吞掉，返回到这里为止
        return [out, i, false];
      }
      const esc = s[i];
      switch (esc) {
        case '"':
          out += '"';
          break;
        case "\\":
          out += "\\";
          break;
        case "/":
          out += "/";
          break;
        case "n":
          out += "\n";
          break;
        case "r":
          out += "\r";
          break;
        case "t":
          out += "\t";
          break;
        case "b":
          out += "\b";
          break;
        case "f":
          out += "\f";
          break;
        case "u": {
          if (i + 4 < s.length) {
            const hex = s.slice(i + 1, i + 5);
            if (/^[0-9a-fA-F]{4}$/.test(hex)) {
              out += String.fromCharCode(parseInt(hex, 16));
              i += 4;
            } else {
              out += "\\u";
            }
          } else {
            // \uXXXX 没收完：到这截断
            return [out, s.length, false];
          }
          break;
        }
        default:
          out += esc;
      }
      i++;
      continue;
    }
    out += ch;
    i++;
  }
  return [out, i, false];
}

/**
 * 跳过非 string 类型的值。简单做：扫到当前对象层级的下一个逗号或 `}` 之前。
 * 处理嵌套 {} / [] 配对，但不处理深层 string 内的特殊字符（够用即可）。
 */
function skipNonStringValue(s: string, start: number): number {
  let depth = 0;
  let inStr = false;
  let escape = false;
  for (let i = start; i < s.length; i++) {
    const ch = s[i];
    if (inStr) {
      if (escape) {
        escape = false;
      } else if (ch === "\\") {
        escape = true;
      } else if (ch === '"') {
        inStr = false;
      }
      continue;
    }
    if (ch === '"') {
      inStr = true;
    } else if (ch === "{" || ch === "[") {
      depth++;
    } else if (ch === "}" || ch === "]") {
      if (depth === 0) return i;
      depth--;
    } else if (ch === "," && depth === 0) {
      return i;
    }
  }
  return -1;
}

/**
 * 推断 Edit/Write 工具的 action 标签，与 EditAction 对齐。
 * 仅作 UI 展示，权威值在 EditEntry.action（落盘时由后端决定）。
 */
export function inferDiffAction(
  toolName: string | null | undefined,
  args: PartialEditArgs,
): "create" | "overwrite" | "modify" {
  if (toolName === "Write") return "overwrite";
  // Edit：old_string 完全为空 → create；否则 modify
  if (!args.old_string) return "create";
  return "modify";
}

/**
 * 提取 DiffViewer 的两端文本。
 *
 * - Edit: before = old_string, after = new_string
 * - Write: before = "", after = content
 *
 * 这是架构 §4.13.8 流式 diff 的语义：参数本身就是 diff 的两端，
 * 不读磁盘文件。
 */
export function diffSidesFromArgs(
  toolName: string | null | undefined,
  args: PartialEditArgs,
): { beforeText: string; afterText: string } {
  if (toolName === "Write") {
    return { beforeText: "", afterText: args.content ?? "" };
  }
  // 其它（包括 Edit / 未知 name）按 Edit 处理
  return {
    beforeText: args.old_string ?? "",
    afterText: args.new_string ?? "",
  };
}

// 与 platform/src/reasoning.rs 的检测逻辑保持一致。
// 任意一边新增模型家族时，记得两侧同步。

import type { CatalogEntry, ReasoningConfig, ReasoningEffort } from "@/desktop/ui/types";
import { normalizeModelId } from "@/desktop/ui/lib/contextWindow";

/**
 * 从 models.dev catalog 配置中提取模型的 reasoning/effort 能力。
 *
 * 返回 null 表示该模型不支持 reasoning（或 catalog 没提供相关信息）。
 * 返回非 null 时，effort 字段表示支持的 effort 级别列表。
 */
export function getModelReasoningConfig(
  entry: CatalogEntry | undefined
): { effort: ReasoningEffort[] } | null {
  if (!entry?.reasoning) return null;

  // models.dev 返回了 effort 列表（如 ["low", "medium", "high", "extra"]）
  if (entry.effort && entry.effort.length > 0) {
    return {
      effort: entry.effort.filter((e): e is ReasoningEffort =>
        ["low", "medium", "high", "extra"].includes(e)
      ),
    };
  }

  // models.dev 只标记了 reasoning=true 但没给 effort 列表，用默认的 4 档
  return { effort: ["low", "medium", "high", "extra"] };
}

/**
 * 获取模型支持的 effort 选项列表。
 *
 * 优先从 models.dev catalog 读取，fallback 到硬编码逻辑。
 */
export function getModelEffortOptions(
  providerKind: string,
  model: string,
  entry: CatalogEntry | undefined
): ReasoningEffort[] {
  // 1. 优先用 models.dev catalog
  const catalogConfig = getModelReasoningConfig(entry);
  if (catalogConfig) {
    return catalogConfig.effort;
  }

  // 2. Fallback: 根据 provider kind 和模型名判断
  if (!modelSupportsReasoning(providerKind, model)) {
    return [];
  }

  // 默认 4 档
  return ["low", "medium", "high", "extra"];
}

// ── Anthropic：thinking 模式分三档（与 Rust AnthropicThinkingMode 对齐） ──

export type AnthropicThinkingMode =
  | "opus_47_adaptive" // claude-opus-4-7 / 4-8：thinking adaptive + output_config.effort（含 xhigh）
  | "adaptive_46" // claude-opus-4-6 / claude-sonnet-4-6：thinking adaptive + effort（无 xhigh）
  | "legacy_enabled"; // 3-7 / opus-4{,-1,-5} / sonnet-4{,-5} / haiku-4-5：thinking enabled + budget_tokens

export function anthropicThinkingMode(
  model: string
): AnthropicThinkingMode | null {
  const m = normalizeModelId(model);
  // 4.7 与 4.8 共用同一 adaptive schema（含 xhigh），UI 档位走 low/medium/high/xhigh
  if (m.includes("opus-4-7") || m.includes("opus-4-8")) return "opus_47_adaptive";
  if (m.includes("opus-4-6") || m.includes("sonnet-4-6")) return "adaptive_46";
  if (
    m.includes("claude-3-7") ||
    m.includes("claude-opus-4") ||
    m.includes("claude-sonnet-4") ||
    m.includes("claude-haiku-4")
  ) {
    return "legacy_enabled";
  }
  return null;
}

export function anthropicSupportsThinking(model: string): boolean {
  return anthropicThinkingMode(model) !== null;
}

/**
 * 该 Anthropic 模型是否暴露 1M 上下文开关。
 *
 * 4.6 / 4.7 默认 1M（不暴露开关）；老 Sonnet 4 / Sonnet 4.5 / Opus 4.x 通过
 * `anthropic-beta: context-1m-2025-08-07` 才能开启 1M——这部分模型 UI 上要给开关。
 */
export function anthropicExposesLongContextToggle(model: string): boolean {
  const m = normalizeModelId(model);
  // 4.6 / 4.7 / 4.8 默认就是 1M，不暴露开关
  if (
    m.includes("opus-4-8") ||
    m.includes("opus-4-7") ||
    m.includes("opus-4-6") ||
    m.includes("sonnet-4-6")
  ) {
    return false;
  }
  return m.includes("sonnet-4") || m.includes("opus-4");
}

// ── OpenAI ──

/** o1-mini 等完全不支持 reasoning_effort 的模型。 */
export function openaiSkipsReasoning(model: string): boolean {
  return normalizeModelId(model).startsWith("o1-mini");
}

/** 支持 `reasoning_effort=xhigh` 的模型：gpt-5.4 / 5.5 / 5.1-codex-max。 */
export function openaiSupportsXhigh(model: string): boolean {
  const m = normalizeModelId(model);
  return (
    m.startsWith("gpt-5-4") ||
    m.startsWith("gpt-5-5") ||
    m.includes("gpt-5-1-codex-max")
  );
}

export function openaiSupportsReasoning(model: string): boolean {
  if (openaiSkipsReasoning(model)) return false;
  const m = normalizeModelId(model);
  if (m.startsWith("gpt-5")) return true;
  return (
    m.startsWith("o1") ||
    m.startsWith("o3") ||
    m.startsWith("o4") ||
    m.includes("-reasoning")
  );
}

// ── DeepSeek ──

/**
 * 该 DeepSeek 模型是否支持 thinking。
 *
 * 不依赖 providerType — 用户经常用 anthropic-kind 网关代理 deepseek-v4-pro，
 * 这种情况下 providerKind 是 anthropic 但模型是 deepseek，必须按模型名识别。
 *
 * 规则：v4 系列、`deepseek-reasoner`、`deepseek-r1` 支持 thinking。
 *      `*-nothinking` 后缀显式关闭。
 */
export function deepseekSupportsReasoning(model: string): boolean {
  const m = normalizeModelId(model);
  if (!m.includes("deepseek")) return false;
  if (m.includes("nothinking")) return false;
  if (m.includes("v4")) return true;
  if (m.includes("reasoner")) return true;
  if (m.includes("r1")) return true;
  return false;
}

/** DeepSeek v4 系列：UI 上「极高」档实际下发 `xhigh` effort（其他档原样下发）。 */
export function deepseekSupportsXhigh(model: string): boolean {
  const m = normalizeModelId(model);
  return m.includes("deepseek-v4");
}

// ── 跨家族 ──

/**
 * 模型是否暴露 thinking 控件。**按模型名优先识别**，再按 provider kind 兜底。
 *
 * 跨 kind 场景：anthropic-kind 网关代理 deepseek-v4-pro 时，必须当 deepseek 看；
 * openai-kind 端点代理 claude-opus-4-7 时，必须当 anthropic 看。
 */
export function modelSupportsReasoning(
  providerKind: string,
  model: string
): boolean {
  if (deepseekSupportsReasoning(model)) return true;
  if (anthropicSupportsThinking(model)) return true;
  if (openaiSupportsReasoning(model)) return true;
  if (providerKind === "anthropic") return anthropicSupportsThinking(model);
  if (providerKind === "openai") return openaiSupportsReasoning(model);
  if (providerKind === "deepseek") return deepseekSupportsReasoning(model);
  return false;
}

export function modelExposesLongContextToggle(
  providerKind: string,
  model: string
): boolean {
  const m = model.toLowerCase();
  // 只有 anthropic 原生 Sonnet/Opus 老版有 1M beta 开关；deepseek/openai 走自己的协议。
  if (m.includes("claude")) return anthropicExposesLongContextToggle(model);
  if (providerKind === "anthropic") return anthropicExposesLongContextToggle(model);
  return false;
}

export const DEFAULT_REASONING: ReasoningConfig = {
  enabled: true,
  effort: "extra",
};

export const REASONING_EFFORT_ORDER: ReasoningEffort[] = [
  "low",
  "medium",
  "high",
  "extra",
];

export const REASONING_EFFORT_LABEL: Record<ReasoningEffort, string> = {
  low: "低",
  medium: "中",
  high: "高",
  extra: "极高",
};

/**
 * 把项目档位翻译成在该模型上「实际」会发出的字符串。
 * 仅用于 UI tooltip / banner 文案，不参与请求构造。
 */
export function effortDisplay(
  providerKind: string,
  model: string,
  effort: ReasoningEffort
): string {
  if (providerKind === "anthropic") {
    const mode = anthropicThinkingMode(model);
    if (mode === "opus_47_adaptive") {
      return effort === "extra" ? "xhigh" : effort;
    }
    if (mode === "adaptive_46") {
      // 4.6 没有 xhigh，Extra 钳到 high
      return effort === "extra" ? "high" : effort;
    }
    if (mode === "legacy_enabled") {
      const budgets = { low: 1024, medium: 4096, high: 16384, extra: 32000 };
      return `${budgets[effort]} tok`;
    }
    return effort;
  }
  if (providerKind === "openai") {
    if (effort === "extra") {
      return openaiSupportsXhigh(model) ? "xhigh" : "high";
    }
    return effort;
  }
  // DeepSeek v4 系列：「极高」档实际下发 xhigh，其余原样。
  if (deepseekSupportsReasoning(model)) {
    if (effort === "extra") {
      return deepseekSupportsXhigh(model) ? "xhigh" : "high";
    }
    return effort;
  }
  return effort;
}

export type MatchRange = [number, number];

export interface HighlightSegment {
  text: string;
  highlighted: boolean;
}

export function findLiteralMatches(
  text: string,
  query: string,
  caseSensitive: boolean
): MatchRange[] {
  const needle = query.trim();
  if (!needle) return [];

  const haystack = caseSensitive ? text : text.toLowerCase();
  const normalizedNeedle = caseSensitive ? needle : needle.toLowerCase();
  const matches: MatchRange[] = [];
  let cursor = 0;

  while (cursor <= haystack.length - normalizedNeedle.length) {
    const index = haystack.indexOf(normalizedNeedle, cursor);
    if (index < 0) break;
    matches.push([index, index + normalizedNeedle.length]);
    cursor = index + normalizedNeedle.length;
  }

  return matches;
}

export function findRegexMatches(
  text: string,
  query: string,
  caseSensitive: boolean
): MatchRange[] {
  const pattern = query.trim();
  if (!pattern) return [];

  let regex: RegExp;
  try {
    regex = new RegExp(pattern, caseSensitive ? "g" : "gi");
  } catch {
    return [];
  }

  const matches: MatchRange[] = [];
  let match: RegExpExecArray | null;
  while ((match = regex.exec(text))) {
    if (match[0].length === 0) {
      regex.lastIndex++;
      continue;
    }
    matches.push([match.index, match.index + match[0].length]);
  }
  return matches;
}

export function findSearchMatches(
  text: string,
  query: string,
  caseSensitive: boolean,
  regex: boolean
): MatchRange[] {
  return regex
    ? findRegexMatches(text, query, caseSensitive)
    : findLiteralMatches(text, query, caseSensitive);
}

export function splitHighlightedText(
  text: string,
  matches: MatchRange[]
): HighlightSegment[] {
  if (matches.length === 0) {
    return text ? [{ text, highlighted: false }] : [];
  }

  const segments: HighlightSegment[] = [];
  let cursor = 0;

  for (const [start, end] of matches) {
    const safeStart = Math.max(cursor, Math.min(start, text.length));
    const safeEnd = Math.max(safeStart, Math.min(end, text.length));
    if (safeStart > cursor) {
      segments.push({ text: text.slice(cursor, safeStart), highlighted: false });
    }
    if (safeEnd > safeStart) {
      segments.push({ text: text.slice(safeStart, safeEnd), highlighted: true });
    }
    cursor = safeEnd;
  }

  if (cursor < text.length) {
    segments.push({ text: text.slice(cursor), highlighted: false });
  }

  return segments;
}

/**
 * 架构 §8：Desktop `//` 命令系统。
 *
 * 命令分两类，语义不同（§8.1）：
 *
 * 1. **内置控制命令**（如 `//force-automode`）——本地派发，**不发给 LLM**：
 *    handler 直接调 Tauri command 改 desktop 进程态 / session meta，结果以 toast 回显，
 *    不写 transcript / 不写 model request。失败 fail-closed 弹 toast。
 *
 * 2. **Skill 命令**（如 `//commit`，对应 `~/.hebbian/skills/commit/SKILL.md`）——
 *    本地识别 + 改写后发给 LLM：handler 把 `//<name> [args]` 改写成普通 user message
 *    `/<name> [args]` 并走正常发送路径，模型读到后会自动调用 [`Skill`] 工具读 SKILL.md。
 *    skill 命令必然写进 transcript（这是模型理解上下文的前提）。
 *
 * 调用方（ChatInput）在 submit 路径上调 `dispatchSlashCommand(value, ctx, skills)`：
 * - 命中（内置或 skill）→ 执行 handler，返回 `{ handled: true }`；ChatInput 跳过原始 onSend
 * - 未命中（仍以 `//` 开头但名字陌生且不是 skill）→ `{ handled: true, error: "..." }`，
 *   ChatInput 显示错误 toast，避免把伪命令当 prompt 发给模型
 * - 不以 `//` 开头 → `{ handled: false }`，ChatInput 走原始流程
 *
 * 区别于历史的单斜杠命令（`/compact`）：单斜杠是早期硬编码拦截，将来再统一搬到
 * 这套系统；新命令一律 `//` 前缀，避免与模型可能输出的路径 / 引用记号冲突。
 */

import { api } from "@/desktop/bridge/tauri";
import type { SkillItem } from "@/desktop/ui/types";

export interface SlashContext {
  sessionId: string | null;
  toast: {
    success: (msg: string) => void;
    error: (msg: string) => void;
    info?: (msg: string) => void;
  };
  /**
   * 把一段文本作为 user message 发出去（走正常 onSend 路径）。
   * 仅 skill 命令会用，内置控制命令永远不调（§8.1.5）。
   */
  sendPrompt: (text: string) => Promise<void>;
}

export interface SlashResult {
  handled: boolean;
  error?: string;
}

type BuiltinHandler = (args: string[], ctx: SlashContext) => Promise<void>;

/**
 * 命令清单元数据，供 ChatInput 工具栏的 `//` popup 渲染列表。
 *
 * `kind` 区分命令类型：
 * - `"builtin"`：内置控制命令，handler 在本文件 [`builtinRegistry`] 里
 * - `"skill"`：动态 skill 命令，handler 由 [`dispatchSlashCommand`] 统一处理
 */
export interface SlashCommandMeta {
  /** 不带 `//` 前缀的命令名，例如 `"force-automode"`。 */
  name: string;
  /** 在 popup 列表里跟在命令名后的参数提示，例如 `"[on|off|toggle|status]"`。 */
  args: string;
  /** 一句话描述，rendered 在列表右侧；保持 < 60 字符。 */
  desc: string;
  kind: "builtin" | "skill";
  /** skill 专有：标识它来自哪个 scope（用于 popup 角标）。 */
  skillSource?: SkillItem["source"];
}

/** 内置命令的静态清单，供 popup 列表的"内置"分组使用。 */
export const builtinSlashCommands: SlashCommandMeta[] = [
  {
    name: "force-automode",
    args: "[on|off|toggle|status]",
    desc: "自动模式下遇到不确定操作直接拒绝",
    kind: "builtin",
  },
  {
    name: "plugin",
    args: "<subcommand>",
    desc: "插件管理：install / uninstall / list / marketplace",
    kind: "builtin",
  },
];

const builtinRegistry: Record<string, BuiltinHandler> = {
  "force-automode": async (args, ctx) => {
    if (!ctx.sessionId) {
      throw new Error("当前没有打开的对话");
    }
    const current = await api.getForceAutomode(ctx.sessionId);
    const arg = args[0]?.toLowerCase();
    if (arg === "status") {
      ctx.toast.success(current ? "「自动拒绝」当前已开启" : "「自动拒绝」当前已关闭");
      return;
    }
    const next = parseBoolArg(arg, current);
    const applied = await api.setForceAutomode(ctx.sessionId, next);
    ctx.toast.success(
      applied
        ? "已开启「自动拒绝」：不确定的操作不再询问，直接拒绝"
        : "已关闭「自动拒绝」"
    );
  },

  plugin: async (args, ctx) => {
    await handlePluginCommand(args, ctx);
  },
};

/** 解析 `on` / `off` / `toggle`（或缺省）；缺省 = 翻转当前值。 */
function parseBoolArg(raw: string | undefined, current: boolean): boolean {
  if (!raw) return !current;
  switch (raw) {
    case "on":
    case "true":
    case "1":
    case "enable":
    case "enabled":
      return true;
    case "off":
    case "false":
    case "0":
    case "disable":
    case "disabled":
      return false;
    case "toggle":
      return !current;
    default:
      throw new Error(`无法识别的参数：${raw}（期望 on / off / toggle / status）`);
  }
}

/**
 * `//plugin` 命令族 handler（架构 §6.1.4）。
 *
 * 子命令：
 * - `marketplace add <owner/repo>`
 * - `marketplace list`
 * - `marketplace remove <name>`
 * - `install <name> [@marketplace]`
 * - `uninstall <name>`
 * - `list`
 */
async function handlePluginCommand(args: string[], ctx: SlashContext): Promise<void> {
  if (args.length === 0) {
    throw new Error(
      "用法：//plugin <子命令>\n" +
      "  marketplace add <owner/repo>  — 添加插件市场\n" +
      "  marketplace list              — 列出已添加的市场\n" +
      "  marketplace remove <name>     — 删除市场\n" +
      "  install <name>                — 安装插件\n" +
      "  uninstall <name>              — 卸载插件\n" +
      "  list                          — 列出已安装插件"
    );
  }

  const sub = args[0].toLowerCase();

  if (sub === "marketplace" || sub === "market") {
    const action = args[1]?.toLowerCase();
    if (action === "add") {
      const source = args[2];
      if (!source) throw new Error("缺少来源：//plugin marketplace add <owner/repo>");
      const name = await api.pluginMarketplaceAdd(source);
      ctx.toast.success(`已添加 marketplace：${name}`);
    } else if (action === "list") {
      const list = await api.pluginMarketplaceList();
      if (list.length === 0) {
        ctx.toast.info?.("还没有添加任何 marketplace") ??
          ctx.toast.success("还没有添加任何 marketplace");
      } else {
        const lines = list.map(([n, s]) => `  ${n} — ${s}`).join("\n");
        ctx.toast.success(`已添加的 marketplace：\n${lines}`);
      }
    } else if (action === "remove" || action === "rm") {
      const name = args[2];
      if (!name) throw new Error("缺少名字：//plugin marketplace remove <name>");
      await api.pluginMarketplaceRemove(name);
      ctx.toast.success(`已删除 marketplace：${name}`);
    } else {
      throw new Error(
        "未知 marketplace 操作：" + (action ?? "(空)") +
        "（支持 add / list / remove）"
      );
    }
    return;
  }

  if (sub === "install") {
    const raw = args[1];
    if (!raw) throw new Error("缺少插件名：//plugin install <name>");
    // 支持 name@marketplace 格式
    let name: string;
    let marketplace: string | null = null;
    const atIdx = raw.indexOf("@");
    if (atIdx > 0) {
      name = raw.slice(0, atIdx);
      marketplace = raw.slice(atIdx + 1);
    } else {
      name = raw;
    }
    const result = await api.pluginInstall(name, marketplace);
    const parts: string[] = [];
    if (result.skills_count > 0) parts.push(`${result.skills_count} skills`);
    if (result.agents_count > 0) parts.push(`${result.agents_count} agents`);
    if (result.has_hooks) parts.push("hooks");
    if (result.mcp_servers_count > 0) parts.push(`${result.mcp_servers_count} MCP servers`);
    const summary = parts.length > 0 ? `（${parts.join("、")}）` : "";
    ctx.toast.success(`已安装插件：${result.display_name ?? result.name}${summary}`);
    return;
  }

  if (sub === "uninstall") {
    const name = args[1];
    if (!name) throw new Error("缺少插件名：//plugin uninstall <name>");
    await api.pluginUninstall(name);
    ctx.toast.success(`已卸载插件：${name}`);
    return;
  }

  if (sub === "list") {
    const list = await api.pluginList();
    if (list.length === 0) {
      ctx.toast.info?.("还没有安装任何插件") ??
        ctx.toast.success("还没有安装任何插件");
    } else {
      const lines = list.map((p) => {
        const label = p.display_name ?? p.name;
        const ver = p.version ? ` v${p.version}` : "";
        return `  ${label}${ver}`;
      }).join("\n");
      ctx.toast.success(`已安装插件：\n${lines}`);
    }
    return;
  }

  if (sub === "update") {
    // TODO: plugin update
    throw new Error("//plugin update 暂未实现");
  }

  throw new Error(
    `未知子命令：${sub}（支持 marketplace / install / uninstall / list）`
  );
}

/** Skill 公开名：frontmatter alias 优先（与目录名不同时），回退目录名。 */
function skillDisplayName(s: SkillItem): string {
  return s.alias && s.alias !== s.name ? s.alias : s.name;
}

/**
 * 把动态 skills 拼到内置清单后，得到 popup 完整列表。
 *
 * - 仅展示 `enabled=true` 的 skill（被禁用的就不该出现在命令面板里）
 * - 同名 skill 若与内置命令冲突，**内置优先**（理论上不该撞，撞了内置覆盖）
 * - skill 命令的 args 提示固定为 `[args…]`，desc 取 SKILL.md 的 description 截断
 * - **公开名**用 alias（frontmatter `name:`）优先，目录名做副名——和 SkillTool
 *   description 给模型看到的列表保持一致，避免用户敲 `//karpathy-guidelines` 时
 *   popup 里只显示目录名 `karpathy` 看不到对应项
 */
export function buildSlashCommandCatalog(skills: SkillItem[]): SlashCommandMeta[] {
  const builtinNames = new Set(builtinSlashCommands.map((c) => c.name));
  const skillMetas = skills
    .filter((s) => s.enabled && !builtinNames.has(skillDisplayName(s)))
    .map<SlashCommandMeta>((s) => ({
      name: skillDisplayName(s),
      args: "[args…]",
      desc: trimDesc(s.description),
      kind: "skill",
      skillSource: s.source,
    }));
  return [...builtinSlashCommands, ...skillMetas];
}

function trimDesc(s: string, limit = 80): string {
  const oneLine = s.replace(/\s+/g, " ").trim();
  if (oneLine.length <= limit) return oneLine;
  return oneLine.slice(0, limit) + "…";
}

/**
 * 尝试把一行输入当作 `//` 命令派发；返回是否被消费。
 *
 * `skills` 来自上层（ChatInput 在 workdir 变化时调 `api.listSkills` 拉一次）。
 * 命令查找顺序：内置 → enabled skill。
 *
 * 输入的 leading/trailing 空白由调用方负责裁剪；本函数从第一个 token 解析命令名。
 */
export async function dispatchSlashCommand(
  raw: string,
  ctx: SlashContext,
  skills: SkillItem[]
): Promise<SlashResult> {
  if (!raw.startsWith("//")) {
    return { handled: false };
  }
  const body = raw.slice(2).trim();
  if (!body) {
    return { handled: true, error: "空命令：示例 `//force-automode on`" };
  }
  const [name, ...args] = body.split(/\s+/);

  // 1) 内置控制命令
  const builtin = builtinRegistry[name];
  if (builtin) {
    try {
      await builtin(args, ctx);
      return { handled: true };
    } catch (e: any) {
      return { handled: true, error: e?.message ?? String(e) };
    }
  }

  // 2) Skill 命令：转化为 user message 让模型自动调 Skill 工具
  //    匹配规则：目录名 (`s.name`) 或 frontmatter alias 任一命中即可
  const skill = skills.find((s) => s.name === name || s.alias === name);
  if (skill) {
    if (!skill.enabled) {
      return {
        handled: true,
        error: `Skill「${name}」已禁用，请到 Skills 面板启用后再用`,
      };
    }
    try {
      // 转发文本：用模型在 SkillTool description 里看到的公开名（alias 优先），
      // 让模型按 `/<skill-name> <args>` 的形式触发 Skill 工具。SKILL.md 的内容由
      // SkillTool 在 tool_result 里回填——这里不内嵌内容，避免重复污染上下文。
      const forwardName = skillDisplayName(skill);
      const forwarded = args.length > 0 ? `/${forwardName} ${args.join(" ")}` : `/${forwardName}`;
      await ctx.sendPrompt(forwarded);
      return { handled: true };
    } catch (e: any) {
      return { handled: true, error: e?.message ?? String(e) };
    }
  }

  // 3) 既不是内置也不是 skill → 提示用户已注册名单（公开名）
  const knownBuiltin = Object.keys(builtinRegistry)
    .map((n) => `//${n}`)
    .join(", ");
  const knownSkills = skills
    .filter((s) => s.enabled)
    .map((s) => `//${skillDisplayName(s)}`)
    .join(", ");
  const hint = knownSkills ? `${knownBuiltin}; skills: ${knownSkills}` : knownBuiltin;
  return {
    handled: true,
    error: `未知命令：//${name}（已注册：${hint}）`,
  };
}

import { useEffect, useState } from "react";
import { api } from "@/desktop/bridge/tauri";

/**
 * 计算 `oldString` 在 `originalText` 里的起始行号（1-based）。
 *
 * - `oldString` 为空 / 未匹配上 → 返回 1（DiffViewer 默认行号语义）。
 * - 命中多次：取第一次出现的位置。前端无法消歧，但 agent-core 的
 *   `unique_match` 校验已保证后端真正写盘时 oldString 全局唯一，所以
 *   流式预览阶段第一次出现的位置和真实落点一致。
 */
export function lineOfOldString(originalText: string, oldString: string): number {
  if (!originalText || !oldString) return 1;
  const idx = originalText.indexOf(oldString);
  if (idx < 0) return 1;
  let line = 1;
  for (let i = 0; i < idx; i++) {
    if (originalText.charCodeAt(i) === 10) line++;
  }
  return line;
}

/**
 * 把可能的相对路径解析到绝对路径。
 * - 已是绝对路径（unix `/` 开头 / windows drive `C:\`）→ 原样返回。
 * - 相对路径且有 workdir → `workdir/path`（用 `/` 拼接，跨平台 readTextFile 都吃）。
 * - 否则返回 null（无法解析就跳过读盘）。
 */
function resolvePath(path: string | undefined, workdir: string | null): string | null {
  if (!path) return null;
  if (path.startsWith("/") || /^[a-zA-Z]:[\\/]/.test(path)) return path;
  if (!workdir) return null;
  const sep = workdir.endsWith("/") || workdir.endsWith("\\") ? "" : "/";
  return `${workdir}${sep}${path}`;
}

/**
 * Edit diff 渲染时获取「原文件文本」用于定位 old_string 起始行号。
 *
 * 三种调用点行为：
 * - 流式：file_path / workdir 解析出绝对路径后读一次盘，缓存住，后续 args 字符级
 *   抖动不重读。
 * - 审批 / 非放大 detail：参数已完整，同样读一次盘。
 * - 完整 payload 可用时（放大 detail）调用方不应调本 hook，传 base=1 即可。
 *
 * 读盘失败（路径错 / 文件不存在 / 超 8MiB）→ originalText 保持 null；调用方
 * 应 fallback 到 base=1。
 */
export function useOriginalFileText(
  filePath: string | undefined,
  workdir: string | null,
  enabled: boolean,
): string | null {
  const [text, setText] = useState<string | null>(null);
  const absPath = resolvePath(filePath, workdir);

  useEffect(() => {
    if (!enabled || !absPath) {
      setText(null);
      return;
    }
    let cancelled = false;
    api
      .readTextFile(absPath)
      .then((t) => {
        if (!cancelled) setText(t);
      })
      .catch(() => {
        if (!cancelled) setText(null);
      });
    return () => {
      cancelled = true;
    };
  }, [absPath, enabled]);

  return text;
}

import clsx, { type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
