    set((state) => ({
      currentSession: s,
      pendingPromptId: s.prompt_id ?? "",
      currentInputQueue: state.inputQueues[s.id] ?? [],
      ...mirrorFromSlot(state.sessionStreams[s.id]),
    }));
  },

