//! `//force-automode` 命令的 desktop 进程级开关（架构 §4.4.4 / §8）。
//!
//! 仅在内存中保留 session_id → bool 映射，不写盘：
//! - 关掉 / 重启 desktop 进程后回到 `false`（这是一个明示「放手跑、不打断我」
//!   的危险开关，重启回归默认更安全）
//! - 多窗口共享同一进程 → 同一张表，并发由 `Mutex` 兜底
//!
//! Tauri 命令 `set_force_automode` 写入这张表；`chat::send_and_save` 在构造
//! `SessionConfig` 时读它填到 `force_automode` 字段。

use std::collections::HashMap;
use std::sync::Mutex;

#[derive(Default)]
pub struct ForceAutomodeState {
    inner: Mutex<HashMap<String, bool>>,
}

impl ForceAutomodeState {
    pub fn is_enabled(&self, session_id: &str) -> bool {
        self.inner
            .lock()
            .unwrap()
            .get(session_id)
            .copied()
            .unwrap_or(false)
    }

    pub fn set(&self, session_id: String, enabled: bool) {
        let mut guard = self.inner.lock().unwrap();
        if enabled {
            guard.insert(session_id, true);
        } else {
            guard.remove(&session_id);
        }
    }
}

apps/desktop/src/hebisland_client.rs.content:
// hebisland socket client
//
// 启动时建立一条到 `~/.hebbian/island.sock` 的持久连接，
// 后续所有通知推送和 action 回传都走这一条连接。
//
// 推送方向（Desktop → hebisland）：
//   {"type":"show","id":"...","card":{...}}
//   {"type":"dismiss","id":"..."}
//
// 回传方向（hebisland → Desktop）：
//   {"msg_id":"...","action":"...","selected":[...],"input":"...","checked":[...]}
//
// 回传收到后调 `hitl::resolve_hitl_from_island` 落地审批决定，
// 或 `hitl::answer_question_from_island` 落地问答回答。

use std::io::{BufRead, BufReader, Write};
use std::os::unix::net::UnixStream;
use std::sync::mpsc;

use tauri::AppHandle;

enum ClientMsg {
    /// 推送一条通知到 hebisland。json 是完整序列化后的 {"type":"show",...}
    Show { json: String },
    /// 关闭一条通知
    Dismiss { json: String },
}

/// 客户端句柄：clone 安全，内部只是一个 channel sender。
#[derive(Clone)]
pub struct HebislandClient {
    tx: mpsc::Sender<ClientMsg>,
}

impl HebislandClient {
    /// 推送一条通知。id 同时用作 msg_id（回传时映射回 request_id）。
    /// card_type: "approval" | "info" | "question" | "success"
    /// extra_fields: 可选的额外 card 字段（options / multiSelect / subcommands），
    ///   格式如 r#","options":[{"label":"A"},{"label":"B"}],"multiSelect":false"#
    pub fn push(
        &self,
        id: String,
        card_type: &str,
        title: &str,
        body: &str,
        session_id: Option<&str>,
        extra_fields: Option<&str>,
    ) {
        let sid = match session_id {
            Some(s) => format!(r#","sessionId":"{}""#, s),
            None => String::new(),
        };
        let extra = extra_fields.unwrap_or("");
        let json = format!(
            r#"{{"type":"show","id":"{id}","card":{{"id":"{id}","cardType":"{card_type}","title":"{title}","body":"{body}"{sid}{extra}}}}}"#
        );
        let _ = self.tx.send(ClientMsg::Show { json });
    }

    /// 关闭一条通知。
    pub fn dismiss(&self, id: &str) {
        let json = format!(r#"{{"type":"dismiss","id":"{id}"}}"#);
        let _ = self.tx.send(ClientMsg::Dismiss { json });
    }
}

/// 启动时调用一次，建立 socket 连接并启动后台 IO 线程。
/// 返回 client handle 供 chat.rs 等调用。
pub fn init_hebisland_client(app: AppHandle) -> HebislandClient {
    let (tx, rx) = mpsc::channel::<ClientMsg>();

    let app_for_reader = app.clone();
    std::thread::spawn(move || {
        client_loop(app_for_reader, rx);
    });

    HebislandClient { tx }
}

fn client_loop(app: AppHandle, rx: mpsc::Receiver<ClientMsg>) {
    let sock_path = dirs::home_dir()
        .expect("无法获取 home 目录")
        .join(".hebbian")
        .join("island.sock");

    let mut stream = match UnixStream::connect(&sock_path) {
        Ok(s) => s,
        Err(e) => {
            tracing::warn!("hebisland daemon 未运行 ({e})，通知将不弹出");
            for _ in rx {}
            return;
        }
    };

    tracing::info!("hebisland socket 已连接: {}", sock_path.display());

    let reader_stream = match stream.try_clone() {
        Ok(s) => s,
        Err(e) => {
            tracing::warn!("hebisland try_clone 失败: {e}");
            return;
        }
    };

    // reader 线程：接收 action 回传 → 落地 HITL
    let reader_app = app.clone();
    std::thread::spawn(move || {
        let reader = BufReader::new(reader_stream);
        for line in reader.lines() {
            match line {
                Ok(line) => {
                    if let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) {
                        let msg_id = v["msg_id"].as_str().unwrap_or("");
                        let action = v["action"].as_str().unwrap_or("");
                        tracing::info!(msg_id, action, "hebisland action 回传");

                        // 提取可选的 selected / input / checked
                        let selected = v["selected"].as_array().map(|arr| {
                            arr.iter().filter_map(|x| x.as_i64().map(|n| n as usize)).collect::<Vec<_>>()
                        });
                        let input = v["input"].as_str().map(|s| s.to_string());
                        let checked = v["checked"].as_array().map(|arr| {
                            arr.iter().filter_map(|x| x.as_i64().map(|n| n as usize)).collect::<Vec<_>>()
                        });

                        // msg_id 格式为 "perm-{request_id}" 或 "question-{request_id}"
                        let (prefix, request_id) = if let Some(rid) = msg_id.strip_prefix("perm-") {
                            ("perm", rid)
                        } else if let Some(rid) = msg_id.strip_prefix("question-") {
                            ("question", rid)
                        } else {
                            ("unknown", msg_id)
                        };

                        match prefix {
                            "perm" => {
                                crate::hitl::resolve_hitl_from_island(
                                    &reader_app, request_id, action,
                                    checked.as_deref(),
                                );
                            }
                            "question" => {
                                crate::hitl::answer_question_from_island(
                                    &reader_app, request_id, action,
                                    selected.as_deref(), input.as_deref(),
                                );
                            }
                            _ => {
                                tracing::warn!(msg_id, action, "未知 msg_id 前缀");
                            }
                        }
                    }
                }
                Err(e) => {
                    tracing::warn!("hebisland socket 读错误: {e}");
                    break;
                }
            }
        }
    });

    // writer 循环
    for msg in rx {
        let (json, label) = match &msg {
            ClientMsg::Show { json } => (json.as_str(), "show"),
            ClientMsg::Dismiss { json } => (json.as_str(), "dismiss"),
        };
        let mut buf = json.as_bytes().to_vec();
        buf.push(b'\n');
        if stream.write_all(&buf).is_err() {
            tracing::warn!("hebisland socket 写失败，停止推送 ({label})");
            break;
        }
    }
}

apps/desktop/src/hitl.rs.content:
//! HITL 桥接：审批 / 提问 共用一张表。
//!
//! `chat::send_and_save` 在 spawn run 前后把 `Arc<HitlGate>` 关联到
//! 当前事件流；事件回调里看到 `PermissionRequested` / `UserQuestionRequested`
//! 时调 [`HitlState::track`] 把 `request_id → HitlGate` 注册进表。
//!
//! Tauri 命令 `approve_permission` / `answer_question` 通过 request_id
//! 找到对应 HitlGate 并 resolve / answer。
//!
//! Run 结束时调 [`HitlState::forget`] 清掉残留映射，避免泄漏。

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use agent_core::tools::hitl::HitlGate;
use common::runtime::CancelFlag;

#[derive(Default)]
pub struct HitlState {
    pending: Mutex<HashMap<String, Arc<HitlGate>>>,
    runs: Mutex<HashMap<String, (CancelFlag, Arc<HitlGate>)>>,
}

impl HitlState {
    /// 关联一次前端 request_id 到当前 run 的取消标志和 HitlGate。
    pub fn track_run(&self, request_id: String, cancel: CancelFlag, gate: Arc<HitlGate>) {
        self.runs.lock().unwrap().insert(request_id, (cancel, gate));
    }

    /// 关联 `request_id` 到当前 run 的 HitlGate。
    pub fn track(&self, request_id: String, gate: Arc<HitlGate>) {
        self.pending.lock().unwrap().insert(request_id, gate);
    }

    pub fn cancel_run(&self, request_id: &str) -> bool {
        let Some((cancel, gate)) = self.runs.lock().unwrap().get(request_id).cloned() else {
            return false;
        };
        cancel.store(true, std::sync::atomic::Ordering::SeqCst);
        gate.cancel_all_pending();
        true
    }

    pub fn resolve_approval(
        &self,
        request_id: &str,
        decision: protocol::ApprovalDecision,
    ) -> Result<(), String> {
        let gate = self
            .pending
            .lock()
            .unwrap()
            .remove(request_id)
            .ok_or_else(|| format!("找不到 request_id: {request_id}"))?;
        gate.resolve(
            &protocol::PermissionRequestId::from_raw(request_id),
            decision,
        );
        Ok(())
    }

    pub fn answer_question(
        &self,
        request_id: &str,
        answer: protocol::UserAnswer,
    ) -> Result<(), String> {
        let gate = self
            .pending
            .lock()
            .unwrap()
            .remove(request_id)
            .ok_or_else(|| format!("找不到 request_id: {request_id}"))?;
        gate.answer(&protocol::PermissionRequestId::from_raw(request_id), answer);
        Ok(())
    }

    /// run 结束时清掉指向该 gate 的所有残留映射。
    pub fn forget(&self, gate: &Arc<HitlGate>) {
        self.pending
            .lock()
            .unwrap()
            .retain(|_id, g| !Arc::ptr_eq(g, gate));
        self.runs
            .lock()
            .unwrap()
            .retain(|_id, (_cancel, g)| !Arc::ptr_eq(g, gate));
    }

    /// 把所有 pending 的审批 / 提问按"取消"resolve；用于 desktop 关窗等场景，
    /// 让正在 await 的 spawn_ask / spawn_tool 即刻醒来收尾。
    /// 返回被取消的 gate 唯一数量（去重后）。
    pub fn cancel_all_pending(&self) -> usize {
        let gates: Vec<Arc<HitlGate>> = {
            let mut seen: Vec<Arc<HitlGate>> = Vec::new();
            let mut pending = self.pending.lock().unwrap();
            for gate in pending.values() {
                if !seen.iter().any(|g| Arc::ptr_eq(g, gate)) {
                    seen.push(gate.clone());
                }
            }
            pending.clear();
            drop(pending);

            let mut runs = self.runs.lock().unwrap();
            for (cancel, gate) in runs.values() {
                cancel.store(true, std::sync::atomic::Ordering::SeqCst);
                if !seen.iter().any(|g| Arc::ptr_eq(g, gate)) {
                    seen.push(gate.clone());
                }
            }
            runs.clear();
            seen
        };
        let count = gates.len();
        for gate in gates {
            gate.cancel_all_pending();
        }
        count
    }

    /// 当前是否有未 resolve 的 HITL 请求。
    pub fn has_pending(&self) -> bool {
        !self.pending.lock().unwrap().is_empty()
    }
}

/// Island 浮层快捷审批入口：支持 AllowOnce / Deny / AllowAndRemember。
/// `checked` 是用户在子命令列表中勾选的索引（空 = 全部勾选）。
pub fn resolve_hitl_from_island(
    app: &tauri::AppHandle,
    request_id: &str,
    decision_str: &str,
    checked: Option<&[usize]>,
) {
    use std::sync::Arc;
    use tauri::Manager;

    let Some(state) = app.try_state::<Arc<HitlState>>() else {
        tracing::warn!("island_approve: HitlState not available");
        return;
    };
    let decision = match decision_str {
        "allow" => protocol::ApprovalDecision::AllowOnce,
        "deny" => protocol::ApprovalDecision::Deny,
        "allow_conversation" => protocol::ApprovalDecision::AllowAndRemember {
            scope: protocol::PermissionScope::Session,
            pattern: None,
            extra_patterns: vec![],
        },
        "allow_project" => protocol::ApprovalDecision::AllowAndRemember {
            scope: protocol::PermissionScope::Project,
            pattern: None,
            extra_patterns: vec![],
        },
        "allow_global" => protocol::ApprovalDecision::AllowAndRemember {
            scope: protocol::PermissionScope::Global,
            pattern: None,
            extra_patterns: vec![],
        },
        other => {
            tracing::warn!(decision = other, "island_approve: unknown decision");
            return;
        }
    };
    if let Err(e) = state.resolve_approval(request_id, decision) {
        tracing::warn!(error = %e, "island_approve: failed to resolve");
    }
}

/// Island 问答回答入口：支持 Selected / SelectedMulti / Custom / Cancelled。
/// `selected` 是用户选中的选项索引，`input` 是自由输入文本。
pub fn answer_question_from_island(
    app: &tauri::AppHandle,
    request_id: &str,
    action: &str,
    selected: Option<&[usize]>,
    input: Option<&str>,
) {
    use std::sync::Arc;
    use tauri::Manager;

    let Some(state) = app.try_state::<Arc<HitlState>>() else {
        tracing::warn!("island_answer: HitlState not available");
        return;
    };
    let answer = match action {
        "skip" => protocol::UserAnswer::Cancelled,
        "submit" => {
            // 优先用自由输入，其次用选中项
            if let Some(text) = input {
                protocol::UserAnswer::Custom { text: text.to_string() }
            } else if let Some(indices) = selected {
                if indices.len() == 1 {
                    // 单选：用索引占位，实际 label 由后端从 options 里取
                    protocol::UserAnswer::Selected { label: format!("option_{}", indices[0]) }
                } else {
                    protocol::UserAnswer::SelectedMulti {
                        labels: indices.iter().map(|i| format!("option_{i}")).collect(),
                    }
                }
            } else {
                protocol::UserAnswer::Cancelled
            }
        }
        other => {
            tracing::warn!(action = other, "island_answer: unknown action");
            return;
        }
    };
    if let Err(e) = state.answer_question(request_id, answer) {
        tracing::warn!(error = %e, "island_answer: failed to answer");
    }
}

