#[derive(Debug, Clone, serde::Serialize)]
struct InjectUserMessageResult {
    message: agent_core::storage::sessions::Message,
    injected: bool,
}

#[tauri::command]
fn cancel_message(hitl: State<'_, Arc<HitlState>>, request_id: String) -> bool {
