#[tauri::command]
fn add_permission(
    app: AppHandle,
    scope: String,
    effect: String,
    pattern: String,
    session_id: Option<String>,
    workdir: Option<PathBuf>,
) -> AppResult<()> {
    let scope = parse_perm_scope(&scope)?;
    let effect = parse_rule_effect(&effect)?;
    core(&app)?
        .add_permission(
            scope,
            session_id.as_deref(),
            workdir.as_deref(),
            effect,
