//! 前端可见的引擎事件（与 desktop `apps/desktop/src/engine/mod.rs` 字段对齐）。
//!
//! v1 在 hebweb 内复制一份是为了让浏览器前端能消费同一份 JSON 结构（前端 types.ts 不动）。
//! v2 会把这套类型 + 翻译函数抽到共享 crate（暂名 `crates/surface-events`），desktop / hebweb
//! 一起依赖那里。届时本文件删除。
//!
//! 与 desktop 版差异：本文件不渲染 StepStarted/Finished、PermissionAutoJudged、EditSnapshot*
//! 这些 v1 浏览器 surface 暂不需要的事件（前端 store 会忽略未知 variant）。

use protocol::{Event as AgentEvent, EventPayload};
use serde::Serialize;
use serde_json::Value;

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum EngineEvent {
    TextDelta {
        text: String,
        /// 子 NestedRun 事件来源标识（架构 §4.4.11.8）。前端按此字段嵌套渲染到父 Task 卡片内部。
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    TextDone {
        full_text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    Reasoning {
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    ToolCallDelta {
        index: usize,
        id: Option<String>,
        name: Option<String>,
        arguments_delta: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    ToolStart {
        index: usize,
        id: String,
        name: String,
        input: Value,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    ToolDone {
        index: usize,
        id: String,
        result: String,
        duration_ms: u64,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        artifact_path: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    /// 工具执行中的流式输出片段（架构 §4.4.1）。Bash 前台 stdout/stderr 按 chunk 推过来。
    ToolOutputDelta {
        index: usize,
        id: String,
        chunk: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        subagent_call_id: Option<String>,
    },
    RunSuspended {
        reason: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        resumes_at_ms: Option<i64>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        waiting_for_task_ids: Vec<String>,
    },
    RunResumed {
        cause: String,
    },
    PermissionRequested {
        request_id: String,
        kind: String,
        tool_name: String,
        input: Value,
        summary: String,
        risk: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        paths: Vec<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        fingerprint: Option<String>,
        /// Bash / PowerShell compound 命令的所有段 fingerprint（架构 §4.4.2）。
        /// 前端据此渲染"多选 list + scope 按钮"——每段一行 checkbox。
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        command_segments: Vec<String>,
        /// 完整段级状态（只读 / 已白名单 / 不可记忆 / 待审批），弹窗逐段展示
        /// （架构 §4.4.2.3）。
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        segments: Vec<protocol::ApprovalSegment>,
        /// 危险复合模式：任何作用域都不可记住，弹窗隐藏记忆区（架构 §4.4.2.2）。
        #[serde(default, skip_serializing_if = "std::ops::Not::not")]
        refuse_remember: bool,
    },
    PermissionResolved {
        request_id: String,
        decision: String,
    },
    RunModeChanged {
        from: String,
        to: String,
    },
    /// Turn 边界——一次"模型请求 + 可选 tool_call 批"结束（架构 §3 / §4.2）。
    /// 前端据此把当前 streaming bubble 冻结成"已完成 turn 快照"，下一个 Turn 起新
    /// streaming bubble；streaming 中的插队 user message 才能落在它真正回应的 Turn
    /// 之后、下个 Turn 之前。
    TurnFinished {
        /// "end_turn" / "max_iterations" / "permission_denied" / "cancelled" / "failed"
        stop_reason: String,
    },
    UserQuestionRequested {
        request_id: String,
        question: String,
        options: Vec<QuestionOptionDto>,
        #[serde(default)]
        multi: bool,
    },
    UserQuestionAnswered {
        request_id: String,
        kind: String,
        text: String,
    },
    /// 新会话首轮跑完后，agent_core 后台 task 异步生成的标题已落盘 jsonl。
    /// 前端用它更新 sidebar / chat header；落盘已由 agent_core 完成。
    SessionTitleChanged {
        session_id: String,
        title: String,
    },
    Error {
        message: String,
    },
}

#[derive(Debug, Clone, Serialize)]
pub struct QuestionOptionDto {
    pub label: String,
    pub description: String,
}

/// AgentEvent → EngineEvent。仅翻译浏览器 surface 需要的事件，其余返回 None。
pub fn translate(event: &AgentEvent) -> Option<EngineEvent> {
    use EventPayload::*;
    let subagent = event.subagent_call_id.clone();
    Some(match &event.payload {
        TextDelta { text } => EngineEvent::TextDelta {
            text: text.clone(),
            subagent_call_id: subagent.clone(),
        },
        TextDone { full_text } => EngineEvent::TextDone {
            full_text: full_text.clone(),
            subagent_call_id: subagent.clone(),
        },
        Reasoning { text } => EngineEvent::Reasoning {
            text: text.clone(),
            subagent_call_id: subagent.clone(),
        },
        ToolCallDelta {
            index,
            id,
            name,
            arguments_delta,
        } => EngineEvent::ToolCallDelta {
            index: *index,
            id: id.clone(),
            name: name.clone(),
            arguments_delta: arguments_delta.clone(),
            subagent_call_id: subagent.clone(),
        },
        ToolCallStarted {
            index,
            call_id,
            name,
            input,
        } => EngineEvent::ToolStart {
            index: *index,
            id: call_id.clone(),
            name: name.clone(),
            input: input.clone(),
            subagent_call_id: subagent.clone(),
        },
        ToolCallFinished {
            index,
            call_id,
            result,
            duration_ms,
            artifact_path,
            ..
        } => EngineEvent::ToolDone {
            index: *index,
            id: call_id.clone(),
            result: result.clone(),
            duration_ms: *duration_ms,
            artifact_path: artifact_path.clone(),
            subagent_call_id: subagent.clone(),
        },
        ToolCallOutputDelta {
            index,
            call_id,
            chunk,
        } => EngineEvent::ToolOutputDelta {
            index: *index,
            id: call_id.clone(),
            chunk: chunk.clone(),
            subagent_call_id: subagent.clone(),
        },
        RunFailed { error } => EngineEvent::Error {
            message: error.message.clone(),
        },
        RunSuspended {
            reason,
            resumes_at_ms,
            waiting_for_task_ids,
        } => EngineEvent::RunSuspended {
            reason: format!("{reason:?}").to_lowercase(),
            resumes_at_ms: *resumes_at_ms,
            waiting_for_task_ids: waiting_for_task_ids.clone(),
        },
        RunResumed { cause } => EngineEvent::RunResumed {
            cause: format!("{cause:?}"),
        },
        PermissionRequested {
            request_id,
            kind,
            summary,
            risk,
        } => {
            use protocol::PermissionKind::*;
            let (
                kind_str,
                tool_name,
                tool_input,
                paths,
                fingerprint,
                command_segments,
                segments,
                refuse_remember,
            ) = match kind {
                ToolCall {
                    tool_name,
                    input,
                    fingerprint,
                    command_segments,
                    segments,
                    refuse_remember,
                } => (
                    "tool_call",
                    tool_name.clone(),
                    input.clone(),
                    Vec::<String>::new(),
                    fingerprint.clone(),
                    command_segments.clone(),
                    segments.clone(),
                    *refuse_remember,
                ),
                PathAccess { tool_name, paths } => (
                    "path_access",
                    tool_name.clone(),
                    Value::Null,
                    paths.clone(),
                    None,
                    Vec::new(),
                    Vec::new(),
                    false,
                ),
                Plan { .. } => (
                    "plan",
                    String::new(),
                    Value::Null,
                    Vec::new(),
                    None,
                    Vec::new(),
                    Vec::new(),
                    false,
                ),
                ContinueLongRun { .. } => (
                    "continue_long_run",
                    String::new(),
                    Value::Null,
                    Vec::new(),
                    None,
                    Vec::new(),
                    Vec::new(),
                    false,
                ),
            };
            EngineEvent::PermissionRequested {
                request_id: request_id.as_str().to_string(),
                kind: kind_str.into(),
                tool_name,
                input: tool_input,
                summary: summary.clone(),
                risk: format!("{risk:?}").to_lowercase(),
                paths,
                fingerprint,
                command_segments,
                segments,
                refuse_remember,
            }
        }
        PermissionResolved {
            request_id,
            decision,
        } => {
            use protocol::ApprovalDecision::*;
            EngineEvent::PermissionResolved {
                request_id: request_id.as_str().to_string(),
                decision: match decision {
                    AllowOnce => "allow_once".into(),
                    AllowAndRemember { .. } => "allow_and_remember".into(),
                    Deny => "deny".into(),
                    DenyWithFeedback { .. } => "deny_with_feedback".into(),
                },
            }
        }
        UserQuestionRequested {
            request_id,
            question,
            options,
            multi,
        } => EngineEvent::UserQuestionRequested {
            request_id: request_id.as_str().to_string(),
            question: question.clone(),
            options: options
                .iter()
                .map(|o| QuestionOptionDto {
                    label: o.label.clone(),
                    description: o.description.clone(),
                })
                .collect(),
            multi: *multi,
        },
        UserQuestionAnswered { request_id, answer } => {
            use protocol::UserAnswer::*;
            let (kind, text) = match answer {
                Selected { label } => ("selected".to_string(), label.clone()),
                SelectedMulti { labels } => ("selected_multi".to_string(), labels.join("、")),
                Custom { text } => ("custom".to_string(), text.clone()),
                Cancelled => ("cancelled".to_string(), String::new()),
            };
            EngineEvent::UserQuestionAnswered {
                request_id: request_id.as_str().to_string(),
                kind,
                text,
            }
        }
        RunModeChanged { from, to } => EngineEvent::RunModeChanged {
            from: from.clone(),
            to: to.clone(),
        },
        TurnFinished { stop_reason, .. } => EngineEvent::TurnFinished {
            stop_reason: match stop_reason {
                protocol::StopReason::EndTurn => "end_turn",
                protocol::StopReason::MaxIterations => "max_iterations",
                protocol::StopReason::PermissionDenied => "permission_denied",
                protocol::StopReason::Cancelled => "cancelled",
                protocol::StopReason::Failed => "failed",
            }
            .to_string(),
        },
        SessionTitleChanged { session_id, title } => EngineEvent::SessionTitleChanged {
            session_id: session_id.clone(),
            title: title.clone(),
        },
        _ => return None,
    })
}

apps/web-server/src/main.rs.content:
//! hebweb — 浏览器 surface 的 HTTP + WebSocket server。
//!
//! # 启动
//!
//! ```bash
//! hebweb                                    # 默认 127.0.0.1:3030，data_dir ~/.hebbian
//! hebweb --port 4040                        # 自定义端口
//! hebweb --static-dir apps/desktop/frontend/dist  # 指定前端打包产物
//! hebweb --data-dir /tmp/hebbian-test       # 隔离的数据目录（多 AI 测试用）
//! ```
//!
//! # 一个 hebweb 进程 = 一组 session 的服务端
//!
//! 多个浏览器 / Playwright 各自打开 WS 连接，subscribe 到不同 session_id 即可看到
//! 各自的事件流（按 session 路由）。同一进程内多个 session 各自独立，互不阻塞。
//! 多 AI 调试推荐每人自己开 `hebweb --port <random>`——进程间通过 `~/.hebbian/`
//! 文件锁保证写安全。

use std::net::SocketAddr;
use std::path::PathBuf;

use anyhow::Result;
use clap::Parser;
use tracing::info;

mod chat_helpers;
mod events;
mod protocol;
mod server;
mod session;

#[derive(Parser, Debug)]
#[command(
    name = "hebweb",
    about = "Hebbian web surface（HTTP + WebSocket）",
    version
)]
struct Args {
    /// 监听地址（默认 127.0.0.1:3030）
    #[arg(long, default_value = "127.0.0.1:3030")]
    addr: String,

    /// 监听端口（覆盖 --addr 的端口）
    #[arg(long, short = 'p')]
    port: Option<u16>,

    /// 数据目录（默认 ~/.hebbian）
    #[arg(long)]
    data_dir: Option<PathBuf>,

    /// 前端静态文件目录（默认自动探测 apps/desktop/frontend/dist）
    #[arg(long)]
    static_dir: Option<PathBuf>,
}

#[tokio::main]
async fn main() -> Result<()> {
    observability::init("info");

    let args = Args::parse();
    let data_dir = args
        .data_dir
        .clone()
        .unwrap_or_else(agent_core::storage::default_data_dir);
    std::fs::create_dir_all(&data_dir)?;

    let static_dir = args.static_dir.clone().or_else(autodetect_static_dir);

    let state = server::ServerState::new(data_dir.clone());
    let app = server::build_router(state, static_dir.clone());

    // 解析监听地址
    let mut addr: SocketAddr = args.addr.parse()?;
    if let Some(p) = args.port {
        addr.set_port(p);
    }

    info!(
        addr = %addr,
        data_dir = %data_dir.display(),
        static_dir = ?static_dir,
        "hebweb starting"
    );
    eprintln!(
        "hebweb listening on http://{addr}  (data_dir={})",
        data_dir.display()
    );

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(listener, app).await?;
    Ok(())
}

/// 探测前端 dist 目录。优先 cwd 下 `apps/desktop/frontend/dist`，
/// 找不到时返回 None（用户用 vite dev server 自行访问）。
fn autodetect_static_dir() -> Option<PathBuf> {
    let candidates = [
        "apps/desktop/frontend/dist",
        "../apps/desktop/frontend/dist",
        "../../apps/desktop/frontend/dist",
    ];
    candidates
        .iter()
        .map(PathBuf::from)
        .find(|p| p.exists())
        .or_else(|| {
            // 同时尝试 CARGO_MANIFEST_DIR 相邻
            let here = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
            here.join("../desktop/frontend/dist")
                .canonicalize()
                .ok()
                .filter(|p| p.exists())
        })
}

apps/web-server/src/protocol.rs.content:
//! WebSocket 协议：client ↔ server 消息类型。
//!
//! 设计目标：与 desktop 的 Tauri invoke/emit 语义 1:1 对应，
//! 让前端只需 runtime detect 切换 transport 即可复用同一份业务代码。

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// client → server
#[derive(Debug, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum WsClientMessage {
    /// 绑定到某个 session 的事件流。建立 WS 连接后第一条必须是 subscribe。
    /// 同一连接可以多次 subscribe 切 session（前一个绑定自动取消）。
    Subscribe { session_id: String },
    /// 取消订阅（不关连接）
    Unsubscribe,
    /// 调用一个 server-side command（对应 Tauri invoke）
    /// id 由 client 生成，用于匹配响应；cmd 是命令名（snake_case）；args 是参数对象
    Invoke {
        id: String,
        cmd: String,
        #[serde(default)]
        args: Value,
        /// 可选：本次 invoke 关联的 session_id（多数 command 都需要）
        #[serde(default)]
        session_id: Option<String>,
    },
}

/// server → client
#[derive(Debug, Serialize, Clone)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum WsServerMessage {
    /// 连接握手回应（subscribe 之前）
    Hello { server_version: &'static str },
    /// 订阅成功
    Subscribed { session_id: String },
    /// invoke 的响应（按 id 匹配 client 请求）
    InvokeResponse {
        id: String,
        ok: bool,
        #[serde(skip_serializing_if = "Option::is_none")]
        data: Option<Value>,
        #[serde(skip_serializing_if = "Option::is_none")]
        error: Option<String>,
    },
    /// 来自 agent_core 的事件（按 session_id 路由）
    /// 形如 Tauri 的 emit("engine-event", payload)
    Event {
        session_id: String,
        name: String,
        payload: Value,
    },
}

impl WsServerMessage {
    pub fn ok(id: String, data: Option<Value>) -> Self {
        Self::InvokeResponse {
            id,
            ok: true,
            data,
            error: None,
        }
    }
    pub fn err(id: String, error: impl ToString) -> Self {
        Self::InvokeResponse {
            id,
            ok: false,
            data: None,
            error: Some(error.to_string()),
        }
    }
}

apps/web-server/src/server.rs.content:
//! axum router + WebSocket 处理 + invoke 命令派发。
//!
//! Routes:
//!   GET  /healthz         — 健康检查
//!   GET  /ws              — WebSocket 升级
//!   GET  /*               — 前端静态文件（dist 目录）
//!
//! 命令派发：每条 `Invoke` WS 消息 → 查 cmd 名字 → 调对应 handler → 回 InvokeResponse。
//! 事件流：handler 通过 `runtime.emit_engine_event(...)` 广播到所有订阅本 session 的 WS。

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc, Mutex,
};

use agent_core::{
    core_client::{CoreClient, LocalCoreClient},
    edits::{self, EditsWorktree},
    permissions::PermissionStore,
    storage::{
        projects as projects_store, prompts as prompts_store, sessions as sessions_store,
        sessions_dir, settings as settings_store,
    },
    workspace::Workspace,
};
use anyhow::{anyhow, Result};
use axum::{
    extract::{
        ws::{Message as WsMessage, WebSocket, WebSocketUpgrade},
        State,
    },
    response::IntoResponse,
    routing::{get, get_service},
    Json, Router,
};
use futures_util::{SinkExt, StreamExt};
use protocol::{ApprovalDecision, PermissionScope, UserAnswer};
use serde_json::{json, Value};
use tokio::sync::{broadcast, mpsc, RwLock};
use tower_http::services::ServeDir;
use tracing::{info, warn};

use crate::protocol::{WsClientMessage, WsServerMessage};
use crate::session::{run_turn, SessionRuntime};

const SERVER_VERSION: &str = env!("CARGO_PKG_VERSION");
const EVENT_CHANNEL_CAPACITY: usize = 1024;

// ─── 共享 server 状态 ─────────────────────────────────────────────────────

#[derive(Clone)]
pub struct ServerState {
    pub data_dir: PathBuf,
    /// session_id → SessionRuntime（多 session 共享同一进程）
    pub sessions: Arc<RwLock<HashMap<String, Arc<SessionRuntime>>>>,
    pub permission_store: Option<Arc<PermissionStore>>,
    /// 复用 desktop 同一个业务 facade。CoreClient trait 暴露的 25+ 方法
    /// 直接可用——无需 hebweb 自己再 wrap 一遍 storage / model_gateway API。
    pub core: Arc<LocalCoreClient>,
}

impl ServerState {
    pub fn new(data_dir: PathBuf) -> Self {
        let permission_store = PermissionStore::open(&data_dir).ok().map(Arc::new);
        // hebweb 内不挂 Harness——每个 SessionRuntime 自己跑 agent_loop。
        // facade 仅承担同步 API 转发（list/save/get providers / sessions / prompts / ...）。
        let core = Arc::new(LocalCoreClient::new(
            None,
            data_dir.clone(),
            permission_store.clone(),
        ));
        Self {
            data_dir,
            sessions: Arc::new(RwLock::new(HashMap::new())),
            permission_store,
            core,
        }
    }

    /// 取已 attach 的 SessionRuntime；若不存在则按 session.json 自动 attach 一个。
    /// attach 失败（session 不存在 / 缺 provider）返回 Err。
    pub async fn ensure_runtime(&self, session_id: &str) -> Result<Arc<SessionRuntime>> {
        if let Some(rt) = self.sessions.read().await.get(session_id).cloned() {
            return Ok(rt);
        }
        // 加锁后再检查一次，避免并发重复 attach
        let mut guard = self.sessions.write().await;
        if let Some(rt) = guard.get(session_id).cloned() {
            return Ok(rt);
        }

        let session = sessions_store::load(&self.data_dir, session_id)
            .map_err(|e| anyhow!("session {session_id} 不存在：{e}"))?;
        sessions_dir::ensure_session_dirs(&self.data_dir, session_id)?;

        let (input_tx, mut input_rx) = mpsc::unbounded_channel::<String>();
        let (event_tx, _) = broadcast::channel::<WsServerMessage>(EVENT_CHANNEL_CAPACITY);
        let run_mode = session.run_mode;

        let runtime = Arc::new(SessionRuntime {
            session_id: session_id.to_string(),
            data_dir: self.data_dir.clone(),
            provider_id: session.provider_id.clone(),
            model: session.model.clone(),
            reasoning: None,
            pending_approvals: Mutex::new(HashMap::new()),
            pending_questions: Mutex::new(HashMap::new()),
            active_run: AtomicBool::new(false),
            cancel_flag: Mutex::new(None),
            pending_inputs: Mutex::new(None),
            run_mode: Mutex::new(run_mode),
            force_automode: AtomicBool::new(false),
            input_tx,
            event_tx,
            permission_store: self.permission_store.clone(),
        });

        // 启动 turn 主循环：依次处理 input_rx 的每条输入
        let rt_for_loop = runtime.clone();
        tokio::spawn(async move {
            while let Some(text) = input_rx.recv().await {
                if let Err(e) = run_turn(rt_for_loop.clone(), text).await {
                    rt_for_loop.emit_engine_event(crate::events::EngineEvent::Error {
                        message: e.to_string(),
                    });
                }
            }
        });

        guard.insert(session_id.to_string(), runtime.clone());
        Ok(runtime)
    }
}

// ─── axum router ──────────────────────────────────────────────────────────

/// 启动 server。`static_dir` 是 dist/ 目录；不存在时只提供 healthz + ws。
pub fn build_router(state: ServerState, static_dir: Option<PathBuf>) -> Router {
    let mut router = Router::new()
        .route("/healthz", get(healthz))
        .route("/ws", get(ws_upgrade));

    if let Some(dir) = static_dir {
        if dir.exists() {
            // fallback_service：未匹配的路径都走静态文件
            router = router.fallback_service(get_service(ServeDir::new(dir.clone())));
            info!(?dir, "serving static frontend");
        } else {
            warn!(?dir, "static frontend dir 不存在，跳过");
        }
    }

    router.with_state(state)
}

async fn healthz(State(state): State<ServerState>) -> impl IntoResponse {
    let active: Vec<String> = state.sessions.read().await.keys().cloned().collect();
    Json(json!({
        "ok": true,
        "version": SERVER_VERSION,
        "data_dir": state.data_dir.display().to_string(),
        "active_sessions": active,
    }))
}

async fn ws_upgrade(ws: WebSocketUpgrade, State(state): State<ServerState>) -> impl IntoResponse {
    ws.on_upgrade(move |socket| handle_ws(socket, state))
}

// ─── 单 WS 连接 ────────────────────────────────────────────────────────────

async fn handle_ws(socket: WebSocket, state: ServerState) {
    let (mut sender, mut receiver) = socket.split();
    let (out_tx, mut out_rx) = mpsc::unbounded_channel::<WsServerMessage>();

    // 发送任务：把 WsServerMessage 序列化后写到 ws
    let send_task = tokio::spawn(async move {
        while let Some(msg) = out_rx.recv().await {
            let Ok(text) = serde_json::to_string(&msg) else {
                continue;
            };
            if sender.send(WsMessage::Text(text)).await.is_err() {
                break;
            }
        }
    });

    // 握手
    let _ = out_tx.send(WsServerMessage::Hello {
        server_version: SERVER_VERSION,
    });

    // 当前订阅的 session（同一连接同时只订阅一个；切换时 abort 旧 task）
    let mut event_task: Option<tokio::task::JoinHandle<()>> = None;

    while let Some(Ok(msg)) = receiver.next().await {
        let text = match msg {
            WsMessage::Text(t) => t,
            WsMessage::Close(_) => break,
            _ => continue,
        };
        let parsed: WsClientMessage = match serde_json::from_str(&text) {
            Ok(p) => p,
            Err(e) => {
                let _ = out_tx.send(WsServerMessage::err(
                    String::new(),
                    format!("invalid message: {e}"),
                ));
                continue;
            }
        };

        match parsed {
            WsClientMessage::Subscribe { session_id } => {
                // 终止旧订阅
                if let Some(t) = event_task.take() {
                    t.abort();
                }
                match state.ensure_runtime(&session_id).await {
                    Ok(runtime) => {
                        let mut rx = runtime.event_tx.subscribe();
                        let tx = out_tx.clone();
                        let sid = session_id.clone();
                        event_task = Some(tokio::spawn(async move {
                            while let Ok(ev) = rx.recv().await {
                                if tx.send(ev).is_err() {
                                    break;
                                }
                            }
                            tracing::debug!(session_id = %sid, "event subscription ended");
                        }));
                        let _ = out_tx.send(WsServerMessage::Subscribed { session_id });
                    }
                    Err(e) => {
                        let _ = out_tx.send(WsServerMessage::err(
                            String::new(),
                            format!("subscribe failed: {e}"),
                        ));
                    }
                }
            }
            WsClientMessage::Unsubscribe => {
                if let Some(t) = event_task.take() {
                    t.abort();
                }
            }
            WsClientMessage::Invoke {
                id,
                cmd,
                args,
                session_id,
            } => {
                let response = dispatch_invoke(&state, &cmd, args, session_id).await;
                let msg = match response {
                    Ok(data) => WsServerMessage::ok(id, data),
                    Err(e) => WsServerMessage::err(id, e),
                };
                let _ = out_tx.send(msg);
            }
        }
    }

    if let Some(t) = event_task {
        t.abort();
    }
    drop(out_tx);
    let _ = send_task.await;
}

