        "read_memory" => cmd_read_memory(state, args).await.map(Some),
        // providers 写
        "save_providers" => cmd_save_providers(state, args).await.map(|_| None),
        "upsert_provider" => cmd_upsert_provider(state, args).await.map(Some),
