async fn cmd_get_run_mode(state: &ServerState, session_id: Option<String>) -> Result<Value> {
    let sid = need_session(session_id)?;
    let runtime = state.ensure_runtime(&sid).await?;
    let mode = *runtime.run_mode.lock().unwrap();
