use model_gateway::types::{AssistantEntry, TranscriptEntry};

/// 粗略 token 估算（约 4 字符/token）
pub fn estimate_tokens(text: &str) -> usize {
    // 中文约 1.5 字符/token，英文约 4 字符/token，取平均
    let chars = text.chars().count();
    let bytes = text.len();
    // 如果字节数远超字符数，说明含大量 CJK，调整估算
    if bytes > chars * 2 {
        chars // CJK: ~1 token per char
    } else {
        bytes / 4
    }
}

/// 计算整个 transcript 的估算 token 数
pub fn estimate_transcript_tokens(system: Option<&str>, entries: &[TranscriptEntry]) -> usize {
    let mut total = 0;

    if let Some(s) = system {
        total += estimate_tokens(s) + 4; // role overhead
    }

    for entry in entries {
        total += entry_tokens(entry);
    }

    total
}

fn entry_tokens(entry: &TranscriptEntry) -> usize {
    match entry {
        TranscriptEntry::User(user) => {
            let attachment_tokens: usize = user
                .attachments
                .iter()
                .map(|a| match a {
                    common::attachments::MessageAttachment::TextFile { content, .. } => {
                        estimate_tokens(content) + 16
                    }
                    common::attachments::MessageAttachment::Image { data, .. } => {
                        (data.len() / 1024) * 85 + 128
                    }
                })
                .sum();
            estimate_tokens(&user.text) + attachment_tokens + 4
        }
        TranscriptEntry::Assistant(AssistantEntry {
            text,
            reasoning,
            tool_calls,
            ..
        }) => {
            let mut n = estimate_tokens(text) + estimate_tokens(reasoning) + 4;
            for c in tool_calls {
                n += estimate_tokens(&c.name) + estimate_tokens(&c.input.to_string()) + 8;
            }
            n
        }
        TranscriptEntry::ToolResults(results) => results
            .iter()
            .map(|r| estimate_tokens(&r.content) + 8)
            .sum(),
    }
}

crates/agent-core/src/context/compaction.content:
use std::sync::atomic::AtomicBool;
use std::sync::Arc;

use crate::context::budget;
use crate::definition::CompactionPolicy;
use model_gateway::client::ModelClient;
use model_gateway::types::{
    AssistantEntry, ModelError, ModelRequest, ModelResponse, TranscriptEntry, UserEntry,
};

/// 默认的中文压缩 prompt。让模型把历史浓缩成接力摘要，下一个 LLM
/// 不读原对话也能继续工作。
pub const COMPACT_PROMPT: &str = "你正在执行【上下文压缩】。请把当前对话历史浓缩成一份简明、结构化的接力摘要，让另一个 LLM 能在不读原对话的情况下无缝继续工作。\n\n请覆盖：\n- 用户的核心目标 / 约束 / 偏好\n- 已完成的关键工作和重要决策（含影响后续判断的细节）\n- 仍未完成的事项 / 下一步\n- 关键数据：文件路径、命令、代码片段、错误信息、外部链接\n- 任何模型不读上下文就会丢的隐含上下文\n\n输出要求：\n- 直接给摘要正文，不要寒暄、不要 “以下是摘要” 之类的引导语\n- 紧凑但不丢关键信息；优先 bullet list\n- 保持中文";

/// 压缩结果：用于 surface 端展示前后对比。
pub struct CompactionResult {
    pub entries: Vec<TranscriptEntry>,
    pub before_tokens: usize,
    pub after_tokens: usize,
    /// LLM 摘要时填入；结构化裁剪时为空。
    pub summary: String,
}

/// 结构化裁剪：保留 system + 最近 keep_recent_turns 轮
pub fn compact_structural(
    system: Option<&str>,
    entries: Vec<TranscriptEntry>,
    policy: &CompactionPolicy,
) -> CompactionResult {
    let before_tokens = budget::estimate_transcript_tokens(system, &entries);

    if before_tokens <= policy.token_budget {
        let after_tokens = before_tokens;
        return CompactionResult {
            entries,
            before_tokens,
            after_tokens,
            summary: String::new(),
        };
    }

    let keep = policy.keep_recent_turns * 3;
    let total = entries.len();
    let raw_start = if total > keep { total - keep } else { 0 };

    // 从 raw_start 向后找第一个 User entry 作为起始点，保证 transcript 以 User 开头。
    // 若 [raw_start..total] 内没有 User（全是 asst/tool_result），则不强制对齐 User，
    // 直接用 raw_start——否则 skip(total) 会产生空 transcript，模型完全失忆。
    let start = {
        let mut s = raw_start;
        while s < total {
            if matches!(entries[s], TranscriptEntry::User(_)) {
                break;
            }
            s += 1;
        }
        if s >= total { raw_start } else { s }
    };

    let compacted: Vec<TranscriptEntry> = entries.into_iter().skip(start).collect();
    let after_tokens = budget::estimate_transcript_tokens(system, &compacted);

    CompactionResult {
        entries: compacted,
        before_tokens,
        after_tokens,
        summary: String::new(),
    }
}

/// 检查是否需要压缩
pub fn needs_compaction(
    system: Option<&str>,
    entries: &[TranscriptEntry],
    policy: &CompactionPolicy,
) -> bool {
    budget::estimate_transcript_tokens(system, entries) > policy.token_budget
}

/// LLM 摘要式压缩：用一次 `complete()` 调用把整段对话浓缩成一份简明摘要，
/// 然后用 `[前情概要 + assistant 确认]` 这一对消息替换原 entries。
pub async fn compact_with_llm(
    client: &dyn ModelClient,
    system: Option<&str>,
    entries: Vec<TranscriptEntry>,
    custom_instructions: Option<&str>,
) -> Result<CompactionResult, ModelError> {
    let before_tokens = budget::estimate_transcript_tokens(system, &entries);

    let mut summarize_entries = entries;
    let prompt_text = match custom_instructions.map(str::trim).filter(|s| !s.is_empty()) {
        Some(extra) => format!("{COMPACT_PROMPT}\n\n附加指令：{extra}"),
        None => COMPACT_PROMPT.to_string(),
    };

    // 末尾若已是 user（典型场景：用户主动调 /compact 时刚 push 完 user message），
    // 直接合并到现有 content，避免出现两条连续 user entry——Anthropic provider
    // 不接受连续相同 role 的 message，会返回 400。
    if let Some(TranscriptEntry::User(user_entry)) = summarize_entries.last_mut() {
        user_entry.text = format!("{}\n\n{}", user_entry.text, prompt_text);
    } else {
        summarize_entries.push(TranscriptEntry::User(UserEntry::text(prompt_text)));
    }

    let req = ModelRequest {
        model: String::new(),
        system: system.map(str::to_string),
        entries: summarize_entries,
        tools: Vec::new(),
        max_tokens: 4096,
        reasoning: None,
    };
    let cancel = Arc::new(AtomicBool::new(false));
    let summary = match client.complete(req, cancel).await? {
        ModelResponse::Done { text, .. } | ModelResponse::ToolCalls { text, .. } => text,
    };

    let summary = summary.trim().to_string();
    if summary.is_empty() {
        return Err(ModelError::Other("压缩失败：模型返回了空摘要".to_string()));
    }

    let new_entries = vec![
        TranscriptEntry::User(UserEntry::text(format!("[前情概要]\n{summary}"))),
        TranscriptEntry::Assistant(AssistantEntry {
            text: "已收到前情概要，将基于此继续。".to_string(),
            reasoning: String::new(),
            reasoning_signature: String::new(),
            tool_calls: Vec::new(),
        }),
    ];
    let after_tokens = budget::estimate_transcript_tokens(system, &new_entries);

    Ok(CompactionResult {
        entries: new_entries,
        before_tokens,
        after_tokens,
        summary,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use async_trait::async_trait;
    use common::CancelFlag;
    use model_gateway::types::{ModelStreamEvent, Usage};

    /// 极简 mock：固定返回一段非空摘要，不关心入参。
    struct StubClient;

    #[async_trait]
    impl ModelClient for StubClient {
        fn provider_id(&self) -> &str {
            "stub"
        }

        async fn complete(
            &self,
            _req: ModelRequest,
            _cancel: CancelFlag,
        ) -> Result<ModelResponse, ModelError> {
            Ok(ModelResponse::Done {
                finish: model_gateway::types::FinishReason::Stop,
                text: "摘要正文".to_string(),
                reasoning: String::new(),
                attachments: Vec::new(),
                usage: Usage::default(),
                reasoning_signature: String::new(),
            })
        }

        async fn stream(
            &self,
            req: ModelRequest,
            cancel: CancelFlag,
            _on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
        ) -> Result<ModelResponse, ModelError> {
            self.complete(req, cancel).await
        }
    }

    /// 捕获 stream 入参的 mock，用来断言 compact_with_llm 传入的 entries 形态。
    struct CapturingClient {
        captured: std::sync::Mutex<Option<Vec<TranscriptEntry>>>,
    }

    #[async_trait]
    impl ModelClient for CapturingClient {
        fn provider_id(&self) -> &str {
            "capturing"
        }

        async fn complete(
            &self,
            req: ModelRequest,
            _cancel: CancelFlag,
        ) -> Result<ModelResponse, ModelError> {
            *self.captured.lock().unwrap() = Some(req.entries);
            Ok(ModelResponse::Done {
                finish: model_gateway::types::FinishReason::Stop,
                text: "摘要正文".to_string(),
                reasoning: String::new(),
                attachments: Vec::new(),
                usage: Usage::default(),
                reasoning_signature: String::new(),
            })
        }

        async fn stream(
            &self,
            req: ModelRequest,
            cancel: CancelFlag,
            _on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
        ) -> Result<ModelResponse, ModelError> {
            self.complete(req, cancel).await
        }
    }

    #[tokio::test]
    async fn merges_prompt_when_last_entry_is_user() {
        let client = CapturingClient {
            captured: std::sync::Mutex::new(None),
        };
        let entries = vec![
            TranscriptEntry::User(UserEntry::text("第一条 user")),
            TranscriptEntry::Assistant(AssistantEntry {
                text: "回复".into(),
                reasoning: String::new(),
                tool_calls: Vec::new(),
                reasoning_signature: String::new(),
            }),
            TranscriptEntry::User(UserEntry::text("用户主动 /compact")),
        ];

        let _ = compact_with_llm(&client, None, entries, None)
            .await
            .unwrap();

        let captured = client.captured.lock().unwrap().clone().unwrap();
        // 仍是 3 条（没有新增第 4 条 user），最后一条 user 的 text 同时包含原文与 prompt
        assert_eq!(captured.len(), 3);
        let last = captured.last().expect("non-empty");
        match last {
            TranscriptEntry::User(u) => {
                assert!(u.text.contains("用户主动 /compact"));
                assert!(u.text.contains("上下文压缩"));
            }
            _ => panic!("last entry should be user"),
        }
        // 最后两条不应都是 user（即倒数第二条不是 user）
        let second_last = &captured[captured.len() - 2];
        assert!(
            !matches!(second_last, TranscriptEntry::User(_)),
            "should not produce two consecutive user entries"
        );
    }

    #[tokio::test]
    async fn appends_prompt_when_last_entry_is_not_user() {
        let client = CapturingClient {
            captured: std::sync::Mutex::new(None),
        };
        let entries = vec![
            TranscriptEntry::User(UserEntry::text("第一条 user")),
            TranscriptEntry::Assistant(AssistantEntry {
                text: "结尾是 assistant".into(),
                reasoning: String::new(),
                tool_calls: Vec::new(),
                reasoning_signature: String::new(),
            }),
        ];

        let _ = compact_with_llm(&client, None, entries, None)
            .await
            .unwrap();

        let captured = client.captured.lock().unwrap().clone().unwrap();
        // 新增一条 user prompt，共 3 条
        assert_eq!(captured.len(), 3);
        match captured.last().unwrap() {
            TranscriptEntry::User(u) => assert!(u.text.contains("上下文压缩")),
            _ => panic!("last entry should be user"),
        }
    }

    #[tokio::test]
    async fn returns_compacted_pair_on_success() {
        let entries = vec![TranscriptEntry::User(UserEntry::text("hi"))];
        let result = compact_with_llm(&StubClient, None, entries, None)
            .await
            .unwrap();
        assert_eq!(result.entries.len(), 2);
        assert!(matches!(result.entries[0], TranscriptEntry::User(_)));
        assert!(matches!(result.entries[1], TranscriptEntry::Assistant(_)));
        assert_eq!(result.summary, "摘要正文");
    }

    /// 回归：transcript 里只有一条 User（第 0 条），后面全是 assistant+tool_result 对。
    /// 旧逻辑在「找 User 起点」时走到 total，skip(total) = 空 transcript，模型完全失忆。
    /// 修复后：找不到 User 时退回 raw_start，至少保留最后 N 条。
    #[test]
    fn compact_structural_no_user_in_window_does_not_empty_transcript() {
        use model_gateway::types::{AssistantEntry, ToolResult, UserEntry};
        // 构造 1 user + 50 assistant+tool 对 = 101 条
        // keep_recent_turns * 3 = 8 * 3 = 24；raw_start = 101 - 24 = 77
        // entries[77..101] 全是 assistant/tool_result，找不到 User
        let mut entries = vec![TranscriptEntry::User(UserEntry::text("initial user"))];
        for _ in 0..50 {
            entries.push(TranscriptEntry::Assistant(AssistantEntry {
                text: "doing work".to_string(),
                reasoning: String::new(),
                reasoning_signature: String::new(),
                tool_calls: vec![model_gateway::types::ToolCall {
                    id: "c1".to_string(),
                    name: "Bash".to_string(),
                    input: serde_json::json!({"command": "ls"}),
                }],
            }));
            entries.push(TranscriptEntry::ToolResults(vec![ToolResult {
                call_id: "c1".to_string(),
                name: "Bash".to_string(),
                content: "file1.rs\nfile2.rs".to_string(),
                artifact: None,
            }]));
        }
        assert_eq!(entries.len(), 101);

        let policy = crate::definition::CompactionPolicy {
            token_budget: 1, // 强制触发
            keep_recent_turns: 8,
            strategy: crate::definition::CompactionStrategy::Structural,
        };
        let result = compact_structural(None, entries, &policy);

        // 修复前：空 transcript；修复后：非空（保留 raw_start 到末尾）
        assert!(
            !result.entries.is_empty(),
            "compact_structural 不应返回空 transcript"
        );
        // 应该保留最后 24 条（raw_start = 77）
        assert_eq!(result.entries.len(), 24);
    }
}

crates/agent-core/src/context/microcompa.content:
//! Microcompact：工具结果大输出 shadow。
//!
//! 每轮模型请求**之前**扫描 transcript，把单条 token 超限的工具结果替换成占位符，
//! 原文通过 [`crate::storage::tool_results::save_tool_result`] 落盘
//! `~/.hebbian/sessions/<sid>/tool_results/<call_id>.txt`，agent 按需用 Grep/Read 检索。
//!
//! 触发条件：单条可压缩工具结果 token 数 > `max_tokens_per_result`（默认 10,000）。
//! 不看累积数量——超限即压，小输出永远保留。

use crate::context::budget::estimate_tokens;
use model_gateway::types::{ToolResult, TranscriptEntry};

/// 进入压缩白名单的工具名称。这些工具的大输出"看过即过"，不值得占 context。
const COMPACTABLE_TOOLS: &[&str] = &["Bash", "Read", "Grep", "Glob", "Edit", "Fetch", "WebSearch"];

/// 占位符前缀，用于幂等检测。
pub const SHADOWED_PLACEHOLDER_PREFIX: &str = "[结果已被压缩";

/// Microcompact 配置。
#[derive(Debug, Clone, Copy)]
pub struct MicrocompactPolicy {
    /// 单条可压缩工具结果超过此 token 数时 shadow（架构 §4.7.3）。
    pub max_tokens_per_result: usize,
}

impl Default for MicrocompactPolicy {
    fn default() -> Self {
        Self {
            max_tokens_per_result: 10_000,
        }
    }
}

/// 一次 microcompact 的统计。
#[derive(Debug, Clone, Default)]
pub struct MicrocompactReport {
    pub shadowed_count: usize,
    pub kept_count: usize,
    pub total_compactable: usize,
    /// 被压缩的工具结果原文备份：`(call_id, original_content)`。
    /// agent_loop 拿到后落盘到 `tool_results/<call_id>.txt`。
    pub shadowed_artifacts: Vec<(String, String)>,
}

fn is_compactable(name: &str) -> bool {
    COMPACTABLE_TOOLS.iter().any(|n| *n == name)
}

fn is_already_shadowed(content: &str) -> bool {
    content.starts_with(SHADOWED_PLACEHOLDER_PREFIX)
}

/// 对 entries 就地做一次 microcompact。
///
/// 扫描所有 `ToolResults`，单条可压缩结果 token 数超过 `max_tokens_per_result` 即 shadow。
/// 幂等——已是占位符的不重复替换。
pub fn microcompact(
    entries: &mut [TranscriptEntry],
    policy: &MicrocompactPolicy,
) -> MicrocompactReport {
    let mut shadowed = 0usize;
    let mut kept = 0usize;
    let mut total = 0usize;
    let mut artifacts: Vec<(String, String)> = Vec::new();

    for entry in entries.iter_mut() {
        let TranscriptEntry::ToolResults(results) = entry else {
            continue;
        };
        for r in results.iter_mut() {
            if !is_compactable(&r.name) {
                continue;
            }
            total += 1;
            if is_already_shadowed(&r.content) {
                // 已压缩，算作 shadowed（不重复落 artifacts）
                shadowed += 1;
                continue;
            }
            if estimate_tokens(&r.content) <= policy.max_tokens_per_result {
                kept += 1;
                continue;
            }
            // 超限：shadow
            artifacts.push((r.call_id.clone(), r.content.clone()));
            let placeholder = format!(
                "[结果已被压缩。原始内容可通过 Read 工具按路径检索：tool_results/{}.txt]",
                r.call_id
            );
            *r = ToolResult {
                call_id: r.call_id.clone(),
                name: r.name.clone(),
                content: placeholder,
                artifact: None,
            };
            shadowed += 1;
        }
    }

    MicrocompactReport {
        shadowed_count: shadowed,
        kept_count: kept,
        total_compactable: total,
        shadowed_artifacts: artifacts,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use model_gateway::types::ToolResult;

    fn tr(name: &str, content: &str) -> ToolResult {
        ToolResult {
            call_id: format!("c-{name}"),
            name: name.to_string(),
            content: content.to_string(),
            artifact: None,
        }
    }

    fn large_content(tokens: usize) -> String {
        // estimate_tokens: bytes/4 for ASCII，所以 tokens*4 个字符 ≈ tokens token
        "x".repeat(tokens * 4)
    }

    #[test]
    fn small_result_not_shadowed() {
        let mut entries = vec![TranscriptEntry::ToolResults(vec![
            tr("Bash", "hello"),
            tr("Read", "short content"),
        ])];
        let report = microcompact(&mut entries, &MicrocompactPolicy::default());
        assert_eq!(report.shadowed_count, 0);
        assert_eq!(report.kept_count, 2);
        assert_eq!(report.total_compactable, 2);
    }

    #[test]
    fn large_result_immediately_shadowed() {
        let big = large_content(11_000); // > 10k token
        let mut entries = vec![TranscriptEntry::ToolResults(vec![
            tr("Bash", &big),
        ])];
        let report = microcompact(&mut entries, &MicrocompactPolicy::default());
        assert_eq!(report.shadowed_count, 1);
        assert_eq!(report.kept_count, 0);
        assert_eq!(report.shadowed_artifacts.len(), 1);
        if let TranscriptEntry::ToolResults(results) = &entries[0] {
            assert!(results[0].content.starts_with(SHADOWED_PLACEHOLDER_PREFIX));
        }
    }

    #[test]
    fn small_results_always_kept_regardless_of_count() {
        // 20 个小结果，全保留（不因数量多就压）
        let items: Vec<ToolResult> = (0..20).map(|i| tr("Bash", &format!("output {i}"))).collect();
        let mut entries = vec![TranscriptEntry::ToolResults(items)];
        let report = microcompact(&mut entries, &MicrocompactPolicy::default());
        assert_eq!(report.shadowed_count, 0);
        assert_eq!(report.kept_count, 20);
    }

    #[test]
    fn mix_large_and_small() {
        let big = large_content(11_000);
        let mut entries = vec![TranscriptEntry::ToolResults(vec![
            tr("Bash", "small"),
            tr("Read", &big),
            tr("Grep", "small grep"),
        ])];
        let report = microcompact(&mut entries, &MicrocompactPolicy::default());
        assert_eq!(report.shadowed_count, 1); // only Read
        assert_eq!(report.kept_count, 2);
        if let TranscriptEntry::ToolResults(results) = &entries[0] {
            assert_eq!(results[0].content, "small");
            assert!(results[1].content.starts_with(SHADOWED_PLACEHOLDER_PREFIX));
            assert_eq!(results[2].content, "small grep");
        }
    }

    #[test]
    fn non_compactable_tools_skipped() {
        let big = large_content(11_000);
        let mut entries = vec![TranscriptEntry::ToolResults(vec![
            tr("ask", &big),
            tr("TodoWrite", &big),
        ])];
        let report = microcompact(&mut entries, &MicrocompactPolicy::default());
        assert_eq!(report.total_compactable, 0);
        assert_eq!(report.shadowed_count, 0);
    }

    #[test]
    fn idempotent() {
        let big = large_content(11_000);
        let mut entries = vec![TranscriptEntry::ToolResults(vec![tr("Bash", &big)])];
        let r1 = microcompact(&mut entries, &MicrocompactPolicy::default());
        let r2 = microcompact(&mut entries, &MicrocompactPolicy::default());
        assert_eq!(r1.shadowed_artifacts.len(), 1);
        assert_eq!(r2.shadowed_artifacts.len(), 0); // 第二次不再重复落 artifacts
    }
}

