//! `/compact` 时压缩前的 transcript 落盘为 markdown（架构 §4.7 / §6.1）。
//!
//! 路径形如 `~/.hebbian/sessions/<sid>/compactions/compact-<ts>.md`。
//! 当前模块只暴露写入函数；触发点由 context engine 在 Step 9 接入。

use std::path::{Path, PathBuf};

use common::AppResult;

use super::lock;

pub fn dir_for_session(data_dir: &Path, session_id: &str) -> PathBuf {
    data_dir
        .join("sessions")
        .join(session_id)
        .join("compactions")
}

pub fn save_compaction(
    data_dir: &Path,
    session_id: &str,
    timestamp_label: &str,
    markdown: &str,
) -> AppResult<PathBuf> {
    let dir = dir_for_session(data_dir, session_id);
    std::fs::create_dir_all(&dir)?;
    let path = dir.join(format!("compact-{timestamp_label}.md"));
    lock::write_atomic(&path, markdown.as_bytes())?;
    Ok(path)
}

crates/agent-core/src/storage/export_cla.content:
//! 把一段对话转成 Claude Code 会话格式，供 `claude --resume <uuid>` 直接恢复。
//!
//! 纯转换：只读源 session，产出「目标目录名 + 新 session uuid + 逐行 JSON 字符串」，
//! **不落盘**。写文件交给 surface 层——目标在本应用数据目录之外（用户的 claude 目录），
//! 不该由这里的存储层越界写。
//!
//! 目标格式：每行一条记录，靠 `parentUuid → uuid` 串成一条链；assistant 的工具调用
//! 拆成 `assistant` 行的 `tool_use` 块 + 紧跟一条 `user` 行的 `tool_result` 块（与本侧
//! 把结果内联在调用里的存法相反，这里负责拆开配对，否则恢复后首个请求会因 tool_use
//! 缺配对被 API 拒）。

use std::path::Path;

use chrono::{DateTime, SecondsFormat};
use common::AppResult;
use serde_json::{json, Value};
use uuid::Uuid;

use super::sessions::{self, Message, MessagePart, Role};

/// 写进每行的 `version` 字段。恢复方会用自己的版本覆盖，这里只需是个合理值。
const CLAUDE_VERSION: &str = "2.1.156";

/// 转换结果。`lines` 已是逐行 JSON 文本，surface 直接 `join("\n")` 落盘即可。
pub struct ClaudeResumeExport {
    /// 目标项目目录名（cwd 编码后），落在 `<claude>/projects/<dir_name>/`。
    pub dir_name: String,
    /// 解析后的 cwd（绝对路径）。恢复方按当前目录定位会话文件，故恢复命令需先 `cd` 到这里。
    pub cwd: String,
    /// 新会话 uuid，既是文件名也是 `claude --resume <uuid>` 的参数。
    pub session_uuid: String,
    pub lines: Vec<String>,
}

/// 读取本侧某段对话，转成 Claude 会话的逐行记录。
///
/// `include_thinking`：是否把思维链转成 `thinking` 块。本侧不持有恢复方所需的 `signature`，
/// 因此带上思维链时恢复后的首个请求可能被签名校验拒绝——届时关掉本开关重新导出即可。
///
/// `fallback_cwd`：会话无 workdir 时用它兜底。**不能为空**——恢复方按 cwd 编码的目录定位
/// 会话文件，空目录名会让它直接「Failed to resume」。surface 注入一个真实目录（如用户 home）。
pub fn build_claude_resume(
    data_dir: &Path,
    session_id: &str,
    include_thinking: bool,
    fallback_cwd: &Path,
) -> AppResult<ClaudeResumeExport> {
    let session = sessions::load(data_dir, session_id)?;

    let cwd = session
        .workdir
        .as_ref()
        .map(|p| p.to_string_lossy().to_string())
        .filter(|s| !s.trim().is_empty())
        .unwrap_or_else(|| fallback_cwd.to_string_lossy().to_string());
    let dir_name = claude_project_dir(&cwd);
    let session_uuid = Uuid::new_v4().to_string();

    let lines = convert_messages(&session.messages, &cwd, &session_uuid, include_thinking)
        .iter()
        .map(Value::to_string)
        .collect();

    Ok(ClaudeResumeExport {
        dir_name,
        cwd,
        session_uuid,
        lines,
    })
}

/// 把消息序列转成 Claude 会话的逐行记录（每行一个 JSON 对象）。纯函数，便于直接测试。
fn convert_messages(
    messages: &[Message],
    cwd: &str,
    session_uuid: &str,
    include_thinking: bool,
) -> Vec<Value> {
    let mut lines: Vec<Value> = Vec::new();
    let mut parent: Option<String> = None;

    let mut push = |typ: &str, message: Value, ts_ms: i64| {
        let uuid = Uuid::new_v4().to_string();
        lines.push(json!({
            "parentUuid": parent,
            "isSidechain": false,
            "userType": "external",
            "cwd": cwd,
            "sessionId": session_uuid,
            "version": CLAUDE_VERSION,
            "gitBranch": "",
            "type": typ,
            "message": message,
            "uuid": uuid,
            "timestamp": iso_millis(ts_ms),
        }));
        parent = Some(uuid);
    };

    for msg in messages {
        match msg.role {
            // 分隔标记 / system_prompt 不进恢复上下文：恢复方用它自己的 system prompt。
            Role::Marker | Role::System => continue,
            Role::User => {
                if msg.content.trim().is_empty() {
                    continue;
                }
                push(
                    "user",
                    json!({ "role": "user", "content": [{ "type": "text", "text": msg.content }] }),
                    msg.created_at,
                );
            }
            Role::Assistant => {
                let (blocks, tool_results) = assistant_blocks(msg, include_thinking);
                if blocks.is_empty() {
                    continue;
                }
                push(
                    "assistant",
                    json!({
                        "id": format!("msg_{}", Uuid::new_v4().to_string().replace('-', "")),
                        "type": "message",
                        "role": "assistant",
                        "model": "",
                        "content": blocks,
                        "stop_reason": "end_turn",
                        "stop_sequence": null,
                        "stop_details": null,
                        "usage": { "input_tokens": 0, "output_tokens": 0 }
                    }),
                    msg.created_at,
                );
                if !tool_results.is_empty() {
                    let content: Vec<Value> = tool_results
                        .into_iter()
                        .map(|(id, result)| {
                            json!({ "type": "tool_result", "tool_use_id": id, "content": result })
                        })
                        .collect();
                    push(
                        "user",
                        json!({ "role": "user", "content": content }),
                        msg.created_at,
                    );
                }
            }
        }
    }

    // claude --resume 读取最后一个 last-prompt 行的 leafUuid 定位对话末端，
    // 没有这行会直接报 "Failed to resume"。
    if let Some(leaf_uuid) = lines.last().and_then(|l| l["uuid"].as_str()).map(String::from) {
        lines.push(json!({
            "type": "last-prompt",
            "leafUuid": leaf_uuid,
            "sessionId": session_uuid,
        }));
    }

    lines
}

/// 把 assistant 消息拆成 (content 块数组, 待配对的 tool_result)。
///
/// 优先用 `parts`（有序，能保住思维链/正文/工具调用的先后），`parts` 为空的老消息
/// 回退到 `content` + `tool_calls`。`thinking` 块统一提到最前——API 要求思维链紧跟 turn
/// 开头，不能夹在正文之间。
fn assistant_blocks(msg: &Message, include_thinking: bool) -> (Vec<Value>, Vec<(String, String)>) {
    let mut thinking: Vec<Value> = Vec::new();
    let mut body: Vec<Value> = Vec::new();
    let mut tool_results: Vec<(String, String)> = Vec::new();

    if !msg.parts.is_empty() {
        for part in &msg.parts {
            match part {
                MessagePart::Reasoning { text } => {
                    if include_thinking && !text.trim().is_empty() {
                        // thinking block 需要 API 颁发的 signature，本侧未存储无法伪造；
                        // 包成 thinking 标签的 text block，续聊时上下文仍可见，且不触发签名校验。
                        thinking.push(json!({
                            "type": "text",
                            "text": format!("<thinking>\n{text}\n</thinking>")
                        }));
                    }
                }
                MessagePart::Text { text } => {
                    if !text.trim().is_empty() {
                        body.push(json!({ "type": "text", "text": text }));
                    }
                }
                MessagePart::ToolCall {
                    id,
                    name,
                    input,
                    result,
                    ..
                } => {
                    body.push(
                        json!({ "type": "tool_use", "id": id, "name": name, "input": input }),
                    );
                    tool_results.push((id.clone(), tool_result_text(result)));
                }
            }
        }
    } else {
        if !msg.content.trim().is_empty() {
            body.push(json!({ "type": "text", "text": msg.content }));
        }
        for tc in &msg.tool_calls {
            body.push(
                json!({ "type": "tool_use", "id": tc.id, "name": tc.name, "input": tc.input }),
            );
            tool_results.push((tc.id.clone(), tool_result_text(&tc.result)));
        }
    }

    thinking.extend(body);
    (thinking, tool_results)
}

/// 工具结果文本。结果缺失（运行被中断）也得给个占位，保证每个 `tool_use` 有配对，
/// 否则恢复后的首个请求会被 API 拒。
fn tool_result_text(result: &Option<String>) -> String {
    match result {
        Some(r) => r.clone(),
        None => "[no result: interrupted]".to_string(),
    }
}

/// cwd 编码为 claude 项目目录名：每个非 `[A-Za-z0-9]` 字符替换成 `-`
/// （例 `/Users/x/.app` → `-Users-x--app`）。注意这套规则与本应用自身的 workdir
/// 编码不同（后者保留 `.`），不可互换。
fn claude_project_dir(cwd: &str) -> String {
    cwd.chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
        .collect()
}

/// 毫秒时间戳 → `2026-05-29T08:04:06.795Z`。非法值回退到 epoch。
fn iso_millis(ms: i64) -> String {
    DateTime::from_timestamp_millis(ms)
        .unwrap_or_else(|| DateTime::from_timestamp_millis(0).unwrap())
        .to_rfc3339_opts(SecondsFormat::Millis, true)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn msg(role: Role, content: &str, parts: Vec<MessagePart>) -> Message {
        Message {
            id: Uuid::new_v4().to_string(),
            role,
            content: content.to_string(),
            attachments: vec![],
            tool_calls: vec![],
            parts,
            created_at: 1_780_000_000_000,
            meta: None,
            subagent_call_id: None,
        }
    }

    fn sample() -> Vec<Message> {
        vec![
            msg(Role::Marker, "", vec![]),
            msg(Role::User, "帮我读一下文件", vec![]),
            msg(
                Role::Assistant,
                "先读文件",
                vec![
                    MessagePart::Reasoning {
                        text: "我应该先 Read".into(),
                    },
                    MessagePart::Text {
                        text: "先读文件".into(),
                    },
                    MessagePart::ToolCall {
                        id: "toolu_1".into(),
                        name: "Read".into(),
                        input: json!({ "path": "a.txt" }),
                        arguments: String::new(),
                        result: Some("file body".into()),
                        duration_ms: Some(10),
                    },
                ],
            ),
        ]
    }

    fn convert(include_thinking: bool) -> Vec<Value> {
        convert_messages(&sample(), "/tmp/x", "sess-uuid", include_thinking)
    }

    #[test]
    fn parent_chain_is_contiguous() {
        let lines = convert(true);
        // 过滤掉 last-prompt 等元数据行，只验证 user/assistant 的链式结构
        let msg_lines: Vec<&Value> = lines
            .iter()
            .filter(|l| matches!(l["type"].as_str(), Some("user") | Some("assistant")))
            .collect();
        assert_eq!(msg_lines.first().unwrap()["parentUuid"], Value::Null);
        for w in msg_lines.windows(2) {
            assert_eq!(w[1]["parentUuid"], w[0]["uuid"], "链断裂");
        }
        // marker 被跳过：user + assistant + tool_result = 3 行，另有 1 行 last-prompt
        assert_eq!(msg_lines.len(), 3);
        assert_eq!(lines.len(), 4);

        // last-prompt 指向最后一条消息
        let last_prompt = lines.iter().rev().find(|l| l["type"] == "last-prompt").unwrap();
        assert_eq!(last_prompt["leafUuid"], msg_lines.last().unwrap()["uuid"]);
    }

    #[test]
    fn every_tool_use_has_a_matching_tool_result() {
        let lines = convert(true);
        let mut uses = vec![];
        let mut results = vec![];
        for l in &lines {
            for b in l["message"]["content"].as_array().into_iter().flatten() {
                match b["type"].as_str() {
                    Some("tool_use") => uses.push(b["id"].as_str().unwrap().to_string()),
                    Some("tool_result") => {
                        results.push(b["tool_use_id"].as_str().unwrap().to_string())
                    }
                    _ => {}
                }
            }
        }
        assert_eq!(uses, vec!["toolu_1".to_string()]);
        assert_eq!(results, uses, "每个 tool_use 必须有配对 tool_result");
    }

    #[test]
    fn thinking_toggle_controls_thinking_block() {
        // thinking 内容以 <thinking> text block 形式导出（非 thinking 类型块，避免 API signature 校验）
        let has_thinking_text = |include: bool| {
            convert(include).iter().any(|l| {
                l["message"]["content"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .any(|b| {
                        b["type"] == "text"
                            && b["text"].as_str().unwrap_or("").contains("<thinking>")
                    })
            })
        };
        assert!(has_thinking_text(true), "开启时应有 thinking 内容");
        assert!(!has_thinking_text(false), "关闭时不应有 thinking 内容");
    }

    #[test]
    fn claude_project_dir_replaces_non_alnum() {
        assert_eq!(claude_project_dir("/Users/x/.app"), "-Users-x--app");
        assert_eq!(claude_project_dir("/a/b_c"), "-a-b-c");
    }
}

crates/agent-core/src/storage/import_cla.content:
//! 反向：读 Claude Code 的会话文件，重建成本侧 Session（导入后可在本侧继续聊）。
//!
//! 与 [`super::export_claude`] 对称。难点同样在工具调用：Claude 把 `tool_use`（assistant）
//! 与 `tool_result`（紧跟的 user）分成两行，本侧则把结果内联在 assistant 的工具调用里——
//! 这里负责按 `tool_use_id` 把 result 回填到对应 assistant 消息，tool_result 行本身不产生
//! 独立消息。

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use chrono::DateTime;
use common::AppResult;
use serde_json::Value;

use super::sessions::{self, Message, MessagePart, MessageToolCall, Role};

/// 标题最大长度（取首条用户消息兜底时截断）。
const TITLE_MAX: usize = 40;

/// 扫描得到的一个可导入会话概要（不解析全部消息，仅够列表展示）。
pub struct ClaudeSessionInfo {
    pub path: PathBuf,
    pub uuid: String,
    pub title: String,
    /// 原会话工作目录；列表按它分组，导入后作为本侧 workdir。
    pub cwd: String,
    pub message_count: usize,
    pub modified_ms: i64,
}

/// 完整解析结果：重建出的会话内容。
pub struct ParsedClaudeSession {
    pub title: String,
    pub workdir: Option<PathBuf>,
    pub model: String,
    pub messages: Vec<Message>,
}

/// 扫描 claude projects 根目录，列出所有可导入会话，按修改时间倒序。
/// 目录不存在 / 读不动时返回空列表（不报错，UI 显示「没有可导入的会话」即可）。
pub fn list_importable(projects_dir: &Path) -> AppResult<Vec<ClaudeSessionInfo>> {
    let mut out = Vec::new();
    let Ok(projects) = std::fs::read_dir(projects_dir) else {
        return Ok(out);
    };
    for proj in projects.flatten() {
        if !proj.path().is_dir() {
            continue;
        }
        let Ok(files) = std::fs::read_dir(proj.path()) else {
            continue;
        };
        for f in files.flatten() {
            let p = f.path();
            if p.extension().and_then(|e| e.to_str()) != Some("jsonl") {
                continue;
            }
            if let Some(info) = scan_one(&p) {
                out.push(info);
            }
        }
    }
    out.sort_by(|a, b| b.modified_ms.cmp(&a.modified_ms));
    Ok(out)
}

/// 轻量扫描单个文件：只取标题 / cwd / 消息数 / mtime，不重建消息。
fn scan_one(path: &Path) -> Option<ClaudeSessionInfo> {
    let content = std::fs::read_to_string(path).ok()?;
    let uuid = path.file_stem()?.to_string_lossy().to_string();

    let mut custom_title: Option<String> = None;
    let mut first_user_title: Option<String> = None;
    let mut cwd = String::new();
    let mut count = 0usize;

    for line in content.lines() {
        let Ok(v) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        match v.get("type").and_then(Value::as_str) {
            Some("custom-title") => {
                custom_title = v
                    .get("customTitle")
                    .and_then(Value::as_str)
                    .map(String::from);
            }
            Some("user") | Some("assistant") => {
                count += 1;
                if cwd.is_empty() {
                    if let Some(c) = v.get("cwd").and_then(Value::as_str) {
                        cwd = c.to_string();
                    }
                }
                if first_user_title.is_none()
                    && v.get("type").and_then(Value::as_str) == Some("user")
                {
                    if let Some(t) = user_text(&v) {
                        if !t.trim().is_empty() {
                            first_user_title = Some(truncate_title(&t));
                        }
                    }
                }
            }
            _ => {}
        }
    }

    if count == 0 {
        return None; // 空会话不列
    }
    let modified_ms = std::fs::metadata(path)
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0);

    Some(ClaudeSessionInfo {
        path: path.to_path_buf(),
        uuid,
        title: custom_title
            .or(first_user_title)
            .unwrap_or_else(|| "（无标题）".into()),
        cwd,
        message_count: count,
        modified_ms,
    })
}

/// 完整解析一个 Claude 会话文件内容，重建本侧消息序列。
pub fn parse_claude_jsonl(content: &str) -> AppResult<ParsedClaudeSession> {
    let mut messages: Vec<Message> = Vec::new();
    let mut custom_title: Option<String> = None;
    let mut first_user_title: Option<String> = None;
    let mut cwd = String::new();
    let mut model = String::new();
    // tool_use_id → 它所属 assistant 消息在 messages 里的下标，用于回填 result。
    let mut owner: HashMap<String, usize> = HashMap::new();
    let mut seq = 0i64; // 无 timestamp 时的单调兜底

    for line in content.lines() {
        let Ok(v) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        let typ = v.get("type").and_then(Value::as_str).unwrap_or("");
        if cwd.is_empty() {
            if let Some(c) = v.get("cwd").and_then(Value::as_str) {
                cwd = c.to_string();
            }
        }
        let ts = v
            .get("timestamp")
            .and_then(Value::as_str)
            .and_then(parse_iso_millis)
            .unwrap_or_else(|| {
                seq += 1;
                seq
            });

        match typ {
            "custom-title" => {
                custom_title = v
                    .get("customTitle")
                    .and_then(Value::as_str)
                    .map(String::from);
            }
            "user" => {
                // 先看是不是工具结果回传：是则回填到 owner，不产生独立消息。
                if let Some(arr) = v.pointer("/message/content").and_then(Value::as_array) {
                    let results: Vec<(String, String)> = arr
                        .iter()
                        .filter(|b| b.get("type").and_then(Value::as_str) == Some("tool_result"))
                        .filter_map(|b| {
                            let id = b.get("tool_use_id")?.as_str()?.to_string();
                            Some((id, tool_result_text(b.get("content"))))
                        })
                        .collect();
                    if !results.is_empty() {
                        for (id, text) in results {
                            if let Some(&idx) = owner.get(&id) {
                                fill_result(&mut messages[idx], &id, text);
                            }
                        }
                        continue;
                    }
                }
                let text = user_text(&v).unwrap_or_default();
                if text.trim().is_empty() {
                    continue;
                }
                if first_user_title.is_none() {
                    first_user_title = Some(truncate_title(&text));
                }
                messages.push(plain_message(Role::User, text, ts));
            }
            "assistant" => {
                if model.is_empty() {
                    if let Some(m) = v.pointer("/message/model").and_then(Value::as_str) {
                        model = m.to_string();
                    }
                }
                let (msg, tool_ids) = assistant_message(&v, ts);
                if msg.content.is_empty() && msg.parts.is_empty() && msg.tool_calls.is_empty() {
                    continue;
                }
                let idx = messages.len();
                for id in tool_ids {
                    owner.insert(id, idx);
                }
                messages.push(msg);
            }
            _ => {} // system / attachment / mode / file-history-snapshot 等不进上下文
        }
    }

    let workdir = (!cwd.trim().is_empty()).then(|| PathBuf::from(&cwd));
    Ok(ParsedClaudeSession {
        title: custom_title
            .or(first_user_title)
            .unwrap_or_else(|| "（导入）".into()),
        workdir,
        model: if model.is_empty() {
            "claude".into()
        } else {
            model
        },
        messages,
    })
}

/// 从一行 user 记录里抽出纯文本（content 为 string 或 text 块数组）。
fn user_text(v: &Value) -> Option<String> {
    let c = v.pointer("/message/content")?;
    if let Some(s) = c.as_str() {
        return Some(s.to_string());
    }
    let arr = c.as_array()?;
    let text = arr
        .iter()
        .filter(|b| b.get("type").and_then(Value::as_str) == Some("text"))
        .filter_map(|b| b.get("text").and_then(Value::as_str))
        .collect::<Vec<_>>()
        .join("\n");
    (!text.is_empty()).then_some(text)
}

/// 把一行 assistant 记录拆成本侧 Message + 它发起的 tool_use_id 列表（供回填）。
fn assistant_message(v: &Value, ts: i64) -> (Message, Vec<String>) {
    let mut text_parts: Vec<String> = Vec::new();
    let mut parts: Vec<MessagePart> = Vec::new();
    let mut tool_calls: Vec<MessageToolCall> = Vec::new();
    let mut tool_ids: Vec<String> = Vec::new();

    if let Some(blocks) = v.pointer("/message/content").and_then(Value::as_array) {
        for b in blocks {
            match b.get("type").and_then(Value::as_str) {
                Some("thinking") => {
                    if let Some(t) = b.get("thinking").and_then(Value::as_str) {
                        if !t.trim().is_empty() {
                            parts.push(MessagePart::Reasoning {
                                text: t.to_string(),
                            });
                        }
                    }
                }
                Some("text") => {
                    if let Some(t) = b.get("text").and_then(Value::as_str) {
                        if !t.trim().is_empty() {
                            text_parts.push(t.to_string());
                            parts.push(MessagePart::Text {
                                text: t.to_string(),
                            });
                        }
                    }
                }
                Some("tool_use") => {
                    let id = b
                        .get("id")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string();
                    let name = b
                        .get("name")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string();
                    let input = b.get("input").cloned().unwrap_or(Value::Null);
                    parts.push(MessagePart::ToolCall {
                        id: id.clone(),
                        name: name.clone(),
                        input: input.clone(),
                        arguments: String::new(),
                        result: None,
                        duration_ms: None,
                    });
                    tool_calls.push(MessageToolCall {
                        id: id.clone(),
                        name,
                        input,
                        result: None,
                        duration_ms: None,
                    });
                    tool_ids.push(id);
                }
                _ => {}
            }
        }
    }

    let mut msg = plain_message(Role::Assistant, text_parts.join("\n\n"), ts);
    msg.parts = parts;
    msg.tool_calls = tool_calls;
    (msg, tool_ids)
}

/// 把工具结果回填到 assistant 消息里对应 id 的 tool_call 与 part。
fn fill_result(msg: &mut Message, id: &str, text: String) {
    if let Some(tc) = msg.tool_calls.iter_mut().find(|tc| tc.id == id) {
        tc.result = Some(text.clone());
    }
    for part in &mut msg.parts {
        if let MessagePart::ToolCall {
            id: pid, result, ..
        } = part
        {
            if pid == id {
                *result = Some(text);
                break;
            }
        }
    }
}

/// tool_result 的 content：可能是字符串，或 `[{type:text,text}]` 块数组。
fn tool_result_text(content: Option<&Value>) -> String {
    match content {
        Some(Value::String(s)) => s.clone(),
        Some(Value::Array(arr)) => arr
            .iter()
            .filter_map(|b| b.get("text").and_then(Value::as_str))
            .collect::<Vec<_>>()
            .join("\n"),
        _ => String::new(),
    }
}

fn plain_message(role: Role, content: String, ts: i64) -> Message {
    Message {
        id: sessions::new_id(),
        role,
        content,
        attachments: Vec::new(),
        tool_calls: Vec::new(),
        parts: Vec::new(),
        created_at: ts,
        meta: None,
        subagent_call_id: None,
    }
}

/// ISO8601（`2026-05-29T08:04:06.795Z`）→ 毫秒。
fn parse_iso_millis(s: &str) -> Option<i64> {
    DateTime::parse_from_rfc3339(s)
        .ok()
        .map(|d| d.timestamp_millis())
}

/// 按字符（非字节）截断标题，避免切碎多字节中文。
fn truncate_title(s: &str) -> String {
    let t = s.trim();
    if t.chars().count() <= TITLE_MAX {
        return t.to_string();
    }
    t.chars().take(TITLE_MAX).collect::<String>() + "…"
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"{"type":"custom-title","customTitle":"读文件任务"}
{"type":"user","cwd":"/tmp/proj","message":{"role":"user","content":[{"type":"text","text":"帮我读 a.txt"}]},"timestamp":"2026-05-29T08:00:00.000Z"}
{"type":"assistant","message":{"role":"assistant","model":"claude-opus-4-8","content":[{"type":"thinking","thinking":"先 Read"},{"type":"text","text":"好的"},{"type":"tool_use","id":"toolu_1","name":"Read","input":{"path":"a.txt"}}]},"timestamp":"2026-05-29T08:00:01.000Z"}
{"type":"user","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_1","content":"file body"}]},"timestamp":"2026-05-29T08:00:02.000Z"}
{"type":"summary","summary":"x"}"#;

    #[test]
    fn rebuilds_messages_and_inlines_tool_result() {
        let p = parse_claude_jsonl(SAMPLE).unwrap();
        assert_eq!(p.title, "读文件任务");
        assert_eq!(p.workdir, Some(PathBuf::from("/tmp/proj")));
        assert_eq!(p.model, "claude-opus-4-8");
        // tool_result 不产生独立消息：只有 user + assistant 两条。
        assert_eq!(p.messages.len(), 2);
        assert_eq!(p.messages[0].role, Role::User);

        let a = &p.messages[1];
        assert_eq!(a.role, Role::Assistant);
        assert_eq!(a.content, "好的");
        // 结果已回填到内联工具调用。
        assert_eq!(a.tool_calls.len(), 1);
        assert_eq!(a.tool_calls[0].result.as_deref(), Some("file body"));
        // parts 保住有序：reasoning / text / tool_call。
        assert!(matches!(a.parts[0], MessagePart::Reasoning { .. }));
        assert!(matches!(a.parts[1], MessagePart::Text { .. }));
        match &a.parts[2] {
            MessagePart::ToolCall { result, .. } => {
                assert_eq!(result.as_deref(), Some("file body"))
            }
            _ => panic!("第三块应是 tool_call"),
        }
    }

    #[test]
    fn falls_back_to_first_user_text_for_title() {
        let no_title = SAMPLE.lines().skip(1).collect::<Vec<_>>().join("\n");
        let p = parse_claude_jsonl(&no_title).unwrap();
        assert_eq!(p.title, "帮我读 a.txt");
    }

    #[test]
    fn truncate_title_counts_chars_not_bytes() {
        let long = "中".repeat(50);
        let out = truncate_title(&long);
        assert_eq!(out.chars().count(), TITLE_MAX + 1); // 40 + 省略号
    }
}

crates/agent-core/src/storage/lock.rs.content:
//! 文件锁 + 原子写（架构 §6.3）。
//!
//! 三个原语：
//! - [`write_atomic`]：排他锁 → tmp 文件 → rename，整文件替换。
//! - [`append_jsonl`]：排他锁 → O_APPEND open → write + fsync，单行追加。
//! - [`read_locked`]：共享锁 → read 全部内容。
//!
//! 每个被保护的文件配一个 `<path>.lock`。锁本身的生命周期与本函数调用一致，
//! 调用返回时 lock 释放（Drop fs2::FileExt）。
//!
//! CLI 与 Desktop 共享 `~/.hebbian/`，两边可同时跑——所有共享文件必须经此模块。

use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::{Path, PathBuf};

use fs2::FileExt;

use common::{AppError, AppResult};

fn lock_path(path: &Path) -> PathBuf {
    let mut s = path.as_os_str().to_owned();
    s.push(".lock");
    PathBuf::from(s)
}

fn open_lock_file(path: &Path) -> AppResult<File> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let lock = lock_path(path);
    Ok(OpenOptions::new()
        .create(true)
        .read(true)
        .write(true)
        .open(&lock)?)
}

/// 排他锁包装：lock 文件在返回后立即 release。
fn with_exclusive<R>(path: &Path, f: impl FnOnce() -> AppResult<R>) -> AppResult<R> {
    let lf = open_lock_file(path)?;
    lf.lock_exclusive()
        .map_err(|e| AppError::msg(format!("acquire exclusive lock: {e}")))?;
    let res = f();
    let _ = fs2::FileExt::unlock(&lf);
    res
}

/// 共享锁包装。
fn with_shared<R>(path: &Path, f: impl FnOnce() -> AppResult<R>) -> AppResult<R> {
    let lf = open_lock_file(path)?;
    lf.lock_shared()
        .map_err(|e| AppError::msg(format!("acquire shared lock: {e}")))?;
    let res = f();
    let _ = fs2::FileExt::unlock(&lf);
    res
}

/// 原子整文件覆盖（持排他锁；tmp + rename）。
///
/// 父目录会自动创建；写入失败时尝试清理 tmp。
pub fn write_atomic(path: &Path, content: &[u8]) -> AppResult<()> {
    with_exclusive(path, || {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let tmp = path.with_extension(format!(
            "{}.tmp.{}",
            path.extension().and_then(|s| s.to_str()).unwrap_or(""),
            uuid::Uuid::new_v4()
        ));
        let mut f = OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&tmp)?;
        f.write_all(content)?;
        f.sync_all()?;
        drop(f);
        std::fs::rename(&tmp, path)?;
        Ok(())
    })
}

/// 单行 jsonl 追加（持排他锁；O_APPEND + write + fsync）。
///
/// `line` 不含末尾换行，函数自动补 `\n`。
pub fn append_jsonl(path: &Path, line: &str) -> AppResult<()> {
    with_exclusive(path, || {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        let mut f = OpenOptions::new().create(true).append(true).open(path)?;
        f.write_all(line.as_bytes())?;
        f.write_all(b"\n")?;
        f.sync_data()?;
        Ok(())
    })
}

/// 读全文件（持共享锁；允许多读并发）。
pub fn read_locked(path: &Path) -> AppResult<Vec<u8>> {
    with_shared(path, || {
        let mut f = OpenOptions::new().read(true).open(path)?;
        let mut buf = Vec::new();
        f.read_to_end(&mut buf)?;
        Ok(buf)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp(name: &str) -> PathBuf {
        let dir =
            std::env::temp_dir().join(format!("hebbian-lock-{name}-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        dir.join("data.bin")
    }

    #[test]
    fn write_atomic_roundtrip() {
        let p = tmp("atomic");
        write_atomic(&p, b"hello").unwrap();
        let bytes = read_locked(&p).unwrap();
        assert_eq!(bytes, b"hello");
    }

    #[test]
    fn append_jsonl_two_lines() {
        let p = tmp("append");
        append_jsonl(&p, r#"{"a":1}"#).unwrap();
        append_jsonl(&p, r#"{"a":2}"#).unwrap();
        let bytes = read_locked(&p).unwrap();
        let s = String::from_utf8(bytes).unwrap();
        assert_eq!(s, "{\"a\":1}\n{\"a\":2}\n");
    }
}

