//! ~/.hebbian 统一持久化（架构 §6）。
//!
//! 本模块负责所有共享数据的落盘、读取与并发保护。子模块按数据类别拆分：
//!
//! - [`lock`]：文件锁 + 原子写原语（架构 §6.3）
//! - [`sessions`]：对话历史 jsonl 读写（rollout v1）
//! - [`sessions_dir`]：每段对话目录骨架 + partial sidecar + meta.json
//! - [`prompts`]：用户 persona 列表（prompts.json）
//! - [`settings`]：全局通用 settings.json
//! - [`permissions`]：Global 级审批规则（架构 §4.6 / §4.5.4）
//! - [`mcp`]：MCP server 配置（mcp.json）
//! - [`tool_results`]：工具结果 txt（含大输出落盘 + 压缩占位符）
//! - [`compactions`]：/compact 时压缩前 markdown
//! - [`oauth`]：provider OAuth 凭据（目录占位）
//!
//! `~/.hebbian/providers.json` 因被 `model-gateway` 单独读写、避免反向依赖
//! `agent-core`，其路径 helper 仍保留在 [`common::storage`]。

pub mod compactions;
pub mod export_claude;
pub mod import_claude;
pub mod lock;
pub mod mcp;
pub mod memory;
pub mod model_io;
pub mod models_catalog;
pub mod oauth;
pub mod permissions;
pub mod plan_comments;
pub mod plans;
pub mod plugins;
pub mod projects;
pub mod prompts;
pub mod run_checkpoint;
pub mod sessions;
pub mod sessions_dir;
pub mod settings;
pub mod skill_collections;
pub mod skills;
pub mod subagents;
pub mod tool_results;

use std::path::{Path, PathBuf};

/// 默认数据目录：`~/.hebbian/`。
///
/// 架构 §6.1：Desktop 多窗口/多进程共享同一根目录，跨平台保持一致（决策 D10）。
/// 早期使用了 `~/Library/Application Support/dev.ricardo.hebbian/`（macOS）等
/// 平台原生路径，本函数若发现旧路径存在但新路径为空，会迁移到 `~/.hebbian/`。
///
/// 同时会触发 sessions 老布局（`sessions/<date>/<id>.jsonl` 或平铺
/// `sessions/<id>.jsonl`）到新布局（`sessions/<id>/session.jsonl`）的一次性迁移。
pub fn default_data_dir() -> PathBuf {
    let new = home_dir().join(".hebbian");
    if !new.exists() {
        if let Some(old) = legacy_data_dir() {
            if old.exists() && old != new {
                if let Err(e) = migrate_legacy_data_dir(&old, &new) {
                    tracing::warn!(error = %e, from = %old.display(), to = %new.display(), "迁移旧数据目录失败");
                } else {
                    tracing::info!(from = %old.display(), to = %new.display(), "已迁移旧数据目录到 ~/.hebbian/");
                }
            }
        }
    }
    let _ = std::fs::create_dir_all(&new);
    match sessions::migrate_legacy_layout_if_needed(&new) {
        Ok(0) => {}
        Ok(n) => tracing::info!(count = n, "已迁移 sessions 老布局到新目录化布局"),
        Err(e) => tracing::warn!(error = %e, "sessions 老布局迁移失败"),
    }
    new
}

fn home_dir() -> PathBuf {
    dirs::home_dir().unwrap_or_else(|| PathBuf::from("."))
}

/// 旧 Tauri bundle 路径：跨平台映射到 `dirs::data_dir()/dev.ricardo.hebbian`。
fn legacy_data_dir() -> Option<PathBuf> {
    dirs::data_dir().map(|d| d.join("dev.ricardo.hebbian"))
}

/// 把整个旧目录 rename 到新位置；rename 失败（如跨卷）退回到 copy 后保留旧目录。
fn migrate_legacy_data_dir(from: &Path, to: &Path) -> std::io::Result<()> {
    if let Some(parent) = to.parent() {
        std::fs::create_dir_all(parent)?;
    }
    if std::fs::rename(from, to).is_ok() {
        return Ok(());
    }
    // 跨卷或权限问题：递归 copy 后留底（不删旧目录）。
    copy_dir_all(from, to)?;
    Ok(())
}

fn copy_dir_all(src: &Path, dst: &Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let ty = entry.file_type()?;
        let from = entry.path();
        let to = dst.join(entry.file_name());
        if ty.is_dir() {
            copy_dir_all(&from, &to)?;
        } else {
            std::fs::copy(&from, &to)?;
        }
    }
    Ok(())
}

crates/agent-core/src/storage/model_io.r.content:
//! 读 `<sid>/model_io.jsonl`：把每行 [`DumpEntry`] 反序列化成 surface 友好的列表。
//!
//! 写盘走 [`crate::model_io_dump`]（actor 模式异步落盘）；读这边只走只读 IO，
//! 给前端 Model I/O 调试器、heb CLI `model-io` 子命令提供数据源。
//!
//! 容错策略：jsonl 中坏行（解析失败）只记 warn 并跳过，不让一个孤行毁了整次读取——
//! dump 是 best-effort 写入，可能因进程被 SIGKILL 留半截行；调试器要照常打开。
//!
//! ## 增量 messages 存储
//!
//! 写盘侧对 `kind == "main"` 的 entry 做前缀去重：
//! - `messages_carried: N` — 前 N 条与上一条 main entry 相同
//! - `messages_new: [...]` — 第 N+1 条起的新增 messages
//!
//! 读取侧顺序扫描时维护 `accumulated_messages` 累积数组，遇到增量格式时
//! 取前 N 条 + 拼接 new 即可重建完整 messages。兼容老格式（有 `messages` 字段的）。

use std::path::Path;

use serde_json::Value;

use crate::model_io_dump::default_path;

/// 从增量格式重建完整 messages 数组，同时更新累积状态。
///
/// 兼容三种格式：
/// 1. 增量格式：`{messages_carried: N, messages_new: [...]}`
/// 2. 老格式：`{messages: [...]}`
/// 3. 非 main（judge/compaction）：无 messages 相关字段，不更新累积状态
fn rebuild_messages(request: &mut Value, accumulated: &mut Vec<Value>) {
    let obj = match request.as_object_mut() {
        Some(o) => o,
        None => return,
    };

    if let Some(carried_val) = obj.remove("messages_carried") {
        let carried = carried_val.as_u64().unwrap_or(0) as usize;
        let new_msgs = obj
            .remove("messages_new")
            .and_then(|v| match v {
                Value::Array(a) => Some(a),
                _ => None,
            })
            .unwrap_or_default();

        // 从累积状态取前 carried 条 + 拼接 new
        let mut full: Vec<Value> = accumulated.iter().take(carried).cloned().collect();
        full.extend(new_msgs);

        *accumulated = full.clone();
        obj.insert("messages".to_string(), Value::Array(full));
    } else if let Some(messages) = obj.get("messages").and_then(|m| m.as_array()) {
        // 老格式或无去重的条目——直接用 messages 更新累积状态
        *accumulated = messages.clone();
    }
    // judge/compaction 没有 messages 字段，不动累积状态
}

/// 读 session 的所有 model_io 条目（完整重建 messages）。
///
/// ⚠️ 大 session 下会把所有 entry 全部驻留在内存中，仅 CLI 使用。
/// 前端应走 `read_session_summaries` + `read_session_entry` 两级加载。
pub fn read_session(data_dir: &Path, session_id: &str) -> std::io::Result<Vec<Value>> {
    use std::io::BufRead;

    let path = default_path(data_dir, session_id);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let file = std::fs::File::open(&path)?;
    let reader = std::io::BufReader::new(file);
    let mut out = Vec::new();
    let mut accumulated: Vec<Value> = Vec::new();
    for (idx, line_result) in reader.lines().enumerate() {
        let line = line_result?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        match serde_json::from_str::<Value>(trimmed) {
            Ok(mut v) => {
                if let Some(req) = v.get_mut("request") {
                    rebuild_messages(req, &mut accumulated);
                }
                out.push(v);
            }
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    path = %path.display(),
                    line_idx = idx,
                    "model_io jsonl 行解析失败，跳过"
                );
            }
        }
    }
    Ok(out)
}

/// 只返回每条 entry 的摘要（不含 request.messages / response 正文），
/// 给前端侧边栏列表用。即使 jsonl 有几百 MB，摘要总量也只有几十 KB。
///
/// 逐行读取 + 解析 + 提取摘要 + 立刻丢弃完整 Value —— 峰值内存 ≈ 单条 entry 大小，
/// 远低于 `read_session` 的全量驻留。
pub fn read_session_summaries(data_dir: &Path, session_id: &str) -> std::io::Result<Vec<Value>> {
    use std::io::BufRead;

    let path = default_path(data_dir, session_id);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let file = std::fs::File::open(&path)?;
    let reader = std::io::BufReader::new(file);
    let mut out = Vec::new();
    for (idx, line_result) in reader.lines().enumerate() {
        let line = line_result?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        match serde_json::from_str::<Value>(trimmed) {
            Ok(v) => {
                let resp = v.get("response");
                let req = v.get("request");

                // 计算 message_count：兼容增量格式和老格式
                let msg_count = if let Some(carried) =
                    req.and_then(|r| r.get("messages_carried")).and_then(|c| c.as_u64())
                {
                    let new_len = req
                        .and_then(|r| r.get("messages_new"))
                        .and_then(|m| m.as_array())
                        .map(|a| a.len())
                        .unwrap_or(0);
                    (carried as usize + new_len) as u64
                } else if let Some(msgs) =
                    req.and_then(|r| r.get("messages")).and_then(|m| m.as_array())
                {
                    msgs.len() as u64
                } else {
                    0
                };

                out.push(serde_json::json!({
                    "ts": v.get("ts").cloned(),
                    "run_id": v.get("run_id").cloned(),
                    "turn": v.get("turn").cloned(),
                    "model": v.get("model").cloned(),
                    "kind": v.get("kind").cloned(),
                    "duration_ms": v.get("duration_ms").cloned(),
                    "response": {
                        "type": resp.and_then(|r| r.get("type")).cloned(),
                        "usage": resp.and_then(|r| r.get("usage")).cloned()
                    },
                    "message_count": msg_count,
                }));
            }
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    path = %path.display(),
                    line_idx = idx,
                    "model_io jsonl 行解析失败，跳过"
                );
            }
        }
    }
    Ok(out)
}

/// 按索引返回单条完整 entry（增量 messages 已重建）。
///
/// 顺序扫描至目标行，沿途累积 messages 状态以支持增量重建。
/// 未到目标行的行只解析 request 中的 messages 相关字段来维护累积状态，
/// 不保留完整 Value——峰值内存 ≈ 累积 messages 数组大小。
pub fn read_session_entry(
    data_dir: &Path,
    session_id: &str,
    index: usize,
) -> std::io::Result<Option<Value>> {
    use std::io::BufRead;

    let path = default_path(data_dir, session_id);
    if !path.exists() {
        return Ok(None);
    }
    let file = std::fs::File::open(&path)?;
    let reader = std::io::BufReader::new(file);
    let mut accumulated: Vec<Value> = Vec::new();
    let mut valid_idx = 0usize;
    for (line_no, line_result) in reader.lines().enumerate() {
        let line = line_result?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if valid_idx == index {
            // 目标行：完整解析 + 重建 messages
            return match serde_json::from_str::<Value>(trimmed) {
                Ok(mut v) => {
                    if let Some(req) = v.get_mut("request") {
                        rebuild_messages(req, &mut accumulated);
                    }
                    Ok(Some(v))
                }
                Err(e) => {
                    tracing::warn!(
                        error = %e,
                        path = %path.display(),
                        line_idx = line_no,
                        "model_io entry 解析失败"
                    );
                    Ok(None)
                }
            };
        }
        // 非目标行：只更新累积状态
        if let Ok(mut v) = serde_json::from_str::<Value>(trimmed) {
            if let Some(req) = v.get_mut("request") {
                rebuild_messages(req, &mut accumulated);
            }
        }
        valid_idx += 1;
    }
    Ok(None)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn read_returns_empty_when_file_missing() {
        let tmp = tempfile::tempdir().unwrap();
        let entries = read_session(tmp.path(), "missing-sid").unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn read_parses_well_formed_lines_and_skips_garbage() {
        let tmp = tempfile::tempdir().unwrap();
        let path = default_path(tmp.path(), "sid1");
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        let body = format!(
            "{}\n{}\nnot json here\n{}\n",
            serde_json::to_string(&json!({"turn": 1, "model": "m1"})).unwrap(),
            serde_json::to_string(&json!({"turn": 2, "model": "m1"})).unwrap(),
            serde_json::to_string(&json!({"turn": 3, "model": "m1"})).unwrap(),
        );
        std::fs::write(&path, body).unwrap();
        let entries = read_session(tmp.path(), "sid1").unwrap();
        assert_eq!(entries.len(), 3);
        assert_eq!(entries[0]["turn"], 1);
        assert_eq!(entries[2]["turn"], 3);
    }

    #[test]
    fn incremental_messages_rebuild() {
        let tmp = tempfile::tempdir().unwrap();
        let path = default_path(tmp.path(), "sid2");
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();

        // 第一条：全量 messages（老格式或第一次写入）
        let entry1 = json!({
            "ts": "2026-01-01T00:00:00Z",
            "run_id": "r1",
            "turn": 0,
            "model": "m1",
            "kind": "main",
            "duration_ms": 100,
            "request": {
                "messages": [
                    {"role": "user", "content": "hello"},
                    {"role": "assistant", "content": "hi"}
                ]
            },
            "response": {"type": "Done"}
        });
        // 第二条：增量格式，carried=2，new=[新消息]
        let entry2 = json!({
            "ts": "2026-01-01T00:01:00Z",
            "run_id": "r1",
            "turn": 1,
            "model": "m1",
            "kind": "main",
            "duration_ms": 200,
            "request": {
                "messages_carried": 2,
                "messages_new": [
                    {"role": "user", "content": "how are you"},
                    {"role": "assistant", "content": "good"}
                ]
            },
            "response": {"type": "Done"}
        });
        // 第三条：judge（不影响累积状态）
        let entry3 = json!({
            "ts": "2026-01-01T00:01:30Z",
            "run_id": "r1",
            "turn": 0,
            "model": "m1",
            "kind": "judge",
            "duration_ms": 50,
            "request": {"tool": "Bash", "input": {"cmd": "ls"}},
            "response": {"raw": "allow", "final": "allow"}
        });
        // 第四条：基于第二条的增量
        let entry4 = json!({
            "ts": "2026-01-01T00:02:00Z",
            "run_id": "r1",
            "turn": 2,
            "model": "m1",
            "kind": "main",
            "duration_ms": 300,
            "request": {
                "messages_carried": 4,
                "messages_new": [
                    {"role": "user", "content": "bye"}
                ]
            },
            "response": {"type": "Done"}
        });

        let body = format!(
            "{}\n{}\n{}\n{}\n",
            serde_json::to_string(&entry1).unwrap(),
            serde_json::to_string(&entry2).unwrap(),
            serde_json::to_string(&entry3).unwrap(),
            serde_json::to_string(&entry4).unwrap(),
        );
        std::fs::write(&path, body).unwrap();

        // read_session 全量读
        let entries = read_session(tmp.path(), "sid2").unwrap();
        assert_eq!(entries.len(), 4);
        // 第一条：原样
        let msgs0 = entries[0]["request"]["messages"].as_array().unwrap();
        assert_eq!(msgs0.len(), 2);
        assert_eq!(msgs0[0]["content"], "hello");
        // 第二条：重建完整 4 条
        let msgs1 = entries[1]["request"]["messages"].as_array().unwrap();
        assert_eq!(msgs1.len(), 4);
        assert_eq!(msgs1[0]["content"], "hello");
        assert_eq!(msgs1[2]["content"], "how are you");
        // 第三条 judge：没有 messages
        assert!(entries[2]["request"]["messages"].is_null() || entries[2]["request"].get("messages").is_none());
        // 第四条：重建完整 5 条
        let msgs3 = entries[3]["request"]["messages"].as_array().unwrap();
        assert_eq!(msgs3.len(), 5);
        assert_eq!(msgs3[4]["content"], "bye");

        // read_session_entry 单条读
        let single = read_session_entry(tmp.path(), "sid2", 3).unwrap().unwrap();
        let single_msgs = single["request"]["messages"].as_array().unwrap();
        assert_eq!(single_msgs.len(), 5);
        assert_eq!(single_msgs[0]["content"], "hello");
        assert_eq!(single_msgs[4]["content"], "bye");

        // read_session_summaries message_count
        let summaries = read_session_summaries(tmp.path(), "sid2").unwrap();
        assert_eq!(summaries[0]["message_count"], 2);
        assert_eq!(summaries[1]["message_count"], 4);
        assert_eq!(summaries[2]["message_count"], 0); // judge
        assert_eq!(summaries[3]["message_count"], 5);
    }
}

crates/agent-core/src/storage/models_cat.content:
//! models.dev 模型目录缓存（架构 §6.2 / §7 扩展）。
//!
//! 数据来源：<https://models.dev/models.json>，覆盖 180+ 模型的元数据（context/output 大小、
//! 输入/输出模态、reasoning 支持等）。前端用这些数据给模型卡片打标签，让 ModelPicker 的每行
//! 显示丰富的元信息，而不是光秃秃的 model id。
//!
//! ## 三层回退
//!
//! 1. 磁盘缓存：`~/.hebbian/models_catalog.json`（含 etag + 时间戳）
//! 2. 内置兜底：编译期 `include_bytes!` 的 `models_catalog_fallback.json`
//!
//! ## 更新策略
//!
//! 24h TTL + ETag。[`read_catalog`] 会返回可用数据（磁盘 or 兜底）；如 TTL 过期，调用方
//! 应 fire-and-forget 调 [`refresh_catalog`] 联网拉取。联网带 `If-None-Match: <etag>`，
//! 304 时不覆盖磁盘。刷新失败时保留旧缓存，不影响使用。
//!
//! ## 文件锁
//!
//! 写盘走 [`lock::write_atomic`]（atomic rename + 排他锁），与 §6.3 一致，多窗口/多进程
//! 并发刷新互不覆盖。

use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use common::{AppError, AppResult};
use serde::{Deserialize, Serialize};

/// 联网刷新的最小间隔：24h 内命中缓存直接返回，不联网。
const TTL: Duration = Duration::from_secs(24 * 60 * 60);

/// 联网请求的超时；models.dev 通常 < 1s，留 10s 余量防止网络抖动卡死启动。
const REQUEST_TIMEOUT: Duration = Duration::from_secs(10);

/// 兜底 JSON：编译期嵌入，离线也能有完整目录。
const FALLBACK_JSON: &str = include_str!("./models_catalog_fallback.json");

/// 缓存文件名。
const CACHE_FILENAME: &str = "models_catalog.json";

/// 单个模型条目，与 models.dev 的 schema 对齐。
///
/// 字段全部 optional 化——models.dev 不保证每个模型都齐，缺失字段按 `None` / 默认值处理，
/// 前端渲染时对 `None` 不显示对应徽章。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CatalogEntry {
    /// 模型 id，形如 `anthropic/claude-opus-4-5`。
    pub id: String,
    /// 人类可读名字。
    pub name: Option<String>,
    /// 模型家族（用于按组渲染卡片网格）。
    pub family: Option<String>,
    /// 是否支持 reasoning / thinking。
    #[serde(default)]
    pub reasoning: bool,
    /// 是否支持工具调用。
    #[serde(default)]
    pub tool_call: bool,
    /// 是否支持附件（图片/pdf 等）。
    #[serde(default)]
    pub attachment: bool,
    /// 支持的 effort 级别列表（如 ["low", "medium", "high", "extra"]），null 表示不限制。
    #[serde(default)]
    pub effort: Option<Vec<String>>,
    /// 推理配置的类型（如 "thinking"、"reasoning_effort"），null 表示无。
    #[serde(default)]
    pub reasoning_effort: Option<String>,
    /// 是否支持 thinking（与 reasoning_effort 互斥），null 表示不限制。
    #[serde(default)]
    pub thinking: Option<bool>,
    /// 输入/输出模态。
    pub modalities: Option<CatalogModalities>,
    /// context / output / input 大小限制。
    pub limit: Option<CatalogLimits>,
    /// 训练数据截止日期。
    pub knowledge: Option<String>,
    /// 发布日期。
    pub release_date: Option<String>,
    /// 最近更新日期。
    pub last_updated: Option<String>,
}

/// 输入/输出模态。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CatalogModalities {
    /// 输入模态：text / image / audio / video / pdf 等。
    #[serde(default)]
    pub input: Vec<String>,
    /// 输出模态：text / image / audio 等。
    #[serde(default)]
    pub output: Vec<String>,
}

/// 模型大小限制（token 数）。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CatalogLimits {
    /// 上下文窗口（输入 + 输出总上限）。
    pub context: Option<usize>,
    /// 单条请求输入上限。
    pub input: Option<usize>,
    /// 最大输出 token 数。
    pub output: Option<usize>,
}

/// 磁盘缓存文件结构。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CatalogCache {
    /// HTTP 缓存用的 ETag；下次刷新带 `If-None-Match`，304 时跳过写盘。
    pub etag: Option<String>,
    /// 上次成功刷新的 Unix 毫秒时间戳。
    pub last_fetched_at_ms: i64,
    /// 模型目录，按 `id` 索引。
    pub entries: HashMap<String, CatalogEntry>,
}

/// 读取当前目录。先尝试磁盘缓存，失败则用内置兜底。
///
/// 调用方拿到 `CatalogCache` 后应检查 [`is_stale`]：如果过期，fire-and-forget 调
/// [`refresh_catalog`] 联网更新（不阻塞当前返回）。
pub fn read_catalog(data_dir: &Path) -> CatalogCache {
    match try_load_disk_cache(data_dir) {
        Ok(Some(cache)) => cache,
        Ok(None) => {
            tracing::info!("models_catalog 无磁盘缓存，使用内置兜底");
            fallback_cache()
        }
        Err(e) => {
            tracing::warn!(error = %e, "models_catalog 读取磁盘缓存失败，使用内置兜底");
            fallback_cache()
        }
    }
}

/// 磁盘缓存是否在 TTL 内。
pub fn is_stale(cache: &CatalogCache) -> bool {
    let now = now_ms();
    let age = now.saturating_sub(cache.last_fetched_at_ms);
    age as u64 > TTL.as_millis() as u64
}

/// 联网刷新目录。带 ETag，304 时仅更新时间戳；200 时覆盖 entries + etag；
/// 任何网络 / 解析失败都只 warn 不抛错（调用方仍能用旧缓存）。
///
/// 返回 `true` 表示有更新（200 写了新 entries），`false` 表示未修改或失败。
pub async fn refresh_catalog(data_dir: &Path) -> bool {
    let current = try_load_disk_cache(data_dir).ok().flatten();
    let if_none_match = current.as_ref().and_then(|c| c.etag.clone());

    match fetch_remote(if_none_match.as_deref()).await {
        Ok(RemoteResult::NotModified) => {
            tracing::debug!("models_catalog 远端未修改（304），保留缓存");
            // 304：只推进时间戳，让下次 TTL 检查不再过期。
            if let Some(mut cache) = current {
                cache.last_fetched_at_ms = now_ms();
                if let Err(e) = save_cache(data_dir, &cache) {
                    tracing::warn!(error = %e, "models_catalog 304 后推进时间戳失败");
                }
            }
            false
        }
        Ok(RemoteResult::Updated { entries, etag }) => {
            let count = entries.len();
            let cache = CatalogCache {
                etag,
                last_fetched_at_ms: now_ms(),
                entries,
            };
            if let Err(e) = save_cache(data_dir, &cache) {
                tracing::warn!(error = %e, "models_catalog 写磁盘缓存失败");
                return false;
            }
            tracing::info!(count, "models_catalog 已更新");
            true
        }
        Err(e) => {
            tracing::warn!(error = %e, "models_catalog 联网刷新失败，保留旧缓存");
            false
        }
    }
}

/// 缓存文件路径。
fn cache_path(data_dir: &Path) -> PathBuf {
    data_dir.join(CACHE_FILENAME)
}

fn try_load_disk_cache(data_dir: &Path) -> std::io::Result<Option<CatalogCache>> {
    let path = cache_path(data_dir);
    if !path.exists() {
        return Ok(None);
    }
    let bytes = std::fs::read(&path)?;
    match serde_json::from_slice::<CatalogCache>(&bytes) {
        Ok(cache) => Ok(Some(cache)),
        Err(e) => {
            tracing::warn!(error = %e, "models_catalog 解析磁盘缓存失败，视为不存在");
            Ok(None)
        }
    }
}

fn fallback_cache() -> CatalogCache {
    let entries: HashMap<String, CatalogEntry> =
        serde_json::from_str(FALLBACK_JSON).unwrap_or_else(|e| {
            panic!("内置 models_catalog_fallback.json 解析失败：{e}")
        });
    let count = entries.len();
    tracing::debug!(count, "models_catalog 内置兜底加载完成");
    CatalogCache {
        etag: None,
        last_fetched_at_ms: now_ms(),
        entries,
    }
}

fn save_cache(data_dir: &Path, cache: &CatalogCache) -> AppResult<()> {
    let json = serde_json::to_vec_pretty(cache)?;
    crate::storage::lock::write_atomic(&cache_path(data_dir), &json)
}

fn now_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

enum RemoteResult {
    NotModified,
    Updated {
        entries: HashMap<String, CatalogEntry>,
        etag: Option<String>,
    },
}

/// 拉远端 JSON。带 ETag + 超时；304 → `NotModified`，200 → 解析为 `HashMap<id, entry>`。
async fn fetch_remote(if_none_match: Option<&str>) -> AppResult<RemoteResult> {
    let mut builder = reqwest::Client::builder()
        .timeout(REQUEST_TIMEOUT)
        .user_agent("hebbian/1.0 (+models.dev cache)")
        .build()?
        .get("https://models.dev/models.json");
    if let Some(etag) = if_none_match {
        builder = builder.header(reqwest::header::IF_NONE_MATCH, etag);
    }
    let resp = builder.send().await?;
    let status = resp.status();
    if status == reqwest::StatusCode::NOT_MODIFIED {
        return Ok(RemoteResult::NotModified);
    }
    if !status.is_success() {
        return Err(AppError::Msg(format!(
            "models.dev 返回非 2xx 状态：{status}"
        )));
    }
    let etag = resp
        .headers()
        .get(reqwest::header::ETAG)
        .and_then(|v| v.to_str().ok())
        .map(String::from);
    let body = resp.bytes().await?;
    let entries: HashMap<String, CatalogEntry> = serde_json::from_slice(&body).map_err(|e| {
        AppError::Msg(format!("models.dev JSON 解析失败：{e}"))
    })?;
    Ok(RemoteResult::Updated { entries, etag })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fallback_parses() {
        let cache = fallback_cache();
        assert!(!cache.entries.is_empty(), "内置兜底不能是空 map");
        // 抽几个常见模型验证 schema 完整性。
        assert!(cache.entries.contains_key("anthropic/claude-opus-4-5"));
        assert!(cache.entries.contains_key("openai/gpt-5"));
        assert!(cache.entries.contains_key("google/gemini-2.5-pro"));
    }

    #[test]
    fn stale_boundary() {
        let mut cache = fallback_cache();
        // 刚刚加载的兜底不 stale。
        assert!(!is_stale(&cache));
        // 时间戳推到 25h 前，应该 stale。
        cache.last_fetched_at_ms -= TTL.as_millis() as i64 + 3_600_000;
        assert!(is_stale(&cache));
    }

    #[test]
    fn round_trip_serde() {
        let cache = fallback_cache();
        let json = serde_json::to_vec(&cache).unwrap();
        let back: CatalogCache = serde_json::from_slice(&json).unwrap();
        assert_eq!(back.entries.len(), cache.entries.len());
    }
}

