    /// [`RunMode`] 起始快照。老 RolloutMeta 无此字段反序列化为 `AskBeforeEdits`。
    #[serde(default)]
    pub run_mode: RunMode,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub global_rules: Option<Vec<PathBuf>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
