/// 显式指定 surface 来源的 create。CLI 应传 `"cli"`，desktop / 测试用默认值即可。
pub fn create_with_source(
    data_dir: &Path,
    provider_id: String,
    model: String,
    system_prompt: Option<String>,
    prompt_id: Option<String>,
    source: String,
) -> AppResult<Session> {
    let now_ts = now();
    let mut session = Session {
        id: new_id(),
        title: "新对话".into(),
        provider_id,
        model,
        system_prompt,
        prompt_id,
        stream: true,
        messages: Vec::new(),
        workdir: None,
        allowed_paths: None,
        runtime_allowed_paths: Vec::new(),
        pending_runtime_allowed_paths: Vec::new(),
        enabled_tools: None,
        skill_dirs: None,
        reasoning: None,
        token_stats: None,
        source: Some(source.clone()),
        project_id: None,
        run_mode: RunMode::default(),
        global_rules: None,
        rules_files: None,
        todos: Vec::new(),
        active_plan: None,
        pre_plan_mode: None,
        pending_continue: None,
        created_at: now_ts,
        updated_at: now_ts,
    };
    let target = jsonl_path_for(data_dir, &session.id, session.created_at)?;
    write_jsonl_full(&target, &session, source.clone())?;
    // 初始化目录骨架 + meta.json（架构 §4.9.1）。
    super::sessions_dir::ensure_session_dirs(data_dir, &session.id)?;
    let _ = super::sessions_dir::save_meta(
        data_dir,
        &super::sessions_dir::SessionDirMeta {
