/// 写入 / 清空「续作入口」（架构 §4.3）。`Some(_)` = 上一个 Run 非正常结束；
/// `None` = 正常完成或用户已点 continue，清空它。沿用 append-only MetaUpdate 模式。
pub fn set_pending_continue(
    data_dir: &Path,
