//! 系统提示词的唯一来源。
//!
//! 两层：
//!
//! 1. [`BASE_SYSTEM_PROMPT`]：Hebbian 内置的 agent 身份 + 行为准则。**整个仓库唯一的常量**，
//!    跨会话恒定，方便 prompt cache 命中。模型 schema 之外的"策略"全在这里说，工具 schema
//!    本身的字段说明保留在各个 `Tool::description` 上，不在 system 里重复。
//! 2. 用户 persona（[`compose_system_prompt`] 的入参）：用户在 `prompts.json` 里选的角色风格，
//!    每次会话可不同。拼在 base 之后。
//!
//! 另外 [`EnvironmentSnapshot`] 渲染 `<environment>` 块，**不进 system**，走第一条
//! user message 头部，避免 system 段内容随机器/时间漂移。
//!
//! 设计原则：system 段必须是字节稳定的前缀；任何随时间或会话变化的事实都走 user message。
//! 这样 prompt cache 跨会话也能命中。

use std::path::{Path, PathBuf};

use crate::storage::memory::MemoryL0;
use crate::workspace::Workspace;

/// Hebbian 的基础系统提示词。
///
/// 章节顺序：identity → 沟通 → 客观性 → 工具策略 → 行动可逆性 → 工程任务 → 验收
/// → Git → 安全 → 输出 → 环境。
/// 不区分纯聊天 / 写代码模式：模型自己能根据对话内容判断当前任务，不会硬套不相干的章节。
pub const BASE_SYSTEM_PROMPT: &str = include_str!("../prompts/base_system.md");

/// 拼出最终的 system 段：base + 可选用户 persona。
///
/// persona 为空 / 全空白时只返回 base，避免末尾出现空 section。
pub fn compose_system_prompt(persona: Option<&str>) -> String {
    let persona = persona.map(str::trim).filter(|s| !s.is_empty());
    match persona {
        Some(p) => format!("{BASE_SYSTEM_PROMPT}\n\n# 用户角色\n\n{p}"),
        None => BASE_SYSTEM_PROMPT.to_string(),
    }
}

/// 一次会话开始时的环境快照。注入到第一条 user message 头部。
#[derive(Debug, Clone)]
pub struct EnvironmentSnapshot {
    pub workdir: PathBuf,
    pub allowed_paths: Vec<PathBuf>,
    pub platform: &'static str,
    pub shell: Option<String>,
    pub date: String,
    /// 当前运行模式（架构 §4.4.3）。`None` = 不渲染，模型按默认行为推理。
    pub run_mode: Option<&'static str>,
    /// 当前后台 shell 列表（架构 §4.12.7）。非空时在 `<environment>` 旁
    /// 渲染一个 `<background_tasks>` 子块，让模型立刻看到。
    /// 元组：(task_id, state_label, command, elapsed_secs)
    pub background_tasks: Vec<BackgroundTaskSummary>,
    /// PermissionStore 的 paths 白名单（架构 §6.1.2）：global + project paths 合并后的
    /// 扩展可访问目录。与 `allowed_paths`（workspace 自带）独立渲染，标签 `<extra_path>`。
    pub extra_paths: Vec<PathBuf>,
    /// 记忆 L0 清单（架构 §4.14）：global + 当前 project 的一句话摘要，渲染成
    /// `<memory-index>` 块让模型初筛，要详情再 `ReadMemory(id)`。仅首条 user message 注入。
    pub memory_index: Vec<MemoryL0>,
}

/// `<background_tasks>` 渲染所需的最小信息。
#[derive(Debug, Clone)]
pub struct BackgroundTaskSummary {
    pub task_id: String,
    pub state: String,
    pub command: String,
    pub elapsed_secs: u64,
}

impl EnvironmentSnapshot {
    /// 从 workspace + 当前进程环境拼出快照。
    /// 只读 `initial_allowed_paths`：runtime_pending 通过 `<workspace-update>` 单独通知。
    pub fn from_workspace(workspace: &Workspace) -> Self {
        Self {
            workdir: workspace.workdir().to_path_buf(),
            allowed_paths: workspace.initial_allowed_paths().to_vec(),
            platform: std::env::consts::OS,
            shell: detect_shell(),
            date: today_iso(),
            run_mode: None,
            background_tasks: Vec::new(),
            extra_paths: Vec::new(),
            memory_index: Vec::new(),
        }
    }

    /// builder-style：注入 PermissionStore 的 paths 白名单（global + project 合并），
    /// 跟 workspace.allowed_paths 去重。
    pub fn with_extra_paths(mut self, paths: Vec<PathBuf>) -> Self {
        let mut dedup: Vec<PathBuf> = Vec::new();
        for p in paths {
            if !self.allowed_paths.contains(&p) && !dedup.contains(&p) {
                dedup.push(p);
            }
        }
        self.extra_paths = dedup;
        self
    }

    /// builder-style：设置当前 run_mode。
    pub fn with_run_mode(mut self, mode: crate::run_mode::RunMode) -> Self {
        self.run_mode = Some(mode.as_str());
        self
    }

    /// builder-style：把当前后台 shell 列表塞进来（架构 §4.12.7）。
    pub fn with_background_tasks(mut self, tasks: Vec<BackgroundTaskSummary>) -> Self {
        self.background_tasks = tasks;
        self
    }

    /// builder-style：注入记忆 L0 清单（架构 §4.14）。
    pub fn with_memory_index(mut self, index: Vec<MemoryL0>) -> Self {
        self.memory_index = index;
        self
    }

    /// 渲染 `<memory-index>`（若有）+ `<environment>` XML 块，末尾保留空行便于和正文分隔。
    pub fn render(&self) -> String {
        let mut s = String::new();
        if !self.memory_index.is_empty() {
            s.push_str("<memory-index>\n");
            s.push_str("可能与当前任务相关的记忆，要详情用 ReadMemory(id) 读取：\n");
            for m in &self.memory_index {
                s.push_str(&format!("  - [{}] {}\n", m.id, m.summary));
            }
            s.push_str("</memory-index>\n\n");
        }
        s.push_str(&render_environment_xml(
            &self.workdir,
            &self.allowed_paths,
            &self.extra_paths,
            self.platform,
            self.shell.as_deref(),
            &self.date,
            self.run_mode,
        ));
        if !self.background_tasks.is_empty() {
            s.push_str("<background_tasks>\n");
            for t in &self.background_tasks {
                s.push_str(&format!(
                    "  - {} [{}] {}s `{}`\n",
                    t.task_id, t.state, t.elapsed_secs, t.command,
                ));
            }
            s.push_str("</background_tasks>\n\n");
        }
        s
    }
}

/// 把环境块前置到 user content。用于第一条 user message。
pub fn prepend_environment(text: String, snapshot: &EnvironmentSnapshot) -> String {
    let mut s = snapshot.render();
    s.push_str(&text);
    s
}

/// 把 `<background_tasks>` 块单独前置到 user content（架构 §4.12.7）。
/// 用于非首条 user message——首条由 `prepend_environment` 内嵌在
/// `<environment>` 旁，这里覆盖后续每一条。tasks 为空时调用方应跳过本函数。
pub fn prepend_background_tasks(text: String, tasks: &[BackgroundTaskSummary]) -> String {
    if tasks.is_empty() {
        return text;
    }
    let mut s = String::from("<background_tasks>\n");
    for t in tasks {
        s.push_str(&format!(
            "  - {} [{}] {}s `{}`\n",
            t.task_id, t.state, t.elapsed_secs, t.command,
        ));
    }
    s.push_str("</background_tasks>\n\n");
    s.push_str(&text);
    s
}

/// 把 `<plan_comments>` 块前置到 user content（架构 §4.4.5）。
/// 用户在 plan tab / 审批 popup 加的评论以 unconsumed 状态落盘，每次发 user
/// message 前由 [`crate::session::Session::append_user`] 抓出来注入，让 agent
/// 在下一轮 ModelStep 看到。注入后调 [`crate::storage::plan_comments::mark_consumed`]
/// 标记已消费。空 vec 时调用方应跳过本函数。
pub fn prepend_plan_comments(text: String, comments: &[protocol::todo::PlanComment]) -> String {
    if comments.is_empty() {
        return text;
    }
    let mut s = String::from("<plan_comments>\n");
    for c in comments {
        s.push_str(&format!("  - [{}] {}\n", c.anchor, c.body));
    }
    s.push_str("</plan_comments>\n\n");
    s.push_str(&text);
    s
}

fn render_environment_xml(
    workdir: &Path,
    allowed_paths: &[PathBuf],
    extra_paths: &[PathBuf],
    platform: &str,
    shell: Option<&str>,
    date: &str,
    run_mode: Option<&str>,
) -> String {
    let mut s = String::from("<environment>\n");
    s.push_str(&format!("  <cwd>{}</cwd>\n", workdir.display()));
    for d in allowed_paths {
        s.push_str(&format!("  <allowed_path>{}</allowed_path>\n", d.display()));
    }
    for d in extra_paths {
        s.push_str(&format!("  <extra_path>{}</extra_path>\n", d.display()));
    }
    s.push_str(&format!("  <platform>{platform}</platform>\n"));
    if let Some(sh) = shell {
        s.push_str(&format!("  <shell>{sh}</shell>\n"));
    }
    s.push_str(&format!("  <date>{date}</date>\n"));
    if let Some(mode) = run_mode {
        s.push_str(&format!("  <run_mode>{mode}</run_mode>\n"));
    }
    s.push_str("</environment>\n\n");
    s
}

fn detect_shell() -> Option<String> {
    std::env::var("SHELL").ok().and_then(|p| {
        Path::new(&p)
            .file_name()
            .map(|f| f.to_string_lossy().into_owned())
    })
}

fn today_iso() -> String {
    chrono::Utc::now().format("%Y-%m-%d").to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compose_without_persona_returns_base() {
        let s = compose_system_prompt(None);
        assert_eq!(s, BASE_SYSTEM_PROMPT);
    }

    #[test]
    fn compose_appends_persona_section() {
        let s = compose_system_prompt(Some("你是代码搭档"));
        assert!(s.starts_with(BASE_SYSTEM_PROMPT));
        assert!(s.contains("# 用户角色"));
        assert!(s.contains("你是代码搭档"));
    }

    #[test]
    fn compose_treats_empty_persona_as_none() {
        assert_eq!(compose_system_prompt(Some("   ")), BASE_SYSTEM_PROMPT);
        assert_eq!(compose_system_prompt(Some("")), BASE_SYSTEM_PROMPT);
    }

    #[test]
    fn base_covers_core_sections() {
        // 烟雾测试：所有关键章节都在
        let s = BASE_SYSTEM_PROMPT;
        for h in [
            "# 沟通",
            "# 客观性与诚实",
            "# 工具策略",
            "# 行动的可逆性",
            "# 写代码",
            "# 完成与验收",
            "# Git 与版本控制",
            "# 安全",
            "# 输出",
            "# 环境上下文",
        ] {
            assert!(s.contains(h), "missing section: {h}");
        }
    }

    #[test]
    fn environment_xml_includes_workdir_and_dirs() {
        let xml = render_environment_xml(
            Path::new("/tmp/work"),
            &[PathBuf::from("/tmp/extra")],
            &[PathBuf::from("/etc")],
            "darwin",
            Some("zsh"),
            "2026-05-10",
            None,
        );
        assert!(xml.starts_with("<environment>"));
        assert!(xml.contains("<cwd>/tmp/work</cwd>"));
        assert!(xml.contains("<allowed_path>/tmp/extra</allowed_path>"));
        assert!(xml.contains("<extra_path>/etc</extra_path>"));
        assert!(xml.contains("<platform>darwin</platform>"));
        assert!(xml.contains("<shell>zsh</shell>"));
        assert!(xml.contains("<date>2026-05-10</date>"));
        assert!(xml.ends_with("</environment>\n\n"));
    }

    #[test]
    fn prepend_environment_attaches_to_user_text() {
        let snap = EnvironmentSnapshot {
            workdir: PathBuf::from("/tmp"),
            allowed_paths: Vec::new(),
            platform: "darwin",
            shell: None,
            date: "2026-05-10".into(),
            run_mode: None,
            background_tasks: Vec::new(),
            extra_paths: Vec::new(),
            memory_index: Vec::new(),
        };
        let out = prepend_environment("hello".into(), &snap);
        assert!(out.starts_with("<environment>"));
        assert!(out.ends_with("hello"));
    }

    #[test]
    fn with_extra_paths_dedup_against_allowed_paths() {
        let mut snap = EnvironmentSnapshot {
            workdir: PathBuf::from("/tmp"),
            allowed_paths: vec![PathBuf::from("/tmp/a")],
            platform: "darwin",
            shell: None,
            date: "2026-05-10".into(),
            run_mode: None,
            background_tasks: Vec::new(),
            extra_paths: Vec::new(),
            memory_index: Vec::new(),
        };
        snap = snap.with_extra_paths(vec![
            PathBuf::from("/tmp/a"), // 跟 allowed_paths 重复
            PathBuf::from("/etc"),
            PathBuf::from("/etc"), // 自我重复
        ]);
        assert_eq!(snap.extra_paths, vec![PathBuf::from("/etc")]);
    }

    #[test]
    fn memory_index_renders_before_environment() {
        let snap = EnvironmentSnapshot {
            workdir: PathBuf::from("/tmp"),
            allowed_paths: Vec::new(),
            platform: "darwin",
            shell: None,
            date: "2026-05-10".into(),
            run_mode: None,
            background_tasks: Vec::new(),
            extra_paths: Vec::new(),
            memory_index: vec![
                MemoryL0 {
                    id: "global/lang".into(),
                    summary: "用户要求始终用中文".into(),
                    category: "preferences".into(),
                },
                MemoryL0 {
                    id: "proj/architecture".into(),
                    summary: "agent-core 是大脑".into(),
                    category: "architecture".into(),
                },
            ],
        };
        let out = snap.render();
        let mem_pos = out.find("<memory-index>").expect("应渲染 memory-index");
        let env_pos = out.find("<environment>").expect("应渲染 environment");
        assert!(mem_pos < env_pos, "memory-index 应在 environment 之前");
        assert!(out.contains("[global/lang] 用户要求始终用中文"));
        assert!(out.contains("[proj/architecture] agent-core 是大脑"));
    }

    #[test]
    fn empty_memory_index_omits_block() {
        let snap =
            EnvironmentSnapshot::from_workspace(&Workspace::new(PathBuf::from("/tmp"), vec![]));
        let out = snap.render();
        assert!(!out.contains("<memory-index>"), "空清单不应渲染块");
    }
}

crates/agent-core/src/tools/background.r.content:
//! 后台 shell 注册表：让 [`super::bash::BashTool`] 在命令超时（或用户显式
//! `run_in_background`）时把进程转后台继续运行，由 [`super::bash_output::BashOutputTool`]
//! 按 task_id 增量查询，由 [`super::kill_shell::KillShellTool`] 主动终止。
//!
//! 设计要点：
//! - `BackgroundShells` 是进程级单例，在 [`super::default_tools`] 里构造一次后
//!   注入给上述三个工具，跨 session 共享。注册表上限 [`MAX_BACKGROUND_SHELLS`]
//!   个，超过时踢最老的已退出条目。
//! - 每个 `BackgroundShell` 持有一个 tail buffer：合并 stdout/stderr 后只保留
//!   尾部 [`MAX_TAIL_BYTES`] 字节，避免长跑命令吃光内存。读取按 byte 游标增量
//!   返回，模型一次拿不超过 [`READ_CHUNK_BYTES`] 字节。
//! - 进程 stdout/stderr 由后台 task 持续抽到 buffer；waiter task 用 select! 同时
//!   等 child 退出和 kill 信号——SIGKILL 与正常 wait 不会争 child 的可变借用。
//! - 双轨写入（架构 §4.12.3）：若 register 时给了 log_dir，stdout/stderr 在灌
//!   tail buffer 的同时 append 到 `<log_dir>/<task_id>.log`——内存 tail 给
//!   BashOutput 增量查询，磁盘 log 给完整 Read。两条互不依赖：日志文件打开失败
//!   不影响命令运行，仅 fallback 到 tail-only。

use std::collections::{HashMap, VecDeque};
use std::path::{Path, PathBuf};
use std::process::ExitStatus;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Instant;

use tokio::fs::File;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::Child;
use tokio::sync::{oneshot, Mutex as AsyncMutex, Notify};

/// tail buffer 上限（256 KiB）。超过后丢弃最早字节。
pub const MAX_TAIL_BYTES: usize = 256 * 1024;
/// 单次 BashOutput 返回上限（32 KiB），避免一次塞满 model context。
pub const READ_CHUNK_BYTES: usize = 32 * 1024;
/// 注册表保留的活跃条目上限。
pub const MAX_BACKGROUND_SHELLS: usize = 16;

#[derive(Debug, Clone)]
pub enum ShellState {
    Running,
    Exited { code: Option<i32> },
    Killed,
    Failed { error: String },
}

impl ShellState {
    pub fn is_terminal(&self) -> bool {
        !matches!(self, ShellState::Running)
    }

    pub fn label(&self) -> &'static str {
        match self {
            ShellState::Running => "running",
            ShellState::Exited { .. } => "exited",
            ShellState::Killed => "killed",
            ShellState::Failed { .. } => "failed",
        }
    }
}

pub struct BackgroundShell {
    pub task_id: String,
    pub command: String,
    pub cwd: String,
    pub started_at: Instant,
    /// 是否明确标记为后台任务（run_in_background=true 或超时转后台）。
    /// surface 用它把"前台 bash 中间状态"和"真正后台任务"区分开。
    /// 前台正常 exit 的命令会被 BashTool 直接 unregister，不会停留在注册表里；
    /// 这个字段在「前台超时转后台」时由 `promote_to_background` 翻成 true。
    is_background: AtomicBool,
    inner: Mutex<ShellInner>,
    /// 输出/状态变化时唤醒等待方（BashOutput 的 wait_ms 阻塞、KillShell 等终态）。
    notify: Notify,
    /// 磁盘日志路径——`None` 表示未启用落盘（CLI / 单测）。
    log_path: Option<PathBuf>,
}

struct ShellInner {
    state: ShellState,
    total_bytes: u64,
    tail: VecDeque<u8>,
    /// 用户已读到的字节游标（绝对值，对齐 total_bytes）。
    read_cursor: u64,
    finished_at: Option<Instant>,
    /// kill 信号：waiter task 内的 oneshot 接收端等它，KillShell 取出 sender 发送。
    /// 用 oneshot 是因为 `Notify::notify_waiters` 在没人 awaiting 时会丢消息。
    kill_tx: Option<oneshot::Sender<()>>,
}

impl BackgroundShell {
    fn new(
        task_id: String,
        command: String,
        cwd: String,
        is_background: bool,
        kill_tx: oneshot::Sender<()>,
        log_path: Option<PathBuf>,
    ) -> Self {
        Self {
            task_id,
            command,
            cwd,
            is_background: AtomicBool::new(is_background),
            started_at: Instant::now(),
            inner: Mutex::new(ShellInner {
                state: ShellState::Running,
                total_bytes: 0,
                tail: VecDeque::new(),
                read_cursor: 0,
                finished_at: None,
                kill_tx: Some(kill_tx),
            }),
            notify: Notify::new(),
            log_path,
        }
    }

    /// 磁盘日志文件路径——`None` 表示未启用落盘。BashOutput / 转后台返回值
    /// 用它告诉模型「完整输出在哪」（架构 §4.12.3）。
    pub fn log_path(&self) -> Option<&Path> {
        self.log_path.as_deref()
    }

    pub fn is_background(&self) -> bool {
        self.is_background.load(Ordering::Relaxed)
    }

    /// 前台命令超时后被 BashTool 转后台时调一次：把 is_background 翻成 true，
    /// 这样下游过滤（list_background_tasks / bg_summaries）就能正确收录它。
    /// 日志文件不在这里补开——register 时没开就一直没开，转后台后模型用
    /// BashOutput 走 tail buffer 取增量足够；如要完整日志，应该一开始就传
    /// run_in_background=true。
    pub fn promote_to_background(&self) {
        self.is_background.store(true, Ordering::Relaxed);
    }

    pub fn state(&self) -> ShellState {
        self.inner
            .lock()
            .expect("background shell mutex")
            .state
            .clone()
    }

    fn append(&self, prefix: Option<&str>, bytes: &[u8]) {
        {
            let mut inner = self.inner.lock().expect("background shell mutex");
            if let Some(p) = prefix {
                inner.push(p.as_bytes());
            }
            inner.push(bytes);
            if !bytes.ends_with(b"\n") {
                inner.push(b"\n");
            }
        }
        self.notify.notify_waiters();
    }

    fn finish(&self, state: ShellState) {
        {
            let mut inner = self.inner.lock().expect("background shell mutex");
            // 已经是终态就保留首次记录，避免 waiter / kill 互踩
            if inner.state.is_terminal() {
                return;
            }
            inner.state = state;
            inner.finished_at = Some(Instant::now());
        }
        self.notify.notify_waiters();
    }

    /// 按外部传入的 absolute cursor 取增量，**不动**内部 read_cursor。
    /// surface polling 用——每个查询者维护自己的 cursor，互不干扰。
    /// `cursor`：上一次拿到的 `total_bytes`；首次传 0。
    pub fn read_at(&self, cursor: u64) -> ReadOutput {
        let inner = self.inner.lock().expect("background shell mutex");
        let total = inner.total_bytes;
        if cursor >= total {
            return ReadOutput {
                content: String::new(),
                state: inner.state.clone(),
                bytes_dropped: 0,
                total_bytes: total,
            };
        }
        let tail_start = total.saturating_sub(inner.tail.len() as u64);
        let bytes_dropped = tail_start.saturating_sub(cursor);
        let effective_start = cursor.max(tail_start);
        let skip = (effective_start - tail_start) as usize;
        let take = inner.tail.len().saturating_sub(skip);
        let bytes: Vec<u8> = inner.tail.iter().skip(skip).take(take).copied().collect();
        let content = String::from_utf8_lossy(&bytes).into_owned();
        ReadOutput {
            content,
            state: inner.state.clone(),
            bytes_dropped,
            total_bytes: total,
        }
    }

    /// 读取自上次以来未读的输出。`max_bytes` 控制单次返回上限。
    pub fn read_incremental(&self, max_bytes: usize) -> ReadOutput {
        let mut inner = self.inner.lock().expect("background shell mutex");
        let unread = inner.total_bytes.saturating_sub(inner.read_cursor);
        if unread == 0 {
            return ReadOutput {
                content: String::new(),
                state: inner.state.clone(),
                bytes_dropped: 0,
                total_bytes: inner.total_bytes,
            };
        }
        let tail_start = inner.total_bytes.saturating_sub(inner.tail.len() as u64);
        let bytes_dropped = tail_start.saturating_sub(inner.read_cursor);
        let effective_start = inner.read_cursor.max(tail_start);
        let want = unread.min(max_bytes as u64) as usize;
        let skip = (effective_start - tail_start) as usize;
        let take = want.min(inner.tail.len().saturating_sub(skip));
        let bytes: Vec<u8> = inner.tail.iter().skip(skip).take(take).copied().collect();
        let content = String::from_utf8_lossy(&bytes).into_owned();
        inner.read_cursor = effective_start + take as u64;
        ReadOutput {
            content,
            state: inner.state.clone(),
            bytes_dropped,
            total_bytes: inner.total_bytes,
        }
    }

    /// 等待新输出或状态变化（最多 wait_ms 毫秒）。返回时调用方应再 `read_incremental`。
    pub async fn wait_for_change(&self, wait_ms: u64) {
        if wait_ms == 0 {
            return;
        }
        let _ = tokio::time::timeout(
            std::time::Duration::from_millis(wait_ms),
            self.notify.notified(),
        )
        .await;
    }

    /// 等到进入终态。
    pub async fn wait_terminal(&self) {
        loop {
            if self.state().is_terminal() {
                return;
            }
            self.notify.notified().await;
        }
    }
}

impl ShellInner {
    fn push(&mut self, bytes: &[u8]) {
        self.total_bytes += bytes.len() as u64;
        self.tail.extend(bytes.iter().copied());
        if self.tail.len() > MAX_TAIL_BYTES {
            let drop = self.tail.len() - MAX_TAIL_BYTES;
            self.tail.drain(..drop);
        }
    }
}

pub struct ReadOutput {
    pub content: String,
    pub state: ShellState,
    /// 因 tail 容量被永久丢弃的字节数（让模型知道输出有间断）。
    pub bytes_dropped: u64,
    pub total_bytes: u64,
}

/// 后台子 agent 任务（`Task run_in_background=true`）的状态追踪（架构 §4.4.11.7）。
/// WakeupScheduler 的 scan_bg 按 `subagent-` 前缀路由到这里检查终态。
pub struct BgSubagentTask {
    pub task_id: String,
    pub started_at: Instant,
    done: AtomicBool,
    success: AtomicBool,
}

impl BgSubagentTask {
    fn new(task_id: String) -> Self {
        Self {
            task_id,
            started_at: Instant::now(),
            done: AtomicBool::new(false),
            success: AtomicBool::new(false),
        }
    }

    pub fn is_done(&self) -> bool {
        self.done.load(Ordering::Relaxed)
    }

    pub fn is_success(&self) -> bool {
        self.success.load(Ordering::Relaxed)
    }

    /// 子 agent 完成时调用（成功 / 失败均需调用）。
    pub fn finish(&self, success: bool) {
        self.success.store(success, Ordering::Relaxed);
        self.done.store(true, Ordering::Relaxed);
    }

    pub fn elapsed_ms(&self) -> u64 {
        self.started_at.elapsed().as_millis() as u64
    }
}

/// session-scoped 注册表（架构 §4.12.2 修订）。每个 session 持有自己一份，
/// 跨会话不可见。Clone 等价于持 Arc——同一 session 内的 BashTool /
/// BashOutputTool / KillShellTool 共享同一份；跨 chat() 调用
/// 通过 [`registry_for_session`] 拿同一把（按 session_id 路由）。
/// 同时管理 Bash shell（`bash_NNN`）与后台 subagent（`subagent-*`）两类任务。
#[derive(Clone, Default)]
pub struct BgTaskRegistry {
    inner: Arc<Mutex<Inner>>,
    counter: Arc<AtomicU64>,
}

/// 进程内的 `session_id → BgTaskRegistry` 路由表（**不是**进程级单一注册表）。
/// 同一 session 多次 chat() 调用拿到同一份 BgTaskRegistry；不同 session 完全隔离。
/// CLI 等无 session 的路径直接用 `BgTaskRegistry::new()`，不入路由表。
static SESSION_REGISTRY: std::sync::OnceLock<
    Mutex<std::collections::HashMap<String, BgTaskRegistry>>,
> = std::sync::OnceLock::new();

fn session_registry() -> &'static Mutex<std::collections::HashMap<String, BgTaskRegistry>> {
    SESSION_REGISTRY.get_or_init(|| Mutex::new(std::collections::HashMap::new()))
}

/// 按 session_id 取（或首次创建）该 session 的 BgTaskRegistry。
/// 同一 session 多次调用返回同一份；不同 session 互不可见。
pub fn registry_for_session(session_id: &str) -> BgTaskRegistry {
    let mut map = session_registry().lock().expect("session registry mutex");
    map.entry(session_id.to_string())
        .or_insert_with(BgTaskRegistry::default)
        .clone()
}

/// session 关闭 / 删除时从路由表里摘除。已注册的 bg task 会随 Arc drop 一同清掉。
pub fn discard_session_registry(session_id: &str) {
    if let Ok(mut map) = session_registry().lock() {
        map.remove(session_id);
    }
}

/// 列出当前路由表中所有 session_id（diagnostic / WakeupScheduler 扫所有 shells 用）。
pub fn registered_session_ids() -> Vec<String> {
    session_registry()
        .lock()
        .map(|m| m.keys().cloned().collect())
        .unwrap_or_default()
}

#[derive(Default)]
struct Inner {
    shells: Vec<Arc<BackgroundShell>>,
    subagents: HashMap<String, Arc<BgSubagentTask>>,
}

impl BgTaskRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    fn next_id(&self) -> String {
        let n = self.counter.fetch_add(1, Ordering::Relaxed) + 1;
        format!("bash_{n:03}")
    }

    /// 注册一条后台 shell：拿走 child 的 stdout/stderr 流式读，
    /// 用 waiter task 等退出 / kill 信号。
    ///
    /// `log_dir` 给定时（生产环境）会在 `<log_dir>/<task_id>.log` 同步追加 stdout/stderr——
    /// 打开失败仅 warn 不阻塞命令执行，回落到内存 tail-only 路径（架构 §4.12.3）。
    pub fn register(
        &self,
        command: String,
        cwd: String,
        is_background: bool,
        log_dir: Option<&Path>,
        mut child: Child,
    ) -> Arc<BackgroundShell> {
        let task_id = self.next_id();
        let stdout = child.stdout.take();
        let stderr = child.stderr.take();
        let (kill_tx, kill_rx) = oneshot::channel();

        // 打开日志文件：失败回落 tail-only，不破坏 BashTool 主路径。
        let (log_path, log_writer) = match log_dir {
            Some(dir) => {
                let path = dir.join(format!("{task_id}.log"));
                if let Err(e) = std::fs::create_dir_all(dir) {
                    tracing::warn!(?dir, error = %e, "bg shell: mkdir log dir failed; tail-only");
                    (None, None)
                } else {
                    match std::fs::OpenOptions::new()
                        .create(true)
                        .append(true)
                        .open(&path)
                    {
                        Ok(file) => {
                            let writer = Arc::new(AsyncMutex::new(File::from_std(file)));
                            (Some(path), Some(writer))
                        }
                        Err(e) => {
                            tracing::warn!(?path, error = %e, "bg shell: open log file failed; tail-only");
                            (None, None)
                        }
                    }
                }
            }
            None => (None, None),
        };

        let shell = Arc::new(BackgroundShell::new(
            task_id,
            command,
            cwd,
            is_background,
            kill_tx,
            log_path,
        ));

        {
            let mut inner = self.inner.lock().expect("background shells mutex");
            if inner.shells.len() >= MAX_BACKGROUND_SHELLS {
                if let Some(idx) = inner.shells.iter().position(|s| s.state().is_terminal()) {
                    inner.shells.remove(idx);
                }
            }
            inner.shells.push(shell.clone());
        }

        if let Some(stdout) = stdout {
            spawn_reader(shell.clone(), stdout, None, log_writer.clone());
        }
        if let Some(stderr) = stderr {
            spawn_reader(shell.clone(), stderr, Some("[stderr] "), log_writer.clone());
        }
        spawn_waiter(shell.clone(), child, kill_rx);

        shell
    }

    /// 前台命令正常退出后，BashTool 把自己从注册表摘掉，避免 surface 把
    /// "刚跑完的 ls" 当成"已结束的后台任务"展示。仅当目标条目已进入终态时
    /// 才移除——还在 running 的拒绝删，避免误删活进程。
    pub fn unregister(&self, task_id: &str) -> bool {
        let mut inner = self.inner.lock().expect("background shells mutex");
        if let Some(idx) = inner
            .shells
            .iter()
            .position(|s| s.task_id == task_id && s.state().is_terminal())
        {
            inner.shells.remove(idx);
            true
        } else {
            false
        }
    }

    pub fn get(&self, task_id: &str) -> Option<Arc<BackgroundShell>> {
        self.inner
            .lock()
            .expect("background shells mutex")
            .shells
            .iter()
            .find(|s| s.task_id == task_id)
            .cloned()
    }

    /// 列出所有条目（最近的在前）。
    pub fn list(&self) -> Vec<Arc<BackgroundShell>> {
        let mut v = self
            .inner
            .lock()
            .expect("background shells mutex")
            .shells
            .clone();
        v.reverse();
        v
    }

    /// 发出 kill 信号；等到 shell 进入终态。
    pub async fn kill(&self, task_id: &str) -> Option<ShellState> {
        let shell = self.get(task_id)?;
        if shell.state().is_terminal() {
            return Some(shell.state());
        }
        let kill_tx = {
            let mut inner = shell.inner.lock().expect("background shell mutex");
            inner.kill_tx.take()
        };
        if let Some(tx) = kill_tx {
            let _ = tx.send(());
        }
        shell.wait_terminal().await;
        Some(shell.state())
    }

    /// 注册一个后台 subagent 任务（`Task run_in_background=true`）。
    /// 返回 Arc 供 SubagentRunner 在完成时调用 `finish()`。
    pub fn register_subagent(&self, task_id: String) -> Arc<BgSubagentTask> {
        let task = Arc::new(BgSubagentTask::new(task_id.clone()));
        self.inner
            .lock()
            .expect("bg task registry mutex")
            .subagents
            .insert(task_id, task.clone());
        task
    }

    /// 按 task_id 查后台 subagent 任务（`subagent-*` 前缀）。
    pub fn get_subagent(&self, task_id: &str) -> Option<Arc<BgSubagentTask>> {
        self.inner
            .lock()
            .expect("bg task registry mutex")
            .subagents
            .get(task_id)
            .cloned()
    }
}

fn spawn_reader<R>(
    shell: Arc<BackgroundShell>,
    reader: R,
    prefix: Option<&'static str>,
    log_writer: Option<Arc<AsyncMutex<File>>>,
) where
    R: tokio::io::AsyncRead + Send + Unpin + 'static,
{
    tokio::spawn(async move {
        let mut buf = BufReader::new(reader);
        let mut line = Vec::with_capacity(256);
        loop {
            line.clear();
            match buf.read_until(b'\n', &mut line).await {
                Ok(0) => break,
                Ok(_) => {
                    let trimmed = line.strip_suffix(b"\n").unwrap_or(&line[..]);
                    shell.append(prefix, trimmed);
                    // 双轨：同步追加到磁盘日志（架构 §4.12.3）。
                    // 单条 write_all 失败不阻断后续，进程级 fd 罕见 break。
                    if let Some(writer) = log_writer.as_ref() {
                        let mut f = writer.lock().await;
                        if let Some(p) = prefix {
                            let _ = f.write_all(p.as_bytes()).await;
                        }
                        let _ = f.write_all(trimmed).await;
                        let _ = f.write_all(b"\n").await;
                    }
                }
                Err(_) => break,
            }
        }
        // 流结束时 flush，确保最后几行落盘
        if let Some(writer) = log_writer {
            let mut f = writer.lock().await;
            let _ = f.flush().await;
        }
    });
}

fn spawn_waiter(shell: Arc<BackgroundShell>, mut child: Child, kill_rx: oneshot::Receiver<()>) {
    tokio::spawn(async move {
        tokio::select! {
            result = child.wait() => {
                let state = match result {
                    Ok(status) => exit_state(status),
                    Err(e) => ShellState::Failed { error: e.to_string() },
                };
                shell.finish(state);
            }
            _ = kill_rx => {
                let _ = child.start_kill();
                let _ = child.wait().await;
                shell.finish(ShellState::Killed);
            }
        }
    });
}

fn exit_state(status: ExitStatus) -> ShellState {
    ShellState::Exited {
        code: status.code(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::process::Stdio;
    use std::time::Duration;
    use tokio::process::Command;

    fn spawn_bash(cmd: &str) -> Child {
        Command::new("bash")
            .arg("-lc")
            .arg(cmd)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .stdin(Stdio::null())
            .spawn()
            .unwrap()
    }

    #[tokio::test]
    async fn captures_output_and_exits() {
        let shells = BgTaskRegistry::new();
        let child = spawn_bash("echo hello && echo world");
        let shell = shells.register(
            "echo hello && echo world".into(),
            "/".into(),
            false,
            None,
            child,
        );
        shell.wait_terminal().await;
        let out = shell.read_incremental(READ_CHUNK_BYTES);
        assert!(out.content.contains("hello"));
        assert!(out.content.contains("world"));
        assert!(matches!(out.state, ShellState::Exited { code: Some(0) }));
    }

    #[tokio::test]
    async fn read_is_incremental() {
        let shells = BgTaskRegistry::new();
        let child = spawn_bash("echo a; sleep 0.1; echo b");
        let shell = shells.register("...".into(), "/".into(), false, None, child);

        // 先等到至少有 a 出现
        for _ in 0..50 {
            let snapshot = shell.read_incremental(READ_CHUNK_BYTES);
            if snapshot.content.contains('a') {
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        // 再读一次拿到 b（不会重复返回 a）
        shell.wait_terminal().await;
        let after = shell.read_incremental(READ_CHUNK_BYTES);
        assert!(!after.content.contains('a'));
        assert!(after.content.contains('b'));
    }

    #[tokio::test]
    async fn kill_marks_killed() {
        let shells = BgTaskRegistry::new();
        let child = spawn_bash("sleep 30");
        let shell = shells.register("sleep 30".into(), "/".into(), false, None, child);
        let id = shell.task_id.clone();
        let state = shells.kill(&id).await.unwrap();
        assert!(matches!(state, ShellState::Killed));
    }

    /// unregister 只摘已 terminal 的条目，running 的拒绝删——
    /// 保护 BashTool 误调（虽然代码路径上不会，但防御性边界要有）。
    #[tokio::test]
    async fn unregister_only_removes_terminal() {
        let shells = BgTaskRegistry::new();
        // running 条目：unregister 返回 false，列表仍含该条目
        let still_running = shells.register(
            "sleep 30".into(),
            "/".into(),
            true,
            None,
            spawn_bash("sleep 30"),
        );
        assert!(!shells.unregister(&still_running.task_id));
        assert_eq!(shells.list().len(), 1);

        // terminal 条目：unregister 返回 true，列表为空
        let done = shells.register("true".into(), "/".into(), false, None, spawn_bash("true"));
        done.wait_terminal().await;
        assert!(shells.unregister(&done.task_id));
        assert_eq!(shells.list().len(), 1); // 只剩仍 running 的那个

        // 不存在的 task_id 返回 false
        assert!(!shells.unregister("bash_999"));

        // 收尾
        shells.kill(&still_running.task_id).await;
    }

    /// promote_to_background 把 is_background 由 false 翻成 true——
    /// BashTool 前台超时转后台路径用它。
    #[tokio::test]
    async fn promote_flips_is_background() {
        let shells = BgTaskRegistry::new();
        let s = shells.register(
            "sleep 1".into(),
            "/".into(),
            false,
            None,
            spawn_bash("sleep 1"),
        );
        assert!(!s.is_background());
        s.promote_to_background();
        assert!(s.is_background());
        shells.kill(&s.task_id).await;
    }

    #[tokio::test]
    async fn registry_caps_to_max_when_terminal() {
        let shells = BgTaskRegistry::new();
        for _ in 0..(MAX_BACKGROUND_SHELLS + 4) {
            let child = spawn_bash("true");
            let s = shells.register("true".into(), "/".into(), false, None, child);
            s.wait_terminal().await;
        }
        assert!(shells.list().len() <= MAX_BACKGROUND_SHELLS);
    }

    /// 双轨：log_dir 给定时输出落到 `<log_dir>/<task_id>.log`，内容包含 stdout + stderr 行。
    #[tokio::test]
    async fn writes_log_file_when_log_dir_given() {
        let tmp = tempfile::tempdir().unwrap();
        let shells = BgTaskRegistry::new();
        let child = spawn_bash("echo hi; echo oops >&2");
        let shell = shells.register(
            "echo hi; echo oops >&2".into(),
            "/".into(),
            false,
            Some(tmp.path()),
            child,
        );
        shell.wait_terminal().await;
        // 等 spawn_reader 把缓冲 flush
        for _ in 0..50 {
            if shell
                .log_path()
                .and_then(|p| std::fs::read_to_string(p).ok())
                .map(|s| s.contains("hi") && s.contains("oops"))
                .unwrap_or(false)
            {
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        let path = shell.log_path().expect("log_path set");
        let content = std::fs::read_to_string(path).unwrap();
        assert!(content.contains("hi"));
        assert!(content.contains("[stderr] oops"));
    }
}

