//! Edit 工具（架构 §4.4.6 / §4.4.10）。
//!
//! 精准替换文件中的一段文本；统一承担创建 / 全覆盖 / 局部修改三种语义：
//! - `old_string == ""` → 创建新文件（new_string 作为完整内容）
//! - `old_string == 完整旧内容` → 全量覆盖
//! - 其余 → 精确字符串替换（默认要求唯一匹配，`replace_all=true` 时全量替换）
//!
//! 前置条件追踪由 [`ReadStateTracker`] 承担：editing 已有文件前必须先 Read，
//! 且 Read 之后磁盘 mtime 没被外部改动。具体校验流程见架构 §4.4.10 表格
//! （errorCode 与 Claude Code 2.1.144 同号 0-12）。
//!
//! 注意：edits-worktree 快照（§4.13）由 dispatcher 在 execute 前后包夹完成，
//! 不在本工具里——工具只负责"是否允许改 + 怎么改"。

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use async_trait::async_trait;
use common::{AppError, AppResult};
use serde_json::{json, Value};
use tokio::fs;

use super::Tool;
use crate::read_state::{EditPrecheck, ReadStateTracker};
use crate::workspace::Workspace;

const MAX_FILE_BYTES: u64 = 1024 * 1024 * 1024; // 1 GB，与 Claude Code 2.1.144 一致

pub struct EditTool {
    tracker: Option<Arc<ReadStateTracker>>,
}

impl EditTool {
    pub fn new(_workspace: Arc<Workspace>, tracker: Option<Arc<ReadStateTracker>>) -> Self {
        Self { tracker }
    }
}

#[async_trait]
impl Tool for EditTool {
    fn name(&self) -> &str {
        "Edit"
    }

    fn description(&self) -> &str {
        "对文件做精准字符串替换。\
         old_string 必须在文件中精确存在（含原始缩进；CRLF/LF 自动归一），\
         默认要求在文件内唯一——非唯一时请加更多上下文，或设 replace_all=true 替换全部出现。\
         old_string=\"\" 时视为创建新文件（new_string 作为完整内容；目标路径必须不存在或为空）。\
         编辑已有文件前必须先用 Read 读取该文件（避免盲改和过期写入）。\
         需要审批；路径必须在对话允许的路径范围内。"
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["file_path", "old_string", "new_string"],
            "properties": {
                "file_path": {
                    "type": "string",
                    "description": "文件绝对路径"
                },
                "old_string": {
                    "type": "string",
                    "description": "要被替换的原文，含原始缩进。\"\" 时视为创建新文件。"
                },
                "new_string": {
                    "type": "string",
                    "description": "替换后的新文本。"
                },
                "replace_all": {
                    "type": "boolean",
                    "default": false,
                    "description": "true 时替换文件中所有出现；false 时要求 old_string 在文件中唯一。"
                }
            }
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let file_path_str = input["file_path"]
            .as_str()
            .ok_or_else(|| AppError::msg("Edit: 缺少 file_path"))?;
        let old_string = input["old_string"]
            .as_str()
            .ok_or_else(|| AppError::msg("Edit: 缺少 old_string"))?;
        let new_string = input["new_string"]
            .as_str()
            .ok_or_else(|| AppError::msg("Edit: 缺少 new_string"))?;
        let replace_all = input
            .get("replace_all")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);

        // 路径越界由 dispatcher 兜底（架构 §4.4.2），这里不重复

        // ── Step 3: old_string == new_string（架构 §4.4.10 errorCode 1）
        if old_string == new_string {
            return Err(AppError::msg(
                "Edit: 没有变化——old_string 与 new_string 完全一致",
            ));
        }

        let file_path = PathBuf::from(file_path_str);

        // ── Step 7: .ipynb（errorCode 5）
        if file_path.extension().and_then(|e| e.to_str()) == Some("ipynb") {
            return Err(AppError::msg(
                "Edit: Jupyter Notebook 暂不支持，请改用 Read+Bash 的 jq/jupyter 命令操作单元格",
            ));
        }

        // ── old_string == "" 分支：创建新文件
        if old_string.is_empty() {
            return self
                .execute_create(&file_path, file_path_str, new_string)
                .await;
        }

        // ── 修改路径
        let exists = fs::try_exists(&file_path).await.unwrap_or(false);
        if !exists {
            return Err(AppError::msg(format!(
                "Edit: 文件不存在 {file_path_str}。要创建新文件请用 old_string=\"\""
            )));
        }

        let meta = fs::metadata(&file_path)
            .await
            .map_err(|e| AppError::msg(format!("Edit: 读取元数据失败 {file_path_str}: {e}")))?;

        // ── Step 5: 1GB 上限（errorCode 10）
        if meta.len() > MAX_FILE_BYTES {
            return Err(AppError::msg(format!(
                "Edit: 文件过大 ({} 字节)，上限 1GB",
                meta.len()
            )));
        }
        // ── Step 6: 不是目录 / 特殊类型（errorCode 11）
        if meta.is_dir() {
            return Err(AppError::msg(format!(
                "Edit: {file_path_str} 是目录，不是文件"
            )));
        }

        let current_mtime_ms = meta
            .modified()
            .ok()
            .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
            .map(|d| d.as_millis() as i64)
            .unwrap_or(0);

        // ── Step 8 + 9: ReadStateTracker 强约束（errorCode 6 / 7）
        if let Some(tracker) = self.tracker.as_ref() {
            match tracker.precheck(&file_path, current_mtime_ms) {
                EditPrecheck::NotRead => {
                    return Err(AppError::msg(format!(
                        "Edit: 文件尚未读取——先用 Read 工具读取 {file_path_str} 后再编辑"
                    )));
                }
                EditPrecheck::Stale => {
                    return Err(AppError::msg(format!(
                        "Edit: 文件 {file_path_str} 在读取后被外部修改（用户 / linter / 其他工具），请重新 Read 后再编辑"
                    )));
                }
                EditPrecheck::Fresh => {}
            }
        }

        let content = fs::read_to_string(&file_path)
            .await
            .map_err(|e| AppError::msg(format!("Edit: 读取失败 {file_path_str}: {e}")))?;

        // ── Step 10: 查找 + CRLF 归一化 + Unicode escape 容错（errorCode 8）
        let normalized_content = content.replace("\r\n", "\n");
        let normalized_old = old_string.replace("\r\n", "\n");

        let (actual_old, match_count) = match find_matches(&normalized_content, &normalized_old) {
            Some(c) => (normalized_old.clone(), c),
            None => match swap_unicode_escapes(&normalized_old) {
                Some(swapped) => match find_matches(&normalized_content, &swapped) {
                    Some(c) => (swapped, c),
                    None => {
                        return Err(AppError::msg(
                            "Edit: 文件中找不到 old_string（已尝试 \\uXXXX 转义/反转义两种形式都不匹配）。请重新 Read 并复制确切的上下文。",
                        ));
                    }
                },
                None => {
                    return Err(AppError::msg(
                        "Edit: 文件中找不到 old_string。请重新 Read 并复制确切的上下文。",
                    ));
                }
            },
        };

        // ── Step 11: 唯一性（errorCode 9）
        if match_count > 1 && !replace_all {
            return Err(AppError::msg(format!(
                "Edit: 匹配到 {match_count} 处，但 replace_all=false。请加更多上下文以唯一定位，或设 replace_all=true。"
            )));
        }

        // ── 执行替换
        let new_content = if replace_all {
            normalized_content.replace(&actual_old, new_string)
        } else {
            normalized_content.replacen(&actual_old, new_string, 1)
        };

        let original_bytes = content.len();
        let new_bytes = new_content.len();

        fs::write(&file_path, &new_content)
            .await
            .map_err(|e| AppError::msg(format!("Edit: 写入失败 {file_path_str}: {e}")))?;

        // 写后立刻更新 tracker：再次写盘的 mtime 必须 = 当前 mtime
        if let Some(tracker) = self.tracker.as_ref() {
            let mtime_ms = current_disk_mtime(&file_path).await;
            tracker.record(&file_path, hash_bytes(new_content.as_bytes()), mtime_ms);
        }

        if replace_all && match_count > 1 {
            Ok(format!(
                "已修改文件 {file_path_str}（替换 {match_count} 处，{original_bytes} → {new_bytes} 字节）"
            ))
        } else {
            Ok(format!(
                "已修改文件 {file_path_str}（{original_bytes} → {new_bytes} 字节）"
            ))
        }
    }
}

impl EditTool {
    /// `old_string == ""` 分支：创建新文件（errorCode 3）。
    async fn execute_create(
        &self,
        file_path: &Path,
        file_path_str: &str,
        new_string: &str,
    ) -> AppResult<String> {
        let exists = fs::try_exists(file_path).await.unwrap_or(false);
        if exists {
            let existing = fs::read_to_string(file_path)
                .await
                .unwrap_or_else(|_| String::new());
            if !existing.trim().is_empty() {
                return Err(AppError::msg(format!(
                    "Edit: 无法创建——文件已存在且非空 {file_path_str}。如要全量覆盖，请先 Read 再 Edit（old_string=完整旧内容）"
                )));
            }
        }

        if let Some(parent) = file_path.parent() {
            fs::create_dir_all(parent)
                .await
                .map_err(|e| AppError::msg(format!("Edit: 创建父目录失败 {e}")))?;
        }

        fs::write(file_path, new_string)
            .await
            .map_err(|e| AppError::msg(format!("Edit: 写入失败 {file_path_str}: {e}")))?;

        if let Some(tracker) = self.tracker.as_ref() {
            let mtime_ms = current_disk_mtime(file_path).await;
            tracker.record(file_path, hash_bytes(new_string.as_bytes()), mtime_ms);
        }

        Ok(format!(
            "已创建文件 {file_path_str}（{} 字节，{} 行）",
            new_string.len(),
            new_string.lines().count()
        ))
    }
}

/// 返回 `needle` 在 `haystack` 中的出现次数。0 次返回 None，便于上层走容错分支。
fn find_matches(haystack: &str, needle: &str) -> Option<usize> {
    if needle.is_empty() {
        return None;
    }
    let count = haystack.matches(needle).count();
    if count == 0 {
        None
    } else {
        Some(count)
    }
}

/// 把 `\uXXXX` 字面形式转换为真实 Unicode 字符。
/// 返回 `Some(swapped)` 当且仅当至少完成一次有效转换，否则 `None`。
fn swap_unicode_escapes(s: &str) -> Option<String> {
    if !s.contains("\\u") {
        return None;
    }
    let bytes = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let mut changed = false;
    while i < bytes.len() {
        if bytes[i] == b'\\' && i + 5 < bytes.len() && bytes[i + 1] == b'u' {
            let hex = &s[i + 2..i + 6];
            if hex.chars().all(|c| c.is_ascii_hexdigit()) {
                if let Ok(code) = u32::from_str_radix(hex, 16) {
                    if let Some(ch) = char::from_u32(code) {
                        out.push(ch);
                        i += 6;
                        changed = true;
                        continue;
                    }
                }
            }
        }
        // 取一个 UTF-8 字符
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    if changed {
        Some(out)
    } else {
        None
    }
}

fn hash_bytes(bytes: &[u8]) -> u64 {
    let mut hasher = DefaultHasher::new();
    bytes.hash(&mut hasher);
    hasher.finish()
}

async fn current_disk_mtime(path: &Path) -> i64 {
    fs::metadata(path)
        .await
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::time::{sleep, Duration};

    fn workspace_at(path: &std::path::Path) -> Arc<Workspace> {
        Workspace::new(path, Vec::new())
    }

    fn tool_with_tracker() -> (Arc<ReadStateTracker>, tempfile::TempDir, EditTool) {
        let tmp = tempfile::tempdir().unwrap();
        let tracker = Arc::new(ReadStateTracker::new());
        let tool = EditTool::new(workspace_at(tmp.path()), Some(tracker.clone()));
        (tracker, tmp, tool)
    }

    #[tokio::test]
    async fn create_new_file_when_old_string_empty() {
        let (_tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("nested/dir/out.txt");
        let result = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "",
                "new_string": "hello",
            }))
            .await
            .unwrap();
        assert!(result.contains("创建"));
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "hello");
    }

    #[tokio::test]
    async fn create_rejects_existing_nonempty_file() {
        let (_tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "old content").unwrap();

        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "",
                "new_string": "new",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("文件已存在且非空"));
    }

    #[tokio::test]
    async fn modify_rejects_unread_file() {
        let (_tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "abc").unwrap();

        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "abc",
                "new_string": "xyz",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("尚未读取"));
    }

    #[tokio::test]
    async fn modify_rejects_stale_file() {
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "abc").unwrap();

        // 模拟"已读"但时戳早于当前 mtime
        tracker.record(&target, 0, 0);

        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "abc",
                "new_string": "xyz",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("外部修改"));
    }

    #[tokio::test]
    async fn modify_succeeds_when_fresh_and_unique() {
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "hello world").unwrap();

        // 注册"已读"且 mtime ≥ 当前 mtime
        let mtime = current_disk_mtime(&target).await;
        tracker.record(&target, 0, mtime);

        let result = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "world",
                "new_string": "rust",
            }))
            .await
            .unwrap();
        assert!(result.contains("已修改"));
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "hello rust");
    }

    #[tokio::test]
    async fn rejects_non_unique_old_string_without_replace_all() {
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "ab ab ab").unwrap();
        tracker.record(&target, 0, current_disk_mtime(&target).await);

        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "ab",
                "new_string": "cd",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("匹配到 3 处"));
    }

    #[tokio::test]
    async fn replace_all_replaces_every_occurrence() {
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "ab ab ab").unwrap();
        tracker.record(&target, 0, current_disk_mtime(&target).await);

        let result = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "ab",
                "new_string": "cd",
                "replace_all": true,
            }))
            .await
            .unwrap();
        assert!(result.contains("替换 3 处"));
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "cd cd cd");
    }

    #[tokio::test]
    async fn crlf_lf_normalized_match() {
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "line1\r\nline2\r\nline3").unwrap();
        tracker.record(&target, 0, current_disk_mtime(&target).await);

        // old_string 用 LF 也应该能匹配 CRLF 文件
        let result = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "line1\nline2",
                "new_string": "L1\nL2",
            }))
            .await
            .unwrap();
        assert!(result.contains("已修改"));
    }

    #[tokio::test]
    async fn unicode_escape_swap_matches() {
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "前缀: \u{4e2d}\u{6587}后缀").unwrap();
        tracker.record(&target, 0, current_disk_mtime(&target).await);

        // old_string 用 \uXXXX 字面形式，文件里是真实字符
        let result = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "\\u4e2d\\u6587",
                "new_string": "中文OK",
            }))
            .await;
        // 至少不能因"找不到"而失败；如果实现得对，应当替换成功
        let result = result.unwrap();
        assert!(result.contains("已修改"));
    }

    #[tokio::test]
    async fn rejects_old_equals_new() {
        let (_tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "abc").unwrap();
        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "abc",
                "new_string": "abc",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("没有变化"));
    }

    #[tokio::test]
    async fn rejects_ipynb_files() {
        let (_tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.ipynb");
        // 不需要真的创建文件——.ipynb 检查在 path 解析阶段
        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "x",
                "new_string": "y",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("Jupyter Notebook"));
    }

    #[tokio::test]
    async fn rejects_modify_missing_file() {
        let (_tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("nope.txt");
        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "x",
                "new_string": "y",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("文件不存在"));
    }

    #[tokio::test]
    async fn precheck_detects_external_modification_between_read_and_edit() {
        // 完整端到端：模拟 Read 之后用户改了文件，Edit 必须拒绝
        let (tracker, tmp, tool) = tool_with_tracker();
        let target = tmp.path().join("a.txt");
        std::fs::write(&target, "v1").unwrap();
        let initial_mtime = current_disk_mtime(&target).await;
        tracker.record(&target, 0, initial_mtime);

        // 等 fs 时钟跨毫秒，再外部写一次
        sleep(Duration::from_millis(20)).await;
        std::fs::write(&target, "v1-modified-externally").unwrap();

        let err = tool
            .execute(json!({
                "file_path": target.to_string_lossy(),
                "old_string": "v1",
                "new_string": "v2",
            }))
            .await
            .unwrap_err();
        assert!(err.to_string().contains("外部修改"));
    }
}

crates/agent-core/src/tools/exit_plan_mo.content:
//! ExitPlanMode：PlanMode 下唯一退出途径（架构 §4.4.5）。
//!
//! agent 在 PlanMode 调研完成后调用此工具，把最终 plan markdown 作为输入提交。
//! 真正的行为（落盘 / emit `PlanReady` / 发起 HITL 审批 / 切回 pre_plan_mode /
//! 拼未消费的 plan_comments）由 [`crate::dispatch::ToolDispatcher`] 的
//! short-circuit 分支处理——它持有 `data_dir + session_id + hitl + sink` 上下文，
//! 而 [`Tool`] trait 不带这些。
//!
//! 本文件只剩 Tool trait 实现（schema 给模型看），`execute` 走兜底返回汇总字符串，
//! 实际不会被 dispatcher 调到。

use async_trait::async_trait;
use serde::Deserialize;
use serde_json::Value;

use common::{AppError, AppResult};

use crate::tools::Tool;

pub const EXIT_PLAN_MODE_TOOL_NAME: &str = "ExitPlanMode";

#[derive(Debug, Deserialize)]
pub struct ExitPlanInput {
    pub plan_markdown: String,
    /// 一句话摘要，UI 列表 / 通知用。可空。
    #[serde(default)]
    pub summary: String,
}

pub struct ExitPlanModeTool;

#[async_trait]
impl Tool for ExitPlanModeTool {
    fn name(&self) -> &str {
        EXIT_PLAN_MODE_TOOL_NAME
    }

    fn description(&self) -> &str {
        "Exit PlanMode by submitting the final plan as markdown for user approval. \
         Call this only after read-only investigation is complete and you have a \
         concrete plan. The user will be shown the plan and asked to approve, edit, \
         or reject (with feedback). On approval, run mode switches back to the \
         pre-PlanMode mode and you may proceed with implementation. On rejection, \
         use the feedback to revise and call ExitPlanMode again. \
         Required field `plan_markdown` should be structured (Scope, Steps, \
         Affected files, Risks). Optional `summary` is a one-line headline."
    }

    fn parameters_schema(&self) -> Value {
        serde_json::json!({
            "type": "object",
            "required": ["plan_markdown"],
            "properties": {
                "plan_markdown": {
                    "type": "string",
                    "description": "Markdown formatted plan. Include sections: Scope, Steps, Affected files, Risks."
                },
                "summary": {
                    "type": "string",
                    "description": "Optional one-line summary for the approval popup title."
                }
            }
        })
    }

    /// 兜底实现：当 dispatcher 没走 short-circuit（理论上不该发生）时返回错误。
    /// 真正的逻辑见 [`crate::dispatch::ToolDispatcher::spawn_exit_plan_mode`]。
    async fn execute(&self, _input: Value) -> AppResult<String> {
        Err(AppError::msg(
            "ExitPlanMode 必须由 dispatcher short-circuit 处理；走到 Tool::execute 说明 dispatch 路径有 bug",
        ))
    }
}

/// 解析模型传入的 input。供 dispatcher short-circuit 复用。
pub fn parse_input(input: Value) -> AppResult<ExitPlanInput> {
    serde_json::from_value::<ExitPlanInput>(input)
        .map_err(|e| AppError::msg(format!("invalid ExitPlanMode input: {e}")))
}

/// 从 plan 文件绝对路径生成 plan_id（取 file stem，如 `plan-20260525143012`）。
pub fn plan_id_from_path(path: &std::path::Path) -> String {
    path.file_stem()
        .and_then(|s| s.to_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| "plan-unknown".to_string())
}

crates/agent-core/src/tools/grep.rs.content:
//! Grep 工具：基于 ripgrep 同源 crates 在 workspace 范围内搜索文件内容。
//!
//! - read-only：默认 auto-approve
//! - 默认搜 workdir；可指定 `path`，但必须落在 workspace 内
//! - 默认 `files_with_matches` 模式；`output_mode: "content"` 显示匹配行

use std::collections::HashMap;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use async_trait::async_trait;
use common::{AppError, AppResult};
use grep_regex::RegexMatcherBuilder;
use grep_searcher::{sinks::Lossy, BinaryDetection, MmapChoice, SearcherBuilder};
use ignore::{
    overrides::OverrideBuilder,
    types::{Types, TypesBuilder},
    WalkBuilder,
};
use serde_json::{json, Value};
use tokio::time;

use super::Tool;
use crate::workspace::Workspace;

const MAX_OUTPUT_BYTES: usize = 30_000;
const TIMEOUT: Duration = Duration::from_secs(30);
const DEFAULT_EXCLUDE_GLOBS: &[&str] = &["!.git", "!.svn", "!.hg", "!node_modules", "!target"];

pub struct GrepTool {
    workspace: Arc<Workspace>,
}

impl GrepTool {
    pub fn new(workspace: Arc<Workspace>) -> Self {
        Self { workspace }
    }
}

#[async_trait]
impl Tool for GrepTool {
    fn name(&self) -> &str {
        "Grep"
    }

    fn description(&self) -> &str {
        "用 ripgrep 在文件内容中搜索正则。默认搜对话的 workdir。\
         output_mode 默认 \"files_with_matches\"，可选 \"content\" 显示匹配行（带行号）\
         或 \"count\" 显示每个文件的命中次数。\
         glob 用于按文件名过滤；type 用于按语言过滤（如 rust/py/ts）。\
         path 必须在对话允许的路径范围内。"
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["pattern"],
            "properties": {
                "pattern": {
                    "type": "string",
                    "description": "正则模式（ripgrep 语法）"
                },
                "path": {
                    "type": "string",
                    "description": "搜索路径（绝对路径）。不传则用对话 workdir。"
                },
                "glob": {
                    "type": "string",
                    "description": "文件名 glob，比如 \"*.rs\" 或 \"*.{ts,tsx}\""
                },
                "type": {
                    "type": "string",
                    "description": "ripgrep 语言类型，比如 rust / py / ts / go / js"
                },
                "output_mode": {
                    "type": "string",
                    "enum": ["files_with_matches", "content", "count"],
                    "description": "默认 files_with_matches"
                },
                "case_insensitive": {
                    "type": "boolean",
                    "description": "忽略大小写。默认 false。"
                },
                "head_limit": {
                    "type": "integer",
                    "minimum": 1,
                    "description": "限制输出前 N 行。默认 200。"
                }
            }
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let pattern = input["pattern"]
            .as_str()
            .ok_or_else(|| AppError::msg("Grep: 缺少 pattern"))?;

        let path = match input["path"].as_str().filter(|s| !s.is_empty()) {
            // 越界检查在 agent_loop 统一做
            Some(p) => PathBuf::from(p),
            None => self.workspace.workdir().to_path_buf(),
        };

        let mode = input["output_mode"]
            .as_str()
            .unwrap_or("files_with_matches");
        let case_insensitive = input["case_insensitive"].as_bool().unwrap_or(false);
        let head_limit = input["head_limit"].as_u64().unwrap_or(200) as usize;

        match mode {
            "files_with_matches" | "count" | "content" => {}
            other => return Err(AppError::msg(format!("Grep: 无效的 output_mode {other}"))),
        }

        let glob = input["glob"]
            .as_str()
            .filter(|s| !s.is_empty())
            .map(str::to_string);
        let file_type = input["type"]
            .as_str()
            .filter(|s| !s.is_empty())
            .map(str::to_string);

        let search = SearchRequest {
            path,
            mode: mode.to_string(),
            pattern: pattern.to_string(),
            case_insensitive,
            glob,
            file_type,
        };
        let lines = match time::timeout(
            TIMEOUT,
            tokio::task::spawn_blocking(move || run_search(search)),
        )
        .await
        {
            Ok(Ok(result)) => result?,
            Ok(Err(e)) => return Err(AppError::msg(format!("Grep: 搜索任务失败 {e}"))),
            Err(_) => return Err(AppError::msg("Grep: 搜索超时（30s）")),
        };

        if lines.is_empty() {
            return Ok("(无匹配)".into());
        }
        let total = lines.len();
        let kept: Vec<&str> = lines.iter().map(String::as_str).take(head_limit).collect();
        let mut result = kept.join("\n");
        if total > head_limit {
            result.push_str(&format!(
                "\n…（共 {total} 行，已截到前 {head_limit} 行；调高 head_limit 看更多）"
            ));
        }
        Ok(truncate_bytes(&result, MAX_OUTPUT_BYTES))
    }
}

struct SearchRequest {
    path: PathBuf,
    mode: String,
    pattern: String,
    case_insensitive: bool,
    glob: Option<String>,
    file_type: Option<String>,
}

fn run_search(request: SearchRequest) -> AppResult<Vec<String>> {
    let mut lines = Vec::new();
    let display_root = if request.path.is_file() {
        request
            .path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| request.path.clone())
    } else {
        request.path.clone()
    };
    let matcher = RegexMatcherBuilder::new()
        .case_insensitive(request.case_insensitive)
        .multi_line(false)
        .line_terminator(Some(b'\n'))
        .build(&request.pattern)
        .map_err(|e| AppError::msg(format!("Grep: 无效的正则 {e}")))?;
    let mut walker = WalkBuilder::new(&request.path);
    walker
        .hidden(false)
        .require_git(false)
        .follow_links(false)
        .overrides(build_overrides(&display_root, request.glob.as_deref())?);
    if let Some(types) = build_types(request.file_type.as_deref())? {
        walker.types(types);
    }
    let mut searcher = SearcherBuilder::new()
        .line_number(true)
        .memory_map(mmap_choice())
        .binary_detection(BinaryDetection::quit(b'\x00'))
        .build();

    for entry in walker.build() {
        let entry = match entry {
            Ok(entry) => entry,
            Err(err) => {
                tracing::debug!("Grep: skip unreadable entry: {err}");
                continue;
            }
        };
        if !entry.file_type().is_some_and(|ty| ty.is_file()) {
            continue;
        }
        let path = entry.path();
        let rel = display_path(path, &display_root);
        match request.mode.as_str() {
            "files_with_matches" => {
                let mut matched = false;
                searcher
                    .search_path(
                        &matcher,
                        path,
                        Lossy(|_, _| {
                            matched = true;
                            Ok(false)
                        }),
                    )
                    .map_err(grep_io_error)?;
                if matched {
                    lines.push(rel);
                }
            }
            "count" => {
                let mut count = 0usize;
                searcher
                    .search_path(
                        &matcher,
                        path,
                        Lossy(|_, _| {
                            count += 1;
                            Ok(true)
                        }),
                    )
                    .map_err(grep_io_error)?;
                if count > 0 {
                    lines.push(format!("{rel}:{count}"));
                }
            }
            "content" => {
                searcher
                    .search_path(
                        &matcher,
                        path,
                        Lossy(|line_number, line| {
                            lines.push(format!(
                                "{rel}:{line_number}:{}",
                                line.trim_end_matches('\n')
                            ));
                            Ok(true)
                        }),
                    )
                    .map_err(grep_io_error)?;
            }
            _ => unreachable!("mode was validated before search"),
        }
    }

    Ok(lines)
}

fn grep_io_error(err: io::Error) -> AppError {
    AppError::msg(format!("Grep: 搜索失败 {err}"))
}

fn mmap_choice() -> MmapChoice {
    #[cfg(target_os = "macos")]
    {
        MmapChoice::never()
    }
    #[cfg(not(target_os = "macos"))]
    {
        // SAFETY: Matches ripgrep's performance-oriented search strategy. The
        // searcher only maps regular files selected by the ignore walker, and
        // falls back to normal reads when mmap is not appropriate.
        unsafe { MmapChoice::auto() }
    }
}

fn build_overrides(root: &Path, glob: Option<&str>) -> AppResult<ignore::overrides::Override> {
    let mut builder = OverrideBuilder::new(root);
    for glob in DEFAULT_EXCLUDE_GLOBS {
        builder
            .add(glob)
            .map_err(|e| AppError::msg(format!("Grep: 无效的默认排除 glob {glob}: {e}")))?;
    }
    if let Some(glob) = glob {
        builder
            .add(glob)
            .map_err(|e| AppError::msg(format!("Grep: 无效的 glob {glob}: {e}")))?;
    }
    builder
        .build()
        .map_err(|e| AppError::msg(format!("Grep: 无效的 glob 配置 {e}")))
}

fn build_types(file_type: Option<&str>) -> AppResult<Option<Types>> {
    let Some(file_type) = file_type else {
        return Ok(None);
    };
    let mut builder = TypesBuilder::new();
    builder.add_defaults();
    for (name, glob) in extra_type_defs() {
        builder
            .add(name, glob)
            .map_err(|e| AppError::msg(format!("Grep: 内置 type 定义失败 {name}:{glob}: {e}")))?;
    }
    builder.select(file_type);
    builder
        .build()
        .map(Some)
        .map_err(|e| AppError::msg(format!("Grep: 无效的 type {file_type}: {e}")))
}

fn extra_type_defs() -> HashMap<&'static str, &'static str> {
    HashMap::from([
        ("rs", "*.rs"),
        ("py", "*.py"),
        ("ts", "*.ts"),
        ("tsx", "*.tsx"),
        ("js", "*.js"),
        ("javascript", "*.{js,jsx,mjs,cjs}"),
        ("md", "*.{md,markdown}"),
        ("yml", "*.{yaml,yml}"),
    ])
}

fn display_path(path: &Path, root: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .to_string_lossy()
        .into_owned()
}

fn truncate_bytes(s: &str, limit: usize) -> String {
    if s.len() <= limit {
        return s.to_string();
    }
    let mut end = limit;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}\n…[已截断，共 {} 字节]", &s[..end], s.len())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    fn workspace_at(path: &std::path::Path) -> Arc<Workspace> {
        Workspace::new(path, Vec::new())
    }

    #[tokio::test]
    async fn finds_matching_files() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("a.txt"), "hello world").unwrap();
        std::fs::write(tmp.path().join("b.txt"), "nothing here").unwrap();

        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool.execute(json!({"pattern": "hello"})).await.unwrap();
        assert!(out.contains("a.txt"));
        assert!(!out.contains("b.txt"));
    }

    #[tokio::test]
    async fn content_mode_includes_line_numbers() {
        let tmp = tempfile::tempdir().unwrap();
        let mut f = std::fs::File::create(tmp.path().join("a.txt")).unwrap();
        writeln!(f, "first").unwrap();
        writeln!(f, "needle here").unwrap();
        writeln!(f, "third").unwrap();

        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool
            .execute(json!({
                "pattern": "needle",
                "output_mode": "content",
            }))
            .await
            .unwrap();
        assert!(out.contains("2:needle here"));
    }

    #[tokio::test]
    async fn no_matches_returns_friendly_message() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("a.txt"), "abc").unwrap();
        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool.execute(json!({"pattern": "xyzunique"})).await.unwrap();
        assert!(out.contains("无匹配"));
    }

    #[tokio::test]
    async fn filters_by_type_and_brace_glob() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("a.ts"), "needle").unwrap();
        std::fs::write(tmp.path().join("b.tsx"), "needle").unwrap();
        std::fs::write(tmp.path().join("c.js"), "needle").unwrap();
        std::fs::write(tmp.path().join("d.txt"), "needle").unwrap();

        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool
            .execute(json!({
                "pattern": "needle",
                "glob": "*.{ts,tsx}",
                "type": "ts",
            }))
            .await
            .unwrap();

        assert!(out.contains("a.ts"));
        assert!(out.contains("b.tsx"));
        assert!(!out.contains("c.js"));
        assert!(!out.contains("d.txt"));
    }

    #[tokio::test]
    async fn count_mode_counts_matches_per_file() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("a.txt"), "needle\nneedle\nother").unwrap();
        std::fs::write(tmp.path().join("b.txt"), "needle").unwrap();

        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool
            .execute(json!({
                "pattern": "needle",
                "output_mode": "count",
            }))
            .await
            .unwrap();

        assert!(out.contains("a.txt:2"));
        assert!(out.contains("b.txt:1"));
    }

    #[tokio::test]
    async fn respects_gitignore_like_ripgrep() {
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join(".gitignore"), "ignored.log\n").unwrap();
        std::fs::write(tmp.path().join("kept.txt"), "needle").unwrap();
        std::fs::write(tmp.path().join("ignored.log"), "needle").unwrap();

        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool.execute(json!({"pattern": "needle"})).await.unwrap();

        assert!(out.contains("kept.txt"));
        assert!(!out.contains("ignored.log"));
    }

    #[tokio::test]
    async fn does_not_require_rg_on_path() {
        if std::env::var_os("HEBBIAN_GREP_EMPTY_PATH_CHILD").is_none() {
            let bin = tempfile::tempdir().unwrap();
            let output = std::process::Command::new(std::env::current_exe().unwrap())
                .arg("--exact")
                .arg("tools::grep::tests::does_not_require_rg_on_path")
                .arg("--nocapture")
                .env("PATH", bin.path())
                .env("HEBBIAN_GREP_EMPTY_PATH_CHILD", "1")
                .output()
                .unwrap();

            assert!(
                output.status.success(),
                "child test failed\nstdout:\n{}\nstderr:\n{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            return;
        }

        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("a.txt"), "hello from rust grep").unwrap();

        let tool = GrepTool::new(workspace_at(tmp.path()));
        let out = tool.execute(json!({"pattern": "rust grep"})).await.unwrap();
        assert!(out.contains("a.txt"));
    }
}

crates/agent-core/src/tools/hitl.rs.content:
//! HITL（Human-in-the-Loop）统一通道：审批 / 提问 / 路径越界 / 长 run 续跑共用一张
//! pending 表，按 `PermissionRequestId` 索引，用 oneshot waiter 解除挂起。
//!
//! 两种 pending 互不干扰：
//! - **审批**（[`HitlGate::check`] / [`HitlGate::open_approval`]）：用户回 [`ApprovalDecision`]
//! - **提问**（[`HitlGate::open_question`]）：用户回 [`UserAnswer`]
//!
//! Surface 端（CLI / Desktop / Server）只看到统一的 `request_id`，靠事件 payload 的
//! kind 字段判断该用审批 UI 还是提问 UI。
//!
//! ## 记忆粒度
//!
//! 审批被批准并选择"记住"时，按下面顺序生效：
//! - `pattern = Some(s)` → 记 `(tool_name, s)` 命令前缀对，下次同前缀直接放行
//! - `pattern = None` 且工具不在 [`NO_TOOL_LEVEL_MEMORY`] → 工具名级记忆（旧行为）
//! - `pattern = None` 且工具在 [`NO_TOOL_LEVEL_MEMORY`] → 不记忆（兜底为 `AllowOnce`）
//!
//! 前缀匹配按空白 token 边界（`fingerprint == prefix` 或 `fingerprint.starts_with(prefix + " ")`），
//! 避免 `"git statusbad"` 误中 `"git status"`。

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use protocol::{
    ApprovalDecision, ApprovalSegment, ApprovalSegmentStatus, PermissionRequestId, PermissionScope,
    UserAnswer,
};
use tokio::sync::oneshot;
use tracing::info;

use crate::definition::{DefaultPermission, PermissionPolicy};
use crate::effects::{EffectClass, Effects};
use crate::permissions::{PermissionMatch, PermissionStore, RuleEffect};

/// 单次工具调用的权限决策结果。
#[derive(Debug)]
pub enum PermissionDecision {
    /// 自动批准，直接执行。
    Approved,
    /// 被策略拒绝，不执行。
    Denied { reason: String },
    /// 需要用户交互确认。waiter 在用户回应后被 resolve。
    NeedsApproval {
        request_id: PermissionRequestId,
        waiter: oneshot::Receiver<ApprovalDecision>,
    },
}

/// 内部 pending 条目：审批与提问共用一张表。
enum Pending {
    Approval {
        sender: oneshot::Sender<ApprovalDecision>,
        /// resolve 时若 decision = AllowAndRemember 用来定位记忆条目。
        /// 路径越界审批走 `open_approval(None, None)` 不写 learned 表。
        tool_name: Option<String>,
        fingerprint: Option<String>,
        effects: Option<Effects>,
        /// 危险复合模式（架构 §4.4.2.2）触发的审批：resolve 时即使收到
        /// AllowAndRemember 也**不**落 learned 表 / PermissionStore——cd-git-compound
        /// 这类不可信复合不该一键放行同类后续命令。
        refuse_remember: bool,
    },
    Question(oneshot::Sender<UserAnswer>),
}

/// 累计的会话级 "Allow & Remember" 规则。
#[derive(Debug, Clone, Default)]
struct LearnedRules {
    /// 工具名级允许（旧行为）。
    auto_approved_tools: Vec<String>,
    /// 命令前缀级允许：`(tool_name, prefix)`，按空白 token 边界匹配。
    auto_approved_patterns: Vec<(String, String)>,
    /// 工具名级永久拒绝。
    auto_denied_tools: Vec<String>,
}

/// 不允许做工具名级记忆的工具：粒度太粗会引入安全 bug。
///
/// 示例：用户对 `ls` 选了 "AllowAndRemember"（`pattern=None`），若按工具名记忆
/// 则之后所有 Bash 调用（包括 `rm -rf /`）都会自动放行。这些工具应当走命令前缀级
/// 记忆（`pattern=Some(...)`），UI 应只暴露前缀按钮。
const NO_TOOL_LEVEL_MEMORY: &[&str] = &["Bash"];

fn scope_label(scope: PermissionScope) -> &'static str {
    match scope {
        PermissionScope::Once => "once",
        PermissionScope::Session => "session",
        PermissionScope::Project => "project",
        PermissionScope::Global => "global",
    }
}

fn decision_label(decision: &ApprovalDecision) -> &'static str {
    match decision {
        ApprovalDecision::AllowOnce => "allow_once",
        ApprovalDecision::AllowAndRemember { .. } => "allow_and_remember",
        ApprovalDecision::Deny => "deny",
        ApprovalDecision::DenyWithFeedback { .. } => "deny_with_feedback",
    }
}

fn store_effect_label(effect: RuleEffect) -> &'static str {
    match effect {
        RuleEffect::Allow => "allow",
        RuleEffect::Deny => "deny",
    }
}

fn log_store_hit(tool_name: &str, hit: &PermissionMatch) {
    info!(
        target: "permission",
        tool = %tool_name,
        matched = true,
        level = scope_label(hit.scope),
        effect = store_effect_label(hit.effect),
        pattern = %hit.pattern,
        "[Permission:Match] PermissionStore rule matched"
    );
}

/// HITL 统一闸门。
///
/// `permission_store` + `session_id` + `workdir` 可选：当 surface 启动 PermissionStore
/// 时挂上来，resolve 时把 AllowAndRemember(Session/Project/Global) 翻成
/// [`PermissionRule`] 落盘。`workdir` 仅 `Project` scope 必填（架构 §4.5.4）。
/// 不挂时仅在 in-memory `learned` 表里记忆（保留旧行为）。
pub struct HitlGate {
    policy: PermissionPolicy,
    pending: Mutex<HashMap<PermissionRequestId, Pending>>,
    learned: Mutex<LearnedRules>,
    permission_store: Option<Arc<PermissionStore>>,
    session_id: Option<String>,
    workdir: Option<PathBuf>,
}

impl HitlGate {
    pub fn new(policy: PermissionPolicy) -> Self {
        Self {
            policy,
            pending: Mutex::new(HashMap::new()),
            learned: Mutex::new(LearnedRules::default()),
            permission_store: None,
            session_id: None,
            workdir: None,
        }
    }

    /// 挂上 PermissionStore + 当前 session_id + workdir，让 AllowAndRemember 真正落盘。
    /// `workdir` 用于 `PermissionScope::Project` 规则（架构 §4.5.4）。
    pub fn with_store(
        mut self,
        store: Arc<PermissionStore>,
        session_id: impl Into<String>,
        workdir: Option<PathBuf>,
    ) -> Self {
        self.permission_store = Some(store);
        self.session_id = Some(session_id.into());
        self.workdir = workdir;
        self
    }

    /// 共享的 PermissionStore（用于 dispatcher 级别的路径越界检查也纳入全局规则）。
    pub fn permission_store(&self) -> Option<&Arc<PermissionStore>> {
        self.permission_store.as_ref()
    }

    /// 评估一次工具调用：依 effects 默认行为 + 用户累计规则 + 策略规则三层判断。
    ///
    /// `effects` 由 [`crate::effects::analyze_effects`] 解析得到（架构 §4.4.2）。
    /// 其中 `command_fingerprint` 用于命令级记忆——支持的工具（Bash/PowerShell）
    /// 优先按前缀匹配；其它工具退回工具名级判断。
    ///
    /// 返回 `NeedsApproval` 时，调用方应：
    /// 1. emit `PermissionRequested` 事件（用 request_id）
    /// 2. await waiter
    /// 3. 收到 `ApprovalDecision` 后决定是否执行
    pub fn check(&self, tool_name: &str, effects: &Effects) -> PermissionDecision {
        let fingerprint = effects.command_fingerprint.as_deref();

        if let Some(decision) = self.check_without_policy(tool_name, effects) {
            return decision;
        }

        // 6) 静态策略按名命中
        if self.policy.auto_approve.iter().any(|n| n == tool_name) {
            info!(
                target: "permission",
                tool = %tool_name,
                matched = true,
                level = "policy",
                "[Permission:Match] policy.auto_approve → Approved"
            );
            return PermissionDecision::Approved;
        }
        if self.policy.always_ask.iter().any(|n| n == tool_name) {
            info!(
                target: "permission",
                tool = %tool_name,
                matched = false,
                level = "policy",
                result = "waiting_for_approval",
                "[Permission:Match] policy.always_ask → waiting for approval"
            );
            return self.needs_approval(tool_name, fingerprint, effects);
        }

        // 7) 按 effects 默认行为
        let decision = match effects.class {
            EffectClass::Network | EffectClass::Mutating | EffectClass::Destructive => {
                match self.policy.default_action {
                    DefaultPermission::Auto => {
                        info!(
                            target: "permission",
                            tool = %tool_name,
                            class = ?effects.class,
                            matched = true,
                            level = "policy",
                            "[Permission:Match] default_action=Auto → Approved"
                        );
                        PermissionDecision::Approved
                    }
                    DefaultPermission::Ask => {
                        info!(
                            target: "permission",
                            tool = %tool_name,
                            class = ?effects.class,
                            matched = false,
                            level = "none",
                            result = "waiting_for_approval",
                            "[Permission:Match] no allow rule matched → waiting for approval"
                        );
                        self.needs_approval(tool_name, fingerprint, effects)
                    }
                    DefaultPermission::Deny => {
                        info!(
                            target: "permission",
                            tool = %tool_name,
                            class = ?effects.class,
                            matched = true,
                            level = "policy",
                            "[Permission:Match] default_action=Deny → Denied"
                        );
                        PermissionDecision::Denied {
                            reason: "策略默认拒绝".into(),
                        }
                    }
                }
            }
            EffectClass::ReadOnly | EffectClass::NeedsHumanInput => {
                unreachable!("已在前面分支短路")
            }
        };
        decision
    }

    fn check_without_policy(
        &self,
        tool_name: &str,
        effects: &Effects,
    ) -> Option<PermissionDecision> {
        let fingerprint = effects.command_fingerprint.as_deref();
        let has_segments = !effects.segments.is_empty();

        let fp_display = fingerprint.unwrap_or("");
        let class_label = match effects.class {
            EffectClass::ReadOnly => "ReadOnly",
            EffectClass::Mutating => "Mutating",
            EffectClass::Destructive => "Destructive",
            EffectClass::Network => "Network",
            EffectClass::NeedsHumanInput => "NeedsHumanInput",
        };

        // 1) NeedsHumanInput 不走审批（dispatcher 走 ask 路径）
        if matches!(effects.class, EffectClass::NeedsHumanInput) {
            info!(
                target: "permission",
                tool = %tool_name,
                matched = true,
                level = "ask_path",
                "[Permission:Match] NeedsHumanInput → Approved"
            );
            return Some(PermissionDecision::Approved);
        }

        // 2) 用户显式"永久拒绝"优先于一切
        {
            let learned = self.learned.lock().unwrap();
            if learned.auto_denied_tools.iter().any(|n| n == tool_name) {
                info!(
                    target: "permission",
                    tool = %tool_name,
                    matched = true,
                    level = "session_memory",
                    effect = "deny",
                    "[Permission:Match] auto_denied_tools → Denied"
                );
                return Some(PermissionDecision::Denied {
                    reason: "用户已永久拒绝该工具".into(),
                });
            }
        }

        // 3) 危险复合模式（架构 §4.4.2.2）：强制走人工审批，覆盖一切 allow 规则。
        if effects.has_dangerous_pattern() {
            info!(
                target: "permission",
                tool = %tool_name,
                kinds = ?effects.dangerous_kinds,
                matched = false,
                level = "dangerous_pattern",
                result = "waiting_for_approval",
                "[Permission:Match] dangerous pattern → waiting for approval"
            );
            return Some(self.needs_approval_no_remember(tool_name, fingerprint, effects));
        }

        // 4) ReadOnly 永远放行：effects 自报无副作用，always_ask 不该再拦。
        if matches!(effects.class, EffectClass::ReadOnly) {
            info!(
                target: "permission",
                tool = %tool_name,
                fingerprint = fp_display,
                matched = true,
                level = "read_only",
                "[Permission:Match] ReadOnly → Approved"
            );
            return Some(PermissionDecision::Approved);
        }

        // 4b) 不可记忆命令（rm/dd/mkfs/...，架构 §4.4.2.3）：任一会写段命中即强制审批。
        //     rm 段自身永远拿不到 allow 规则（弹窗不让勾、step 4b 又先于 store 检查短路），
        //     所以含 rm 的整条**每次都确认**。但**允许记忆同条里的良性段**（如
        //     `pnpm install && rm …` 里的 pnpm）——只是这条命令本身仍每次弹，记下的
        //     pnpm 惠及以后不含 rm 的命令。故走可记忆的 needs_approval（不再毒化整条）。
        if let Some(seg) = effects.segments.iter().find(|s| s.unmemorable) {
            info!(
                target: "permission",
                tool = %tool_name,
                segment = %seg.fingerprint,
                matched = false,
                level = "never_remember",
                result = "waiting_for_approval",
                "[Permission:Match] unmemorable segment → waiting for approval (benign segments still memorable)"
            );
            return Some(self.needs_approval(tool_name, fingerprint, effects));
        }

        // 5) 用户累计的"允许并记住"——Bash/PowerShell 走段级匹配，其它工具退回工具名级。
        {
            let learned = self.learned.lock().unwrap();
            let patterns_count = learned.auto_approved_patterns.len();
            let tools_count = learned.auto_approved_tools.len();
            if has_segments {
                let mut all_seg_allowed = true;
                for seg in &effects.segments {
                    // 只读段免匹配（架构 §4.4.2）：只要求会写段全部命中记忆。
                    if seg.is_readonly {
                        continue;
                    }
                    let seg_matched = learned.auto_approved_patterns.iter().any(|(t, prefix)| {
                        t == tool_name && fingerprint_matches(&seg.fingerprint, prefix)
                    });
                    if seg_matched {
                        info!(
                            target: "permission",
                            tool = %tool_name,
                            segment = %seg.fingerprint,
                            matched = true,
                            level = "session_memory",
                            "[Permission:Match] segment matched session learned pattern"
                        );
                    } else {
                        info!(
                            target: "permission",
                            tool = %tool_name,
                            segment = %seg.fingerprint,
                            patterns_count = patterns_count,
                            matched = false,
                            level = "session_memory",
                            "[Permission:Match] segment not matched in session learned patterns"
                        );
                        all_seg_allowed = false;
                    }
                }
                if all_seg_allowed {
                    info!(
                        target: "permission",
                        tool = %tool_name,
                        n_segments = effects.segments.len(),
                        matched = true,
                        level = "session_memory",
                        "[Permission:Match] all segments matched session learned patterns → Approved"
                    );
                    return Some(PermissionDecision::Approved);
                }
            } else if let Some(fp) = fingerprint {
                let pat_matched = learned
                    .auto_approved_patterns
                    .iter()
                    .any(|(t, prefix)| t == tool_name && fingerprint_matches(fp, prefix));
                if pat_matched {
                    info!(
                        target: "permission",
                        tool = %tool_name,
                        fingerprint = %fp,
                        matched = true,
                        level = "session_memory",
                        "[Permission:Match] fingerprint matched session learned pattern → Approved"
                    );
                    return Some(PermissionDecision::Approved);
                } else {
                    info!(
                        target: "permission",
                        tool = %tool_name,
                        fingerprint = %fp,
                        patterns_count = patterns_count,
                        matched = false,
                        level = "session_memory",
                        "[Permission:Match] fingerprint not matched in session learned patterns"
                    );
                }
            }
            let tool_matched = learned.auto_approved_tools.iter().any(|n| n == tool_name);
            if tool_matched {
                info!(
                    target: "permission",
                    tool = %tool_name,
                    matched = true,
                    level = "session_memory",
                    "[Permission:Match] tool-level session learned rule → Approved"
                );
                return Some(PermissionDecision::Approved);
            }
            if !has_segments && fingerprint.is_none() {
                info!(
                    target: "permission",
                    tool = %tool_name,
                    patterns_count = patterns_count,
                    tools_count = tools_count,
                    class = class_label,
                    matched = false,
                    level = "session_memory",
                    "[Permission:Match] no session learned rules matched"
                );
            }
        }

        // 5b) PermissionStore（Session → Project → Global）—— 长期规则
        if let Some(store) = &self.permission_store {
            let sid = self.session_id.as_deref();
            let wd = self.workdir.as_deref();
            let store_hit = if has_segments {
                let r = store.find_for_segments_diagnostic(sid, wd, tool_name, &effects.segments);
                info!(
                    target: "permission",
                    tool = %tool_name,
                    result = ?r.as_ref().map(|r| format!("{:?}", r)),
                    segments = ?effects.segments.iter().map(|s| &s.fingerprint).collect::<Vec<_>>(),
                    "[Permission:Match] PermissionStore.find_for_segments"
                );
                r
            } else if !effects.paths.is_empty() {
                let path_strs: Vec<String> = effects
                    .paths
                    .iter()
                    .map(|p| p.to_string_lossy().into_owned())
                    .collect();
                let r =
                    store.find_for_paths_diagnostic(sid, wd, tool_name, fingerprint, &path_strs);
                info!(
                    target: "permission",
                    tool = %tool_name,
                    result = ?r.as_ref().map(|r| format!("{:?}", r)),
                    paths = path_strs.join(", "),
                    "[Permission:Match] PermissionStore.find_for_paths"
                );
                r
            } else {
                let r = store.find_diagnostic(sid, wd, tool_name, fingerprint, None);
                info!(
                    target: "permission",
                    tool = %tool_name,
                    result = ?r.as_ref().map(|r| format!("{:?}", r)),
                    "[Permission:Match] PermissionStore.find"
                );
                r
            };
            if let Some(hit) = store_hit {
                log_store_hit(tool_name, &hit);
                return Some(match hit.effect {
                    RuleEffect::Allow => PermissionDecision::Approved,
                    RuleEffect::Deny => PermissionDecision::Denied {
                        reason: "PermissionStore 规则拒绝".into(),
                    },
                });
            } else {
                info!(
                    target: "permission",
                    tool = %tool_name,
                    class = class_label,
                    matched = false,
                    level = "permission_store",
                    "[Permission:Match] PermissionStore miss"
                );
            }
        } else {
            info!(
                target: "permission",
                tool = %tool_name,
                class = class_label,
                matched = false,
                level = "permission_store",
                "[Permission:Match] no PermissionStore configured"
            );
        }

        None
    }

    /// 返回本次调用中「会写 + 可记忆 + **尚未被任何 allow 规则/记忆覆盖**」的段
    /// fingerprint（去重保序）。用于审批弹窗的记忆勾选区——只读段、不可记忆段（rm…）、
    /// 以及**之前已审批/已记住的段**（如记过的 `cd`）都不出现，用户只对本次真正
    /// 新增、需要决定是否记忆的会写段做勾选（架构 §4.4.2.3）。
    pub fn unapproved_memorable_writable_segments(
        &self,
        tool_name: &str,
        effects: &Effects,
    ) -> Vec<String> {
        let learned = self.learned.lock().unwrap();
        let sid = self.session_id.as_deref();
        let wd = self.workdir.as_deref();
        let mut out: Vec<String> = Vec::new();
        for seg in &effects.segments {
            if seg.is_readonly || seg.unmemorable {
                continue;
            }
            // 本会话 learned 已记？（工具名级 or 命令前缀级）
            let learned_hit = learned.auto_approved_tools.iter().any(|n| n == tool_name)
                || learned
                    .auto_approved_patterns
                    .iter()
                    .any(|(t, p)| t == tool_name && fingerprint_matches(&seg.fingerprint, p));
            // PermissionStore（session / project / global）已记？按单段查。
            let store_hit = self.permission_store.as_ref().is_some_and(|store| {
                matches!(
                    store
                        .find_for_segments_diagnostic(sid, wd, tool_name, std::slice::from_ref(seg))
                        .map(|m| m.effect),
                    Some(RuleEffect::Allow)
                )
            });
            if learned_hit || store_hit {
                continue;
            }
            if !out.contains(&seg.fingerprint) {
                out.push(seg.fingerprint.clone());
            }
        }
        out
    }

    /// 复合命令逐段的白名单状态（架构 §4.4.2.3）。供审批弹窗逐段展示：已白名单段标
    /// ✓ 跳过、rm 段红色禁选、待审段可勾选。**每次调用都实时查 learned + store**（store
    /// 内部按 mtime 刷新 global/project、session 内存实时），所以上一次审批刚写的规则这次立刻可见。
    pub fn approval_segments(&self, tool_name: &str, effects: &Effects) -> Vec<ApprovalSegment> {
        let learned = self.learned.lock().unwrap();
        let sid = self.session_id.as_deref();
        let wd = self.workdir.as_deref();
        effects
            .segments
            .iter()
            .map(|seg| {
                let status = if seg.is_readonly {
                    ApprovalSegmentStatus::Readonly
                } else if seg.unmemorable {
                    ApprovalSegmentStatus::Unmemorable
                } else {
                    let learned_hit = learned.auto_approved_tools.iter().any(|n| n == tool_name)
                        || learned.auto_approved_patterns.iter().any(|(t, p)| {
                            t == tool_name && fingerprint_matches(&seg.fingerprint, p)
                        });
                    let store_hit = self.permission_store.as_ref().is_some_and(|store| {
                        matches!(
                            store
                                .find_for_segments_diagnostic(
                                    sid,
                                    wd,
                                    tool_name,
                                    std::slice::from_ref(seg),
                                )
                                .map(|m| m.effect),
                            Some(RuleEffect::Allow)
                        )
                    });
                    if learned_hit || store_hit {
                        ApprovalSegmentStatus::Whitelisted
                    } else {
                        ApprovalSegmentStatus::NeedsApproval
                    }
                };
                ApprovalSegment {
                    fingerprint: seg.fingerprint.clone(),
                    status,
                }
            })
            .collect()
    }

    /// 显式开一张审批 pending（路径越界、长 run 续跑等无法用 `check` 表达的场景）。
    /// 跳过策略，调用方直接拿 `(id, waiter)` 自行 emit 事件并 await。
    ///
    /// 可选 `tool_name` / `fingerprint` 让 resolve 时能落 learned 表。路径越界不在
    /// 工具名维度，应传 `None`。
    pub fn open_approval(
        &self,
        tool_name: Option<&str>,
        fingerprint: Option<&str>,
    ) -> (PermissionRequestId, oneshot::Receiver<ApprovalDecision>) {
        self.open_approval_inner(tool_name, fingerprint, None, false)
    }

    /// 同 [`open_approval`](Self::open_approval)，但 resolve 时即使收到 `AllowAndRemember`
    /// 也**不**写 learned 表 / PermissionStore（架构 §4.4.2.2 危险复合模式）。
    pub fn open_approval_no_remember(
        &self,
        tool_name: Option<&str>,
        fingerprint: Option<&str>,
    ) -> (PermissionRequestId, oneshot::Receiver<ApprovalDecision>) {
        self.open_approval_inner(tool_name, fingerprint, None, true)
    }

    fn open_tool_approval(
        &self,
        tool_name: &str,
        fingerprint: Option<&str>,
        effects: &Effects,
        refuse_remember: bool,
    ) -> PermissionDecision {
        let (request_id, waiter) = self.open_approval_inner(
            Some(tool_name),
            fingerprint,
            Some(effects.clone()),
            refuse_remember,
        );
        PermissionDecision::NeedsApproval { request_id, waiter }
    }

    fn open_approval_inner(
        &self,
        tool_name: Option<&str>,
        fingerprint: Option<&str>,
        effects: Option<Effects>,
        refuse_remember: bool,
    ) -> (PermissionRequestId, oneshot::Receiver<ApprovalDecision>) {
        let request_id = PermissionRequestId::new();
        let (tx, rx) = oneshot::channel();
        self.pending.lock().unwrap().insert(
            request_id.clone(),
            Pending::Approval {
                sender: tx,
                tool_name: tool_name.map(str::to_owned),
                fingerprint: fingerprint.map(str::to_owned),
                effects,
                refuse_remember,
            },
        );
        info!(
            target: "permission",
            request_id = %request_id,
            tool = tool_name.unwrap_or(""),
            fingerprint = fingerprint.unwrap_or(""),
            refuse_remember,
            result = "waiting_for_approval",
            "[Permission:Approval] opened pending approval"
        );
        (request_id, rx)
    }

    /// 开一张提问 pending（ask 工具）。
    pub fn open_question(&self) -> (PermissionRequestId, oneshot::Receiver<UserAnswer>) {
        let request_id = PermissionRequestId::new();
        let (tx, rx) = oneshot::channel();
        self.pending
            .lock()
            .unwrap()
            .insert(request_id.clone(), Pending::Question(tx));
        (request_id, rx)
    }

    /// request_id 是否仍在本 gate 的 pending 表里。
    pub fn is_pending(&self, request_id: &PermissionRequestId) -> bool {
        self.pending.lock().unwrap().contains_key(request_id)
    }

    /// Surface 提交审批结果，唤醒对应 waiter。
    /// 当 `decision` 为 `AllowAndRemember` 且 scope 是 Session/Run 时按 pending 中保存的
    /// tool_name / fingerprint 写入 learned 表。
    pub fn resolve(&self, request_id: &PermissionRequestId, decision: ApprovalDecision) {
        let entry = self.pending.lock().unwrap().remove(request_id);
        let Some(Pending::Approval {
            sender,
            tool_name,
            fingerprint,
            effects,
            refuse_remember,
        }) = entry
        else {
            info!(
                target: "permission",
                request_id = %request_id,
                decision = decision_label(&decision),
                "[Permission:Approval] resolve ignored, request not pending"
            );
            return;
        };

        let (decision_scope, decision_pattern, decision_extra_patterns) = match &decision {
            ApprovalDecision::AllowAndRemember {
                scope,
                pattern,
                extra_patterns,
            } => (
                scope_label(*scope),
                pattern.as_deref().unwrap_or(""),
                extra_patterns.join(","),
            ),
            _ => ("", "", String::new()),
        };
        let segment_summary = effects
            .as_ref()
            .map(|e| {
                e.segments
                    .iter()
                    .map(|s| s.fingerprint.as_str())
                    .collect::<Vec<_>>()
                    .join(" | ")
            })
            .unwrap_or_default();
        info!(
            target: "permission",
            request_id = %request_id,
            tool = tool_name.as_deref().unwrap_or(""),
            fingerprint = fingerprint.as_deref().unwrap_or(""),
            segments = %segment_summary,
            decision = decision_label(&decision),
            scope = decision_scope,
            pattern = decision_pattern,
            extra_patterns = %decision_extra_patterns,
            "[Permission:Approval] backend received approval decision"
        );

        if let ApprovalDecision::AllowAndRemember {
            scope,
            pattern,
            extra_patterns,
        } = &decision
        {
            if refuse_remember {
                tracing::debug!(
                    tool = tool_name.as_deref().unwrap_or(""),
                    fingerprint = fingerprint.as_deref().unwrap_or(""),
                    "AllowAndRemember 被拒绝落盘：审批是由危险复合模式触发的（架构 §4.4.2.2）"
                );
            } else if let Some(name) = &tool_name {
                self.remember(*scope, name, pattern.as_deref(), fingerprint.as_deref());
                // compound 命令场景：额外段前缀逐一落盘，让 `cd /tmp && touch x` 类
                // 命令一次审批就能让段级判定（架构 §4.4.2）的"全段 allow"条件满足。
                for extra in extra_patterns {
                    self.remember(*scope, name, Some(extra.as_str()), fingerprint.as_deref());
                }
                self.resolve_matching_pending_after_remember(request_id);
            }
        }

        let _ = sender.send(decision);
    }

    fn resolve_matching_pending_after_remember(&self, current_request_id: &PermissionRequestId) {
        let mut auto_resolved: Vec<(PermissionRequestId, oneshot::Sender<ApprovalDecision>)> =
            Vec::new();
        {
            let mut pending = self.pending.lock().unwrap();
            let matching_ids: Vec<PermissionRequestId> = pending
                .iter()
                .filter_map(|(id, entry)| {
                    if id == current_request_id {
                        return None;
                    }
                    let Pending::Approval {
                        tool_name: Some(tool_name),
                        effects: Some(effects),
                        refuse_remember: false,
                        ..
                    } = entry
                    else {
                        return None;
                    };
                    if matches!(
                        self.check_without_policy(tool_name, effects),
                        Some(PermissionDecision::Approved)
                    ) {
                        Some(id.clone())
                    } else {
                        None
                    }
                })
                .collect();

            for id in matching_ids {
                if let Some(Pending::Approval { sender, .. }) = pending.remove(&id) {
                    auto_resolved.push((id, sender));
                }
            }
        }

        for (id, sender) in auto_resolved {
            info!(
                target: "permission",
                request_id = %id,
                current_request_id = %current_request_id,
                decision = "allow_once",
                "[Permission:Approval] auto-resolved pending approval after remember"
            );
            let _ = sender.send(ApprovalDecision::AllowOnce);
        }
    }

    /// Surface 提交提问回应，唤醒对应 waiter。
    pub fn answer(&self, request_id: &PermissionRequestId, answer: UserAnswer) {
        if let Some(Pending::Question(tx)) = self.pending.lock().unwrap().remove(request_id) {
            let _ = tx.send(answer);
        }
    }

    /// 取消所有未决（run 被 interrupt 时调用）。
    /// 审批默认 Deny；提问默认 Cancelled。
    pub fn cancel_all_pending(&self) {
        let mut pending = self.pending.lock().unwrap();
        for (_id, entry) in pending.drain() {
            match entry {
                Pending::Approval { sender, .. } => {
                    let _ = sender.send(ApprovalDecision::Deny);
                }
                Pending::Question(tx) => {
                    let _ = tx.send(UserAnswer::Cancelled);
                }
            }
        }
    }

    fn needs_approval(
        &self,
        tool_name: &str,
        fingerprint: Option<&str>,
        effects: &Effects,
    ) -> PermissionDecision {
        self.open_tool_approval(tool_name, fingerprint, effects, false)
    }

    /// 同 [`needs_approval`](Self::needs_approval)，但 pending 带 `refuse_remember=true`。
    /// 用于危险复合模式触发的强制审批（架构 §4.4.2.2）。
    fn needs_approval_no_remember(
        &self,
        tool_name: &str,
        fingerprint: Option<&str>,
        effects: &Effects,
    ) -> PermissionDecision {
        self.open_tool_approval(tool_name, fingerprint, effects, true)
    }

    /// 把 AllowAndRemember 翻成对应 scope 的记忆。
    ///
    /// 行为分级：
    /// - `Once`：不写任何地方
    /// - `Session`：
    ///   - 优先写 in-memory learned 表（兼容旧 dispatch 命中路径）
    ///   - 若挂了 PermissionStore，再写一条 [`PermissionRule`] 进 session 内存视图
    /// - `Project`：写一条 PermissionRule 进 ~/.hebbian/permissions.json，
    ///   带 `workdir = self.workdir`。未挂 PermissionStore 或 workdir 缺失 → warn 退回 AllowOnce
    /// - `Global`：写一条 PermissionRule 进 ~/.hebbian/permissions.json
    ///   未挂时打 warn，"按钮"等同 AllowOnce
    fn remember(
        &self,
        scope: PermissionScope,
        tool_name: &str,
        pattern: Option<&str>,
        fingerprint: Option<&str>,
    ) {
        let _ = fingerprint; // 仅 debug 备用
        let _no_tool_level = NO_TOOL_LEVEL_MEMORY.contains(&tool_name);
        match scope {
            PermissionScope::Once => {
                info!(
                    target: "permission",
                    tool = tool_name,
                    pattern = pattern.unwrap_or(""),
                    level = "once",
                    "[Permission:Resolve] once scope, no rule persisted"
                );
            }
            PermissionScope::Session => {
                // (1) in-memory learned（旧路径，立即对本 run 后续工具调用生效）
                let mut learned = self.learned.lock().unwrap();
                match (pattern, _no_tool_level) {
                    (Some(prefix), _) => {
                        let prefix = prefix.trim();
                        if !prefix.is_empty() {
                            let entry = (tool_name.to_string(), prefix.to_string());
                            if !learned.auto_approved_patterns.contains(&entry) {
                                learned.auto_approved_patterns.push(entry);
                            }
                            info!(
                                target: "permission",
                                tool = tool_name,
                                pattern = prefix,
                                level = "session",
                                "[Permission:Resolve] stored session learned pattern"
                            );
                        }
                    }
                    (None, false) => {
                        let name = tool_name.to_string();
                        if !learned.auto_approved_tools.contains(&name) {
                            learned.auto_approved_tools.push(name);
                        }
                        info!(
                            target: "permission",
                            tool = tool_name,
                            level = "session",
                            "[Permission:Resolve] stored session learned tool"
                        );
                    }
                    (None, true) => {
                        tracing::debug!(
                            tool = tool_name,
                            "AllowAndRemember(Session) 没有 pattern，工具在 NO_TOOL_LEVEL_MEMORY 黑名单，本次不记忆"
                        );
                    }
                }
                drop(learned);
                // (2) PermissionStore：让 session.jsonl 也能回放出同样的规则
                if let (Some(store), Some(sid)) = (&self.permission_store, &self.session_id) {
                    if let Some(pat) = build_pattern(tool_name, pattern) {
                        if let Err(e) = store.add(
                            PermissionScope::Session,
                            Some(sid.as_str()),
                            None,
                            RuleEffect::Allow,
                            pat.clone(),
                        ) {
                            tracing::warn!(error = %e, "PermissionStore.add(Session) 失败");
                        } else {
                            info!(
                                target: "permission",
                                tool = tool_name,
                                pattern = %pat,
                                level = "session",
                                "[Permission:Resolve] stored PermissionStore rule"
                            );
                        }
                    }
                }
            }
            PermissionScope::Project => {
                let Some(store) = self.permission_store.as_ref() else {
                    tracing::warn!(
                        tool = tool_name,
                        "AllowAndRemember(Project) 但未挂 PermissionStore，等同 AllowOnce"
                    );
                    return;
                };
                let Some(wd) = self.workdir.clone() else {
                    tracing::warn!(
                        tool = tool_name,
                        "AllowAndRemember(Project) 但 HitlGate 未持 workdir，等同 AllowOnce"
                    );
                    return;
                };
                if let Some(pat) = build_pattern(tool_name, pattern) {
                    if let Err(e) = store.add(
                        PermissionScope::Project,
                        None,
                        Some(wd.as_path()),
                        RuleEffect::Allow,
                        pat.clone(),
                    ) {
                        tracing::warn!(error = %e, "PermissionStore.add(Project) 失败");
                    } else {
                        info!(
                            target: "permission",
                            tool = tool_name,
                            pattern = %pat,
                            level = "project",
                            "[Permission:Resolve] stored PermissionStore rule"
                        );
                    }
                }
            }
            PermissionScope::Global => {
                let Some(store) = self.permission_store.as_ref() else {
                    tracing::warn!(
                        tool = tool_name,
                        "AllowAndRemember(Global) 但未挂 PermissionStore，等同 AllowOnce"
                    );
                    return;
                };
                if let Some(pat) = build_pattern(tool_name, pattern) {
                    if let Err(e) = store.add(
                        PermissionScope::Global,
                        None,
                        None,
                        RuleEffect::Allow,
                        pat.clone(),
                    ) {
                        tracing::warn!(error = %e, "PermissionStore.add(Global) 失败");
                    } else {
                        info!(
                            target: "permission",
                            tool = tool_name,
                            pattern = %pat,
                            level = "global",
                            "[Permission:Resolve] stored PermissionStore rule"
                        );
                    }
                }
            }
        }
    }
}

/// 把 (tool_name, command/path pattern) 拼成 PermissionStore 字符串 pattern 语法。
/// 例：("Bash", Some("git status")) → "Bash(git status)"；("Read", None) → "Read"。
fn build_pattern(tool_name: &str, pattern: Option<&str>) -> Option<String> {
    match pattern {
        None => Some(tool_name.to_string()),
        Some(p) => {
            let p = p.trim();
            if p.is_empty() {
                return None;
            }
            Some(format!("{tool_name}({p})"))
        }
    }
}

impl Default for HitlGate {
    fn default() -> Self {
        Self::new(PermissionPolicy::default())
    }
}

/// 按空白 token 边界判定 fingerprint 是否命中 prefix：完全相等，或 prefix 后紧跟空白。
fn fingerprint_matches(fingerprint: &str, prefix: &str) -> bool {
    if fingerprint == prefix {
        return true;
    }
    if let Some(rest) = fingerprint.strip_prefix(prefix) {
        rest.starts_with(' ') || rest.starts_with('\t')
    } else {
        false
    }
}

