//! Skill 系统（架构 §6.1.3）：按三层来源加载 SKILL.md 并按需注入：
//!
//! 1. `~/.hebbian/skills/`                          ← 全局
//! 2. `~/.hebbian/projects/<enc(workdir)>/skills/`  ← 项目私有（hebbian 内聚）
//! 3. `<workdir>/.claude/skills/`                   ← 项目代码内嵌（跟 git 同步）
//!
//! 同名 skill 后者覆盖前者。`~/.claude/skills/` **不默认加载**——通过
//! [`crate::storage::skills::import_from_claude`] 一次性导入。
//!
//! - SKILL.md 头部 frontmatter（YAML）解析 name + description
//! - SkillTool 是「读取 SKILL.md 套壳」：模型给出 skill 名，我们把整篇内容塞回去
//! - 工具 description 动态包含可用 skill 列表（让模型知道有哪些 skill 可调用）
//! - read-only：默认 auto-approve

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use async_trait::async_trait;
use common::{AppError, AppResult};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use super::Tool;
use crate::storage::projects;

const MAX_SKILL_BYTES: u64 = 200 * 1024;
const MAX_DESC_PREVIEW: usize = 200;

/// 一个加载好的 skill
#[derive(Debug, Clone, Serialize)]
pub struct Skill {
    /// 目录名——`<skills_dir>/<name>/SKILL.md` 拼路径用，永远存在。
    pub name: String,
    /// frontmatter `name:` 字段，仅当与目录名**不同**时填。模型在 prompt 里
    /// 看到的「公开名」优先取它（如果有），调用 Skill 工具时按 name 或 alias 任一匹配。
    /// 用于支持 Claude Code 风格的 skill——目录名是简写、frontmatter 写完整名。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub alias: Option<String>,
    pub description: String,
    pub path: PathBuf,
    pub source: SkillSource,
    /// 用户在 hebbian 里是否启用该 skill。`false` 时 SkillTool 不会把它暴露给模型。
    /// 由 `storage::skills::apply_disabled` 根据 `~/.hebbian/disabled_skills.json` 填写。
    pub enabled: bool,
    /// 所属 collection id（架构 §6.1.3）。仅给 `CoreClient::list_skills` 这条
    /// 路径用——前端按它分组展示。SkillTool 运行时路径不填（None），不影响模型。
    /// 仅 Global source 的 skill 可能有值；Project / ProjectCode 永远 None。
    #[serde(skip_serializing_if = "Option::is_none")]
    pub collection_id: Option<String>,
}

impl Skill {
    /// 模型在 prompt / 命令面板里看到的公开名：frontmatter alias 优先，回退目录名。
    pub fn display_name(&self) -> &str {
        self.alias.as_deref().unwrap_or(&self.name)
    }

    /// SkillTool 调用时是否命中该 skill：目录名或 alias 任一匹配。
    pub fn matches(&self, key: &str) -> bool {
        self.name == key || self.alias.as_deref() == Some(key)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SkillSource {
    /// `~/.hebbian/skills/<name>/SKILL.md`
    Global,
    /// `~/.hebbian/projects/<enc>/skills/<name>/SKILL.md`
    Project,
    /// `<workdir>/.claude/skills/<name>/SKILL.md`
    ProjectCode,
}

/// 默认 skill 目录（含 source 标签），按"前 → 后覆盖"顺序排列。
pub fn default_skill_dirs(data_dir: &Path, workdir: &Path) -> Vec<(SkillSource, PathBuf)> {
    vec![
        (SkillSource::Global, data_dir.join("skills")),
        (
            SkillSource::Project,
            projects::project_dir(data_dir, workdir).join("skills"),
        ),
        (SkillSource::ProjectCode, workdir.join(".claude/skills")),
    ]
}

/// 从带 source 的目录列表加载 skills。后面的目录会覆盖前面的同名 skill。
pub fn load_skills(sources: &[(SkillSource, PathBuf)]) -> Vec<Skill> {
    let mut out: BTreeMap<String, Skill> = BTreeMap::new();
    for (source, dir) in sources {
        load_dir_into(dir, *source, &mut out);
    }
    out.into_values().collect()
}

/// 只查一层 `<skills_dir>/<skill-name>/SKILL.md`，不递归。
///
/// `Skill.name` 永远是目录名（read_skill_md 靠它拼路径）；frontmatter 的 `name`
/// 字段若存在且与目录名不同，存到 `Skill.alias`——既作为模型 prompt 里的公开名，
/// 也参与 lookup 兜底匹配。这样 `~/.hebbian/skills/karpathy/` 里
/// `name: karpathy-guidelines` 的 skill 可以被 `/karpathy` 或 `/karpathy-guidelines`
/// 任一调到（Claude Code 风格的 skill 经常这么写）。
fn load_dir_into(dir: &Path, source: SkillSource, out: &mut BTreeMap<String, Skill>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let skill_md = path.join("SKILL.md");
        if !skill_md.exists() {
            continue;
        }
        let Ok(content) = std::fs::read_to_string(&skill_md) else {
            continue;
        };
        let (name_opt, desc_opt) = parse_frontmatter(&content);
        let name = path
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| "unnamed".into());
        let alias = name_opt.filter(|n| !n.is_empty() && n != &name);
        let description = desc_opt.unwrap_or_else(|| extract_first_paragraph(&content));
        out.insert(
            name.clone(),
            Skill {
                name,
                alias,
                description,
                path: skill_md,
                source,
                enabled: true,
                collection_id: None,
            },
        );
    }
}

/// 极简 YAML frontmatter 解析：只取 `name:` 和 `description:`
fn parse_frontmatter(content: &str) -> (Option<String>, Option<String>) {
    let mut lines = content.lines();
    if lines.next().map(|s| s.trim()) != Some("---") {
        return (None, None);
    }
    let mut name = None;
    let mut description = None;
    for line in lines {
        let trimmed = line.trim();
        if trimmed == "---" {
            break;
        }
        if let Some(rest) = trimmed.strip_prefix("name:") {
            name = Some(strip_quotes(rest.trim()).to_string());
        } else if let Some(rest) = trimmed.strip_prefix("description:") {
            description = Some(strip_quotes(rest.trim()).to_string());
        }
    }
    (name, description)
}

fn strip_quotes(s: &str) -> &str {
    s.trim_matches(|c: char| c == '"' || c == '\'')
}

fn extract_first_paragraph(content: &str) -> String {
    let after_frontmatter = if content.starts_with("---") {
        content
            .splitn(3, "---")
            .nth(2)
            .unwrap_or(content)
            .trim_start()
    } else {
        content
    };
    let para: String = after_frontmatter
        .lines()
        .skip_while(|l| l.trim().is_empty() || l.trim_start().starts_with('#'))
        .take_while(|l| !l.trim().is_empty())
        .collect::<Vec<_>>()
        .join(" ");
    if para.len() > MAX_DESC_PREVIEW {
        format!("{}…", &para[..MAX_DESC_PREVIEW])
    } else {
        para
    }
}

pub struct SkillTool {
    skills: Arc<Vec<Skill>>,
    /// 拼好的描述（含可用 skill 列表）
    description: String,
}

impl SkillTool {
    pub fn new(skills: Vec<Skill>) -> Self {
        let description = render_description(&skills);
        Self {
            skills: Arc::new(skills),
            description,
        }
    }
}

fn render_description(skills: &[Skill]) -> String {
    let mut s = String::from(
        "在主对话里执行一个 skill。Skill 是放在 `.claude/skills/<name>/SKILL.md` 里的\
         markdown 指令包；调用本工具会把整篇 SKILL.md 内容回填到对话里，\
         让模型按其中的指令行动。\n\n",
    );
    if skills.is_empty() {
        s.push_str(
            "当前**没有**可用的 skills。用户可以在 `~/.hebbian/skills/<name>/SKILL.md`、\
             项目目录 `~/.hebbian/projects/<enc>/skills/<name>/SKILL.md` 或项目代码内嵌的 \
             `<workdir>/.claude/skills/<name>/SKILL.md` 里创建。",
        );
    } else {
        s.push_str("可用 skills（按名字调用）：\n");
        for skill in skills {
            let scope = match skill.source {
                SkillSource::Global => "global",
                SkillSource::Project => "project",
                SkillSource::ProjectCode => "project-code",
            };
            let preview = first_words(&skill.description, 80);
            // alias != 目录名时同时列出，让模型知道两个名字都能调（不少 Claude Code
            // 风格 skill 目录名是简写 / frontmatter name 是完整名，如 karpathy /
            // karpathy-guidelines）
            match &skill.alias {
                Some(alias) => s.push_str(&format!(
                    "- `{alias}`（或 `{}`，{scope}）: {preview}\n",
                    skill.name
                )),
                None => s.push_str(&format!("- `{}` ({scope}): {preview}\n", skill.name)),
            }
        }
    }
    s
}

fn first_words(s: &str, limit: usize) -> String {
    if s.len() <= limit {
        return s.to_string();
    }
    let mut end = limit;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &s[..end])
}

#[async_trait]
impl Tool for SkillTool {
    fn name(&self) -> &str {
        "Skill"
    }

    fn description(&self) -> &str {
        &self.description
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["skill"],
            "properties": {
                "skill": {
                    "type": "string",
                    "description": "skill 名称（不带前缀斜杠）"
                }
            }
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let name = input["skill"]
            .as_str()
            .ok_or_else(|| AppError::msg("Skill: 缺少 skill"))?
            .trim()
            .trim_start_matches('/');
        let skill = self
            .skills
            .iter()
            .find(|s| s.matches(name))
            .ok_or_else(|| AppError::msg(format!("Skill: 未找到 skill `{name}`")))?;

        let meta = std::fs::metadata(&skill.path)
            .map_err(|e| AppError::msg(format!("Skill: stat 失败 {e}")))?;
        if meta.len() > MAX_SKILL_BYTES {
            return Err(AppError::msg(format!(
                "Skill: SKILL.md 过大（{} 字节），跳过",
                meta.len()
            )));
        }
        let content = std::fs::read_to_string(&skill.path)
            .map_err(|e| AppError::msg(format!("Skill: 读取失败 {e}")))?;

        let body = strip_frontmatter(&content);
        let base_dir = skill
            .path
            .parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default();
        Ok(format!(
            "Skill: {}\nBase directory: {base_dir}\n\n{body}",
            skill.name
        ))
    }
}

fn strip_frontmatter(content: &str) -> &str {
    if !content.starts_with("---") {
        return content;
    }
    content
        .splitn(3, "---")
        .nth(2)
        .map(|s| s.trim_start_matches('\n'))
        .unwrap_or(content)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn write_skill(dir: &Path, name: &str, frontmatter: &str, body: &str) {
        let skill_dir = dir.join(name);
        std::fs::create_dir_all(&skill_dir).unwrap();
        let content = if frontmatter.is_empty() {
            body.to_string()
        } else {
            format!("---\n{frontmatter}\n---\n{body}")
        };
        std::fs::write(skill_dir.join("SKILL.md"), content).unwrap();
    }

    #[test]
    fn parses_frontmatter_name_and_description() {
        let (name, desc) =
            parse_frontmatter("---\nname: commit\ndescription: \"Commit changes\"\n---\nbody\n");
        assert_eq!(name.as_deref(), Some("commit"));
        assert_eq!(desc.as_deref(), Some("Commit changes"));
    }

    #[tokio::test]
    async fn executes_returns_skill_md_body() {
        let tmp = tempfile::tempdir().unwrap();
        let skills_dir = tmp.path().join(".claude/skills");
        write_skill(
            &skills_dir,
            "demo",
            "name: demo\ndescription: A demo",
            "Hello from skill",
        );

        let mut m = BTreeMap::new();
        load_dir_into(&skills_dir, SkillSource::Project, &mut m);
        let skills: Vec<_> = m.into_values().collect();

        let tool = SkillTool::new(skills);
        let out = tool.execute(json!({"skill": "demo"})).await.unwrap();
        assert!(out.contains("Hello from skill"));
        assert!(out.contains("Skill: demo"));
    }

    #[tokio::test]
    async fn unknown_skill_errors() {
        let tool = SkillTool::new(Vec::new());
        let res = tool.execute(json!({"skill": "missing"})).await;
        assert!(res.is_err());
    }

    /// 回归 2026-05-23：~/.hebbian/skills/karpathy/SKILL.md 的 frontmatter
    /// `name: karpathy-guidelines` 之前会被丢弃，导致模型按 `/karpathy-guidelines`
    /// 调用时 SkillTool lookup 失败。
    #[tokio::test]
    async fn frontmatter_alias_is_callable_alongside_dir_name() {
        let tmp = tempfile::tempdir().unwrap();
        let skills_dir = tmp.path().join("skills");
        write_skill(
            &skills_dir,
            "karpathy",
            "name: karpathy-guidelines\ndescription: Behavioral guidelines",
            "Karpathy body",
        );

        let mut m = BTreeMap::new();
        load_dir_into(&skills_dir, SkillSource::Global, &mut m);
        let skills: Vec<_> = m.into_values().collect();
        assert_eq!(skills.len(), 1);
        assert_eq!(skills[0].name, "karpathy");
        assert_eq!(skills[0].alias.as_deref(), Some("karpathy-guidelines"));
        assert_eq!(skills[0].display_name(), "karpathy-guidelines");

        let tool = SkillTool::new(skills);
        // 目录名调用照常工作
        let by_dir = tool.execute(json!({"skill": "karpathy"})).await.unwrap();
        assert!(by_dir.contains("Karpathy body"));
        // 带前缀斜杠 + frontmatter 完整名也能命中
        let by_alias = tool
            .execute(json!({"skill": "/karpathy-guidelines"}))
            .await
            .unwrap();
        assert!(by_alias.contains("Karpathy body"));
    }

    /// frontmatter `name:` 等于目录名时 alias 应为 None（避免冗余显示）。
    #[test]
    fn alias_is_none_when_frontmatter_matches_dir_name() {
        let tmp = tempfile::tempdir().unwrap();
        let skills_dir = tmp.path().join("skills");
        write_skill(
            &skills_dir,
            "commit",
            "name: commit\ndescription: same",
            "body",
        );
        let mut m = BTreeMap::new();
        load_dir_into(&skills_dir, SkillSource::Global, &mut m);
        let skills: Vec<_> = m.into_values().collect();
        assert_eq!(skills[0].alias, None);
    }
}

crates/agent-core/src/tools/task.rs.content:
//! Task：subagent 调度工具（架构 §4.4.11）。
//!
//! 模型调 `Task(subagent_type, prompt, mode, run_in_background)` 委托一个子任务给
//! 自定义 system prompt + 受限工具子集的 subagent，跑一次嵌套 agent_loop（NestedRun）。
//!
//! 真正的 NestedRun 执行体由 [`crate::dispatch::ToolDispatcher`] 的 short-circuit 分支
//! 处理（持有 client / hitl / workspace / sink 等父 run 上下文），Tool trait 本身只
//! 描述 schema。P1 阶段 dispatcher short-circuit 尚未接入，工具实际不会被模型选中（条件
//! 注入：[`default_tools`] 仅在加载到至少一个启用的 subagent 定义时才注入 Task），
//! 所以 `execute` 走兜底返回 P1 占位错误是合理的：dispatcher 接好之前，工具就不该被调到。

use std::sync::Arc;

use async_trait::async_trait;
use common::{AppError, AppResult};
use serde::Deserialize;
use serde_json::{json, Value};

use crate::storage::subagents::SubagentDefinition;
use crate::tools::Tool;

pub const TASK_TOOL_NAME: &str = "Task";

/// `mode` 参数（架构 §4.4.11.3）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TaskMode {
    /// 子 Session 起手 transcript 仅一条 user message（prompt）。
    Isolated,
    /// 子 Session 起手 transcript = 父当前 messages 的深拷贝 + 追加 prompt。
    Inherit,
}

impl Default for TaskMode {
    fn default() -> Self {
        TaskMode::Isolated
    }
}

#[derive(Debug, Deserialize)]
pub struct TaskInput {
    /// 哪个 subagent（与 `~/.hebbian/subagents/<name>.md` 文件名一致）。
    pub subagent_type: String,
    /// 任务描述。isolated 模式下子只看到这一条；inherit 模式下追加在父 transcript 副本之后。
    pub prompt: String,
    #[serde(default)]
    pub mode: TaskMode,
    /// UI 卡片标题用的短标签。可空。
    #[serde(default)]
    pub description: Option<String>,
    /// 后台模式（架构 §4.4.11.7）。true 时立即返回 task_id，NestedRun 在 BgTaskRegistry
    /// 后台跑，完成时通过 WakeupScheduler 通知父模型。
    #[serde(default)]
    pub run_in_background: bool,
}

pub struct TaskTool {
    /// 当前会话可用的 subagent 列表（已应用启用合并，仅含 enabled=true 的项）。
    /// description 拼接里平铺出 subagent_type + description 给模型选用。
    subagents: Arc<Vec<SubagentDefinition>>,
    description: String,
}

impl TaskTool {
    pub fn new(subagents: Vec<SubagentDefinition>) -> Self {
        let description = render_description(&subagents);
        Self {
            subagents: Arc::new(subagents),
            description,
        }
    }

    /// 拿引用给 dispatcher short-circuit 查找定义。
    pub fn subagents(&self) -> &[SubagentDefinition] {
        &self.subagents
    }
}

fn render_description(subagents: &[SubagentDefinition]) -> String {
    let mut s = String::from(
        "Dispatch a sub-task to a specialized subagent that has its own system prompt and a restricted tool subset. \
         Use this when you want to delegate a self-contained piece of work (code review, focused research, writing tests, etc.).\n\n\
         `mode` choices:\n\
         - `isolated` (default): the subagent only sees the `prompt` argument; the parent conversation is hidden. \
         Use for self-contained tasks where context is captured fully in `prompt`.\n\
         - `inherit`: the subagent starts from a snapshot of the parent conversation plus the `prompt`. \
         Use when the sub-task continues the current discussion (e.g. \"write tests for the implementation we just designed\").\n\n\
         `run_in_background=true` returns immediately with a task_id; the system will send a BgTaskFinished \
         wakeup notification when it completes. Use this when you want to do other work in parallel, \
         or finish the current turn and wait for the notification.\n\n",
    );
    if subagents.is_empty() {
        s.push_str("No subagents are currently available; this tool should not be invoked.");
    } else {
        s.push_str("Available subagents (use as `subagent_type`):\n");
        for def in subagents {
            s.push_str(&format!("- `{}`: {}\n", def.name, def.description));
        }
    }
    s
}

#[async_trait]
impl Tool for TaskTool {
    fn name(&self) -> &str {
        TASK_TOOL_NAME
    }

    fn description(&self) -> &str {
        &self.description
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["subagent_type", "prompt"],
            "properties": {
                "subagent_type": {
                    "type": "string",
                    "description": "Which subagent to invoke (see the list in this tool's description)."
                },
                "prompt": {
                    "type": "string",
                    "description": "The task description sent to the subagent."
                },
                "mode": {
                    "type": "string",
                    "enum": ["isolated", "inherit"],
                    "default": "isolated",
                    "description": "isolated = subagent only sees `prompt`. inherit = subagent inherits a snapshot of the parent conversation plus `prompt`."
                },
                "description": {
                    "type": "string",
                    "description": "Short label of the sub-task for UI display."
                },
                "run_in_background": {
                    "type": "boolean",
                    "default": false,
                    "description": "If true, return immediately with a task_id; the subagent runs in the background and the system sends a BgTaskFinished wakeup when it completes."
                }
            }
        })
    }

    /// 兜底实现：dispatcher short-circuit 接入前不应被调到（default_tools 条件注入兜底）。
    /// 走到这里说明 dispatch 路径未把 Task 路由到 SubagentRunner，是 bug。
    async fn execute(&self, _input: Value) -> AppResult<String> {
        Err(AppError::msg(
            "Task 必须由 dispatcher short-circuit 路由到 SubagentRunner；走到 Tool::execute 说明 dispatch 路径未接入 NestedRun",
        ))
    }
}

/// 解析模型传入的 input。供 dispatcher short-circuit 复用。
pub fn parse_input(input: Value) -> AppResult<TaskInput> {
    serde_json::from_value::<TaskInput>(input)
        .map_err(|e| AppError::msg(format!("invalid Task input: {e}")))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn make_def(name: &str, desc: &str) -> SubagentDefinition {
        SubagentDefinition {
            name: name.to_string(),
            description: desc.to_string(),
            tools: None,
            model: None,
            max_iterations: None,
            system_prompt: format!("You are {name}."),
            enabled: true,
        }
    }

    #[test]
    fn description_lists_available_subagents() {
        let tool = TaskTool::new(vec![
            make_def("code-reviewer", "Reviews code for bugs."),
            make_def("doc-researcher", "Searches docs."),
        ]);
        let d = tool.description();
        assert!(d.contains("`code-reviewer`: Reviews code for bugs."));
        assert!(d.contains("`doc-researcher`: Searches docs."));
        assert!(d.contains("isolated"));
        assert!(d.contains("inherit"));
        assert!(d.contains("run_in_background"));
    }

    #[test]
    fn description_with_empty_subagents_says_unavailable() {
        let tool = TaskTool::new(Vec::new());
        let d = tool.description();
        assert!(d.contains("No subagents are currently available"));
    }

    #[test]
    fn schema_requires_subagent_type_and_prompt() {
        let tool = TaskTool::new(Vec::new());
        let schema = tool.parameters_schema();
        let required = schema["required"].as_array().unwrap();
        let req: Vec<&str> = required.iter().filter_map(|v| v.as_str()).collect();
        assert!(req.contains(&"subagent_type"));
        assert!(req.contains(&"prompt"));
    }

    #[test]
    fn parse_input_defaults_mode_to_isolated() {
        let raw = json!({
            "subagent_type": "code-reviewer",
            "prompt": "review the diff"
        });
        let input = parse_input(raw).unwrap();
        assert_eq!(input.subagent_type, "code-reviewer");
        assert_eq!(input.mode, TaskMode::Isolated);
        assert!(!input.run_in_background);
    }

    #[test]
    fn parse_input_accepts_inherit_mode_and_background_flag() {
        let raw = json!({
            "subagent_type": "doc",
            "prompt": "continue what we discussed",
            "mode": "inherit",
            "run_in_background": true
        });
        let input = parse_input(raw).unwrap();
        assert_eq!(input.mode, TaskMode::Inherit);
        assert!(input.run_in_background);
    }

    #[tokio::test]
    async fn execute_returns_error_until_dispatcher_short_circuit_is_wired() {
        let tool = TaskTool::new(vec![make_def("x", "x")]);
        let res = tool
            .execute(json!({"subagent_type":"x","prompt":"y"}))
            .await;
        assert!(res.is_err());
        let msg = res.unwrap_err().to_string();
        assert!(msg.contains("dispatcher short-circuit"));
    }
}

crates/agent-core/src/tools/todo_write.r.content:
//! TodoWrite 工具（架构 §4.4.6）。
//!
//! 模型用它维护一份"当前 session 的 todo 列表"以组织长任务。每次调用
//! **整列表覆盖**前一次——简化心智，避免增量合并的 corner case。
//!
//! 落盘 + 事件 emit 由 [`crate::dispatch`] 的 short-circuit 分支处理；
//! 本工具本身只做：解析 input + 校验 + 返回一行汇总文本（"Updated 5 todos:
//! 2 completed, 1 in_progress, 2 pending"）。Dispatcher 落盘后 emit
//! [`protocol::EventPayload::TodoListUpdated`]。
//!
//! 为什么不在 execute 里直接落盘：execute 不持有 `data_dir + session_id`
//! 上下文，加这两个参数会污染 Tool trait（其他工具用不到）。Dispatcher 已经
//! 有这两个参数，让它处理落盘 / emit 是最干净的分工——与 [`crate::tools::hitl`]
//! 把 HITL 路由收到 dispatcher 同款思路。

use async_trait::async_trait;
use serde::Deserialize;
use serde_json::Value;

use common::{AppError, AppResult};
use protocol::todo::{TodoItem, TodoStatus};

use crate::tools::Tool;

pub const TODO_WRITE_TOOL_NAME: &str = "TodoWrite";

#[derive(Debug, Deserialize)]
pub struct TodoWriteInput {
    pub todos: Vec<TodoInputItem>,
}

#[derive(Debug, Deserialize)]
pub struct TodoInputItem {
    #[serde(default)]
    pub id: Option<String>,
    pub content: String,
    /// 模型协议字段名（驼峰）与协议 [`TodoItem::active_form`] 对齐。
    #[serde(rename = "activeForm")]
    pub active_form: String,
    pub status: TodoStatus,
}

pub struct TodoWriteTool;

#[async_trait]
impl Tool for TodoWriteTool {
    fn name(&self) -> &str {
        TODO_WRITE_TOOL_NAME
    }

    fn description(&self) -> &str {
        "Maintain a structured todo list for the current session. \
         Use it for any task with 3+ steps to track progress, organize work, \
         and surface status to the user. Each call REPLACES the prior list \
         (send the full set every time). Each item carries: \
         `content` (imperative form, e.g. \"Run tests\"), \
         `activeForm` (present continuous, e.g. \"Running tests\"), and \
         `status` ∈ pending / in_progress / completed. \
         Exactly one item should be `in_progress` at a time."
    }

    fn parameters_schema(&self) -> Value {
        serde_json::json!({
            "type": "object",
            "required": ["todos"],
            "properties": {
                "todos": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "required": ["content", "activeForm", "status"],
                        "properties": {
                            "id": {
                                "type": "string",
                                "description": "Optional stable id (ulid-like). Reuse it across calls \
                                                to update the same item; omit for new items."
                            },
                            "content": {
                                "type": "string",
                                "description": "Imperative form. e.g. \"Run tests\""
                            },
                            "activeForm": {
                                "type": "string",
                                "description": "Present continuous form. e.g. \"Running tests\""
                            },
                            "status": {
                                "type": "string",
                                "enum": ["pending", "in_progress", "completed"]
                            }
                        }
                    }
                }
            }
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let parsed = parse_input(input)?;
        let todos = normalize(parsed.todos);
        Ok(summary(&todos))
    }
}

/// 解析 model 传入的 input。错误会被转成 `AppError::msg`。
pub fn parse_input(input: Value) -> AppResult<TodoWriteInput> {
    serde_json::from_value::<TodoWriteInput>(input)
        .map_err(|e| AppError::msg(format!("invalid TodoWrite input: {e}")))
}

/// 把 input items 规约成协议 [`TodoItem`]——补 id（缺时用 content+activeForm 的
/// 稳定 hash）、修剪空白。
///
/// **为什么要稳定 id 而不是随机**：sidebar 需要把"同一次任务清单的多次更新（pending →
/// in_progress → completed）"识别为**同一个块**。判定依据是 todo id 重叠——如果模型
/// 不传 id 我们就发随机 id，每次都不同，会被前端误认为新建块。content+activeForm
/// 的 hash 保证模型按同样描述重传时 id 一致。
pub fn normalize(items: Vec<TodoInputItem>) -> Vec<TodoItem> {
    items
        .into_iter()
        .map(|it| {
            let content = it.content.trim().to_string();
            let active_form = it.active_form.trim().to_string();
            let id = it
                .id
                .unwrap_or_else(|| stable_todo_id(&content, &active_form));
            TodoItem {
                id,
                content,
                active_form,
                status: it.status,
            }
        })
        .collect()
}

/// 汇总文本：`"Updated 5 todos (2 completed, 1 in_progress, 2 pending)"`。
pub fn summary(todos: &[TodoItem]) -> String {
    let mut completed = 0;
    let mut in_progress = 0;
    let mut pending = 0;
    for t in todos {
        match t.status {
            TodoStatus::Completed => completed += 1,
            TodoStatus::InProgress => in_progress += 1,
            TodoStatus::Pending => pending += 1,
        }
    }
    format!(
        "Updated {} todos ({} completed, {} in_progress, {} pending)",
        todos.len(),
        completed,
        in_progress,
        pending
    )
}

/// 从 content + active_form 计算稳定 id——同 content 重传保证 id 相同。
/// 用 FNV-1a 32-bit hash 足够：碰撞概率在 session 内 <50 条 todo 量级可忽略。
fn stable_todo_id(content: &str, active_form: &str) -> String {
    let mut hash: u64 = 0xcbf29ce484222325;
    for b in content.bytes().chain([0u8]).chain(active_form.bytes()) {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("td-{hash:x}")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[tokio::test]
    async fn execute_returns_summary() {
        let tool = TodoWriteTool;
        let input = json!({
            "todos": [
                { "content": "Write tests", "activeForm": "Writing tests", "status": "in_progress" },
                { "content": "Ship feature", "activeForm": "Shipping feature", "status": "pending" },
            ]
        });
        let out = tool.execute(input).await.unwrap();
        assert!(out.contains("Updated 2 todos"));
        assert!(out.contains("1 in_progress"));
        assert!(out.contains("1 pending"));
    }

    #[test]
    fn normalize_fills_missing_id() {
        let items = vec![TodoInputItem {
            id: None,
            content: "  trim me  ".into(),
            active_form: "trimming".into(),
            status: TodoStatus::Pending,
        }];
        let out = normalize(items);
        assert_eq!(out[0].content, "trim me");
        assert!(out[0].id.starts_with("td-"));
    }

    /// 稳定 id：同 content + activeForm 重传应得到同 id——
    /// sidebar 才能把"pending → completed"识别为同一条 todo 而非新建。
    #[test]
    fn stable_id_idempotent_for_same_content() {
        let a = stable_todo_id("写代码", "正在写代码");
        let b = stable_todo_id("写代码", "正在写代码");
        assert_eq!(a, b);
        let c = stable_todo_id("跑测试", "正在跑测试");
        assert_ne!(a, c);
    }
}

crates/agent-core/src/tools/web_fetch.rs.content:
use std::{
    collections::HashMap,
    net::IpAddr,
    sync::{Mutex, OnceLock},
    time::{Duration, Instant},
};

use super::Tool;
use async_trait::async_trait;
use common::{AppError, AppResult};
use reqwest::{
    header::{CONTENT_LENGTH, CONTENT_TYPE, LOCATION},
    StatusCode, Url,
};
use serde_json::{json, Value};

const MAX_URL_LENGTH: usize = 2_000;
const MAX_HTTP_CONTENT_LENGTH: usize = 10 * 1024 * 1024;
const FETCH_TIMEOUT: Duration = Duration::from_secs(60);
const MAX_REDIRECTS: usize = 10;
const MAX_MARKDOWN_LENGTH: usize = 100_000;
const CACHE_TTL: Duration = Duration::from_secs(15 * 60);

#[derive(Debug, Clone)]
struct NormalizedFetchUrl {
    original_url: Url,
    request_url: Url,
}

#[derive(Debug, Clone)]
struct FetchedContent {
    final_url: Url,
    bytes: usize,
    code: StatusCode,
    code_text: String,
    content_type: String,
    markdown: String,
}

#[derive(Debug, Clone)]
struct RedirectInfo {
    original_url: Url,
    redirect_url: Url,
    status: StatusCode,
}

#[derive(Debug, Clone)]
enum FetchOutcome {
    Content(FetchedContent),
    Redirect(RedirectInfo),
}

#[derive(Debug, Clone)]
struct CacheEntry {
    fetched_at: Instant,
    content: FetchedContent,
}

pub struct WebFetchTool;

#[async_trait]
impl Tool for WebFetchTool {
    fn name(&self) -> &str {
        "Fetch"
    }

    fn description(&self) -> &str {
        "Fetch a URL, convert readable web content to markdown, and return content relevant \
         to the provided prompt. HTTP URLs are upgraded to HTTPS. Cross-host redirects are \
         reported instead of followed."
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "url": {
                    "type": "string",
                    "format": "uri",
                    "description": "The fully-formed http:// or https:// URL to fetch"
                },
                "prompt": {
                    "type": "string",
                    "description": "What information to extract or focus on from the fetched content"
                }
            },
            "required": ["url", "prompt"]
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let url = input["url"]
            .as_str()
            .ok_or_else(|| AppError::msg("web_fetch: 缺少 url 参数"))?;
        let prompt = input["prompt"]
            .as_str()
            .ok_or_else(|| AppError::msg("web_fetch: 缺少 prompt 参数"))?
            .trim();
        if prompt.is_empty() {
            return Err(AppError::msg("web_fetch: prompt 不能为空"));
        }

        fetch_page(url, prompt).await
    }
}

async fn fetch_page(url: &str, prompt: &str) -> AppResult<String> {
    let normalized = normalize_fetch_url(url)?;
    let outcome = get_url_markdown_content(&normalized).await?;

    match outcome {
        FetchOutcome::Content(content) => Ok(format_fetch_result(prompt, &content)),
        FetchOutcome::Redirect(redirect) => Ok(format_redirect_result(prompt, &redirect)),
    }
}

fn normalize_fetch_url(url: &str) -> AppResult<NormalizedFetchUrl> {
    if url.len() > MAX_URL_LENGTH {
        return Err(AppError::msg(format!(
            "web_fetch: URL 超过最大长度 {MAX_URL_LENGTH}"
        )));
    }

    let original_url =
        Url::parse(url).map_err(|_| AppError::msg(format!("web_fetch: 无效 URL {url}")))?;
    match original_url.scheme() {
        "http" | "https" => {}
        scheme => {
            return Err(AppError::msg(format!(
                "web_fetch: 不支持的 URL 协议 {scheme}"
            )));
        }
    }

    if !original_url.username().is_empty() || original_url.password().is_some() {
        return Err(AppError::msg("web_fetch: URL 不能包含用户名或密码凭据"));
    }

    let host = original_url
        .host_str()
        .ok_or_else(|| AppError::msg("web_fetch: URL 缺少 host"))?;
    if !is_public_fetch_host(host) {
        return Err(AppError::msg(format!(
            "web_fetch: 出于安全原因拒绝抓取非公网 host {host}"
        )));
    }

    let mut request_url = original_url.clone();
    if request_url.scheme() == "http" {
        request_url
            .set_scheme("https")
            .map_err(|_| AppError::msg("web_fetch: 无法将 HTTP URL 升级为 HTTPS"))?;
    }

    Ok(NormalizedFetchUrl {
        original_url,
        request_url,
    })
}

fn is_public_fetch_host(host: &str) -> bool {
    if host.eq_ignore_ascii_case("localhost") || host.ends_with(".local") {
        return false;
    }

    if let Ok(ip) = host.parse::<IpAddr>() {
        return match ip {
            IpAddr::V4(ip) => {
                !(ip.is_private()
                    || ip.is_loopback()
                    || ip.is_link_local()
                    || ip.is_broadcast()
                    || ip.is_unspecified())
            }
            IpAddr::V6(ip) => {
                !(ip.is_loopback()
                    || ip.is_unspecified()
                    || ip.is_unique_local()
                    || ip.is_unicast_link_local())
            }
        };
    }

    host.contains('.')
}

async fn get_url_markdown_content(normalized: &NormalizedFetchUrl) -> AppResult<FetchOutcome> {
    if let Some(content) = get_cached_content(normalized.original_url.as_str()) {
        return Ok(FetchOutcome::Content(content));
    }

    let client = reqwest::Client::builder()
        .user_agent("Mozilla/5.0 (compatible; Hebbian/0.1; +https://github.com)")
        .redirect(reqwest::redirect::Policy::none())
        .timeout(FETCH_TIMEOUT)
        .build()?;

    let outcome = get_with_permitted_redirects(&client, normalized).await?;
    if let FetchOutcome::Content(content) = &outcome {
        set_cached_content(normalized.original_url.as_str(), content.clone());
    }
    Ok(outcome)
}

async fn get_with_permitted_redirects(
    client: &reqwest::Client,
    normalized: &NormalizedFetchUrl,
) -> AppResult<FetchOutcome> {
    let mut current = normalized.request_url.clone();

    for _ in 0..=MAX_REDIRECTS {
        let response = client
            .get(current.clone())
            .header(
                "Accept",
                "text/markdown, text/html, text/plain, application/json, */*",
            )
            .send()
            .await?;
        let status = response.status();

        if is_manual_redirect(status) {
            let location = response
                .headers()
                .get(LOCATION)
                .and_then(|value| value.to_str().ok())
                .ok_or_else(|| AppError::msg("web_fetch: redirect 缺少 Location header"))?;
            let redirect_url = current
                .join(location)
                .map_err(|_| AppError::msg("web_fetch: 无效 redirect URL"))?;

            if is_permitted_redirect(&current, &redirect_url) {
                current = redirect_url;
                continue;
            }

            return Ok(FetchOutcome::Redirect(RedirectInfo {
                original_url: current,
                redirect_url,
                status,
            }));
        }

        if !status.is_success() {
            return Err(AppError::msg(format!(
                "web_fetch: HTTP {} from {}",
                status, current
            )));
        }

        if let Some(content_length) = response
            .headers()
            .get(CONTENT_LENGTH)
            .and_then(|value| value.to_str().ok())
            .and_then(|value| value.parse::<usize>().ok())
        {
            if content_length > MAX_HTTP_CONTENT_LENGTH {
                return Err(AppError::msg(format!(
                    "web_fetch: 响应过大，超过 {} bytes",
                    MAX_HTTP_CONTENT_LENGTH
                )));
            }
        }

        let content_type = response
            .headers()
            .get(CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .unwrap_or("")
            .to_string();
        if is_binary_content_type(&content_type) {
            return Err(AppError::msg(format!(
                "web_fetch: 暂不支持二进制内容类型 {content_type}"
            )));
        }

        let bytes = response.bytes().await?;
        if bytes.len() > MAX_HTTP_CONTENT_LENGTH {
            return Err(AppError::msg(format!(
                "web_fetch: 响应过大，超过 {} bytes",
                MAX_HTTP_CONTENT_LENGTH
            )));
        }

        let body = String::from_utf8_lossy(&bytes).to_string();
        let markdown = if content_type.to_ascii_lowercase().contains("html") {
            html_to_markdown(&body)
        } else {
            normalize_text(&decode_html_entities(&body))
        };

        return Ok(FetchOutcome::Content(FetchedContent {
            final_url: current,
            bytes: bytes.len(),
            code: status,
            code_text: status.canonical_reason().unwrap_or("").to_string(),
            content_type,
            markdown,
        }));
    }

    Err(AppError::msg(format!(
        "web_fetch: redirect 次数超过 {MAX_REDIRECTS}"
    )))
}

fn get_cached_content(url: &str) -> Option<FetchedContent> {
    let mut cache = content_cache().lock().ok()?;
    let entry = cache.get(url)?;
    if entry.fetched_at.elapsed() <= CACHE_TTL {
        return Some(entry.content.clone());
    }
    cache.remove(url);
    None
}

fn set_cached_content(url: &str, content: FetchedContent) {
    if let Ok(mut cache) = content_cache().lock() {
        cache.insert(
            url.to_string(),
            CacheEntry {
                fetched_at: Instant::now(),
                content,
            },
        );
    }
}

fn content_cache() -> &'static Mutex<HashMap<String, CacheEntry>> {
    static CACHE: OnceLock<Mutex<HashMap<String, CacheEntry>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

fn is_manual_redirect(status: StatusCode) -> bool {
    matches!(status.as_u16(), 301 | 302 | 303 | 307 | 308)
}

fn is_permitted_redirect(original_url: &Url, redirect_url: &Url) -> bool {
    if original_url.scheme() != redirect_url.scheme() {
        return false;
    }
    if original_url.port_or_known_default() != redirect_url.port_or_known_default() {
        return false;
    }
    if !redirect_url.username().is_empty() || redirect_url.password().is_some() {
        return false;
    }

    let original_host = original_url
        .host_str()
        .unwrap_or("")
        .trim_start_matches("www.");
    let redirect_host = redirect_url
        .host_str()
        .unwrap_or("")
        .trim_start_matches("www.");
    original_host.eq_ignore_ascii_case(redirect_host)
}

#[cfg(test)]
fn is_permitted_redirect_url(original_url: &str, redirect_url: &str) -> bool {
    match (Url::parse(original_url), Url::parse(redirect_url)) {
        (Ok(original), Ok(redirect)) => is_permitted_redirect(&original, &redirect),
        _ => false,
    }
}

fn is_binary_content_type(content_type: &str) -> bool {
    let lower = content_type.to_ascii_lowercase();
    lower.starts_with("image/")
        || lower.starts_with("audio/")
        || lower.starts_with("video/")
        || lower.contains("application/octet-stream")
        || lower.contains("application/zip")
        || lower.contains("application/x-")
        || lower.contains("font/")
}

fn format_redirect_result(prompt: &str, redirect: &RedirectInfo) -> String {
    let status_text = redirect.status.canonical_reason().unwrap_or("");
    format!(
        "REDIRECT DETECTED: The URL redirects to a different host.\n\n\
         Original URL: {}\n\
         Redirect URL: {}\n\
         Status: {} {}\n\n\
         To complete the request, call web_fetch again with:\n\
         - url: \"{}\"\n\
         - prompt: \"{}\"",
        redirect.original_url,
        redirect.redirect_url,
        redirect.status.as_u16(),
        status_text,
        redirect.redirect_url,
        prompt
    )
}

fn format_fetch_result(prompt: &str, content: &FetchedContent) -> String {
    let markdown = if content.markdown.len() > MAX_MARKDOWN_LENGTH {
        format!(
            "{}\n\n[Content truncated due to length: showing first {} chars of {} chars]",
            content
                .markdown
                .chars()
                .take(MAX_MARKDOWN_LENGTH)
                .collect::<String>(),
            MAX_MARKDOWN_LENGTH,
            content.markdown.len()
        )
    } else {
        content.markdown.clone()
    };

    format!(
        "Fetched URL: {}\n\
         Status: {} {}\n\
         Bytes: {}\n\
         Content-Type: {}\n\
         Prompt: {}\n\n\
         Page content:\n{}",
        content.final_url,
        content.code.as_u16(),
        content.code_text,
        content.bytes,
        if content.content_type.is_empty() {
            "unknown"
        } else {
            content.content_type.as_str()
        },
        prompt,
        markdown
    )
}

fn html_to_markdown(html: &str) -> String {
    let mut html = html.to_string();
    for tag in ["script", "style", "noscript", "svg"] {
        html = remove_tag_block(&html, tag);
    }

    let mut output = String::with_capacity(html.len() / 2);
    let mut rest = html.as_str();
    let mut active_link: Option<(String, String)> = None;

    while let Some(tag_start) = rest.find('<') {
        push_text(&mut output, &mut active_link, &rest[..tag_start]);
        let after_start = &rest[tag_start + 1..];
        let Some(tag_end) = after_start.find('>') else {
            push_text(&mut output, &mut active_link, rest);
            rest = "";
            break;
        };

        let raw_tag = after_start[..tag_end].trim();
        handle_html_tag(raw_tag, &mut output, &mut active_link);
        rest = &after_start[tag_end + 1..];
    }
    push_text(&mut output, &mut active_link, rest);

    if let Some((href, text)) = active_link.take() {
        push_markdown_link(&mut output, &href, &text);
    }

    normalize_markdown(&decode_html_entities(&output))
}

fn push_text(output: &mut String, active_link: &mut Option<(String, String)>, text: &str) {
    if text.is_empty() {
        return;
    }
    if let Some((_href, link_text)) = active_link.as_mut() {
        link_text.push_str(text);
    } else {
        output.push_str(text);
    }
}

fn handle_html_tag(raw_tag: &str, output: &mut String, active_link: &mut Option<(String, String)>) {
    let lower = raw_tag.to_ascii_lowercase();
    let is_closing = lower.starts_with('/');
    let name = lower
        .trim_start_matches('/')
        .split_whitespace()
        .next()
        .unwrap_or("")
        .trim_end_matches('/');

    if is_closing && name == "a" {
        if let Some((href, text)) = active_link.take() {
            push_markdown_link(output, &href, &text);
        }
        return;
    }

    if !is_closing && name == "a" {
        if let Some(href) = extract_attr(raw_tag, "href") {
            *active_link = Some((decode_html_entities(&href), String::new()));
        }
        return;
    }

    match (is_closing, name) {
        (false, "h1") => output.push_str("\n# "),
        (false, "h2") => output.push_str("\n## "),
        (false, "h3") => output.push_str("\n### "),
        (false, "h4") => output.push_str("\n#### "),
        (false, "h5") => output.push_str("\n##### "),
        (false, "h6") => output.push_str("\n###### "),
        (true, "h1" | "h2" | "h3" | "h4" | "h5" | "h6") => output.push_str("\n\n"),
        (false, "p" | "div" | "section" | "article" | "main" | "header" | "footer") => {
            output.push_str("\n\n")
        }
        (true, "p" | "div" | "section" | "article" | "main" | "header" | "footer") => {
            output.push_str("\n\n")
        }
        (false, "br") => output.push('\n'),
        (false, "li") => output.push_str("\n- "),
        (true, "li") => output.push('\n'),
        _ => {}
    }
}

fn push_markdown_link(output: &mut String, href: &str, text: &str) {
    let label = normalize_inline_text(&decode_html_entities(text));
    if label.is_empty() {
        return;
    }
    if href.trim().is_empty() {
        output.push_str(&label);
    } else {
        output.push_str(&format!("[{}]({})", label, href.trim()));
    }
}

fn extract_attr(tag: &str, attr: &str) -> Option<String> {
    let lower = tag.to_ascii_lowercase();
    let needle = format!("{attr}=");
    let start = lower.find(&needle)? + needle.len();
    let value = tag[start..].trim_start();
    let quote = value.chars().next()?;

    if quote == '"' || quote == '\'' {
        let end = value[1..].find(quote)?;
        Some(value[1..1 + end].to_string())
    } else {
        let end = value.find(char::is_whitespace).unwrap_or(value.len());
        Some(value[..end].trim_end_matches('/').to_string())
    }
}

fn normalize_markdown(text: &str) -> String {
    let mut lines = Vec::new();
    let mut previous_blank = true;

    for line in text.lines() {
        let normalized = normalize_inline_text(line);
        if normalized.is_empty() {
            if !previous_blank {
                lines.push(String::new());
                previous_blank = true;
            }
        } else {
            lines.push(normalized);
            previous_blank = false;
        }
    }

    lines.join("\n").trim().to_string()
}

fn normalize_text(text: &str) -> String {
    text.lines()
        .map(normalize_inline_text)
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

fn normalize_inline_text(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn decode_html_entities(text: &str) -> String {
    text.replace("&amp;", "&")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&#39;", "'")
        .replace("&apos;", "'")
        .replace("&nbsp;", " ")
        .replace("&mdash;", "-")
        .replace("&ndash;", "-")
}

fn remove_tag_block(html: &str, tag: &str) -> String {
    let open = format!("<{}", tag);
    let close = format!("</{}>", tag);
    let mut result = String::with_capacity(html.len());
    let mut rest = html;

    while let Some(start) = rest.to_ascii_lowercase().find(&open) {
        result.push_str(&rest[..start]);
        let lower_tail = rest[start..].to_ascii_lowercase();
        if let Some(end_offset) = lower_tail.find(&close) {
            rest = &rest[start + end_offset + close.len()..];
        } else {
            rest = "";
            break;
        }
    }

    result.push_str(rest);
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fetch_schema_requires_prompt() {
        let schema = WebFetchTool.parameters_schema();

        assert_eq!(schema["required"], json!(["url", "prompt"]));
        assert!(schema["properties"]["prompt"].is_object());
    }

    #[test]
    fn normalize_fetch_url_rejects_credentials_and_upgrades_http() {
        assert!(normalize_fetch_url("https://user:pass@example.com").is_err());
        assert!(normalize_fetch_url("https://localhost/docs").is_err());

        let normalized = normalize_fetch_url("http://example.com/docs").unwrap();

        assert_eq!(normalized.request_url.as_str(), "https://example.com/docs");
    }

    #[test]
    fn redirect_policy_allows_only_same_site_redirects() {
        assert!(is_permitted_redirect_url(
            "https://example.com/docs",
            "https://www.example.com/guide"
        ));
        assert!(is_permitted_redirect_url(
            "https://www.example.com/docs",
            "https://example.com/guide"
        ));
        assert!(!is_permitted_redirect_url(
            "https://example.com/docs",
            "https://evil.example.net/guide"
        ));
        assert!(!is_permitted_redirect_url(
            "https://example.com/docs",
            "http://example.com/guide"
        ));
    }

    #[test]
    fn html_to_markdown_keeps_readable_structure_and_links() {
        let markdown = html_to_markdown(
            r#"
            <html>
              <body>
                <h1>Docs</h1>
                <p>Hello <a href="https://example.com/start">start</a>.</p>
                <ul><li>First</li><li>Second</li></ul>
                <script>hidden()</script>
              </body>
            </html>
            "#,
        );

        assert!(markdown.contains("# Docs"));
        assert!(markdown.contains("[start](https://example.com/start)"));
        assert!(markdown.contains("- First"));
        assert!(markdown.contains("- Second"));
        assert!(!markdown.contains("hidden"));
    }
}

crates/agent-core/src/tools/web_search.r.content:
use std::time::Instant;

use super::Tool;
use async_trait::async_trait;
use common::{AppError, AppResult};
use reqwest::Url;
use serde_json::{json, Value};

const MAX_SEARCH_RESULTS: usize = 8;

#[derive(Debug, Clone, PartialEq, Eq)]
struct SearchInput {
    query: String,
    allowed_domains: Vec<String>,
    blocked_domains: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SearchHit {
    title: String,
    url: String,
}

pub struct WebSearchTool;

#[async_trait]
impl Tool for WebSearchTool {
    fn name(&self) -> &str {
        "WebSearch"
    }

    fn description(&self) -> &str {
        "Search the web for current information and return source links. Supports optional \
         allowed_domains or blocked_domains filters. Use this for recent information or facts \
         that need web sources."
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "minLength": 2,
                    "description": "The search query to use"
                },
                "allowed_domains": {
                    "type": "array",
                    "items": { "type": "string" },
                    "description": "Only include search results from these domains"
                },
                "blocked_domains": {
                    "type": "array",
                    "items": { "type": "string" },
                    "description": "Never include search results from these domains"
                }
            },
            "required": ["query"]
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let input = parse_search_input(&input)?;
        search_duckduckgo(&input).await
    }
}

fn parse_search_input(input: &Value) -> AppResult<SearchInput> {
    let query = input["query"]
        .as_str()
        .ok_or_else(|| AppError::msg("web_search: 缺少 query 参数"))?
        .trim()
        .to_string();
    if query.len() < 2 {
        return Err(AppError::msg("web_search: query 至少需要 2 个字符"));
    }

    let allowed_domains = parse_domain_list(input.get("allowed_domains"))?;
    let blocked_domains = parse_domain_list(input.get("blocked_domains"))?;
    if !allowed_domains.is_empty() && !blocked_domains.is_empty() {
        return Err(AppError::msg(
            "web_search: allowed_domains 和 blocked_domains 不能同时指定",
        ));
    }

    Ok(SearchInput {
        query,
        allowed_domains,
        blocked_domains,
    })
}

fn parse_domain_list(value: Option<&Value>) -> AppResult<Vec<String>> {
    let Some(value) = value else {
        return Ok(Vec::new());
    };
    let Some(items) = value.as_array() else {
        return Err(AppError::msg("web_search: 域名过滤参数必须是字符串数组"));
    };

    let mut domains = Vec::new();
    for item in items {
        let domain = item
            .as_str()
            .ok_or_else(|| AppError::msg("web_search: 域名过滤参数必须是字符串数组"))?;
        let normalized = normalize_domain(domain)?;
        if !domains.iter().any(|existing| existing == &normalized) {
            domains.push(normalized);
        }
    }
    Ok(domains)
}

fn normalize_domain(domain: &str) -> AppResult<String> {
    let trimmed = domain
        .trim()
        .trim_start_matches("http://")
        .trim_start_matches("https://")
        .trim_matches('/');
    if trimmed.is_empty() {
        return Err(AppError::msg("web_search: 域名不能为空"));
    }

    let candidate = format!("https://{trimmed}");
    let parsed = Url::parse(&candidate)
        .map_err(|_| AppError::msg(format!("web_search: 无效域名 {domain}")))?;
    let host = parsed
        .host_str()
        .ok_or_else(|| AppError::msg(format!("web_search: 无效域名 {domain}")))?
        .to_ascii_lowercase();

    if !host.contains('.') {
        return Err(AppError::msg(format!(
            "web_search: 域名必须包含顶级域名 {domain}"
        )));
    }
    Ok(host)
}

async fn search_duckduckgo(input: &SearchInput) -> AppResult<String> {
    let start = Instant::now();
    let client = reqwest::Client::builder()
        .user_agent("Mozilla/5.0 (compatible; Hebbian/0.1; +https://github.com)")
        .timeout(std::time::Duration::from_secs(20))
        .build()?;

    let url = build_search_url(input);
    let response = client.get(&url).send().await?;
    if !response.status().is_success() {
        return Err(AppError::msg(format!(
            "web_search: HTTP {}",
            response.status()
        )));
    }

    let html = response.text().await?;
    let hits = filter_search_hits(parse_duckduckgo_html(&html), input);

    if hits.is_empty() {
        return search_duckduckgo_instant_answer(input, start).await;
    }

    Ok(format_search_results(
        input,
        &hits,
        start.elapsed().as_secs_f64(),
    ))
}

fn build_search_url(input: &SearchInput) -> String {
    let mut query = input.query.clone();
    if !input.allowed_domains.is_empty() {
        let sites = input
            .allowed_domains
            .iter()
            .map(|domain| format!("site:{domain}"))
            .collect::<Vec<_>>()
            .join(" OR ");
        query.push(' ');
        query.push_str(&sites);
    }
    for domain in &input.blocked_domains {
        query.push_str(" -site:");
        query.push_str(domain);
    }

    format!(
        "https://html.duckduckgo.com/html/?q={}",
        urlencoding::encode(&query)
    )
}

async fn search_duckduckgo_instant_answer(
    input: &SearchInput,
    start: Instant,
) -> AppResult<String> {
    let client = reqwest::Client::builder()
        .user_agent("Mozilla/5.0 (compatible; Hebbian/0.1; +https://github.com)")
        .timeout(std::time::Duration::from_secs(20))
        .build()?;
    let url = format!(
        "https://api.duckduckgo.com/?q={}&format=json&no_html=1&skip_disambig=1",
        urlencoding::encode(&input.query)
    );
    let response = client.get(&url).send().await?;
    if !response.status().is_success() {
        return Err(AppError::msg(format!(
            "web_search: HTTP {}",
            response.status()
        )));
    }

    let json: Value = response.json().await?;
    let mut hits = Vec::new();
    if let Some(topics) = json["RelatedTopics"].as_array() {
        collect_instant_answer_topics(topics, &mut hits);
    }
    let hits = filter_search_hits(hits, input);
    if !hits.is_empty() {
        return Ok(format_search_results(
            input,
            &hits,
            start.elapsed().as_secs_f64(),
        ));
    }

    let abstract_text = json["AbstractText"].as_str().unwrap_or("").trim();
    let answer = json["Answer"].as_str().unwrap_or("").trim();
    let source = json["AbstractSource"].as_str().unwrap_or("").trim();
    let source_url = json["AbstractURL"].as_str().unwrap_or("").trim();

    let mut result = format!(
        "Web search results for query: \"{}\"\nDuration: {:.2}s\n\n",
        input.query,
        start.elapsed().as_secs_f64()
    );
    if !answer.is_empty() {
        result.push_str(&format!("Answer: {answer}\n\n"));
    }
    if !abstract_text.is_empty() {
        if source.is_empty() {
            result.push_str(abstract_text);
            result.push_str("\n\n");
        } else {
            result.push_str(&format!("{source}: {abstract_text}\n\n"));
        }
    }
    if !source_url.is_empty() {
        result.push_str("Sources:\n");
        result.push_str(&format!(
            "- [{}]({})\n\n",
            if source.is_empty() {
                source_url
            } else {
                source
            },
            source_url
        ));
    } else {
        result.push_str("Sources:\n");
        result.push_str(&format!(
            "- [DuckDuckGo results](https://duckduckgo.com/?q={})\n\n",
            urlencoding::encode(&input.query)
        ));
    }
    result.push_str("REMINDER: 必须在回答中引用这些来源，并使用 markdown 链接。");
    Ok(result.trim().to_string())
}

fn collect_instant_answer_topics(topics: &[Value], hits: &mut Vec<SearchHit>) {
    for topic in topics {
        if let (Some(title), Some(url)) = (topic["Text"].as_str(), topic["FirstURL"].as_str()) {
            hits.push(SearchHit {
                title: title.to_string(),
                url: url.to_string(),
            });
        }
        if let Some(nested) = topic["Topics"].as_array() {
            collect_instant_answer_topics(nested, hits);
        }
    }
}

fn parse_duckduckgo_html(html: &str) -> Vec<SearchHit> {
    let mut hits = Vec::new();
    let mut rest = html;

    while let Some(anchor_start) = rest.find("<a") {
        rest = &rest[anchor_start..];
        let Some(tag_end) = rest.find('>') else {
            break;
        };
        let tag = &rest[..=tag_end];
        let after_tag = &rest[tag_end + 1..];
        let Some(anchor_end) = after_tag.find("</a>") else {
            break;
        };
        let body = &after_tag[..anchor_end];
        rest = &after_tag[anchor_end + "</a>".len()..];

        if !tag.contains("result__a") {
            continue;
        }
        let Some(raw_href) = extract_attr(tag, "href") else {
            continue;
        };
        let Some(url) = normalize_result_url(&raw_href) else {
            continue;
        };
        let title = html_to_text(body);
        if title.is_empty() {
            continue;
        }

        hits.push(SearchHit { title, url });
    }

    dedupe_hits(hits)
        .into_iter()
        .take(MAX_SEARCH_RESULTS)
        .collect()
}

fn normalize_result_url(raw_href: &str) -> Option<String> {
    let decoded = decode_html_entities(raw_href);
    let href = decoded.trim();
    let absolute = if href.starts_with("//") {
        format!("https:{href}")
    } else if href.starts_with('/') {
        format!("https://duckduckgo.com{href}")
    } else {
        href.to_string()
    };

    let parsed = Url::parse(&absolute).ok()?;
    if parsed
        .host_str()
        .is_some_and(|host| host.ends_with("duckduckgo.com"))
        && parsed.path().starts_with("/l/")
    {
        for (key, value) in parsed.query_pairs() {
            if key == "uddg" {
                return Some(value.into_owned());
            }
        }
    }

    Some(parsed.to_string())
}

fn filter_search_hits(hits: Vec<SearchHit>, input: &SearchInput) -> Vec<SearchHit> {
    hits.into_iter()
        .filter(|hit| {
            if !input.allowed_domains.is_empty()
                && !input
                    .allowed_domains
                    .iter()
                    .any(|domain| url_matches_domain(&hit.url, domain))
            {
                return false;
            }
            if input
                .blocked_domains
                .iter()
                .any(|domain| url_matches_domain(&hit.url, domain))
            {
                return false;
            }
            true
        })
        .take(MAX_SEARCH_RESULTS)
        .collect()
}

fn url_matches_domain(url: &str, domain: &str) -> bool {
    let Ok(parsed) = Url::parse(url) else {
        return false;
    };
    let Some(host) = parsed.host_str() else {
        return false;
    };
    let host = host.to_ascii_lowercase();
    host == domain || host.ends_with(&format!(".{domain}"))
}

fn format_search_results(input: &SearchInput, hits: &[SearchHit], duration_seconds: f64) -> String {
    let mut result = format!(
        "Web search results for query: \"{}\"\nDuration: {:.2}s\n\nSources:\n",
        input.query, duration_seconds
    );

    if hits.is_empty() {
        result.push_str(&format!(
            "- [DuckDuckGo results](https://duckduckgo.com/?q={})\n",
            urlencoding::encode(&input.query)
        ));
    } else {
        for hit in hits {
            result.push_str(&format!("- [{}]({})\n", hit.title, hit.url));
        }
    }

    result.push_str("\nREMINDER: 必须在回答中引用这些来源，并使用 markdown 链接。");
    result
}

fn dedupe_hits(hits: Vec<SearchHit>) -> Vec<SearchHit> {
    let mut deduped = Vec::new();
    for hit in hits {
        if !deduped
            .iter()
            .any(|existing: &SearchHit| existing.url == hit.url)
        {
            deduped.push(hit);
        }
    }
    deduped
}

fn extract_attr(tag: &str, attr: &str) -> Option<String> {
    let lower = tag.to_ascii_lowercase();
    let needle = format!("{attr}=");
    let start = lower.find(&needle)? + needle.len();
    let value = tag[start..].trim_start();
    let quote = value.chars().next()?;

    if quote == '"' || quote == '\'' {
        let end = value[1..].find(quote)?;
        Some(value[1..1 + end].to_string())
    } else {
        let end = value.find(char::is_whitespace).unwrap_or(value.len());
        Some(value[..end].trim_end_matches('/').to_string())
    }
}

fn html_to_text(html: &str) -> String {
    let mut text = String::new();
    let mut in_tag = false;

    for ch in html.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if in_tag => {}
            _ => text.push(ch),
        }
    }

    decode_html_entities(&text)
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn decode_html_entities(text: &str) -> String {
    text.replace("&amp;", "&")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&#39;", "'")
        .replace("&apos;", "'")
        .replace("&nbsp;", " ")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn search_schema_exposes_domain_filters() {
        let schema = WebSearchTool.parameters_schema();

        assert_eq!(schema["required"], json!(["query"]));
        assert!(schema["properties"]["allowed_domains"].is_object());
        assert!(schema["properties"]["blocked_domains"].is_object());
    }

    #[test]
    fn parse_search_input_rejects_conflicting_domain_filters() {
        let input = json!({
            "query": "rust async traits",
            "allowed_domains": ["doc.rust-lang.org"],
            "blocked_domains": ["example.com"]
        });

        assert!(parse_search_input(&input).is_err());
    }

    #[test]
    fn duckduckgo_html_parser_extracts_result_links() {
        let html = r#"
            <a class="result__a" href="//duckduckgo.com/l/?uddg=https%3A%2F%2Fdoc.rust-lang.org%2Fbook%2F&amp;rut=abc">
              The Rust Programming Language
            </a>
            <a class="result__a" href="https://example.com/nope">Ignored</a>
        "#;

        let hits = parse_duckduckgo_html(html);

        assert_eq!(hits.len(), 2);
        assert_eq!(hits[0].title, "The Rust Programming Language");
        assert_eq!(hits[0].url, "https://doc.rust-lang.org/book/");
    }

    #[test]
    fn domain_filters_and_formatting_keep_sources_visible() {
        let hits = vec![
            SearchHit {
                title: "Rust Book".into(),
                url: "https://doc.rust-lang.org/book/".into(),
            },
            SearchHit {
                title: "Blocked".into(),
                url: "https://example.com/page".into(),
            },
        ];
        let input = SearchInput {
            query: "rust ownership".into(),
            allowed_domains: vec!["doc.rust-lang.org".into()],
            blocked_domains: Vec::new(),
        };

        let filtered = filter_search_hits(hits, &input);
        let formatted = format_search_results(&input, &filtered, 1.25);

        assert_eq!(filtered.len(), 1);
        assert!(formatted.contains("Sources:"));
        assert!(formatted.contains("[Rust Book](https://doc.rust-lang.org/book/)"));
        assert!(formatted.contains("必须在回答中引用这些来源"));
    }
}

crates/agent-core/src/tools/write_memory.content:
//! `WriteMemory` 工具（架构 §4.14）：模型主动把一条值得长期记的事实写入记忆。
//!
//! 落盘必经 [`crate::storage::memory`]——不把内部路径暴露给模型。`scope=project` 但
//! 当前对话未绑定项目时降级写 global，并在返回里说明，避免「记了个寂寞」。

use std::path::PathBuf;

use async_trait::async_trait;
use serde_json::{json, Value};

use common::{AppError, AppResult};

use super::Tool;
use crate::storage::memory::{self, MemoryScope};

pub const WRITE_MEMORY_TOOL_NAME: &str = "WriteMemory";

pub struct WriteMemoryTool {
    data_dir: Option<PathBuf>,
    /// 当前对话绑定的项目 workdir；未绑定项目时 `None`（scope=project 时降级 global）。
    project_workdir: Option<PathBuf>,
}

impl WriteMemoryTool {
    pub fn new(data_dir: Option<PathBuf>, project_workdir: Option<PathBuf>) -> Self {
        Self {
            data_dir,
            project_workdir,
        }
    }
}

#[async_trait]
impl Tool for WriteMemoryTool {
    fn name(&self) -> &str {
        WRITE_MEMORY_TOOL_NAME
    }

    fn description(&self) -> &str {
        "把一条值得以后复用的事实写入长期记忆。scope=project 记到当前项目（结构 / 架构 / \
         约定 / 坑），global 记到跨项目全局（用户偏好等）。key 是这条记忆的稳定标识，\
         用同一个 key 再写会更新它。summary 是一句话摘要（会出现在以后对话的记忆清单里）。"
    }

    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "required": ["scope", "category", "key", "summary", "content"],
            "properties": {
                "scope": {
                    "type": "string",
                    "enum": ["project", "global"],
                    "description": "project=当前项目；global=跨项目全局"
                },
                "category": {
                    "type": "string",
                    "description": "分类，如 structure / architecture / conventions / pitfalls / preferences"
                },
                "key": {
                    "type": "string",
                    "description": "这条记忆的稳定标识；同 key 再写会更新该条"
                },
                "summary": {
                    "type": "string",
                    "description": "一句话摘要（≤120 字），用于以后对话的记忆清单初筛"
                },
                "content": {
                    "type": "string",
                    "description": "正文。可含 ## 概览 / ## 详情 两段；短记忆只写正文即可"
                }
            }
        })
    }

    async fn execute(&self, input: Value) -> AppResult<String> {
        let data_dir = self
            .data_dir
            .as_ref()
            .ok_or_else(|| AppError::msg("记忆功能不可用（当前无数据目录）"))?;

        let get = |k: &str| input.get(k).and_then(|v| v.as_str());
        let requested = get("scope").unwrap_or("global");
        let category = get("category").ok_or_else(|| AppError::msg("缺少参数 category"))?;
        let key = get("key").ok_or_else(|| AppError::msg("缺少参数 key"))?;
        let summary = get("summary").ok_or_else(|| AppError::msg("缺少参数 summary"))?;
        let content = get("content").ok_or_else(|| AppError::msg("缺少参数 content"))?;

        // scope 解析 + project 降级：未绑定项目时 project → global。
        let (scope, note) = match requested {
            "project" if self.project_workdir.is_some() => (MemoryScope::Project, ""),
            "project" => (MemoryScope::Global, "（当前对话未绑定项目，已改记到全局）"),
            _ => (MemoryScope::Global, ""),
        };
        let workdir = match scope {
            MemoryScope::Project => self.project_workdir.as_deref(),
            MemoryScope::Global => None,
        };

        let l0 = memory::write(data_dir, workdir, scope, key, category, summary, content)?;
        let _ = memory::append_log(
            data_dir,
            workdir,
            scope,
            &memory::MemoryLogEntry::new("wrote", format!("主动写入 {}", l0.id)),
        );
        Ok(format!("已记下记忆 {} [{}]{}", l0.id, l0.category, note))
    }
}

crates/agent-core/src/turn_context.rs.content:
use protocol::TokenBudget;

use crate::definition::{CompactionPolicy, PermissionPolicy};

/// 一次 turn（"用户输入 → 助手最终输出"）的所有显式参数。
///
/// 显式持有 turn 上下文是为了：
/// - 同一 run 的不同 turn 可以切换 model
/// - Fork / Rollback 时不需要重建配置——直接复制 TurnContext
/// - 所有审批与压缩判定都在 TurnContext 范围内做，避免隐式全局状态
#[derive(Debug, Clone)]
pub struct TurnContext {
    /// 模型 id（具体由 ModelClient 负责解析）
    pub model: String,
    /// 启用的工具名列表（已经过 AgentDefinition.allowed_tools 过滤）
    pub enabled_tools: Vec<String>,
    /// 是否启用流式
    pub stream: bool,
    /// 审批策略（来自 AgentDefinition）
    pub permission_policy: PermissionPolicy,
    /// 压缩策略
    pub compaction_policy: CompactionPolicy,
    /// Token / 迭代预算
    pub budget: TokenBudget,
}

impl TurnContext {
    pub fn new(model: String, enabled_tools: Vec<String>, stream: bool) -> Self {
        Self {
            model,
            enabled_tools,
            stream,
            permission_policy: PermissionPolicy::default(),
            compaction_policy: CompactionPolicy::default(),
            budget: TokenBudget::default(),
        }
    }
}

