            *self.last_req.lock().unwrap() = Some(req);
            Ok(ModelResponse::Done {
                text: "done".to_string(),
                reasoning: String::new(),
                reasoning_signature: String::new(),
                attachments: vec![],
                usage: Usage::default(),
                finish: model_gateway::types::FinishReason::Stop,
