//! Workspace：单次对话的文件访问边界。
//!
//! 每个对话有独立的 workspace（默认 `~/`）。允许路径分三层：
//!
//! - **initial**：对话起始时锁定的快照。**只有这一层会进首条 user message 的
//!   `<environment>` 块**（由 [`crate::system_prompt::EnvironmentSnapshot`] 渲染）。
//! - **runtime_announced**：对话开始之后追加的路径，且已经通过上一条 user message
//!   的 `<workspace-update>` 通知过模型。仅用于 `allows()` 判定。
//! - **runtime_pending**：刚追加、还没通知模型的路径。下一次 [`take_pending_announcement`]
//!   会把它们 drain 出来供上层注入到下条 user message，然后移入 announced。
//!
//! workspace 数据**完全不进 system 段**。system 段由 [`crate::system_prompt`] 单独管理，
//! 跨会话保持字节稳定，方便 prompt cache 命中。
//!
//! [`take_pending_announcement`]: Workspace::take_pending_announcement

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, RwLock};

#[derive(Debug)]
pub struct Workspace {
    workdir: PathBuf,
    /// 对话起始时确定，整个生命周期不变。进 system XML。
    initial_allowed_paths: Vec<PathBuf>,
    /// 已通知模型的运行时追加路径。仅 `allows()` 使用。
    runtime_announced: RwLock<Vec<PathBuf>>,
    /// 还没通知模型的运行时追加路径。下次 user message 注入。
    runtime_pending: Mutex<Vec<PathBuf>>,
}

impl Workspace {
    /// 默认 workspace：`~/`，无额外允许路径。
    pub fn home_default() -> Arc<Self> {
        Self::with_runtime_state(
            dirs::home_dir().unwrap_or_else(|| PathBuf::from("/")),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        )
    }

    /// 全新会话使用：只给 initial。
    pub fn new(workdir: impl Into<PathBuf>, initial_allowed_paths: Vec<PathBuf>) -> Arc<Self> {
        Self::with_runtime_state(workdir, initial_allowed_paths, Vec::new(), Vec::new())
    }

    /// 从持久化恢复：把上次落盘的 announced + pending 一并塞回来。
    /// 三个集合之间相互去重——pending 中已存在于 initial / announced 的项会被剔除，
    /// announced 中已存在于 initial 的项也会被剔除，避免重复通知 / 重复 allows() 检查。
    ///
    /// 相对路径基于 workdir 解析为绝对路径，保证 `allows()` 的 canonicalize 不受
    /// 进程 CWD 影响（Desktop CWD = `/`，CLI CWD 不定）。
    pub fn with_runtime_state(
        workdir: impl Into<PathBuf>,
        initial_allowed_paths: Vec<PathBuf>,
        runtime_announced: Vec<PathBuf>,
        runtime_pending: Vec<PathBuf>,
    ) -> Arc<Self> {
        let workdir: PathBuf = workdir.into();
        let resolve = |paths: Vec<PathBuf>| -> Vec<PathBuf> {
            paths
                .into_iter()
                .map(|p| if p.is_relative() { workdir.join(&p) } else { p })
                .collect()
        };
        let initial = dedup(resolve(initial_allowed_paths));
        let announced: Vec<PathBuf> = dedup(resolve(runtime_announced))
            .into_iter()
            .filter(|p| !initial.contains(p))
            .collect();
        let pending: Vec<PathBuf> = dedup(resolve(runtime_pending))
            .into_iter()
            .filter(|p| !initial.contains(p) && !announced.contains(p))
            .collect();
        Arc::new(Self {
            workdir,
            initial_allowed_paths: initial,
            runtime_announced: RwLock::new(announced),
            runtime_pending: Mutex::new(pending),
        })
    }

    pub fn workdir(&self) -> &Path {
        &self.workdir
    }

    pub fn initial_allowed_paths(&self) -> &[PathBuf] {
        &self.initial_allowed_paths
    }

    pub fn runtime_announced_snapshot(&self) -> Vec<PathBuf> {
        self.runtime_announced.read().unwrap().clone()
    }

    pub fn runtime_pending_snapshot(&self) -> Vec<PathBuf> {
        self.runtime_pending.lock().unwrap().clone()
    }

    /// initial + announced + pending 合并去重，UI / 描述用。
    pub fn allowed_paths_snapshot(&self) -> Vec<PathBuf> {
        let mut out = self.initial_allowed_paths.clone();
        for p in self.runtime_announced.read().unwrap().iter() {
            if !out.contains(p) {
                out.push(p.clone());
            }
        }
        for p in self.runtime_pending.lock().unwrap().iter() {
            if !out.contains(p) {
                out.push(p.clone());
            }
        }
        out
    }

    /// 运行时扩展允许路径：已存在则跳过，否则进 pending（下次 user message 通知模型）。
    pub fn add_allowed_path(&self, path: impl Into<PathBuf>) {
        let path = path.into();
        if self.initial_allowed_paths.iter().any(|d| d == &path) {
            return;
        }
        if self
            .runtime_announced
            .read()
            .unwrap()
            .iter()
            .any(|d| d == &path)
        {
            return;
        }
        let mut pending = self.runtime_pending.lock().unwrap();
        if !pending.iter().any(|d| d == &path) {
            pending.push(path);
        }
    }

    /// 把 pending 全部移入 announced，返回被移走的列表（顺序保留）。
    /// 上层在 `Session::append_user` 之前调用，用于在下条 user message 头部
    /// 注入 `<workspace-update>` 通知模型。
    pub fn take_pending_announcement(&self) -> Vec<PathBuf> {
        let mut pending = self.runtime_pending.lock().unwrap();
        if pending.is_empty() {
            return Vec::new();
        }
        let drained: Vec<PathBuf> = pending.drain(..).collect();
        let mut announced = self.runtime_announced.write().unwrap();
        for p in &drained {
            if !announced.iter().any(|d| d == p) {
                announced.push(p.clone());
            }
        }
        drained
    }

    /// 路径是否在允许范围内：先 canonicalize 再做前缀匹配，防止 `..` 绕过。
    /// canonicalize 失败时退回到 `canonicalize_lossy`（处理"打算写入但还未创建"的场景）。
    pub fn allows(&self, path: &Path) -> bool {
        if is_unrestricted_device(path) {
            return true;
        }
        let canon = canonicalize_lossy(path);
        if canon.starts_with(canonicalize_lossy(&self.workdir)) {
            return true;
        }
        for root in &self.initial_allowed_paths {
            if canon.starts_with(canonicalize_lossy(root)) {
                return true;
            }
        }
        for root in self.runtime_announced.read().unwrap().iter() {
            if canon.starts_with(canonicalize_lossy(root)) {
                return true;
            }
        }
        for root in self.runtime_pending.lock().unwrap().iter() {
            if canon.starts_with(canonicalize_lossy(root)) {
                return true;
            }
        }
        false
    }

    /// 给 Bash 用：解析 cwd 字段。未指定 → workdir。
    pub fn resolve_cwd(&self, cwd: Option<&str>) -> PathBuf {
        match cwd {
            None | Some("") => self.workdir.clone(),
            Some(p) => PathBuf::from(p),
        }
    }

    /// UI/错误提示用的人类可读描述。
    pub fn describe(&self) -> String {
        let mut s = format!("workdir: {}", self.workdir.display());
        let all = self.allowed_paths_snapshot();
        if !all.is_empty() {
            s.push_str("\nallowed_paths:");
            for d in &all {
                s.push_str(&format!("\n  - {}", d.display()));
            }
        }
        s
    }
}

fn dedup(mut v: Vec<PathBuf>) -> Vec<PathBuf> {
    let mut seen: Vec<PathBuf> = Vec::with_capacity(v.len());
    v.retain(|p| {
        if seen.iter().any(|s| s == p) {
            false
        } else {
            seen.push(p.clone());
            true
        }
    });
    v
}

/// 无危害的设备路径：读永远 EOF/zero/random，写要么丢弃要么只进流，不存在
/// 文件系统副作用。对这些路径的访问不需要审批。
fn is_unrestricted_device(path: &Path) -> bool {
    let s = path.to_string_lossy();
    // Unix device files — writing to null/zero is discarded, reading is EOF/zeros
    if s == "/dev/null" || s == "/dev/zero" || s == "/dev/random" || s == "/dev/urandom" {
        return true;
    }
    // Windows null device
    if s.eq_ignore_ascii_case("nul") || s.eq_ignore_ascii_case("\\\\.\\nul") {
        return true;
    }
    false
}

fn canonicalize_lossy(path: &Path) -> PathBuf {
    if let Ok(p) = std::fs::canonicalize(path) {
        return p;
    }
    // 路径或祖先不存在时（比如 Write 之前的目标文件），向上找第一个存在的祖先做 canonicalize，
    // 然后把剩余的相对部分原样拼回来——这样不存在的尾部不影响越界判定。
    let mut suffix: Vec<&std::ffi::OsStr> = Vec::new();
    let mut cur = path;
    loop {
        if let Ok(p) = std::fs::canonicalize(cur) {
            let mut out = p;
            for part in suffix.iter().rev() {
                out.push(part);
            }
            return out;
        }
        match (cur.parent(), cur.file_name()) {
            (Some(parent), Some(name)) => {
                suffix.push(name);
                cur = parent;
            }
            _ => break,
        }
    }
    path.to_path_buf()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn allows_paths_inside_workdir() {
        let tmp = tempfile::tempdir().unwrap();
        let ws = Workspace::new(tmp.path(), Vec::new());

        assert!(ws.allows(&tmp.path().join("a.txt")));
        assert!(ws.allows(&tmp.path().join("nested/dir/b.txt")));
    }

    #[test]
    fn rejects_paths_outside_workdir() {
        let tmp = tempfile::tempdir().unwrap();
        let ws = Workspace::new(tmp.path(), Vec::new());

        assert!(!ws.allows(Path::new("/etc/passwd")));
    }

    #[test]
    fn add_allowed_path_takes_effect_immediately() {
        let tmp = tempfile::tempdir().unwrap();
        let extra = tempfile::tempdir().unwrap();
        let ws = Workspace::new(tmp.path(), Vec::new());

        assert!(!ws.allows(&extra.path().join("x")));
        ws.add_allowed_path(extra.path());
        assert!(ws.allows(&extra.path().join("x")));
    }

    #[test]
    fn add_allowed_path_lands_in_pending_until_announced() {
        let tmp = tempfile::tempdir().unwrap();
        let extra = tempfile::tempdir().unwrap();
        let ws = Workspace::new(tmp.path(), Vec::new());

        ws.add_allowed_path(extra.path());
        assert!(ws.runtime_announced_snapshot().is_empty());
        assert_eq!(ws.runtime_pending_snapshot().len(), 1);

        let drained = ws.take_pending_announcement();
        assert_eq!(drained.len(), 1);
        assert_eq!(ws.runtime_announced_snapshot().len(), 1);
        assert!(ws.runtime_pending_snapshot().is_empty());

        // 再 take 不会重复
        assert!(ws.take_pending_announcement().is_empty());
    }

    #[test]
    fn add_allowed_path_skips_existing_in_initial_or_announced() {
        let tmp = tempfile::tempdir().unwrap();
        let already = tempfile::tempdir().unwrap();
        let ws = Workspace::with_runtime_state(
            tmp.path(),
            vec![already.path().to_path_buf()],
            Vec::new(),
            Vec::new(),
        );
        ws.add_allowed_path(already.path());
        assert!(ws.runtime_pending_snapshot().is_empty());
    }

    #[test]
    fn relative_allowed_paths_resolved_against_workdir() {
        let tmp = tempfile::tempdir().unwrap();
        let workdir = tmp.path().join("project");
        let sibling = tmp.path().join("sibling");
        let nested = workdir.join("sub");
        std::fs::create_dir_all(&workdir).unwrap();
        std::fs::create_dir_all(&sibling).unwrap();
        std::fs::create_dir_all(&nested).unwrap();

        let ws = Workspace::new(
            &workdir,
            vec![
                PathBuf::from("../sibling"),      // 相对路径
                PathBuf::from("sub"),              // 相对路径
                sibling.clone(),                   // 绝对路径，不该被改
            ],
        );

        // 相对路径 "../sibling" 应被解析为 workdir/../sibling
        assert!(ws.allows(&sibling.join("file.txt")));
        // 相对路径 "sub" 应被解析为 workdir/sub
        assert!(ws.allows(&nested.join("deep/file.txt")));
        // 绝对路径原封不动
        assert!(ws.allows(&sibling.join("another.txt")));
    }
}

crates/agent-core/tests/edit_backend_swi.content:
//! 验证 settings.general.edit_backend 切换时，Read 和 Edit 工具对（含 description / schema）整体被替换。
//!
//! 用户问："设置里的开关可以一键切换回原来的 edit/read 吗包括 prompt"
//! 答：是的——本测试就是证据：注册产物里的 description（即模型看到的 prompt）与 schema 整体跟着 enum 走。

use agent_core::storage::settings::EditBackend;
use agent_core::tools::{background::BgTaskRegistry, default_tools};
use agent_core::wakeup::new_phase_channel;
use agent_core::workspace::Workspace;
use serde_json::Value;

fn build_tools(backend: EditBackend) -> Vec<(String, String, Value)> {
    let tmp = tempfile::tempdir().unwrap();
    let workspace = Workspace::new(tmp.path(), Vec::new());
    let phase = new_phase_channel();
    let shells = BgTaskRegistry::new();

    let tools = default_tools(
        workspace,
        &[],
        None,
        phase,
        shells,
        Some(tmp.path().to_path_buf()),
        None,
        None,
        None,
        backend,
    );

    tools
        .into_iter()
        .map(|t| {
            (
                t.name().to_string(),
                t.description().to_string(),
                t.parameters_schema(),
            )
        })
        .collect()
}

fn find<'a>(tools: &'a [(String, String, Value)], name: &str) -> &'a (String, String, Value) {
    tools.iter().find(|(n, _, _)| n == name).expect("tool")
}

#[test]
fn string_replace_backend_registers_string_replace_edit() {
    let tools = build_tools(EditBackend::StringReplace);
    let (_, _, schema) = find(&tools, "Edit");
    let props = schema["properties"].as_object().unwrap();
    assert!(
        props.contains_key("old_string") && props.contains_key("new_string"),
        "string-replace 后端 Edit schema 必须含 old_string/new_string，实际: {props:?}"
    );
    assert!(
        !props.contains_key("patch"),
        "string-replace 后端 schema 不应有 patch 字段"
    );
}

#[test]
fn hashline_backend_registers_hashline_edit() {
    let tools = build_tools(EditBackend::Hashline);
    let (_, _, schema) = find(&tools, "Edit");
    let props = schema["properties"].as_object().unwrap();
    assert!(
        props.contains_key("patch"),
        "hashline 后端 Edit schema 必须含 patch，实际: {props:?}"
    );
    assert!(
        !props.contains_key("old_string"),
        "hashline 后端 schema 不应有 old_string"
    );
}

#[test]
fn switching_backend_swaps_edit_description_prompt() {
    let sr = build_tools(EditBackend::StringReplace);
    let hl = build_tools(EditBackend::Hashline);

    let (_, sr_desc, _) = find(&sr, "Edit");
    let (_, hl_desc, _) = find(&hl, "Edit");

    assert_ne!(sr_desc, hl_desc, "两种后端的 Edit description 必须不同");
    assert!(
        sr_desc.contains("old_string"),
        "string-replace description 应提及 old_string"
    );
    assert!(
        hl_desc.contains("Hashline") || hl_desc.contains("hashline") || hl_desc.contains("¶"),
        "hashline description 应是 prompt.md 内容（含 Hashline 关键词或 ¶ 符号）"
    );
}

#[test]
fn switching_backend_swaps_read_output_format_description() {
    let sr = build_tools(EditBackend::StringReplace);
    let hl = build_tools(EditBackend::Hashline);

    let (_, sr_desc, _) = find(&sr, "Read");
    let (_, hl_desc, _) = find(&hl, "Read");

    assert_ne!(sr_desc, hl_desc, "两种后端的 Read description 必须不同");
    assert!(
        hl_desc.contains("hashline") || hl_desc.contains("¶") || hl_desc.contains("HASH"),
        "hashline Read description 应说明新输出格式: {hl_desc}"
    );
}

#[test]
fn other_tools_remain_identical_across_backends() {
    let sr = build_tools(EditBackend::StringReplace);
    let hl = build_tools(EditBackend::Hashline);

    // Bash / Grep / TodoWrite 等不应受 edit_backend 影响
    for name in ["Bash", "Grep", "TodoWrite", "WebSearch"] {
        let (_, sr_desc, sr_schema) = find(&sr, name);
        let (_, hl_desc, hl_schema) = find(&hl, name);
        assert_eq!(
            sr_desc, hl_desc,
            "{name} description 不应被 edit_backend 影响"
        );
        assert_eq!(
            sr_schema, hl_schema,
            "{name} schema 不应被 edit_backend 影响"
        );
    }
}

#[test]
fn tool_count_identical_across_backends() {
    let sr = build_tools(EditBackend::StringReplace);
    let hl = build_tools(EditBackend::Hashline);
    assert_eq!(
        sr.len(),
        hl.len(),
        "两个后端的工具总数必须相同：仅 Read+Edit 实现切换，其他工具不变"
    );
}

/// 用 `--nocapture` 运行查看两种后端下 Edit / Read 的注册产物对比：
///   cargo test -p agent-core --test edit_backend_switch dump_for_humans -- --nocapture
#[test]
fn dump_for_humans() {
    for backend in [EditBackend::StringReplace, EditBackend::Hashline] {
        let label = match backend {
            EditBackend::StringReplace => "string-replace",
            EditBackend::Hashline => "hashline",
        };
        let tools = build_tools(backend);
        let (_, edit_desc, edit_schema) = find(&tools, "Edit");
        let (_, read_desc, _) = find(&tools, "Read");

        println!("\n=========== [{label}] Edit schema ===========");
        println!("{}", serde_json::to_string_pretty(edit_schema).unwrap());
        println!("\n=========== [{label}] Edit description (first 400 chars) ===========");
        println!("{}", edit_desc.chars().take(400).collect::<String>());
        println!("\n=========== [{label}] Read description (first 400 chars) ===========");
        println!("{}", read_desc.chars().take(400).collect::<String>());
    }
}

crates/agent-core/tests/hashline_roundtr.content:
use agent_core::edits::hashline::format::hash3;
use agent_core::read_state::ReadStateTracker;
use agent_core::tools::edit_hashline::EditHashlineTool;
use agent_core::tools::read_hashline::ReadHashlineTool;
use agent_core::tools::Tool;
use agent_core::workspace::Workspace;
use serde_json::json;
use std::sync::Arc;
use std::time::{Duration, SystemTime};

fn make_tools(
    tmp: &tempfile::TempDir,
) -> (ReadHashlineTool, EditHashlineTool, Arc<ReadStateTracker>) {
    let tracker = Arc::new(ReadStateTracker::new());
    let ws = Workspace::new(tmp.path(), Vec::new());
    let read_tool = ReadHashlineTool::new(None, None, Some(tracker.clone()));
    let edit_tool = EditHashlineTool::new(ws, Some(tracker.clone()));
    (read_tool, edit_tool, tracker)
}

async fn mark_read(tracker: &ReadStateTracker, path: &std::path::Path) {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    let mtime_ms = std::fs::metadata(path)
        .ok()
        .and_then(|m| m.modified().ok())
        .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0);
    let content = std::fs::read(path).unwrap_or_default();
    let mut hasher = DefaultHasher::new();
    content.hash(&mut hasher);
    tracker.record(path, hasher.finish(), mtime_ms);
}

#[tokio::test]
async fn read_then_edit_roundtrip() {
    let tmp = tempfile::tempdir().unwrap();
    let (read_tool, edit_tool, tracker) = make_tools(&tmp);

    let file = tmp.path().join("src/lib.rs");
    std::fs::create_dir_all(file.parent().unwrap()).unwrap();
    let original: String = (1..=10).map(|i| format!("line {i}\n")).collect();
    std::fs::write(&file, &original).unwrap();

    // 1) Read → 确认 hashline 格式
    let read_out = read_tool
        .execute(json!({ "file_path": file.to_string_lossy() }))
        .await
        .unwrap();

    let h1 = hash3(&original);
    assert!(
        read_out.starts_with("¶"),
        "Read 输出必须以 ¶ 开头: {read_out:.80}"
    );
    assert!(
        read_out.contains(&format!("#{h1}\n")),
        "Read 输出必须含 hash #{h1}: {read_out:.120}"
    );
    assert!(read_out.contains("\n5:line 5\n"), "行号 5 内容匹配");

    // 2) Edit：替换第 4-6 行
    mark_read(&tracker, &file).await;
    let patch = format!(
        "¶{}#{h1}\n4 6\n+L4-new\n+L5-new\n+L6-new\n",
        file.to_string_lossy()
    );
    edit_tool.execute(json!({ "patch": patch })).await.unwrap();

    let after = std::fs::read_to_string(&file).unwrap();
    let expected: String = [
        "line 1", "line 2", "line 3", "L4-new", "L5-new", "L6-new", "line 7", "line 8", "line 9",
        "line 10",
    ]
    .iter()
    .map(|s| format!("{s}\n"))
    .collect();
    assert_eq!(after, expected, "Edit 结果不符");

    // 3) 再次 Read，确认新 hash 与旧不同
    let h2 = hash3(&after);
    assert_ne!(h1, h2, "Edit 后 hash 必须变化");
    let read_out2 = read_tool
        .execute(json!({ "file_path": file.to_string_lossy() }))
        .await
        .unwrap();
    assert!(
        read_out2.contains(&format!("#{h2}\n")),
        "第二次 Read 必须含新 hash #{h2}: {read_out2:.120}"
    );
}

#[tokio::test]
async fn stale_hash_rejected_after_external_write() {
    let tmp = tempfile::tempdir().unwrap();
    let (read_tool, edit_tool, tracker) = make_tools(&tmp);

    let file = tmp.path().join("a.txt");
    std::fs::write(&file, "original\n").unwrap();

    // Read 登记
    read_tool
        .execute(json!({ "file_path": file.to_string_lossy() }))
        .await
        .unwrap();
    mark_read(&tracker, &file).await;

    // 外部修改文件（sleep 1ms 确保 mtime 变化）
    std::thread::sleep(Duration::from_millis(10));
    std::fs::write(&file, "externally-modified\n").unwrap();

    // 用旧 hash 试图 Edit
    let old_hash = hash3("original\n");
    let patch = format!("¶{}#{old_hash}\n1 1\n+z\n", file.to_string_lossy());
    let err = edit_tool
        .execute(json!({ "patch": patch }))
        .await
        .unwrap_err();
    let s = err.to_string();
    assert!(
        s.to_lowercase().contains("stale")
            || s.to_lowercase().contains("hash")
            || s.contains("修改")
            || s.contains("modified"),
        "stale hash 或 tracker mtime 检测必须失败: {err}"
    );
}

#[tokio::test]
async fn eof_append_roundtrip() {
    let tmp = tempfile::tempdir().unwrap();
    let (read_tool, edit_tool, tracker) = make_tools(&tmp);

    let file = tmp.path().join("b.txt");
    std::fs::write(&file, "head\n").unwrap();

    read_tool
        .execute(json!({ "file_path": file.to_string_lossy() }))
        .await
        .unwrap();
    mark_read(&tracker, &file).await;

    let h = hash3("head\n");
    let patch = format!("¶{}#{h}\nEOF\n+tail\n", file.to_string_lossy());
    edit_tool.execute(json!({ "patch": patch })).await.unwrap();

    assert_eq!(std::fs::read_to_string(&file).unwrap(), "head\ntail\n");
}

#[tokio::test]
async fn keep_range_roundtrip() {
    let tmp = tempfile::tempdir().unwrap();
    let (read_tool, edit_tool, tracker) = make_tools(&tmp);

    let file = tmp.path().join("c.txt");
    let original = "A\nB\nC\nD\nE\n";
    std::fs::write(&file, original).unwrap();

    read_tool
        .execute(json!({ "file_path": file.to_string_lossy() }))
        .await
        .unwrap();
    mark_read(&tracker, &file).await;

    let h = hash3(original);
    // 替换 1..5：TOP + 保留 2..4 + BOTTOM
    let patch = format!(
        "¶{}#{h}\n1 5\n+TOP\n&2..4\n+BOTTOM\n",
        file.to_string_lossy()
    );
    edit_tool.execute(json!({ "patch": patch })).await.unwrap();
    assert_eq!(
        std::fs::read_to_string(&file).unwrap(),
        "TOP\nB\nC\nD\nBOTTOM\n"
    );
}

