use common::storage;
use common::{AppError, AppResult};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::Path;

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ProviderKind {
    Openai,
    Anthropic,
    Gemini,
    /// DeepSeek `chat.deepseek.com` 网页端协议（PoW + 路径式 SSE），
    /// 用账号登录拿到的 token 走这一路。
    Deepseek,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum AuthMode {
    ApiKey,
    OauthCodex,
    OauthClaudeCode,
    OauthGeminiCli,
}

impl Default for AuthMode {
    fn default() -> Self {
        AuthMode::ApiKey
    }
}

fn default_enabled() -> bool {
    true
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Provider {
    pub id: String,
    pub name: String,
    pub kind: ProviderKind,
    #[serde(default = "default_enabled")]
    pub enabled: bool,
    #[serde(default)]
    pub auth_mode: AuthMode,
    pub base_url: String,
    pub api_key: String,
    #[serde(default)]
    pub refresh_token: Option<String>,
    #[serde(default)]
    pub token_expires_at: Option<i64>,
    #[serde(default)]
    pub account_id: Option<String>,
    #[serde(default)]
    pub extra_headers: BTreeMap<String, String>,
    #[serde(default)]
    pub models: Vec<String>,
    /// 从 provider `/models` 端点拉取的全量模型 ID 列表（缓存）。
    /// 用于在 UI 关闭再打开时，无需重新拉取即可展示模型列表。
    /// 拉取时按 ID 合并：新模型追加，已存在的保留。
    #[serde(default)]
    pub fetched_models: Option<Vec<String>>,
    #[serde(default)]
    pub default_model: Option<String>,
    /// 是否把这个 provider 用作「标题生成模型」。整个配置最多一个 provider 应该勾上；
    /// 多于一个时 desktop 会取第一个匹配。
    #[serde(default)]
    pub title_gen_enabled: bool,
    /// 配合 `title_gen_enabled` 的具体模型 id（必须在 `models` 列表里）。
    #[serde(default)]
    pub title_gen_model: Option<String>,
    /// 是否在请求体里注入 Claude Code 客户端特征（banner / billing header /
    /// metadata.user_id / context_management），让请求伪装成 Claude Code CLI 流量。
    /// 默认 false。与 auth_mode 独立——OAuth 模式自动注入，此开关让 API Key
    /// 模式也能注入。
    #[serde(default)]
    pub claude_code_compat: bool,
}

#[derive(Debug, Default, Serialize, Deserialize)]
pub struct ProvidersFile {
    #[serde(default)]
    pub providers: Vec<Provider>,
    #[serde(default)]
    pub default_provider_id: Option<String>,
    /// 视觉辅助模型：当目标模型不支持图片输入时，用这个 provider + model
    /// 先"看图"生成文字描述，替换掉原始图片附件。
    #[serde(default)]
    pub vision_provider_id: Option<String>,
    #[serde(default)]
    pub vision_model: Option<String>,
}

pub fn load(data_dir: &Path) -> AppResult<ProvidersFile> {
    let path = storage::providers_path(data_dir);
    storage::read_json(&path)
}

pub fn save(data_dir: &Path, file: &ProvidersFile) -> AppResult<()> {
    let path = storage::providers_path(data_dir);
    storage::write_json(&path, file)
}

pub fn get(data_dir: &Path, id: &str) -> AppResult<Provider> {
    load(data_dir)?
        .providers
        .into_iter()
        .find(|p| p.id == id)
        .ok_or_else(|| AppError::msg(format!("provider {id} not found")))
}

pub fn upsert(data_dir: &Path, provider: Provider) -> AppResult<Provider> {
    let mut file = load(data_dir)?;
    if let Some(existing) = file.providers.iter_mut().find(|p| p.id == provider.id) {
        *existing = provider.clone();
    } else {
        file.providers.push(provider.clone());
    }
    save(data_dir, &file)?;
    Ok(provider)
}

/// 更新指定 provider 的 fetched_models 缓存（合并：新模型追加，已存在保留）
pub fn update_fetched_models(
    data_dir: &Path,
    provider_id: &str,
    new_model_ids: Vec<String>,
) -> AppResult<()> {
    let mut file = load(data_dir)?;
    if let Some(provider) = file.providers.iter_mut().find(|p| p.id == provider_id) {
        let mut cached = provider.fetched_models.clone().unwrap_or_default();
        for id in new_model_ids {
            if !cached.iter().any(|m| *m == id) {
                cached.push(id);
            }
        }
        cached.sort();
        provider.fetched_models = Some(cached);
    }
    save(data_dir, &file)
}

