use async_trait::async_trait;
use reqwest::RequestBuilder;
use serde_json::{json, Value};
use std::collections::BTreeMap;
use tracing::debug;

use crate::config::{AuthMode, Provider};
use crate::{
    client::ModelClient,
    protocols::anthropic as proto,
    providers::apply_auth,
    types::{
        has_image_generation_tool, ModelError, ModelRequest, ModelResponse, ModelStreamEvent,
        ToolCall, ToolCallStreamDelta, Usage,
    },
};
use common::reasoning::{anthropic_long_context_uses_beta, ANTHROPIC_LONG_CONTEXT_BETA};
use common::CancelFlag;

/// 给 Anthropic 请求按需附加 beta 特性头。当前只处理 1M context（其余 beta
/// 由 [`apply_auth`] 在 OAuth 分支里固定带上）。
fn apply_optional_betas(req: RequestBuilder, attach_long_context: bool) -> RequestBuilder {
    if !attach_long_context {
        return req;
    }
    // 重复传 anthropic-beta 是允许的：服务端对所有出现的值取并集。
    req.header("anthropic-beta", ANTHROPIC_LONG_CONTEXT_BETA)
}

/// 从 [`ModelRequest`] 算出本次请求是否需要 1M context beta header。
fn needs_long_context_beta(req: &ModelRequest) -> bool {
    let wants_long = req
        .reasoning
        .as_ref()
        .map(|r| r.wants_long_context())
        .unwrap_or(false);
    wants_long && anthropic_long_context_uses_beta(&req.model)
}

pub struct AnthropicClient {
    provider: Provider,
    http: reqwest::Client,
}

impl AnthropicClient {
    pub fn new(provider: Provider) -> Result<Self, ModelError> {
        let http = super::build_http_client()?;
        Ok(Self { provider, http })
    }

    fn messages_url(&self) -> String {
        format!(
            "{}/v1/messages",
            self.provider.base_url.trim_end_matches('/')
        )
    }

    /// 走 `complete()` 拿到完整响应后，把 reasoning / text / tool_use 一次性 emit
    /// 成 stream events，让上层 (`agent_loop`) 看起来像走了 stream 路径。
    /// 用于 Opus 4.7 + thinking 这种 stream 模式服务端不发 thinking_delta 的场景。
    async fn complete_then_emit(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    ) -> Result<ModelResponse, ModelError> {
        tracing::info!(model = %req.model, "anthropic: 4.7 thinking → complete_then_emit");
        let resp = self.complete(req, cancel).await?;
        match &resp {
            ModelResponse::Done {
                text, reasoning, ..
            } => {
                tracing::info!(
                    reasoning_len = reasoning.len(),
                    text_len = text.len(),
                    "anthropic complete_then_emit: Done"
                );
                if !reasoning.is_empty() {
                    on_event(ModelStreamEvent::ReasoningDelta {
                        text: reasoning.clone(),
                    });
                }
                if !text.is_empty() {
                    on_event(ModelStreamEvent::TextDelta { text: text.clone() });
                }
            }
            ModelResponse::ToolCalls {
                text,
                reasoning,
                calls,
                ..
            } => {
                if !reasoning.is_empty() {
                    on_event(ModelStreamEvent::ReasoningDelta {
                        text: reasoning.clone(),
                    });
                }
                if !text.is_empty() {
                    on_event(ModelStreamEvent::TextDelta { text: text.clone() });
                }
                for (i, call) in calls.iter().enumerate() {
                    on_event(ModelStreamEvent::ToolCallDelta(ToolCallStreamDelta {
                        index: i,
                        id: Some(call.id.clone()),
                        name: Some(call.name.clone()),
                        arguments_delta: Some(call.input.to_string()),
                    }));
                }
            }
        }
        Ok(resp)
    }

    fn is_claude_code_oauth(&self) -> bool {
        matches!(self.provider.auth_mode, AuthMode::OauthClaudeCode)
            || self.provider.claude_code_compat
    }
}

#[async_trait]
impl ModelClient for AnthropicClient {
    fn provider_id(&self) -> &str {
        &self.provider.id
    }

    fn supports_streaming_tools(&self) -> bool {
        // Anthropic SSE 已经能流式发 tool_use（content_block_start + input_json_delta）；
        // 我们的 stream() 实现支持解析这两种，所以可以让 agent_loop 在带 tools 的 turn
        // 也走流式路径，从而实时拿到 thinking_delta。
        true
    }

    async fn complete(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
    ) -> Result<ModelResponse, ModelError> {
        reject_image_generation_tool(&req)?;
        tracing::info!(model = %req.model, "anthropic complete: dispatched");
        let body = proto::build_body(&req, false, self.is_claude_code_oauth())?;
        let attach_long = needs_long_context_beta(&req);

        if let Some(thinking) = body.get("thinking") {
            debug!(model = %req.model, thinking = %thinking, "anthropic complete: thinking field");
        }

        super::retry_request(cancel, || {
            let body = body.clone();
            async move {
                let resp = apply_optional_betas(
                    apply_auth(self.http.post(self.messages_url()), &self.provider),
                    attach_long,
                )
                .json(&body)
                .send()
                .await?;
                let status = resp.status().as_u16();
                let text = resp.text().await?;
                if status >= 400 {
                    return Err(ModelError::Http { status, body: text });
                }
                let v: Value = serde_json::from_str(&text)?;
                Ok(proto::parse_response(&v))
            }
        })
        .await
    }

    async fn stream(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    ) -> Result<ModelResponse, ModelError> {
        // Opus 4.7 在 stream 模式下不发 thinking_delta（实测：只有 signature_delta），
        // 即使显式 display:"summarized" 也没用。要拿到 thinking 文本只能走 complete()。
        // 这里检查到「4.7 + thinking 启用」就回退到 complete，保证 thinking 能落地；
        // 拿到完整 reasoning 后一次性 emit ReasoningDelta，再分别 emit text 和 tool_use。
        if matches!(
            common::reasoning::anthropic_thinking_mode(&req.model),
            Some(common::reasoning::AnthropicThinkingMode::Opus47Adaptive)
        ) && req
            .reasoning
            .as_ref()
            .map(|r| r.is_enabled())
            .unwrap_or(false)
        {
            return self.complete_then_emit(req, cancel, on_event).await;
        }

        reject_image_generation_tool(&req)?;
        let body = proto::build_body(&req, true, self.is_claude_code_oauth())?;
        let attach_long = needs_long_context_beta(&req);
        tracing::info!(
            model = %req.model,
            stream = %body.get("stream").map(|v| v.to_string()).unwrap_or_default(),
            thinking = %body.get("thinking").map(|v| v.to_string()).unwrap_or_else(|| "(none)".into()),
            output_config = %body.get("output_config").map(|v| v.to_string()).unwrap_or_else(|| "(none)".into()),
            "anthropic stream: dispatched"
        );

        let resp = super::retry_request(cancel.clone(), || {
            let body = body.clone();
            async move {
                let r = apply_optional_betas(
                    apply_auth(self.http.post(self.messages_url()), &self.provider),
                    attach_long,
                )
                .json(&body)
                .send()
                .await?;
                let status = r.status().as_u16();
                if status >= 400 {
                    let body = r.text().await?;
                    return Err(ModelError::Http { status, body });
                }
                Ok(r)
            }
        })
        .await?;

        let mut stream = resp.bytes_stream();
        let mut buf = String::new();
        let mut full_text = String::new();
        let mut full_reasoning = String::new();
        let mut full_signature = String::new();
        let mut current_event_type = String::new();
        let mut thinking_deltas_seen: u64 = 0;

        // tool_use 累积：按 Anthropic content block index 跟踪每个 tool 的 id/name/args。
        // 用 BTreeMap 保留 index 顺序；ToolCallStreamDelta.index 同时透给上层。
        struct ToolAccum {
            id: String,
            name: String,
            args: String,
        }
        let mut tools: BTreeMap<usize, ToolAccum> = BTreeMap::new();
        let mut stop_reason: Option<String> = None;
        // Anthropic 流的 usage 分两次到：message_start 给输入 / 缓存命中 / 缓存写入，
        // message_delta 给最终 output_tokens。最后合并成完整 Usage 跟着 ModelResponse 回去。
        let mut usage = Usage::default();

        while let Some(chunk) = super::next_stream_chunk_or_cancel(&mut stream, &cancel).await? {
            buf.push_str(&String::from_utf8_lossy(&chunk));

            // Anthropic SSE: event: <type>\ndata: <json>\n\n
            while let Some(pos) = buf.find("\n\n").or_else(|| buf.find("\r\n\r\n")) {
                let skip = if buf[pos..].starts_with("\r\n\r\n") {
                    4
                } else {
                    2
                };
                let frame = buf[..pos].to_string();
                buf = buf[pos + skip..].to_string();

                for line in frame.lines() {
                    let line = line.trim_end_matches('\r');
                    if let Some(event) = line.strip_prefix("event:") {
                        current_event_type = event.trim().to_string();
                    } else if let Some(data) = line.strip_prefix("data:") {
                        let data = data.trim();
                        if data.is_empty() {
                            continue;
                        }
                        // SSE `event: error` 帧（上游 overloaded / upstream_error 等）：HTTP 已是
                        // 200，错误只在流里。不拦就会被当未知事件忽略 → 流"正常"结束 → agent_loop
                        // 误判为成功（空回合），既不停也不弹续作。这里转成 Err 让上层正常收尾。
                        if current_event_type == "error" {
                            return Err(ModelError::Other(format!("模型流式返回错误：{data}")));
                        }
                        let Some(parsed) = proto::parse_stream_event(&current_event_type, data)
                        else {
                            tracing::trace!(
                                event_type = %current_event_type,
                                data = %data.chars().take(200).collect::<String>(),
                                "anthropic stream: unparsed event"
                            );
                            continue;
                        };
                        match parsed {
                            proto::AnthropicStreamEvent::Text { delta, .. } => {
                                on_event(ModelStreamEvent::TextDelta {
                                    text: delta.clone(),
                                });
                                full_text.push_str(&delta);
                            }
                            proto::AnthropicStreamEvent::Thinking { delta, .. } => {
                                if thinking_deltas_seen == 0 {
                                    debug!("anthropic stream: first thinking_delta arrived");
                                }
                                thinking_deltas_seen += 1;
                                full_reasoning.push_str(&delta);
                                on_event(ModelStreamEvent::ReasoningDelta { text: delta });
                            }
                            proto::AnthropicStreamEvent::Signature { signature, .. } => {
                                full_signature = signature.clone();
                                on_event(ModelStreamEvent::ReasoningSignature { signature });
                            }
                            proto::AnthropicStreamEvent::ToolUseStart { index, id, name } => {
                                tracing::info!(
                                    sse_index = index,
                                    tool_id = %id,
                                    tool_name = %name,
                                    "anthropic stream: ToolUseStart"
                                );
                                tools.insert(
                                    index,
                                    ToolAccum {
                                        id: id.clone(),
                                        name: name.clone(),
                                        args: String::new(),
                                    },
                                );
                                on_event(ModelStreamEvent::ToolCallDelta(ToolCallStreamDelta {
                                    index,
                                    id: Some(id),
                                    name: Some(name),
                                    arguments_delta: None,
                                }));
                            }
                            proto::AnthropicStreamEvent::ToolInputJsonDelta {
                                index,
                                partial_json,
                            } => {
                                if let Some(acc) = tools.get_mut(&index) {
                                    acc.args.push_str(&partial_json);
                                }
                                on_event(ModelStreamEvent::ToolCallDelta(ToolCallStreamDelta {
                                    index,
                                    id: None,
                                    name: None,
                                    arguments_delta: Some(partial_json),
                                }));
                            }
                            proto::AnthropicStreamEvent::MessageStart { usage: u } => {
                                usage = u;
                            }
                            proto::AnthropicStreamEvent::MessageDelta {
                                stop_reason: sr,
                                usage: u,
                            } => {
                                if sr.is_some() {
                                    stop_reason = sr;
                                }
                                if let Some(delta_usage) = u {
                                    // message_delta 带终态 output_tokens；输入 / 缓存沿用 message_start。
                                    if delta_usage.output_tokens > 0 {
                                        usage.output_tokens = delta_usage.output_tokens;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        if body.get("thinking").is_some() {
            debug!(
                thinking_deltas_seen,
                reasoning_chars = full_reasoning.len(),
                "anthropic stream: finished"
            );
        }

        // 拼成 ModelResponse：stop_reason=tool_use 走 ToolCalls 分支。
        if stop_reason.as_deref() == Some("tool_use") && !tools.is_empty() {
            let calls: Vec<ToolCall> = tools
                .into_values()
                .map(|t| ToolCall {
                    id: t.id,
                    name: t.name,
                    // input_json_delta 拼回来的字符串是合法 JSON；解析失败时退化成
                    // 字符串 value，agent_loop 仍能把原文作为 arguments 传给 tool。
                    input: serde_json::from_str(&t.args).unwrap_or(json!(t.args)),
                })
                .collect();
            return Ok(ModelResponse::ToolCalls {
                text: full_text,
                reasoning: full_reasoning,
                reasoning_signature: full_signature,
                calls,
                attachments: Vec::new(),
                usage,
            });
        }

        Ok(ModelResponse::Done {
            finish: proto::map_anthropic_finish(stop_reason.as_deref().unwrap_or("")),
            text: full_text,
            reasoning: full_reasoning,
            reasoning_signature: full_signature,
            attachments: Vec::new(),
            usage,
        })
    }
}

fn reject_image_generation_tool(req: &ModelRequest) -> Result<(), ModelError> {
    if has_image_generation_tool(&req.tools) {
        return Err(ModelError::Other(
            "image_generation 工具只支持 OpenAI Responses；请切换到 OpenAI provider，或关闭生图工具。"
                .to_string(),
        ));
    }
    Ok(())
}

crates/model-gateway/src/providers/deeps.content:
//! DeepSeek `chat.deepseek.com` web protocol provider。
//!
//! 与 ds2api 等价路径：
//! 1. POST `/api/v0/chat_session/create` 拿 session_id（按 provider 缓存一份）
//! 2. POST `/api/v0/chat/create_pow_challenge` 拿 PoW challenge
//! 3. 本地求解 → 算 `x-ds-pow-response`
//! 4. POST `/api/v0/chat/completion` 流式拉路径式 SSE
//! 5. 边解析边把 Text / Thinking / 出现在最终输出里的 `<tool_calls>` 块
//!    翻译成 `ModelStreamEvent`。
//!
//! 不在内存里跨请求保留 parent_message_id（每次发完整 transcript），与 ds2api 默认行为一致。

use async_trait::async_trait;
use parking_lot::Mutex;
use serde_json::Value;
use std::sync::Arc;

use crate::auth::deepseek_pow::{self, DeepseekChallenge};
use crate::config::Provider;
use crate::protocols::deepseek as proto;
use crate::types::{
    has_image_generation_tool, ModelError, ModelRequest, ModelResponse, ModelStreamEvent,
    ToolCallStreamDelta, Usage,
};
use crate::{client::ModelClient, providers::apply_auth};
use common::CancelFlag;

const SESSION_CREATE_URL: &str = "https://chat.deepseek.com/api/v0/chat_session/create";
const POW_URL: &str = "https://chat.deepseek.com/api/v0/chat/create_pow_challenge";
const COMPLETION_URL: &str = "https://chat.deepseek.com/api/v0/chat/completion";
const COMPLETION_TARGET_PATH: &str = "/api/v0/chat/completion";

pub struct DeepseekClient {
    provider: Provider,
    http: reqwest::Client,
    /// 缓存的 chat_session_id；多轮共用同一个 session 节省创建请求。
    session_id: Arc<Mutex<Option<String>>>,
}

impl DeepseekClient {
    pub fn new(provider: Provider) -> Result<Self, ModelError> {
        let http = super::build_http_client()?;
        Ok(Self {
            provider,
            http,
            session_id: Arc::new(Mutex::new(None)),
        })
    }

    async fn ensure_session(&self) -> Result<String, ModelError> {
        if let Some(id) = self.session_id.lock().clone() {
            return Ok(id);
        }
        let resp = apply_auth(self.http.post(SESSION_CREATE_URL), &self.provider)
            .json(&serde_json::json!({"agent": "chat"}))
            .send()
            .await?;
        let status = resp.status().as_u16();
        let text = resp.text().await?;
        if status >= 400 {
            return Err(ModelError::Http { status, body: text });
        }
        let v: Value = serde_json::from_str(&text)?;
        let id = v
            .pointer("/data/biz_data/id")
            .and_then(Value::as_str)
            .or_else(|| {
                v.pointer("/data/biz_data/chat_session/id")
                    .and_then(Value::as_str)
            })
            .ok_or_else(|| ModelError::Other("DeepSeek create_session 响应缺少 id".into()))?
            .to_string();
        *self.session_id.lock() = Some(id.clone());
        Ok(id)
    }

    async fn fetch_pow_header(&self) -> Result<String, ModelError> {
        let resp = apply_auth(self.http.post(POW_URL), &self.provider)
            .json(&serde_json::json!({"target_path": COMPLETION_TARGET_PATH}))
            .send()
            .await?;
        let status = resp.status().as_u16();
        let text = resp.text().await?;
        if status >= 400 {
            return Err(ModelError::Http { status, body: text });
        }
        let v: Value = serde_json::from_str(&text)?;
        let challenge_v = v
            .pointer("/data/biz_data/challenge")
            .ok_or_else(|| ModelError::Other("DeepSeek pow 响应缺少 challenge".into()))?;
        let challenge: DeepseekChallenge = serde_json::from_value(challenge_v.clone())
            .map_err(|e| ModelError::Other(format!("PoW challenge 解析失败: {e}")))?;
        deepseek_pow::solve_and_build_header(&challenge)
            .map_err(|e| ModelError::Other(e.to_string()))
    }
}

#[async_trait]
impl ModelClient for DeepseekClient {
    fn provider_id(&self) -> &str {
        &self.provider.id
    }

    fn supports_streaming_tools(&self) -> bool {
        // 我们的 ToolCallDelta 是在 SSE 收完后从最终文本里一次性解析的，
        // 但仍在 stream 返回前发出，对 agent_loop 来说和原生流式 tool_call 等价。
        // 返回 true 让 agent_loop 在含工具的 turn 也走流式路径，否则
        // TextDelta / ReasoningDelta 会被 complete 路径吞掉。
        true
    }

    async fn complete(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
    ) -> Result<ModelResponse, ModelError> {
        if has_image_generation_tool(&req.tools) {
            return Err(ModelError::Other(
                "DeepSeek web 协议不支持 image_generation".into(),
            ));
        }
        // 极少数路径（surface 显式调用 complete）：仍然走 SSE，
        // 但事件丢弃 —— Done.text 已经是完整正文（thinking 已被分流）。
        self.stream(req, cancel, &|_| {}).await
    }

    async fn stream(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    ) -> Result<ModelResponse, ModelError> {
        if has_image_generation_tool(&req.tools) {
            return Err(ModelError::Other(
                "DeepSeek web 协议不支持 image_generation".into(),
            ));
        }

        let session_id = self.ensure_session().await?;
        let pow_header = self.fetch_pow_header().await?;

        let prompt = proto::build_prompt(&req, &req.tools);
        let body = proto::build_completion_body(&session_id, None, &prompt, &req.model);
        let thinking_enabled = proto::thinking_enabled_for(&req.model);

        let resp = apply_auth(self.http.post(COMPLETION_URL), &self.provider)
            .header("x-ds-pow-response", pow_header)
            .json(&body)
            .send()
            .await?;
        let status = resp.status().as_u16();
        if status >= 400 {
            let body = resp.text().await?;
            return Err(ModelError::Http { status, body });
        }

        let mut stream = resp.bytes_stream();
        let mut buf = String::new();
        let mut full = String::new();
        // 整轮累积的思维链——回填给 transcript，下一轮 build_prompt 时再发回模型
        let mut full_reasoning = String::new();
        let mut finished = false;
        let mut state = proto::DeepseekStreamState::default();
        // text 通道的 tool_calls XML sieve：边流边把 <tool_calls>…</tool_calls> 扣下不发。
        let mut sieve = proto::ToolCallSieve::new();

        loop {
            let chunk = match super::next_stream_chunk_or_cancel(&mut stream, &cancel).await {
                Ok(Some(chunk)) => chunk,
                Ok(None) => break,
                Err(err) => {
                    // 流被取消 / 网络断开等：把 sieve 里残留的安全文本先吐给 surface，
                    // 再把错误传上去。这样 partial 内容不会在 buffer 里丢失。
                    let trailing = sieve.finalize();
                    if !trailing.is_empty() {
                        full.push_str(&trailing);
                        on_event(ModelStreamEvent::TextDelta { text: trailing });
                    }
                    return Err(err);
                }
            };
            buf.push_str(&String::from_utf8_lossy(&chunk));

            while let Some(pos) = buf.find('\n') {
                let line = buf[..pos].trim_end_matches('\r').to_string();
                buf = buf[pos + 1..].to_string();
                let Some(data) = line.strip_prefix("data:") else {
                    continue;
                };
                let data = data.trim();
                if data.is_empty() {
                    continue;
                }
                if data == "[DONE]" {
                    finished = true;
                    break;
                }
                if std::env::var_os("HEBBIAN_DEEPSEEK_TRACE").is_some() {
                    eprintln!("[deepseek::sse] {data}");
                }
                if let Some(parsed) = proto::parse_sse_line(data, thinking_enabled, &mut state) {
                    let mut role_header_truncated = false;
                    for part in parsed.parts {
                        match part {
                            proto::DeepseekChunkPart::Text(s) => {
                                full.push_str(&s);
                                // 模型一旦开始伪造 "### User" / "### Assistant" /
                                // "### System" / "### Tool" 这类角色头（实测会在工具
                                // 链多轮里"续写整段对话脚本"），把 full 截到该位置、
                                // 丢掉 sieve pending 并停流，再走正常 finalize → 解析。
                                if let Some(cut) = proto::find_fake_role_header_cut(&full) {
                                    full.truncate(cut);
                                    let _ = sieve.finalize();
                                    finished = true;
                                    role_header_truncated = true;
                                    break;
                                }
                                let safe = sieve.push(&s);
                                if !safe.is_empty() {
                                    on_event(ModelStreamEvent::TextDelta { text: safe });
                                }
                            }
                            proto::DeepseekChunkPart::Thinking(s) => {
                                full_reasoning.push_str(&s);
                                on_event(ModelStreamEvent::ReasoningDelta { text: s });
                            }
                        }
                    }
                    if parsed.finished {
                        finished = true;
                    }
                    if role_header_truncated {
                        break;
                    }
                }
            }
            if finished {
                break;
            }
        }
        // 流结束：把 sieve 里残留的安全文本吐完，并补进 full 供后续 transcript 用
        let trailing = sieve.finalize();
        if !trailing.is_empty() {
            full.push_str(&trailing);
            on_event(ModelStreamEvent::TextDelta {
                text: trailing.clone(),
            });
        }

        // DeepSeek web 协议只暴露一个 `accumulated_token_usage`（input+output 合计，
        // 不分 cache）。把它落到 `input_tokens`（语义上"已用 token 总量"），output/cache
        // 保留 0——比当前全 0 强，且不撒谎说有 cache 命中。
        let usage = Usage {
            input_tokens: state.accumulated_token_usage,
            output_tokens: 0,
            cache_read_tokens: 0,
            cache_creation_tokens: 0,
        };

        // 解析 tool_calls：在最终文本里找 `<tool_calls>` 块
        let (clean_text, tool_calls) = proto::extract_tool_calls(&full);
        if !tool_calls.is_empty() {
            // 把 tool_call 也以「流式 delta」形式补发，保证 surface 端能看到
            for (idx, call) in tool_calls.iter().enumerate() {
                on_event(ModelStreamEvent::ToolCallDelta(ToolCallStreamDelta {
                    index: idx,
                    id: Some(call.id.clone()),
                    name: Some(call.name.clone()),
                    arguments_delta: Some(call.input.to_string()),
                }));
            }
            return Ok(ModelResponse::ToolCalls {
                text: clean_text,
                reasoning: full_reasoning,
                reasoning_signature: String::new(),
                calls: tool_calls,
                attachments: Vec::new(),
                usage,
            });
        }

        Ok(ModelResponse::Done {
            finish: crate::types::FinishReason::Stop,
            text: full,
            reasoning: full_reasoning,
            reasoning_signature: String::new(),
            attachments: Vec::new(),
            usage,
        })
    }
}

crates/model-gateway/src/providers/gemin.content:
use async_trait::async_trait;
use serde_json::Value;

use crate::config::{AuthMode, Provider};
use crate::{
    client::ModelClient,
    protocols::gemini as proto,
    providers::apply_auth,
    types::{
        has_image_generation_tool, ModelError, ModelRequest, ModelResponse, ModelStreamEvent, Usage,
    },
};
use common::CancelFlag;

pub struct GeminiClient {
    provider: Provider,
    http: reqwest::Client,
}

impl GeminiClient {
    pub fn new(provider: Provider) -> Result<Self, ModelError> {
        let http = super::build_http_client()?;
        Ok(Self { provider, http })
    }

    fn url(&self, model: &str, stream: bool) -> String {
        let base = self.provider.base_url.trim_end_matches('/');
        let endpoint = if stream {
            "streamGenerateContent"
        } else {
            "generateContent"
        };

        if matches!(self.provider.auth_mode, AuthMode::OauthGeminiCli) {
            let suffix = if stream { "?alt=sse" } else { "" };
            format!("{}/v1beta/models/{}:{}{}", base, model, endpoint, suffix)
        } else {
            let sep = if stream { "alt=sse&" } else { "" };
            format!(
                "{}/v1beta/models/{}:{}?{}key={}",
                base, model, endpoint, sep, self.provider.api_key
            )
        }
    }
}

#[async_trait]
impl ModelClient for GeminiClient {
    fn provider_id(&self) -> &str {
        &self.provider.id
    }

    async fn complete(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
    ) -> Result<ModelResponse, ModelError> {
        reject_image_generation_tool(&req)?;
        let url = self.url(&req.model, false);
        let body = proto::build_body(&req);

        super::retry_request(cancel, || {
            let body = body.clone();
            let url = url.clone();
            async move {
                let resp = apply_auth(self.http.post(&url), &self.provider)
                    .json(&body)
                    .send()
                    .await?;
                let status = resp.status().as_u16();
                let text = resp.text().await?;
                if status >= 400 {
                    return Err(ModelError::Http { status, body: text });
                }
                let v: Value = serde_json::from_str(&text)?;
                Ok(proto::parse_response(&v))
            }
        })
        .await
    }

    async fn stream(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    ) -> Result<ModelResponse, ModelError> {
        reject_image_generation_tool(&req)?;
        let url = self.url(&req.model, true);
        let body = proto::build_body(&req);

        let resp = super::retry_request(cancel.clone(), || {
            let body = body.clone();
            let url = url.clone();
            async move {
                let r = apply_auth(self.http.post(&url), &self.provider)
                    .json(&body)
                    .send()
                    .await?;
                let status = r.status().as_u16();
                if status >= 400 {
                    let body = r.text().await?;
                    return Err(ModelError::Http { status, body });
                }
                Ok(r)
            }
        })
        .await?;

        let mut stream = resp.bytes_stream();
        let mut buf = String::new();
        let mut full = String::new();
        // Gemini 把 usageMetadata 跨多帧推增量，留最新一份即可。
        let mut usage = Usage::default();

        while let Some(chunk) = super::next_stream_chunk_or_cancel(&mut stream, &cancel).await? {
            buf.push_str(&String::from_utf8_lossy(&chunk));

            while let Some(pos) = buf.find("\n\n").or_else(|| buf.find("\r\n\r\n")) {
                let skip = if buf[pos..].starts_with("\r\n\r\n") {
                    4
                } else {
                    2
                };
                let frame = buf[..pos].to_string();
                buf = buf[pos + skip..].to_string();

                for line in frame.lines() {
                    let line = line.trim_end_matches('\r');
                    if let Some(data) = line.strip_prefix("data:") {
                        let data = data.trim();
                        if data.is_empty() {
                            continue;
                        }
                        if let Some(delta) = proto::parse_stream_delta(data) {
                            on_event(ModelStreamEvent::TextDelta {
                                text: delta.clone(),
                            });
                            full.push_str(&delta);
                        }
                        if let Some(u) = proto::parse_stream_usage(data) {
                            usage = u;
                        }
                    }
                }
            }
        }

        Ok(ModelResponse::Done {
            finish: crate::types::FinishReason::Stop,
            text: full,
            reasoning: String::new(),
            reasoning_signature: String::new(),
            attachments: Vec::new(),
            usage,
        })
    }
}

fn reject_image_generation_tool(req: &ModelRequest) -> Result<(), ModelError> {
    if has_image_generation_tool(&req.tools) {
        return Err(ModelError::Other(
            "image_generation 工具只支持 OpenAI Responses；请切换到 OpenAI provider，或关闭生图工具。"
                .to_string(),
        ));
    }
    Ok(())
}

crates/model-gateway/src/providers/mod.r.content:
pub mod anthropic;
pub mod deepseek;
pub mod gemini;
pub mod openai;

use crate::config::{AuthMode, Provider, ProviderKind};
use crate::types::ModelError;
use bytes::Bytes;
use common::{runtime as cancellation, CancelFlag};
use futures_util::{Stream, StreamExt};
#[cfg(not(test))]
use rand::Rng;
use reqwest::RequestBuilder;
use std::time::Duration;

const DEFAULT_MAX_RETRIES: u32 = 4;
#[cfg(not(test))]
const BASE_RETRY_DELAY: Duration = Duration::from_millis(500);
#[cfg(not(test))]
const MAX_RETRY_DELAY: Duration = Duration::from_secs(8);

pub fn build_http_client() -> reqwest::Result<reqwest::Client> {
    // 用 connect_timeout + read_timeout 替代 total timeout：
    // - `.timeout()` 是「整个请求」（含 stream body 接收）的总时长，长 SSE 流（thinking
    //   模式 / 多工具轮 / 长上下文）很容易超过 120s 触发"error decoding response body"。
    // - `.connect_timeout()`：握手 + TLS 阶段超时（避免 DNS/TCP 卡死）。
    // - `.read_timeout()`（reqwest 0.12+）：「两个 chunk 之间」的最大空闲时间，给 SSE
    //   足够空间——只要服务端持续在 push token 就不会触发。
    reqwest::Client::builder()
        .user_agent("Hebbian/0.1")
        .connect_timeout(Duration::from_secs(15))
        .read_timeout(Duration::from_secs(180))
        .pool_idle_timeout(Duration::from_secs(90))
        .build()
}

pub fn apply_auth(req: RequestBuilder, provider: &Provider) -> RequestBuilder {
    let mut req = req;
    match (provider.kind, provider.auth_mode) {
        (ProviderKind::Openai, AuthMode::OauthCodex) => {
            req = req
                .bearer_auth(&provider.api_key)
                .header("originator", "hebbian");
            if let Some(acc) = &provider.account_id {
                req = req.header("ChatGPT-Account-Id", acc.as_str());
            }
        }
        (ProviderKind::Openai, _) => {
            req = req.bearer_auth(&provider.api_key);
        }
        (ProviderKind::Anthropic, AuthMode::OauthClaudeCode) => {
            req = req
                .bearer_auth(&provider.api_key)
                .header("anthropic-version", "2023-06-01")
                .header(
                    "anthropic-beta",
                    "claude-code-20250219,oauth-2025-04-20,interleaved-thinking-2025-05-14,redact-thinking-2026-02-12,context-management-2025-06-27,prompt-caching-scope-2026-01-05,effort-2025-11-24",
                )
                .header("user-agent", "claude-cli/2.1.150 (external, cli)")
                .header("x-app", "cli")
                .header("anthropic-dangerous-direct-browser-access", "true")
                .header("x-stainless-lang", "js")
                .header("x-stainless-package-version", "0.94.0")
                .header("x-stainless-os", "MacOS")
                .header("x-stainless-arch", "arm64")
                .header("x-stainless-runtime", "node")
                .header("x-stainless-runtime-version", "v24.3.0")
                .header("x-stainless-retry-count", "0")
                .header("x-stainless-timeout", "3000");
        }
        (ProviderKind::Anthropic, _) => {
            req = req
                .header("x-api-key", &provider.api_key)
                .header("anthropic-version", "2023-06-01")
                .header(
                    "anthropic-beta",
                    "claude-code-20250219,interleaved-thinking-2025-05-14,redact-thinking-2026-02-12,context-management-2025-06-27,prompt-caching-scope-2026-01-05,effort-2025-11-24",
                )
                .header("user-agent", "claude-cli/2.1.150 (external, cli)")
                .header("x-app", "cli")
                .header("anthropic-dangerous-direct-browser-access", "true")
                .header("x-stainless-lang", "js")
                .header("x-stainless-package-version", "0.94.0")
                .header("x-stainless-os", "MacOS")
                .header("x-stainless-arch", "arm64")
                .header("x-stainless-runtime", "node")
                .header("x-stainless-runtime-version", "v24.3.0")
                .header("x-stainless-retry-count", "0")
                .header("x-stainless-timeout", "3000");
        }
        (ProviderKind::Gemini, AuthMode::OauthGeminiCli) => {
            req = req
                .bearer_auth(&provider.api_key)
                .header("x-goog-api-client", "GeminiCLI/1.0");
        }
        (ProviderKind::Gemini, _) => {}
        (ProviderKind::Deepseek, _) => {
            // chat.deepseek.com web 协议：Bearer + 客户端指纹头（与 ds2api/internal/deepseek/protocol/constants.go 对齐）
            req = req
                .bearer_auth(&provider.api_key)
                .header("Accept", "application/json")
                .header("Content-Type", "application/json")
                .header("accept-charset", "UTF-8")
                .header("Host", "chat.deepseek.com")
                .header("User-Agent", "DeepSeek/2.0.4 Android/35")
                .header("x-client-platform", "android")
                .header("x-client-version", "2.0.4")
                .header("x-client-locale", "zh_CN");
        }
    }
    for (k, v) in &provider.extra_headers {
        req = req.header(k.as_str(), v.as_str());
    }
    req
}

pub(crate) async fn next_stream_chunk_or_cancel<S>(
    stream: &mut S,
    cancel: &CancelFlag,
) -> Result<Option<Bytes>, ModelError>
where
    S: Stream<Item = Result<Bytes, reqwest::Error>> + Unpin,
{
    if cancellation::is_cancelled(cancel) {
        return Err(ModelError::Cancelled);
    }

    tokio::select! {
        chunk = stream.next() => chunk.transpose().map_err(ModelError::from),
        _ = wait_for_cancel(cancel.clone()) => Err(ModelError::Cancelled),
    }
}

pub(crate) async fn retry_request<T, Op, Fut>(
    cancel: CancelFlag,
    mut op: Op,
) -> Result<T, ModelError>
where
    Op: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<T, ModelError>>,
{
    let mut attempt = 0u32;
    loop {
        if cancellation::is_cancelled(&cancel) {
            return Err(ModelError::Cancelled);
        }

        // 用 select! 竞争：cancel 先到就立即返回，不等 HTTP 响应。
        let result = tokio::select! {
            result = op() => result,
            _ = wait_for_cancel(cancel.clone()) => return Err(ModelError::Cancelled),
        };
        match result {
            Ok(value) => return Ok(value),
            Err(err) => {
                attempt += 1;
                if attempt > DEFAULT_MAX_RETRIES || !is_retryable_model_error(&err) {
                    return Err(err);
                }

                sleep_or_cancel(retry_delay(attempt), cancel.clone()).await?;
            }
        }
    }
}

fn is_retryable_model_error(err: &ModelError) -> bool {
    match err {
        ModelError::Http { status, body } => {
            matches!(*status, 408 | 409 | 429 | 500..=599)
                || body.contains("\"type\":\"overloaded_error\"")
                || body.contains("overloaded_error")
        }
        ModelError::Request(err) => err.is_connect() || err.is_timeout(),
        ModelError::Json(_)
        | ModelError::Cancelled
        | ModelError::Suspended
        | ModelError::Other(_) => false,
    }
}

fn retry_delay(attempt: u32) -> Duration {
    #[cfg(test)]
    {
        let _ = attempt;
        return Duration::from_millis(1);
    }

    #[cfg(not(test))]
    {
        let exponent = attempt.saturating_sub(1).min(10);
        let base_ms = (BASE_RETRY_DELAY.as_millis() as u64)
            .saturating_mul(2u64.saturating_pow(exponent))
            .min(MAX_RETRY_DELAY.as_millis() as u64);
        let jitter_ms = rand::thread_rng().gen_range(0..=(base_ms / 4).max(1));
        Duration::from_millis(base_ms + jitter_ms)
    }
}

async fn sleep_or_cancel(delay: Duration, cancel: CancelFlag) -> Result<(), ModelError> {
    tokio::select! {
        _ = tokio::time::sleep(delay) => Ok(()),
        _ = wait_for_cancel(cancel) => Err(ModelError::Cancelled),
    }
}

async fn wait_for_cancel(cancel: CancelFlag) {
    while !cancellation::is_cancelled(&cancel) {
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::types::ModelError;
    use std::sync::{
        atomic::{AtomicBool, Ordering},
        Arc,
    };

    #[tokio::test]
    async fn next_stream_chunk_or_cancel_returns_when_cancelled_before_next_chunk() {
        let cancel = Arc::new(AtomicBool::new(true));
        let mut stream = futures_util::stream::pending::<Result<bytes::Bytes, reqwest::Error>>();

        let result = next_stream_chunk_or_cancel(&mut stream, &cancel).await;

        assert!(matches!(result, Err(ModelError::Cancelled)));
        assert!(cancel.load(Ordering::SeqCst));
    }

    #[tokio::test]
    async fn retry_request_retries_transient_http_errors() {
        let attempts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let attempts_for_op = Arc::clone(&attempts);
        let cancel = Arc::new(AtomicBool::new(false));

        let result = retry_request(cancel, move || {
            let attempts = Arc::clone(&attempts_for_op);
            async move {
                let attempt = attempts.fetch_add(1, Ordering::SeqCst);
                if attempt < 2 {
                    Err(ModelError::Http {
                        status: 500,
                        body: "server busy".to_string(),
                    })
                } else {
                    Ok("ok")
                }
            }
        })
        .await;

        assert_eq!(result.unwrap(), "ok");
        assert_eq!(attempts.load(Ordering::SeqCst), 3);
    }

    #[tokio::test]
    async fn retry_request_does_not_retry_client_errors() {
        let attempts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let attempts_for_op = Arc::clone(&attempts);
        let cancel = Arc::new(AtomicBool::new(false));

        let result = retry_request(cancel, move || {
            let attempts = Arc::clone(&attempts_for_op);
            async move {
                attempts.fetch_add(1, Ordering::SeqCst);
                Err::<(), _>(ModelError::Http {
                    status: 400,
                    body: "unsupported model".to_string(),
                })
            }
        })
        .await;

        assert!(matches!(result, Err(ModelError::Http { status: 400, .. })));
        assert_eq!(attempts.load(Ordering::SeqCst), 1);
    }
}

crates/model-gateway/src/providers/opena.content:
use async_trait::async_trait;
use std::collections::BTreeMap;

use serde_json::Value;

use crate::config::{AuthMode, Provider};
use crate::{
    client::ModelClient,
    protocols::openai as proto,
    providers::apply_auth,
    types::{
        has_image_generation_tool, ModelError, ModelRequest, ModelResponse, ModelStreamEvent,
        ToolCall, ToolCallStreamDelta, Usage,
    },
};
use common::CancelFlag;

pub struct OpenAiClient {
    provider: Provider,
    http: reqwest::Client,
}

impl OpenAiClient {
    pub fn new(provider: Provider) -> Result<Self, ModelError> {
        let http = super::build_http_client()?;
        Ok(Self { provider, http })
    }

    fn chat_url(&self) -> String {
        format!(
            "{}/chat/completions",
            self.provider.base_url.trim_end_matches('/')
        )
    }

    fn responses_url(&self) -> String {
        let base = if matches!(self.provider.auth_mode, AuthMode::OauthCodex)
            && self.provider.base_url.trim_end_matches('/') == "https://api.openai.com/v1"
        {
            "https://chatgpt.com/backend-api/codex"
        } else {
            self.provider.base_url.trim_end_matches('/')
        };
        format!("{base}/responses")
    }

    fn uses_codex_oauth(&self) -> bool {
        matches!(self.provider.auth_mode, AuthMode::OauthCodex)
    }

    fn should_use_responses(&self, req: &ModelRequest) -> bool {
        self.uses_codex_oauth()
            || req
                .tools
                .iter()
                .any(|tool| tool.name == crate::types::IMAGE_GENERATION_TOOL_NAME)
    }
}

#[async_trait]
impl ModelClient for OpenAiClient {
    fn provider_id(&self) -> &str {
        &self.provider.id
    }

    fn supports_streaming_tools(&self) -> bool {
        true
    }

    async fn complete(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
    ) -> Result<ModelResponse, ModelError> {
        let use_responses = self.should_use_responses(&req);
        if use_responses {
            return self
                .complete_responses(req, cancel, self.uses_codex_oauth())
                .await;
        }

        let body = proto::build_body(&req, false)?;

        super::retry_request(cancel, || {
            let body = body.clone();
            async move {
                let resp = apply_auth(self.http.post(self.chat_url()), &self.provider)
                    .json(&body)
                    .send()
                    .await?;
                let status = resp.status().as_u16();
                let text = resp.text().await?;
                if status >= 400 {
                    return Err(ModelError::Http { status, body: text });
                }
                let v: Value = serde_json::from_str(&text)?;
                Ok(proto::parse_response(&v))
            }
        })
        .await
    }

    async fn stream(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    ) -> Result<ModelResponse, ModelError> {
        let use_responses = self.should_use_responses(&req);
        if use_responses {
            return self
                .stream_responses(req, cancel, on_event, self.uses_codex_oauth())
                .await;
        }

        let body = proto::build_body(&req, true)?;

        let resp = super::retry_request(cancel.clone(), || {
            let body = body.clone();
            async move {
                let r = apply_auth(self.http.post(self.chat_url()), &self.provider)
                    .json(&body)
                    .send()
                    .await?;
                let status = r.status().as_u16();
                if status >= 400 {
                    let body = r.text().await?;
                    return Err(ModelError::Http { status, body });
                }
                Ok(r)
            }
        })
        .await?;

        let mut stream = resp.bytes_stream();
        let mut buf = String::new();
        let mut full = String::new();
        let mut full_reasoning = String::new();
        let mut tool_call_parts = Vec::new();
        // OpenAI Chat Completions：开了 stream_options.include_usage 后，最后一帧
        // `choices` 为空、只带 `usage`。多次出现以最新一次为准。
        let mut usage = Usage::default();
        // 终态帧的 finish_reason，用来归一成 FinishReason（架构 §4.11.4）。
        let mut finish_reason: Option<String> = None;

        while let Some(chunk) = super::next_stream_chunk_or_cancel(&mut stream, &cancel).await? {
            buf.push_str(&String::from_utf8_lossy(&chunk));

            while let Some(pos) = buf.find("\n\n").or_else(|| buf.find("\r\n\r\n")) {
                let skip = if buf[pos..].starts_with("\r\n\r\n") {
                    4
                } else {
                    2
                };
                let frame = buf[..pos].to_string();
                buf = buf[pos + skip..].to_string();

                for line in frame.lines() {
                    let line = line.trim_end_matches('\r');
                    if let Some(data) = line.strip_prefix("data:") {
                        let data = data.trim();
                        if data == "[DONE]" || data.is_empty() {
                            continue;
                        }
                        // 流内错误帧（HTTP 200 但 body 里 `{"error":...}`）：不拦会被当未知帧
                        // 忽略 → 流"正常"结束 → agent_loop 误判成功。转 Err 让上层正常收尾。
                        if let Ok(v) = serde_json::from_str::<Value>(data) {
                            if v.get("error").map(|e| !e.is_null()).unwrap_or(false) {
                                return Err(ModelError::Other(format!("模型流式返回错误：{data}")));
                            }
                        }
                        if let Some(parsed) = proto::parse_chat_stream_frame(data) {
                            if let Some(delta) = parsed.reasoning_delta {
                                full_reasoning.push_str(&delta);
                                on_event(ModelStreamEvent::ReasoningDelta { text: delta });
                            }
                            if let Some(delta) = parsed.text_delta {
                                on_event(ModelStreamEvent::TextDelta {
                                    text: delta.clone(),
                                });
                                full.push_str(&delta);
                            }
                            for delta in parsed.tool_calls {
                                emit_tool_call_delta(
                                    on_event,
                                    delta.index,
                                    clean_optional(delta.id.as_deref()),
                                    clean_optional(delta.name.as_deref()),
                                    nonempty_optional(delta.arguments.as_deref()),
                                );
                                apply_tool_call_delta(&mut tool_call_parts, delta);
                            }
                            if let Some(u) = parsed.usage {
                                usage = u;
                            }
                            if parsed.finish_reason.is_some() {
                                finish_reason = parsed.finish_reason;
                            }
                        }
                    }
                }
            }
        }

        let calls = finish_tool_calls(tool_call_parts);
        if calls.is_empty() {
            Ok(ModelResponse::Done {
                finish: proto::map_openai_finish(finish_reason.as_deref().unwrap_or("")),
                text: full,
                reasoning: full_reasoning,
                reasoning_signature: String::new(),
                attachments: Vec::new(),
                usage,
            })
        } else {
            Ok(ModelResponse::ToolCalls {
                text: full,
                reasoning: full_reasoning,
                reasoning_signature: String::new(),
                calls,
                attachments: Vec::new(),
                usage,
            })
        }
    }
}

#[derive(Default)]
struct PartialToolCall {
    id: Option<String>,
    name: Option<String>,
    arguments: String,
}

fn apply_tool_call_delta(
    tool_call_parts: &mut Vec<PartialToolCall>,
    delta: proto::ChatStreamToolCallDelta,
) {
    while tool_call_parts.len() <= delta.index {
        tool_call_parts.push(PartialToolCall::default());
    }

    let part = &mut tool_call_parts[delta.index];
    if let Some(id) = delta.id.filter(|id| !id.trim().is_empty()) {
        part.id = Some(id);
    }
    if let Some(name) = delta.name.filter(|name| !name.trim().is_empty()) {
        part.name = Some(name);
    }
    if let Some(arguments) = delta.arguments {
        part.arguments.push_str(&arguments);
    }
}

fn finish_tool_calls(tool_call_parts: Vec<PartialToolCall>) -> Vec<ToolCall> {
    tool_call_parts
        .into_iter()
        .filter_map(|part| {
            let id = part.id?;
            let name = part.name?;
            let arguments = if part.arguments.trim().is_empty() {
                serde_json::json!({})
            } else {
                serde_json::from_str(&part.arguments).unwrap_or(Value::Null)
            };
            Some(ToolCall {
                id,
                name,
                input: arguments,
            })
        })
        .collect()
}

fn emit_tool_call_delta(
    on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    index: usize,
    id: Option<String>,
    name: Option<String>,
    arguments_delta: Option<String>,
) {
    if id.is_none() && name.is_none() && arguments_delta.is_none() {
        return;
    }

    on_event(ModelStreamEvent::ToolCallDelta(ToolCallStreamDelta {
        index,
        id,
        name,
        arguments_delta,
    }));
}

fn emit_responses_tool_call_item(
    on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
    output_index: Option<usize>,
    item: &Value,
) {
    if item["type"].as_str() != Some("function_call") {
        return;
    }

    emit_tool_call_delta(
        on_event,
        response_tool_index(output_index),
        clean_optional(item["call_id"].as_str()).or_else(|| clean_optional(item["id"].as_str())),
        clean_optional(item["name"].as_str()),
        None,
    );
}

fn response_tool_index(output_index: Option<usize>) -> usize {
    output_index.unwrap_or(0)
}

fn clean_optional(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn nonempty_optional(value: Option<&str>) -> Option<String> {
    value.filter(|value| !value.is_empty()).map(str::to_string)
}

fn responses_http_error(
    status: u16,
    body: String,
    image_generation_enabled: bool,
    model: &str,
) -> ModelError {
    if !image_generation_enabled {
        return ModelError::Http { status, body };
    }

    let body_lower = body.to_lowercase();
    if status == 403 && body_lower.contains("codex official clients") {
        return ModelError::Other(
            "图片生成请求已切到 OpenAI Responses，但当前代理拒绝了该客户端：只允许 Codex 官方客户端。请切换到支持 image_generation 的 OpenAI provider，或在代理端关闭/放行 codex_cli_only。"
                .to_string(),
        );
    }

    if status == 400 && model.to_lowercase().starts_with("gpt-image-") {
        return ModelError::Other(format!(
            "不要把 {model} 作为对话模型来跑生图；请选择 gpt-5.5 / gpt-5.4 这类对话模型，并启用 image_generation 工具。原始错误：{body}"
        ));
    }

    ModelError::Http { status, body }
}

impl OpenAiClient {
    async fn complete_responses(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        codex_oauth: bool,
    ) -> Result<ModelResponse, ModelError> {
        let body = proto::build_responses_body(&req, false, codex_oauth);
        let has_image_generation_tool = has_image_generation_tool(&req.tools);
        let model = req.model.clone();

        super::retry_request(cancel, || {
            let body = body.clone();
            let model = model.clone();
            async move {
                let resp = apply_auth(self.http.post(self.responses_url()), &self.provider)
                    .json(&body)
                    .send()
                    .await?;
                let status = resp.status().as_u16();
                let text = resp.text().await?;
                if status >= 400 {
                    return Err(responses_http_error(
                        status,
                        text,
                        has_image_generation_tool,
                        &model,
                    ));
                }
                parse_responses_body_or_sse(&text)
            }
        })
        .await
    }

    async fn stream_responses(
        &self,
        req: ModelRequest,
        cancel: CancelFlag,
        on_event: &(dyn Fn(ModelStreamEvent) + Send + Sync),
        codex_oauth: bool,
    ) -> Result<ModelResponse, ModelError> {
        let body = proto::build_responses_body(&req, true, codex_oauth);
        let has_image_generation_tool = has_image_generation_tool(&req.tools);
        let model = req.model.clone();

        let resp = super::retry_request(cancel.clone(), || {
            let body = body.clone();
            let model = model.clone();
            async move {
                let r = apply_auth(self.http.post(self.responses_url()), &self.provider)
                    .json(&body)
                    .send()
                    .await?;
                let status = r.status().as_u16();
                if status >= 400 {
                    let body = r.text().await?;
                    return Err(responses_http_error(
                        status,
                        body,
                        has_image_generation_tool,
                        &model,
                    ));
                }
                Ok(r)
            }
        })
        .await?;

        let mut stream = resp.bytes_stream();
        let mut buf = String::new();
        let mut full = String::new();
        let mut full_reasoning = String::new();
        let mut output_items = ResponsesOutputAccumulator::default();
        let mut completed: Option<Value> = None;

        while let Some(chunk) = super::next_stream_chunk_or_cancel(&mut stream, &cancel).await? {
            buf.push_str(&String::from_utf8_lossy(&chunk));

            while let Some(frame) = take_sse_frame(&mut buf) {
                match parse_responses_frame(&frame)? {
                    ParsedResponsesFrame::Delta(delta) => {
                        on_event(ModelStreamEvent::TextDelta {
                            text: delta.clone(),
                        });
                        full.push_str(&delta);
                    }
                    ParsedResponsesFrame::ReasoningDelta(delta) => {
                        full_reasoning.push_str(&delta);
                        on_event(ModelStreamEvent::ReasoningDelta { text: delta });
                    }
                    ParsedResponsesFrame::OutputItemAdded { output_index, item }
                    | ParsedResponsesFrame::OutputItemDone { output_index, item } => {
                        emit_responses_tool_call_item(on_event, output_index, &item);
                        output_items.put_output_item(output_index, item);
                    }
                    ParsedResponsesFrame::FunctionCallArgumentsDelta {
                        output_index,
                        item_id,
                        delta,
                    } => {
                        emit_tool_call_delta(
                            on_event,
                            response_tool_index(output_index),
                            clean_optional(item_id.as_deref()),
                            None,
                            nonempty_optional(Some(&delta)),
                        );
                        output_items.append_function_call_arguments(
                            output_index,
                            item_id.as_deref(),
                            &delta,
                        );
                    }
                    ParsedResponsesFrame::FunctionCallArgumentsDone {
                        output_index,
                        item_id,
                        call_id,
                        name,
                        arguments,
                    } => {
                        emit_tool_call_delta(
                            on_event,
                            response_tool_index(output_index),
                            clean_optional(call_id.as_deref())
                                .or_else(|| clean_optional(item_id.as_deref())),
                            clean_optional(name.as_deref()),
                            None,
                        );
                        output_items.finish_function_call_arguments(
                            output_index,
                            item_id.as_deref(),
                            call_id.as_deref(),
                            name.as_deref(),
                            &arguments,
                        );
                    }
                    ParsedResponsesFrame::Completed(response) => completed = Some(response),
                    ParsedResponsesFrame::Ignore => {}
                }
            }
        }

        let mut response = completed.unwrap_or_else(|| serde_json::json!({}));
        let output_items = merge_response_output(response.get("output"), output_items);
        if !output_items.is_empty() {
            response["output"] = Value::Array(output_items);
        }
        let parsed = proto::parse_responses_response(&response);

        match parsed {
            ModelResponse::Done {
                text,
                reasoning,
                attachments,
                usage,
                finish,
                ..
            } => {
                // 流式累积的 reasoning 优先级最高
                let final_reasoning = if !full_reasoning.is_empty() {
                    full_reasoning
                } else {
                    reasoning
                };
                Ok(ModelResponse::Done {
                    finish,
                    text: if full.is_empty() { text } else { full },
                    reasoning: final_reasoning,
                    reasoning_signature: String::new(),
                    attachments,
                    usage,
                })
            }
            other => Ok(other),
        }
    }
}

enum ParsedResponsesFrame {
    Delta(String),
    ReasoningDelta(String),
    OutputItemAdded {
        output_index: Option<usize>,
        item: Value,
    },
    OutputItemDone {
        output_index: Option<usize>,
        item: Value,
    },
    FunctionCallArgumentsDelta {
        output_index: Option<usize>,
        item_id: Option<String>,
        delta: String,
    },
    FunctionCallArgumentsDone {
        output_index: Option<usize>,
        item_id: Option<String>,
        call_id: Option<String>,
        name: Option<String>,
        arguments: String,
    },
    Completed(Value),
    Ignore,
}

#[derive(Default)]
struct ResponsesOutputAccumulator {
    indexed_items: BTreeMap<usize, Value>,
    unindexed_items: Vec<Value>,
}

impl ResponsesOutputAccumulator {
    fn put_output_item(&mut self, output_index: Option<usize>, item: Value) {
        if let Some(index) = output_index.or_else(|| self.find_index_for_item(&item)) {
            let entry = self
                .indexed_items
                .entry(index)
                .or_insert(serde_json::json!({}));
            merge_response_output_item(entry, item);
            return;
        }

        if let Some(pos) = self.find_unindexed_pos_for_item(&item) {
            merge_response_output_item(&mut self.unindexed_items[pos], item);
        } else {
            self.unindexed_items.push(item);
        }
    }

    fn append_function_call_arguments(
        &mut self,
        output_index: Option<usize>,
        item_id: Option<&str>,
        delta: &str,
    ) {
        if delta.is_empty() {
            return;
        }

        let item = self.function_call_item_mut(output_index, item_id);
        let current = item["arguments"].as_str().unwrap_or("").to_string();
        item["arguments"] = Value::String(format!("{current}{delta}"));
    }

    fn finish_function_call_arguments(
        &mut self,
        output_index: Option<usize>,
        item_id: Option<&str>,
        call_id: Option<&str>,
        name: Option<&str>,
        arguments: &str,
    ) {
        let item = self.function_call_item_mut(output_index, item_id);
        if let Some(call_id) = call_id {
            item["call_id"] = Value::String(call_id.to_string());
        }
        if let Some(name) = name {
            item["name"] = Value::String(name.to_string());
        }
        if !arguments.is_empty() || item["arguments"].as_str().unwrap_or("").is_empty() {
            item["arguments"] = Value::String(arguments.to_string());
        }
        item["status"] = Value::String("completed".to_string());
    }

    fn into_output_items(self) -> Vec<Value> {
        self.indexed_items
            .into_values()
            .chain(self.unindexed_items)
            .collect()
    }

    fn merge_from(&mut self, other: ResponsesOutputAccumulator) {
        for (index, item) in other.indexed_items {
            self.put_output_item(Some(index), item);
        }
        for item in other.unindexed_items {
            self.put_output_item(None, item);
        }
    }

    fn function_call_item_mut(
        &mut self,
        output_index: Option<usize>,
        item_id: Option<&str>,
    ) -> &mut Value {
        if let Some(index) = output_index.or_else(|| self.find_index_for_id(item_id)) {
            let item = self
                .indexed_items
                .entry(index)
                .or_insert_with(|| minimal_function_call_item(item_id));
            ensure_function_call_item(item, item_id);
            return item;
        }

        if let Some(pos) = self.find_unindexed_pos_for_id(item_id) {
            let item = &mut self.unindexed_items[pos];
            ensure_function_call_item(item, item_id);
            return item;
        }

        self.unindexed_items
            .push(minimal_function_call_item(item_id));
        self.unindexed_items.last_mut().unwrap()
    }

    fn find_index_for_item(&self, item: &Value) -> Option<usize> {
        output_item_id(item).and_then(|id| self.find_index_for_id(Some(id)))
    }

    fn find_index_for_id(&self, item_id: Option<&str>) -> Option<usize> {
        let expected_id = item_id?;
        self.indexed_items
            .iter()
            .find_map(|(index, item)| (output_item_id(item) == Some(expected_id)).then_some(*index))
    }

    fn find_unindexed_pos_for_item(&self, item: &Value) -> Option<usize> {
        output_item_id(item).and_then(|id| self.find_unindexed_pos_for_id(Some(id)))
    }

    fn find_unindexed_pos_for_id(&self, item_id: Option<&str>) -> Option<usize> {
        let expected_id = item_id?;
        self.unindexed_items
            .iter()
            .position(|item| output_item_id(item) == Some(expected_id))
    }
}

fn minimal_function_call_item(item_id: Option<&str>) -> Value {
    let mut item = serde_json::json!({
        "type": "function_call",
        "arguments": ""
    });
    if let Some(item_id) = item_id {
        item["id"] = Value::String(item_id.to_string());
    }
    item
}

fn ensure_function_call_item(item: &mut Value, item_id: Option<&str>) {
    if !item.is_object() {
        *item = serde_json::json!({});
    }
    if item["type"].as_str().unwrap_or("").is_empty() {
        item["type"] = Value::String("function_call".to_string());
    }
    if let Some(item_id) = item_id {
        if item["id"].as_str().unwrap_or("").is_empty() {
            item["id"] = Value::String(item_id.to_string());
        }
    }
    if !item["arguments"].is_string() {
        item["arguments"] = Value::String(String::new());
    }
}

fn merge_response_output_item(existing: &mut Value, incoming: Value) {
    let Some(existing_obj) = existing.as_object_mut() else {
        *existing = incoming;
        return;
    };
    let Value::Object(incoming_obj) = incoming else {
        *existing = incoming;
        return;
    };

    for (key, value) in incoming_obj {
        let preserve_existing = match (existing_obj.get(&key), &value) {
            (Some(Value::String(current)), Value::String(next)) => {
                !current.is_empty() && next.is_empty()
            }
            (Some(current), Value::Null) => !current.is_null(),
            _ => false,
        };
        if !preserve_existing {
            existing_obj.insert(key, value);
        }
    }
}

fn output_item_id(item: &Value) -> Option<&str> {
    item["id"].as_str()
}

fn merge_response_output(
    completed_output: Option<&Value>,
    accumulated: ResponsesOutputAccumulator,
) -> Vec<Value> {
    let Some(completed_items) = completed_output.and_then(Value::as_array) else {
        return accumulated.into_output_items();
    };

    let mut merged = ResponsesOutputAccumulator::default();
    for (index, item) in completed_items.iter().cloned().enumerate() {
        merged.put_output_item(Some(index), item);
    }
    merged.merge_from(accumulated);
    merged.into_output_items()
}

fn parse_responses_body_or_sse(body: &str) -> Result<ModelResponse, ModelError> {
    let trimmed = body.trim_start();
    if trimmed.starts_with('{') {
        let v: Value = serde_json::from_str(body)?;
        return Ok(proto::parse_responses_response(&v));
    }

    let mut buf = body.to_string();
    let mut output_items = ResponsesOutputAccumulator::default();
    let mut completed: Option<Value> = None;

    while let Some(frame) = take_sse_frame(&mut buf) {
        match parse_responses_frame(&frame)? {
            ParsedResponsesFrame::OutputItemAdded { output_index, item }
            | ParsedResponsesFrame::OutputItemDone { output_index, item } => {
                output_items.put_output_item(output_index, item);
            }
            ParsedResponsesFrame::FunctionCallArgumentsDelta {
                output_index,
                item_id,
                delta,
            } => output_items.append_function_call_arguments(
                output_index,
                item_id.as_deref(),
                &delta,
            ),
            ParsedResponsesFrame::FunctionCallArgumentsDone {
                output_index,
                item_id,
                call_id,
                name,
                arguments,
            } => output_items.finish_function_call_arguments(
                output_index,
                item_id.as_deref(),
                call_id.as_deref(),
                name.as_deref(),
                &arguments,
            ),
            ParsedResponsesFrame::Completed(response) => completed = Some(response),
            ParsedResponsesFrame::Delta(_)
            | ParsedResponsesFrame::ReasoningDelta(_)
            | ParsedResponsesFrame::Ignore => {}
        }
    }

    let mut response = completed
        .ok_or_else(|| ModelError::Other("Responses SSE 缺少 response.completed".to_string()))?;
    let output_items = merge_response_output(response.get("output"), output_items);
    if !output_items.is_empty() {
        response["output"] = Value::Array(output_items);
    }
    Ok(proto::parse_responses_response(&response))
}

fn take_sse_frame(buf: &mut String) -> Option<String> {
    let (pos, skip) = if let Some(pos) = buf.find("\n\n") {
        (pos, 2)
    } else if let Some(pos) = buf.find("\r\n\r\n") {
        (pos, 4)
    } else {
        return None;
    };
    let frame = buf[..pos].to_string();
    *buf = buf[pos + skip..].to_string();
    Some(frame)
}

fn parse_responses_frame(frame: &str) -> Result<ParsedResponsesFrame, ModelError> {
    let mut event_name = "";
    let mut data_lines = Vec::new();

    for line in frame.lines() {
        let line = line.trim_end_matches('\r');
        if let Some(value) = line.strip_prefix("event:") {
            event_name = value.trim();
        } else if let Some(value) = line.strip_prefix("data:") {
            data_lines.push(value.trim_start());
        }
    }

    if data_lines.is_empty() {
        return Ok(ParsedResponsesFrame::Ignore);
    }

    let data = data_lines.join("\n");
    match proto::parse_responses_sse_event(event_name, &data) {
        proto::ResponsesSseEvent::TextDelta(delta) => Ok(ParsedResponsesFrame::Delta(delta)),
        proto::ResponsesSseEvent::ReasoningDelta(delta) => {
            Ok(ParsedResponsesFrame::ReasoningDelta(delta))
        }
        proto::ResponsesSseEvent::OutputItemAdded { output_index, item } => {
            Ok(ParsedResponsesFrame::OutputItemAdded { output_index, item })
        }
        proto::ResponsesSseEvent::OutputItemDone { output_index, item } => {
            Ok(ParsedResponsesFrame::OutputItemDone { output_index, item })
        }
        proto::ResponsesSseEvent::FunctionCallArgumentsDelta {
            output_index,
            item_id,
            delta,
        } => Ok(ParsedResponsesFrame::FunctionCallArgumentsDelta {
            output_index,
            item_id,
            delta,
        }),
        proto::ResponsesSseEvent::FunctionCallArgumentsDone {
            output_index,
            item_id,
            call_id,
            name,
            arguments,
        } => Ok(ParsedResponsesFrame::FunctionCallArgumentsDone {
            output_index,
            item_id,
            call_id,
            name,
            arguments,
        }),
        proto::ResponsesSseEvent::Completed(response) => {
            Ok(ParsedResponsesFrame::Completed(response))
        }
        proto::ResponsesSseEvent::Failed(message) => Err(ModelError::Other(message)),
        proto::ResponsesSseEvent::Ignore => Ok(ParsedResponsesFrame::Ignore),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::ProviderKind;
    use serde_json::json;

    #[test]
    fn chat_tool_call_delta_keeps_existing_name_when_later_delta_has_no_name() {
        let mut parts = Vec::new();
        apply_tool_call_delta(
            &mut parts,
            proto::ChatStreamToolCallDelta {
                index: 0,
                id: Some("call_1".into()),
                name: Some("web_search".into()),
                arguments: Some(r#"{"query":"#.into()),
            },
        );
        apply_tool_call_delta(
            &mut parts,
            proto::ChatStreamToolCallDelta {
                index: 0,
                id: None,
                name: Some(String::new()),
                arguments: Some(r#""rust"}"#.into()),
            },
        );

        let calls = finish_tool_calls(parts);

        assert_eq!(calls.len(), 1);
        assert_eq!(calls[0].id, "call_1");
        assert_eq!(calls[0].name, "web_search");
        assert_eq!(calls[0].input, json!({"query": "rust"}));
    }

    #[test]
    fn api_key_openai_uses_responses_when_image_generation_tool_is_enabled() {
        let client = OpenAiClient::new(Provider {
            id: "openai".into(),
            name: "OpenAI".into(),
            kind: ProviderKind::Openai,
            enabled: true,
            auth_mode: AuthMode::ApiKey,
            base_url: "https://api.openai.com/v1".into(),
            api_key: "test".into(),
            refresh_token: None,
            token_expires_at: None,
            account_id: None,
            extra_headers: Default::default(),
            models: Vec::new(),
            default_model: None,
            title_gen_enabled: false,
            title_gen_model: None,
            claude_code_compat: false,
        })
        .unwrap();
        let req = ModelRequest {
            model: "gpt-5.5".into(),
            system: None,
            entries: Vec::new(),
            tools: vec![crate::types::ToolDefinition {
                name: crate::types::IMAGE_GENERATION_TOOL_NAME.into(),
                description: "生成图片".into(),
                parameters: json!({"type": "object"}),
            }],
            max_tokens: 8192,
            reasoning: None,
        };

        assert!(client.should_use_responses(&req));
    }

    #[test]
    fn image_generation_codex_client_gate_error_is_actionable() {
        let err = responses_http_error(
            403,
            r#"{"error":{"message":"This account only allows Codex official clients"}}"#
                .to_string(),
            true,
            "gpt-5.5",
        );

        assert!(err.to_string().contains("当前代理拒绝"));
        assert!(err.to_string().contains("codex_cli_only"));
    }

    #[test]
    fn image_generation_direct_image_model_error_is_actionable() {
        let err = responses_http_error(
            400,
            "The 'gpt-image-2' model is not supported when using Codex with a ChatGPT account."
                .to_string(),
            true,
            "gpt-image-2",
        );

        assert!(err.to_string().contains("不要把 gpt-image-2 作为对话模型"));
        assert!(err.to_string().contains("启用 image_generation 工具"));
    }

    #[test]
    fn responses_sse_accumulates_function_call_arguments_delta_and_done() {
        let body = concat!(
            "event: response.output_item.added\n",
            "data: {\"output_index\":0,\"item\":{\"id\":\"fc_1\",\"type\":\"function_call\",\"status\":\"in_progress\",\"call_id\":\"call_1\",\"name\":\"web_search\",\"arguments\":\"\"}}\n\n",
            "event: response.function_call_arguments.delta\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"delta\":\"{\\\"query\\\"\"}\n\n",
            "event: response.function_call_arguments.delta\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"delta\":\":\\\"rust docs\\\"}\"}\n\n",
            "event: response.function_call_arguments.done\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"call_id\":\"call_1\",\"name\":\"web_search\",\"arguments\":\"{\\\"query\\\":\\\"rust docs\\\"}\"}\n\n",
            "event: response.completed\n",
            "data: {\"response\":{\"id\":\"resp_1\",\"output\":[],\"usage\":{\"input_tokens\":3,\"output_tokens\":5}}}\n\n",
        );

        let parsed = parse_responses_body_or_sse(body).unwrap();

        match parsed {
            ModelResponse::ToolCalls { calls, usage, .. } => {
                assert_eq!(calls.len(), 1);
                assert_eq!(calls[0].id, "call_1");
                assert_eq!(calls[0].name, "web_search");
                assert_eq!(calls[0].input, json!({"query": "rust docs"}));
                assert_eq!(usage.input_tokens, 3);
                assert_eq!(usage.output_tokens, 5);
            }
            other => panic!("expected ToolCalls response, got {other:?}"),
        }
    }

    #[test]
    fn responses_sse_preserves_accumulated_arguments_when_done_item_is_empty() {
        let body = concat!(
            "event: response.output_item.added\n",
            "data: {\"output_index\":0,\"item\":{\"id\":\"fc_1\",\"type\":\"function_call\",\"status\":\"in_progress\",\"call_id\":\"call_1\",\"name\":\"web_fetch\",\"arguments\":\"\"}}\n\n",
            "event: response.function_call_arguments.delta\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"delta\":\"{\\\"url\\\":\\\"https://example.com\\\"\"}\n\n",
            "event: response.function_call_arguments.delta\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"delta\":\",\\\"prompt\\\":\\\"summarize\\\"}\"}\n\n",
            "event: response.output_item.done\n",
            "data: {\"output_index\":0,\"item\":{\"id\":\"fc_1\",\"type\":\"function_call\",\"status\":\"completed\",\"call_id\":\"call_1\",\"name\":\"web_fetch\",\"arguments\":\"\"}}\n\n",
            "event: response.completed\n",
            "data: {\"response\":{\"id\":\"resp_1\",\"output\":[],\"usage\":{\"input_tokens\":4,\"output_tokens\":6}}}\n\n",
        );

        let parsed = parse_responses_body_or_sse(body).unwrap();

        match parsed {
            ModelResponse::ToolCalls { calls, .. } => {
                assert_eq!(calls.len(), 1);
                assert_eq!(calls[0].id, "call_1");
                assert_eq!(calls[0].name, "web_fetch");
                assert_eq!(
                    calls[0].input,
                    json!({"url": "https://example.com", "prompt": "summarize"})
                );
            }
            other => panic!("expected ToolCalls response, got {other:?}"),
        }
    }

    #[test]
    fn responses_sse_uses_top_level_name_for_function_call_item() {
        let body = concat!(
            "event: response.output_item.added\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"call_id\":\"call_1\",\"name\":\"web_search\",\"item\":{\"id\":\"fc_1\",\"type\":\"function_call\",\"status\":\"in_progress\",\"arguments\":\"\"}}\n\n",
            "event: response.function_call_arguments.delta\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"delta\":\"{\\\"query\\\":\\\"weather\\\"}\"}\n\n",
            "event: response.output_item.done\n",
            "data: {\"output_index\":0,\"item_id\":\"fc_1\",\"call_id\":\"call_1\",\"item\":{\"id\":\"fc_1\",\"type\":\"function_call\",\"status\":\"completed\",\"arguments\":\"\"}}\n\n",
            "event: response.completed\n",
            "data: {\"response\":{\"id\":\"resp_1\",\"output\":[],\"usage\":{\"input_tokens\":4,\"output_tokens\":6}}}\n\n",
        );

        let parsed = parse_responses_body_or_sse(body).unwrap();

        match parsed {
            ModelResponse::ToolCalls { calls, .. } => {
                assert_eq!(calls.len(), 1);
                assert_eq!(calls[0].id, "call_1");
                assert_eq!(calls[0].name, "web_search");
                assert_eq!(calls[0].input, json!({"query": "weather"}));
            }
            other => panic!("expected ToolCalls response, got {other:?}"),
        }
    }
}

