                    } else {
                        match &response {
                            ModelResponse::Done { reasoning, .. } => reasoning.clone(),
                            ModelResponse::ToolCalls { reasoning, .. } => reasoning.clone(),
                        }
                    };

                    if reasoning.is_empty() {
