crates/protocol/src/permission.rs.content:
use serde::{Deserialize, Serialize};

/// 用户对一次审批请求的回应
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ApprovalDecision {
    /// 批准这一次
    AllowOnce,
    /// 批准并记住（同 scope 内的同类调用以后不再问）
    ///
    /// `pattern` 控制记忆粒度：
    /// - `None` → 工具名级（旧行为，对 Bash 类工具被 hitl 黑名单兜回 AllowOnce）
    /// - `Some("git status")` → 命令前缀级，匹配 `git status` / `git status -uno` 等
    /// - `Some("git")` → 根命令级，匹配所有以 `git ` 开头的命令
    ///
    /// 命中前缀的判定见 [`crate::permission`] 文档（按空白 token 边界匹配）。
    AllowAndRemember {
        scope: PermissionScope,
        #[serde(default)]
        pattern: Option<String>,
        /// 额外要一同记忆的命令前缀（compound 命令场景）。
        /// 例：`cd /tmp && touch foo` 弹审批，用户选「整条都允许」 → `pattern = "cd"`,
        /// `extra_patterns = ["touch"]`。后端循环写多条 PermissionRule。
        /// 空数组（默认）= 仅按 `pattern` 写一条规则（旧行为）。
        #[serde(default)]
        extra_patterns: Vec<String>,
    },
    /// 拒绝
    Deny,
    /// 拒绝并把反馈作为 user message 注入下一轮
    DenyWithFeedback { feedback: String },
}

/// 审批记忆生效的范围（架构 §4.5.3）。
///
/// 四选一：
/// - [`Once`](Self::Once)：本次放行，不持久化。
///   注意：本枚举主要用于 [`ApprovalDecision::AllowAndRemember`] 的 `scope` 字段；
///   单次放行通常应直接发 [`ApprovalDecision::AllowOnce`]，无需带 scope。
/// - [`Session`](Self::Session)：写到该 session 的 `session.jsonl`，重开仍生效。
///   只对当前对话生效。
/// - [`Project`](Self::Project)：写到 `~/.hebbian/permissions.json`，rule.workdir = 当前
///   session.workdir。同一 workdir（含子目录）下任何对话都生效，其他项目不受影响。
/// - [`Global`](Self::Global)：写到 `~/.hebbian/permissions.json`，rule.workdir = null，
///   任意对话生效。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum PermissionScope {
    Once,
    Session,
    Project,
    Global,
}

/// 复合命令里单段相对白名单的状态（审批弹窗据此决定该段怎么展示）。
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ApprovalSegmentStatus {
    /// 只读段：免审批、免记忆（灰显）。
    Readonly,
    /// 已命中某条 allow 规则：本次无需再处理（✓ 跳过）。
    Whitelisted,
    /// 不可记忆命令（rm/dd/…）：红色、不可勾选、每次必须确认（架构 §4.4.2.3）。
    Unmemorable,
    /// 会写且尚未进白名单：本次要决定是否加入（可勾选）。
    NeedsApproval,
}

/// 一段命令 + 它的白名单状态。审批弹窗逐段渲染，让用户看清「哪些已放行、哪些待批、
/// 哪些（rm）永远要确认」（架构 §4.4.2 / §4.4.2.3）。
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApprovalSegment {
    pub fingerprint: String,
    pub status: ApprovalSegmentStatus,
}

/// 审批请求的类别（用于 UI 渲染分类）
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum PermissionKind {
    /// 工具调用审批
    ToolCall {
        tool_name: String,
        input: serde_json::Value,
        /// 命令级记忆指纹（来自 [`crate::permission`] 文档：BashTool 给 `"git status -uno"`）。
        /// UI 据此渲染"记住 `git status` / 记住 `git`"两档按钮；
        /// `None` 时退回工具名级"总是允许 Bash"按钮。
        /// **历史字段**：等于 `command_segments[0]`，保留只为向前兼容（架构 §4.4.2）。
        #[serde(default)]
        fingerprint: Option<String>,
        /// Bash / PowerShell 里「会写 + 可记忆 + 尚未进白名单」的段 fingerprint——
        /// 即弹窗里可勾选记忆的那些。非 Bash 工具为空 vec（架构 §4.4.2）。
        #[serde(default)]
        command_segments: Vec<String>,
        /// 完整段级状态（含只读 / 已白名单 / 不可记忆 / 待审批），供弹窗逐段展示：
        /// 已白名单段标 ✓ 跳过、rm 段红色禁选。空 = 非 Bash 或老事件（架构 §4.4.2.3）。
        #[serde(default)]
        segments: Vec<ApprovalSegment>,
        /// 整条命令出于安全原因**任何作用域都不可记住**（危险复合模式，如 `cd X && git …`，
        /// 架构 §4.4.2.2）。为 true 时弹窗应隐藏作用域/记忆区，只留「允许一次 / 拒绝」。
        /// 注意：仅含 rm 这类不可记忆段**不**置 true——那只让 rm 段不可记，良性段仍可记。
        #[serde(default)]
        refuse_remember: bool,
    },
    /// workspace 越界路径访问审批（Bash/Read/Write/Grep）
    PathAccess {
        tool_name: String,
        paths: Vec<String>,
    },
    /// 计划审批（"按这个计划继续吗？"）。PlanMode 下 agent 调 ExitPlanMode 时
    /// 触发；surface 端用 plan_markdown 渲染完整预览，配合三按钮（通过 /
    /// 编辑后通过 / 重新规划带反馈）。
    ///
    /// - `plan_id` 与同 session 下 `plans/<plan_id>.md` 文件名对齐
    /// - `plan_path` 落盘绝对路径（surface 可直接 read_plan_markdown 重新拉取）
    /// - `plan_markdown` 当前内容快照（编辑后通过的话由 surface 走
    ///   `update_plan_markdown` 命令 patch 文件再发 AllowOnce）
    /// - `summary` 短句摘要，UI 列表 / 通知用
    /// - `steps` 历史字段，留作向前兼容；新版本不再使用
    Plan {
        #[serde(default)]
        plan_id: String,
        #[serde(default)]
        plan_path: String,
        #[serde(default)]
        plan_markdown: String,
        #[serde(default)]
        summary: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        steps: Vec<String>,
    },
    /// 长 run 继续审批
    ContinueLongRun { iterations_used: u32 },
}

// ── Ask：agent 主动向用户提问 ────────────────────────────────────────────────

/// 一个候选选项
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct QuestionOption {
    /// 短标签（按钮文字 / 选项行首），建议 1-12 字
    pub label: String,
    /// 详细说明（可空），用于 hover / 子行展示
    #[serde(default)]
    pub description: String,
}

/// 用户对一次 ask 的回应
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum UserAnswer {
    /// 单选：选了某个固定选项（带回 label）
    Selected { label: String },
    /// 多选：选了若干固定选项（带回 labels，按用户勾选顺序）
    SelectedMulti { labels: Vec<String> },
    /// 用户在自由输入框写的文字
    Custom { text: String },
    /// 用户取消（TUI 中按 ESC、UI 关闭弹窗等）
    Cancelled,
}

impl UserAnswer {
    /// 把答案规约成将要注入下一轮的 tool_result 文本
    pub fn to_agent_text(&self) -> String {
        match self {
            UserAnswer::Selected { label } => format!("用户选择：{label}"),
            UserAnswer::SelectedMulti { labels } => {
                if labels.is_empty() {
                    "[用户未选任何选项]".to_string()
                } else {
                    format!("用户选择（多选）：{}", labels.join("、"))
                }
            }
            UserAnswer::Custom { text } => format!("用户输入：{text}"),
            UserAnswer::Cancelled => "[用户取消了提问]".to_string(),
        }
    }
}

crates/protocol/src/submission.rs.content:
use serde::{Deserialize, Serialize};

use crate::context::TurnOverrides;
use crate::ids::{AgentRef, PermissionRequestId, RunId, SubmissionId};
use crate::permission::ApprovalDecision;

/// 外界向 Core 发出的所有意图都是一个 Submission
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Submission {
    pub id: SubmissionId,
    pub op: Op,
}

impl Submission {
    pub fn new(op: Op) -> Self {
        Self {
            id: SubmissionId::new(),
            op,
        }
    }
}

/// 用户输入（文本 + 可选附件元数据，附件本体走 BlobStore）
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserInput {
    pub text: String,
    /// 附件 blob_id 列表（具体内容由 surface 上传到 BlobStore 后引用）
    #[serde(default)]
    pub attachment_refs: Vec<String>,
}

impl UserInput {
    pub fn text(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            attachment_refs: Vec::new(),
        }
    }
}

/// 所有可对 Core 发起的操作
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Op {
    /// 启动一次新的 run
    StartRun {
        agent: AgentRef,
        input: UserInput,
        #[serde(default)]
        turn_overrides: Option<TurnOverrides>,
        /// 子 run 时填，为父 run 的 RunId
        #[serde(default)]
        parent: Option<RunId>,
    },

    /// 在已有 run 上追加一条用户消息（继续多轮对话）
    SendUserMessage { run_id: RunId, input: UserInput },

    /// 回应一次审批请求
    Approve {
        request_id: PermissionRequestId,
        decision: ApprovalDecision,
    },

    /// 回应一次 agent 主动提问
    AnswerQuestion {
        request_id: PermissionRequestId,
        answer: crate::permission::UserAnswer,
    },

    /// 中断 run（含级联取消子 run）
    Interrupt { run_id: RunId },

    /// 订阅一个 run 的事件流（用于断线重连或多端观察）
    /// 实际订阅在 Harness::subscribe 中处理；此 Op 主要用于跨 surface 协议
    Subscribe {
        run_id: RunId,
        #[serde(default)]
        since_seq: Option<u64>,
    },

    /// 显式压缩
    Compact { run_id: RunId },

    /// 回滚到指定 turn
    Rollback { run_id: RunId, to_turn: u32 },

    /// 从某个 run 在某 turn 处分叉
    Fork {
        from: RunId,
        #[serde(default)]
        at_turn: Option<u32>,
        #[serde(default)]
        agent: Option<AgentRef>,
    },

    /// 运行时切换 RunMode（架构 §10.2）。surface 监听 `RunModeChanged` 事件刷新 UI。
    /// `new_mode` 用字符串载入，actor 端解析为 [`crate::run_mode_str_*`]——避免协议层
    /// 反向依赖 agent-core 的 RunMode enum。
    SwitchRunMode { run_id: RunId, new_mode: String },
}

crates/protocol/src/todo.rs.content:
//! Todo / Plan comment 协议类型（架构 §4.4.6 / §4.4.5）。
//!
//! - [`TodoItem`]：TodoWrite 工具维护的单项 todo。前后端共享同一结构。
//! - [`PlanComment`]：PlanMode 下用户对 plan markdown 加的评论；落盘到
//!   `~/.hebbian/sessions/<sid>/plans/<plan_id>.comments.jsonl`，
//!   下一轮 user message 发送时拼到 SEMI 段并 mark consumed。

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct TodoItem {
    /// ulid，前后端贯通，可用于跨次 TodoWrite 增量更新（v1 仍按整列表覆盖）。
    pub id: String,
    pub content: String,
    /// 进行时形式（"Running tests"）。模型按 TodoWrite 协议要求同时提供两种态。
    #[serde(default)]
    pub active_form: String,
    pub status: TodoStatus,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum TodoStatus {
    Pending,
    InProgress,
    Completed,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PlanComment {
    pub id: String,
    pub plan_id: String,
    /// 锚定 plan markdown 中的某段，v1 为纯文本（如 "L12-15" / 选段首尾 7 字）。
    /// v2 再考虑 selection range / 精确 char offset。
    pub anchor: String,
    pub body: String,
    pub created_at_ms: i64,
    /// 是否已注入到下一轮 user message。append-only 文件，状态翻转通过追加
    /// `PlanCommentConsumed` 行或重写文件实现（见 storage::plan_comments）。
    #[serde(default)]
    pub consumed: bool,
}
